INSERT INTO `centers` VALUES (5,'Photos_ScientificResearchInnovationCenters/luPZsgQINXxAlhr0tY2ZlClHQ5MtJBvs26RhUTyl.jpg','المؤسسة المغربية للعلوم المتقدمة والابتكار والبحث العلمي','Moroccan Foundation for Advanced Science, Innovation and Research','تُعدّ المؤسسة المغربية للعلوم المتقدمة والابتكار والبحث (MAScIR) مؤسسة بحثية مغربية غير ربحية تأسست سنة 2007، وتهدف إلى تعزيز البحث العلمي والتطوير التكنولوجي من أجل دعم الاقتصاد القائم على المعرفة بالمملكة المغربية. وترتبط المؤسسة بـ جامعة محمد السادس متعددة التخصصات التقنية، فيما توجد مقراتها الرئيسية بمدينة العرفان بالعاصمة الرباط.',NULL,'http://www.mascir.com/',5,19,1,'2026-06-04 09:17:06','2026-06-04 09:22:26'),(6,'Photos_ScientificResearchInnovationCenters/3BCyTKacUTsZh29JDAu6ao8TopueAzbRKyalo9FI.png','المركز الوطني للبحث العلمي والتقني','null','يُعدّ المركز الوطني للبحث العلمي والتقني مؤسسة عمومية رسمية تابعة للدولة المغربية، يقع مقرها في مدينة الرباط. تم إحداثه في إطار قانوني لتنظيم وتطوير البحث العلمي والتقني بالمغرب، خاصة بموجب القانون رقم 80.00.',NULL,'https://www.cnrst.ma/ar/cnrst/a-propos/presentation',5,19,1,'2026-06-04 09:21:08','2026-06-04 09:46:56'),(7,'Photos_ScientificResearchInnovationCenters/Zt8cUIKzWEwFHy7hgiwwB0DRzKqIeePJShI7HJVp.png','معهد أبحاث الطاقة الشمسية والطاقات الجديدة','null','معهد البحث في الطاقة الشمسية والطاقات الجديدة (ويعرف اختصاراً بـ IRESEN) هو مؤسسة مغربية مكرسة للبحث والتطوير والابتكار في مجال الطاقة المتجددة وكفاءة الطاقة. \r\nتأسس المعهد في عام 2011، ويعد جزءاً من الاستراتيجية الوطنية للطاقة في المغرب التي تهدف إلى تعزيز مصادر الطاقة المستدامة.',NULL,'https://iresen.org/',5,19,1,'2026-06-04 09:27:40','2026-06-04 09:30:33'),(8,'Photos_ScientificResearchInnovationCenters/ZxG77ZabvXNODtOWLntC24RlwVFom7nbWzxoweMH.png','المركز الوطني للدراسات والبحث في الماء والطاقة','CNEREE','المركز الوطني للدراسات والأبحاث حول الماء والطاقة هو مؤسسة بحثية رائدة في المغرب، يقع مقره الرئيسي في جامعة القاضي عياض بمراكش. \r\n\r\nويهدف المركز إلى دراسة أزمة الإجهاد المائي وتطوير حلول مستدامة تدمج بين ترشيد استهلاك المياه، معالجة المياه العادمة، والطاقات المتجددة.',NULL,'https://cneree.uca.ma/',5,19,1,'2026-06-04 09:40:00','2026-06-10 12:03:42'),(9,'Photos_ScientificResearchInnovationCenters/TkedOee11QBJmrf0i4ASmr1uDvX7Wguu6ytsJpWV.jpg','قطب تكنولوجي وصناعي','Technopolis Rabat','تكنوبوليس الرباط (Technopolis Rabat) هو قطب تكنولوجي وصناعي متكامل يقع قرب مدينة سلا بالمغرب، ويهدف إلى تجميع الشركات التكنولوجية ومراكز البحث والابتكار في فضاء واحد لتعزيز التنمية الصناعية والاقتصاد الرقمي وربط البحث العلمي بالصناعة.\r\n: 2007 سنة التأسيس\r\n (وتم إطلاق أولى مراحله سنة 2008)',NULL,'https://www.medz.ma/fr/zones-industrielles',5,19,1,'2026-06-04 09:44:31','2026-06-04 09:44:31'),(10,'Photos_ScientificResearchInnovationCenters/Yw6FzCXzlGe9PTzkfiMO8T25ApODYLC86d7fIhOF.jpg','مركز الابتكار والأبحاث المتقدمة','Aerospace Research And Innovation Center','تم تأسيس مركز الابتكار والأبحاث \r\n المتقدمة في جامعة خليفة سنة 2012 كمبادرة مشتركة بين شركة مبادلة وجامعة خليفة.\r\nيقوم المركز بإجراء أبحاث متقدمة في مجالات المواد المتطورة، والتقنيات الرقمية التطبيقية، والتقنيات التطبيقية في مجال الصحة، إضافة إلى تقنيات الاستدامة.\r\nويُعدّ المركز منصة بحثية عالمية، حيث يتعاون مع جامعات رائدة حول العالم، ويطوّر فرصًا بحثية في مجالات متعددة، ويساهم في نقل التكنولوجيا ودعم الابتكار في مختلف القطاعات الصناعية.',NULL,'https://www.aric.ae/',5,2,1,'2026-06-04 09:59:31','2026-06-04 10:01:24'),(11,'Photos_ScientificResearchInnovationCenters/rbRJsFUN2MzbK33z5x37m3FeY4DV2Pj6AfWbQbiG.jpg','جامعة خليفة للعلوم والتكنولوجيا','null','جامعة خليفة للعلوم والتكنولوجيا هي جامعة بحثية رائدة في دولة الإمارات العربية المتحدة، تأسست سنة 2007، وتضم مراكز بحثية متخصصة في مجالات الطاقة، الفضاء، الهندسة، الذكاء الاصطناعي، والعلوم الطبية.\r\nتتميز الجامعة بتركيزها على البحث التطبيقي وربط الابتكار بالصناعة، حيث تسهم في تطوير حلول تكنولوجية متقدمة تدعم احتياجات الدولة. كما تلعب دوراً محورياً في دعم التنمية التكنولوجية وبناء اقتصاد معرفي قائم على البحث والابتكار في الإمارات.',NULL,'https://www.ku.ac.ae/',5,2,1,'2026-06-04 10:04:48','2026-06-04 10:06:13'),(12,'Photos_ScientificResearchInnovationCenters/QJecj4nYdRNOXwXCY1uN5dBhKWys05ao8bt158Fa.jpg','مجمع الشارقة للبحث والتكنولوجيا والابتكار','Sharjah Research Technology & Innovation Park','تأسست مجمع الشارقة للبحوث والتكنولوجيا والابتكار بأمر صاحب السمو الشيخ الدكتور سلطان بن محمد القاسمي، عضو المجلس الأعلى، حاكم الشارقة في 2016م. إذ صمم هذا المشروع وفق أفضل الممارسات وأعلى المعايير العالمية المتبعة في بناء مجمعات التكنولوجيا، ويركز على محاور عدة من بينها تكنولوجيا المياه، تكنولوجيا البيئة، الطاقة المتجددة، تكنولوجيا المواصلات، تكنولوجيا المعلومات، والتصميم الصناعي والعمارة، كما يعمل على دعم الصناعات الوطنية التي تندرج تحت هذه المحاور، وتكمن أهمية المجمع في ترجمته رؤية صاحب السمو حاكم الشارقة وقادة دولة الامارات بتفعيل دور التعليم والجامعات في البحث العلمي.',NULL,'https://srtip.ae/',5,2,1,'2026-06-04 10:10:54','2026-06-04 10:17:29'),(13,'Photos_ScientificResearchInnovationCenters/pn9xCW5FP5HGvZwpS1PvjVUbTTpNgx0G8N6ZXUAG.webp','جامعة محمد بن زايد للذكاء الاصطناعي',NULL,'تأسست جامعة محمد بن زايد للذكاء الاصطناعي على يد قادة دولة الإمارات العربية المتحدة الذين يتمتعون برؤية مدروسة للمستقبل. وهي تهدف إلى تعليم طلاب من أصحاب المواهب وتطوير قدراتهم، فضلاً عن تعزيز بيئة تشجع الابتكار، وتوفير مؤسسة بحثية استراتيجية داعمة للقطاعين الحكومي والخاص.\r\n\r\nوقد سُميت الجامعة تيمناً بصاحب السمو الشيخ محمد بن زايد آلِ نهيان، رئيس دولة الإمارات العربية المتحدة.\r\n\r\nتؤدي الجامعة دوراً جوهرياً في تحقيق العديد من الأهداف الاستراتيجية لدولة الإمارات العربية المتحدة، لاسيما وأن الذكاء الاصطناعي يشكل عنصراً بالغ الأهمية لتحقيق النمو والازدهار مستقبلاً. وتسعى رؤية الجامعة ورسالتها الاستراتيجيتان في آنٍ لترسيخ مكانة أبوظبي كقطب من أقطاب مجتمع الذكاء الاصطناعي الدولي.\r\n\r\nولا بد من الإشارة إلى أن الجامعة تجذب أهم الخبراء العالميين على الصعيدين الأكاديمي والعملي في مجالات الرؤية الحاسوبية، وتعلم الآلة، ومعالجة اللغات الطبيعية، وغيرها من المجالات.',NULL,'https://mbzuai.ac.ae/ar/',5,2,1,'2026-06-04 10:25:57','2026-06-04 10:25:57'),(14,'Photos_ScientificResearchInnovationCenters/NFhIrXVysNNhVmgA07NwRjtSEmTnkYZssoCtEcCf.png','معهد الابتكار التكنولوجي','Technology Innovation Institute (TII)','يعد معهد الابتكار التكنولوجي مؤسسةً بحثية رائدة عالمياً تهدف إلى توسيع آفاق المعرفة والبحوث العملية المتقدمة. حيث تعمل فرقنا المتنوعة والمكونة من أمهر العلماء والباحثين والمهندسين ضمن بيئة مرنة تحث على الابتكار والإبداع للمساهمة في إيجاد أحدث الاكتشافات العملية والتقنيات المبتكرة. ويركز عملنا على الوصول إلى الاكتشافات التي ستجهز مجتمعاتنا للمستقبل، كما أننا ملتزمون معاً بمواصلة الابتكار والإلهام من أجل مستقبل أفضل.',NULL,'https://www.tii.ae/ar',5,2,1,'2026-06-04 10:31:53','2026-06-04 10:34:11'),(15,'Photos_ScientificResearchInnovationCenters/GT6q7Ydyv7SDpI8by42hVaFICV2qbk8wRIAYc1oZ.jpg','مدينة مصدر','Masdar city','تُعد مدينة مصدر في أبوظبي نموذجاً عالمياً رائداً للاستدامة. تحتضن المدينة منظومة متكاملة للتقنيات النظيفة وتضم منطقة حرة تحتضن أكثر من 900 شركة. وهي بمثابة \"مركز ابتكار\" (Hub) يهدف لتطوير حلول تغير المناخ، وتشتهر بتصميم \"مبنى حاضنة قطر الأعمال\" (Incubator Building) الذي يتميز بواجهات منحنية مصممة لتوفير الظل للشوارع.\r\nوباعتبارها مجتمعًا حضريًا مستدامًا رائدًا، تقف مدينة مصدر في طليعة تغيير الطريقة التي يعيش بها الناس ويعملون ويتعلمون ويقضون أوقاتهم. وبصفتها مركزًا عالميًا للأعمال والتكنولوجيا، طوّرت مدينة مصدر منظومة مزدهرة من المؤسسات العالمية الرائدة التي تعمل معًا من أجل بناء مستقبل أكثر خضرة واستدامة.\r\nتوفر منطقة مدينة مصدر الحرة بيئة سلسة لمختلف الأنشطة التجارية، كما تعزز تجمعاتها الصناعية ذات التأثير الكبير التعاون والابتكار عبر قطاعات متعددة.',NULL,'https://masdarcity.ae/',5,2,1,'2026-06-04 10:39:21','2026-06-04 10:39:21'),(16,'Photos_ScientificResearchInnovationCenters/9CvAN7qEjdAV9vWXGxktqiqNW6LWGYdFMN9ePMn7.png','المركز الوطني للبحث والتطوير','National Center for Research and Development (NCRD)','تم تأسيس المركز الوطني للبحث والتطوير في أواخر عام 2010 بهدف   تطوير القدرات العلمية في مجالات التكنولوجيا النانوية والطاقة والتكنولوجيا الحيوية وبحوث البادية وأية مجالات بحثية أخرى. ولقد أتبعت للمركز برامج التكنولوجيا النانوية والتكنولوجيا الحيوية والمياه والغذاء بالإضافة إلى مركزي بحوث الطاقة والبادية اللذيْن كانا مركزين مستقلين في السابق.',NULL,'https://www.ncrd.gov.jo/',5,1,1,'2026-06-04 10:57:56','2026-06-04 10:57:56'),(17,'Photos_ScientificResearchInnovationCenters/Kv3NcZLTjpYkvG6ZYI0vAuNoqL3BL0dnTtr3rbnw.jpg','مركز المعلومات الوطني للعلوم والتكنولوجيا','National Information Center for Science & Technology','أنشئ مركز المعلومات الوطني للعلوم والتكنولوجيا كأول مركز للمعلومات في المملكة، وهو أحد المراكز التابعة للمجلس الاعلى للعلوم والتكنلوجيا برئاسة سمو الأمير الحسن بن طلال المعظم  رئيس المجلس الأعلى للعلوم والتكنولوجيا.\r\nوجاء انشاء المركز بهدف تطوير نظام متكامل للمعلومات الوطنية وبالتعاون مع الجهات الرسمية ومؤسسات القطاع الخاص وكذلك المساعدة في بناء قاعدة معلومات علمية وبحثية بما يلبي أهداف المجلس الأعلى.',NULL,'https://www.hcst.gov.jo/ar/node/1398',5,1,1,'2026-06-04 11:14:06','2026-06-04 11:16:05'),(18,'Photos_ScientificResearchInnovationCenters/6tbucZd1NwCeUzHWkzMiEi9fF8PpsVAf2ttiopvo.png','المركز الوطني للإبداع','National Center for Innovation ( NCI )','تم إنشاء المركز الوطني للإبداع في عام 2019، كمظلة وطنية تهدف إلى خلق بيئة ريادية تنافسية من خلال تنظيم وتنسيق كافة الجهود ضمن إطار شمولي تكاملي يرفد بيئة الأعمال باتجاهات واضحة للفرص الاقتصادية واستغلالها لتعزيز المشاركة الاقتصادية ضمن معايير تتوافق مع السوق مما يؤدي إلى تحسين مستوى التنظيم في مجالات الابداع ويكفل التنسيق وضبط المدخلات والمخرجات للارتقاء ببيئة الأعمال الابداعية للوصول إلى أفضل الممارسات العالمية.',NULL,'https://www.hcst.gov.jo/ar/nci2',5,1,1,'2026-06-04 12:39:16','2026-06-04 12:39:16'),(19,'Photos_ScientificResearchInnovationCenters/QK3mbnUgRHpc4SB1EHQZnMKzMrGNeFKyoJ1JE8gX.jpg','المعهد الوطني للروبوتات والتكنولوجيا','National Institute for Robotics and Technology','هو مؤسسة تعليمية وتدريبية متخصصة في مجالات الروبوتات والتكنولوجيا الحديثة، تأسست في العاصمة الأردنية عمّان عام 2018 بهدف تنمية مهارات الطلبة والشباب في مجالات العلوم والتكنولوجيا والهندسة والرياضيات (STEM)، وتعزيز قدراتهم في البرمجة والذكاء الاصطناعي والأتمتة والابتكار التقني.\r\n\r\nيوفر المعهد برامج تدريبية ودورات متخصصة لمختلف الفئات العمرية، إضافة إلى مختبرات تطبيقية ومشاريع عملية تدمج بين الجانب النظري والتطبيقي، بما يسهم في إعداد كوادر قادرة على مواكبة التطورات التكنولوجية والمشاركة في بناء اقتصاد المعرفة. كما يعمل المعهد على تنظيم المسابقات والأنشطة العلمية وإقامة شراكات مع الجامعات والمؤسسات التعليمية والتقنية لدعم الابتكار وريادة الأعمال التقنية.',NULL,'https://nirtjo.com/',5,1,1,'2026-06-04 12:43:29','2026-06-24 13:56:47'),(20,'Photos_ScientificResearchInnovationCenters/njnkVwXU8TX1LF38UOXYEiQwri98HTpbEG4fu4Yc.png','المجلس الأعلى للعلوم والتكنولوجيا صندوق دعم البحث العلمي والتطوير في الصناعة','irdf','أنشئ “المجلس الأعلى للعلوم والتكنولوجيا” في عام 1987 بهدف بناء قاعدة علمية وتكنولوجية وطنية تسهم في تحقيق الأهداف التنموية، وذلك من خلال زيادة الوعي بأهمية البحث العلمي والتطوير، وتقديم الدعم المالي المناسب له، وتوجيه النشاط العلمي والبحثي ضمن أولويات وطنية تنسجم مع التوجهات التنموية، وإنشاء مراكز متخصصة في البحث والتطوير كلما دعت الحاجة إلى ذلك ودعم الإبداع والريادة للإسهام في ترجمة الأفكار العلمية والتكنولوجية إلى منتجات وأعمال تجارية، وعقد الاتفاقيات المتعلقة بالتعاون العلمي والتكنولوجي مع الجهات المحلية والعربية والدولية، وتمثيل المملكة في الانشطة العلمية والتكنولوجية عربياً وإقليمياً ودولياً.',NULL,'https://www.irdf.jo/',5,1,1,'2026-06-04 12:49:07','2026-06-19 13:52:42'),(21,'Photos_ScientificResearchInnovationCenters/xzUb2JpdVWfRr6dx5MSc4X0uFqvPF1LaPERYWcuY.png','مركز البحرين للابتكار ونقل التكنولوجيا','null','تعتبر مراكز نقل التكنولوجيا بالجامعات حلقة وصل بين المجتمع الأكاديمي والمجتمع الخارجي. وتعمل هذه المراكز على حماية التقنيات الجديدة وتسهيل عملية احتضان الشركات الناشئة بناءً على نتائج الأبحاث العلمية. حيث الأمر يؤدي إلى التواصل بعدة لغات في تلك المراكز، وهي لغة العلوم والقانون والتجارة والصناعة ، لتتمكن تلك المراكز من القيام بواجبها كوسيلة لنقل الابتكارات من المختبرات إلى الأسواق المحلية والعالمية.\r\n\r\nنحنُ في مركز البحرين للابتكار ونقل التكنولوجيا نساعد الباحثين على حماية ابتكاراتهم وتحديد إمكانيات تسويق اختراعاتهم. تبدأ رحلتك معنا كمخترع، بملء استمارة الإفصاح عن الاختراع لإعلامنا باختراعك، مما يسمح لنا بدء عملية التقييم والنقل الفعال للتقنيات المناسبة من جامعة البحرين إلى القطاع الصناعي.',NULL,'https://www.uob.edu.bh',5,3,1,'2026-06-04 12:53:01','2026-06-24 14:44:48'),(22,'Photos_ScientificResearchInnovationCenters/1JbAjEVZdofy5Qt2HSiHBEffI5qq0lOqErB5Ei8o.png','مركز ناصر العلمي والتقني',NULL,'تُعتبر مؤسسة ناصر العلمي والتقني مؤسسة تعليمية وتدريبية متخصصة أُسست سنة 2008 في مملكة البحرين، وتهدف إلى تأهيل الشباب في المجالات التقنية والمهنية وفق أحدث المعايير التعليمية والتطبيقية. ويساهم المركز في تطوير الكفاءات الوطنية وتزويدها بالمهارات اللازمة لتلبية احتياجات سوق العمل الصناعي والتكنولوجي، بما ينسجم مع رؤية البحرين 2030 الرامية إلى تنويع الاقتصاد وتعزيز قدرات الشباب في مجالات الابتكار والتكنولوجيا.',NULL,'https://www.ncst.edu.bh/',5,3,1,'2026-06-04 12:55:31','2026-06-04 12:55:31'),(23,'Photos_ScientificResearchInnovationCenters/B4W6nVHb6g1fRTSr97XHXZ6LNbMiKr4Nd1C7iVN8.png','المركز العلمي البحريني لأهداف التنمية المستدامة','null','تم افتتاح المركز العلمي البحريني لأهداف التنمية المستدامة في أغسطس من العام 2018، ويعمل المركز تحت إشراف وزارة شؤون الشباب كأول مركز علمي من نوعه على مستوى العالم لرفع مستوى الوعي حول أهداف التنمية المستدامة الـ 17 وتمكين الشباب من لعب دور فعال في إحداث تأثير إيجابي على مجتمعاتهم المحلية وبلدهم والعالم.',NULL,'https://www.mya.gov.bh/ar/bscsgds',5,3,1,'2026-06-04 12:58:04','2026-06-24 14:21:40'),(24,'Photos_ScientificResearchInnovationCenters/EO53CAP2FbhwWGTz1YHa80fTYG7ik682FG3tPgKh.png','مختبر الابتكار التابع لـهيئة المعلومات والحكومة الإلكترونية','null','يعد مختبر الابتكار إحدى المبادرات المبتكرة التي أطلقتها هيئة المعلومات والحكومة الإلكترونية، والتي تهدف إلى تعزيز ثقافة الابتكار بالقطاع العام في مملكة البحرين عبر تشجيع تبني التقنيات الحديثة، تشمل ولا تقتصر على تقنيات الذكاء الاصطناعي، الرؤية الحاسوبية، سلسلة الكتل، الواقع المعزز. يهدف المركز إلى تأسيس مختبر لتحفيز وإثراء ثقافة الابتكار في القطاع الحكومي من خلال وضع منظومة متكاملة لتعزيز أنشــطة التطويــر والبحــث والابتكار واســتخدام التكنولوجيــا الحديثــة لدعــم جهــود تنميــة القطاعــات الواعــدة بالشــراكة مــع القطــاع الخــاص. يقع المركز الوطني في هيئة المعلومات والحكومة الإلكترونية.',NULL,'https://www.iga.gov.bh/category/innovation-hub',5,3,1,'2026-06-04 13:01:14','2026-06-24 14:07:15'),(25,'Photos_ScientificResearchInnovationCenters/LDFF6jxLUqnmMazbB6jykB84uWmrYnaEgFuYEAnZ.png','مختبر الابتكار  التابع للجامعة الأمريكية','Investcorp Innovation Lab - Powered by AUBH','مختبر إنفستكورب للابتكار (IIL AUBH) المدعوم من American University of Bahrain هو أول مركز ابتكار جامعي في Bahrain يهدف إلى ربط الأوساط الأكاديمية بقطاع الأعمال والصناعة. ويعمل المختبر على تمكين الشركات الناشئة والمؤسسات ورواد الابتكار من خلال توفير حاضنات أعمال متقدمة، وبرامج للابتكار المؤسسي، وإتاحة الوصول إلى شبكات وخبرات عالمية.\r\n\r\nوبصفته المقر الحصري لبرنامج MIT Venture Mentoring Service في البحرين، يوفر المختبر نظامًا متكاملًا للإرشاد والتوجيه يعتمد على منهجيات مجربة عالميًا، لمساعدة المشاريع الريادية على التحقق من جدوى أفكارها، وتعزيز نموها، وتوسيع نطاق أعمالها. كما تجمع برامجه بين الرؤى المستندة إلى البحث العلمي، والتوجيه العملي، والشراكات الاستراتيجية، بما يسهم في تسريع نمو منظومة الابتكار وريادة الأعمال في المملكة والمنطقة.',NULL,'https://bh.linkedin.com/company/investcorp-innovation-lab',5,3,1,'2026-06-04 13:03:54','2026-06-25 08:10:05'),(26,'Photos_ScientificResearchInnovationCenters/5P0hs4yUcoLUEpdF6J4w7qBVipuCEyZ34GvYs5Uk.png','المركز الإقليمي لتكنولوجيا المعلومات والاتصال','null','يعمل المركز الإقليمي لتكنولوجيا المعلومات والاتصال بمملكة البحرين تحت إشراف منظمة اليونسكو، وهو مركز معتمد من الفئة الثانية، إذ يستكمل الجهود التي تقوم بها منظمة اليونسكو لتحقيق أهدافها الاستراتيجية وبناء مجتمعات المعرفة.',NULL,'https://regcict.com/',5,3,1,'2026-06-04 13:33:50','2026-06-24 14:42:53'),(27,'Photos_ScientificResearchInnovationCenters/CfXtpTh4F2lV54KC90YKJQbcAAzxOsKPoQ5sYlbe.png','القطب التكنولوجي بسيدي ثابت',NULL,'يُعدّ القطب التكنولوجي بسيدي ثابت فضاءً علمياً وتكنولوجياً مخصصاً لتعزيز البحث والابتكار في مجال البيوتكنولوجيا والصناعات الحيوية. يهدف إلى ربط البحث العلمي بالقطاع الصناعي من خلال دعم المشاريع المبتكرة، وتشجيع نقل التكنولوجيا، واحتضان المؤسسات الناشئة في مجالات الصحة، الفلاحة، والصناعات الدوائية. كما يساهم في تطوير اقتصاد المعرفة وتعزيز القدرة التنافسية للقطاع الصناعي في تونس.\r\nسنة التأسيس: 1990',NULL,'https://www.biotechpole.tn/ar/',5,4,1,'2026-06-04 13:35:15','2026-06-04 13:35:15'),(28,'Photos_ScientificResearchInnovationCenters/EEQEPqlLzZHLBjJlcDIF2hvoLzDlGkuAAvSQQDF5.png','مركز البيوتكنولوجيا بصفاقس',NULL,'يُمثلّ مركز البيو تكنولوجيا بصفاقس مؤسسة عمومية للبحث العلمي والتطوير التكنولوجي أُسست سنة 1983، وتخضع لإشراف وزارة التعليم العالي والبحث العلمي بالجمهورية التونسية. يختص المركز في مجالات البيو تكنولوجيا والابتكار العلمي، ويعمل على تطوير الأبحاث التطبيقية وربطها بالقطاعين الصناعي والاقتصادي، خاصة في مجالات الصحة، الفلاحة، البيئة، والصناعات الحيوية. كما يساهم المركز في نقل التكنولوجيا، دعم الابتكار، وتكوين الباحثين والكفاءات العلمية المتخصصة.',NULL,'http://www.cbs.rnrt.tn/',5,4,1,'2026-06-04 13:36:22','2026-06-04 13:36:22'),(29,'Photos_ScientificResearchInnovationCenters/SIEfg3uWdggV5lEalzjYD5LPzirnBSNMPaOfWY2m.jpg','مركز بحوث وتكنولوجيات المياه','CERTE','يعتبر مركز بحوث وتكنولوجيات المياه مؤسسة عمومية للبحث العلمي والتطوير التكنولوجي أُسست سنة 2005 بالجمهورية التونسية، وتخضع لإشراف وزارة التعليم العالي والبحث العلمي. يختص المركز بتطوير الأبحاث والتقنيات المرتبطة بقطاع المياه، خاصة في مجالات معالجة المياه، تحلية المياه، إعادة التدوير، والابتكار البيئي، كما يساهم في دعم التنمية المستدامة وتطوير الحلول التكنولوجية لفائدة القطاعين الصناعي والاقتصادي.',NULL,'http://www.certe.rnrt.tn/',5,4,1,'2026-06-04 13:37:17','2026-06-11 13:59:05'),(30,'Photos_ScientificResearchInnovationCenters/IkEWuMKZy8FW4WOqngpnP3anFla67FO97GQ31RU4.png','القطب التكنولوجي بصفاقس',NULL,'يُمثل القطب التكنولوجي بصفاقس فضاءً علمياً وتكنولوجياً يهدف إلى تعزيز الابتكار وربط البحث العلمي بالقطاع الصناعي والاقتصادي. أُسس سنة 2006، ويهتم بدعم المشاريع التكنولوجية والبحثية، وتشجيع ريادة الأعمال، وتطوير مجالات التكنولوجيا الحديثة والصناعة الرقمية، بما يساهم في دعم التنمية الصناعية والاقتصاد القائم على المعرفة في تونس.',NULL,'https://www.tpsfaxe.tn/?utm_source=chatgpt.com',5,4,1,'2026-06-04 13:38:21','2026-06-04 13:38:21'),(31,'Photos_ScientificResearchInnovationCenters/W5nJgRzp5usBtQR6mnXtFdNBNwjN1WgAqTMlq70B.png','مركز البحث في الرقميات بصفاقس','Digital Research Center of Sfax','يمثل مركز البحث الرقمي بصفاقس مؤسسة بحثية متخصصة في مجالات التكنولوجيا الرقمية والابتكار بالجمهورية التونسية. أُسس سنة 2012، ويهتم بتطوير الأبحاث التطبيقية في الذكاء الاصطناعي، إنترنت الأشياء، الأمن السيبراني، وتحليل البيانات. ويساهم المركز في دعم التحول الرقمي وربط البحث العلمي بالقطاع الصناعي والتكنولوجي من خلال تطوير حلول رقمية مبتكرة تخدم التنمية الاقتصادية والصناعية.',NULL,'https://www.crns.rnrt.tn/',5,4,1,'2026-06-04 13:40:21','2026-06-04 13:40:21'),(32,'Photos_ScientificResearchInnovationCenters/rbXjVoXQOIAsXTAWArqGbaS8o9lIhYmcFpg8M4jY.png','المعهد الوطني للبحث الزراعي (في التكنولوجيا الزراعية',NULL,'المعهد الوطني للبحث الزراعي بتونس\r\n\r\nيُعدّ من أقدم المؤسسات البحثية في تونس، ويختص في البحث الزراعي وتطوير التقنيات الفلاحية وتحسين الإنتاج الزراعي. كما يعمل على دعم الابتكار في مجالات الزراعة الذكية والصناعات الغذائية، بما يساهم في تعزيز الأمن الغذائي والتنمية المستدامة.\r\nسنة التأسيس: 1911.',NULL,'http://www.inrat.agrinet.tn/',5,4,1,'2026-06-04 13:42:37','2026-06-04 13:42:37'),(33,'Photos_ScientificResearchInnovationCenters/mAQdZx8QxgtscfRY0al2hwBLEfIYNNFmnHbcx39R.png','القطب التكنولوجي ببرج السدرية','Technopole Borj Cédria','القطب التكنولوجي ببرج السدرية\r\n\r\nفضاء بحث وتطوير يجمع بين مراكز علمية ومخابر متخصصة في مجالات الطاقة والبيئة والمواد. يهدف إلى ربط البحث العلمي بالصناعة ودعم الابتكار التكنولوجي وتطوير حلول مستدامة في مجالات الطاقة النظيفة والصناعة الخضراء.\r\nسنة التأسيس: 2000',NULL,'https://www.tbs.rnrt.tn/',5,4,1,'2026-06-04 13:44:31','2026-06-04 13:44:31'),(34,'Photos_ScientificResearchInnovationCenters/yDAyQybB5eOQSlz2ohC993YcqNNKgAgs5Rdhjns8.png','مركز البحوث وتكنولوجيات الطاقة',NULL,'مركز البحوث وتكنولوجيات الطاقة\r\nمركز بحثي يختص في الطاقات المتجددة وكفاءة الطاقة والتقنيات الطاقية الحديثة.\r\n يساهم في تطوير حلول تكنولوجية تدعم الصناعة وتقلل من استهلاك الطاقة، مع تعزيز الابتكار في مجال التحول الطاقي والتنمية المستدامة.\r\nسنة التأسيس: 1989',NULL,'http://www.crten.rnrt.tn/',5,4,1,'2026-06-04 13:45:40','2026-06-04 13:45:40'),(35,'Photos_ScientificResearchInnovationCenters/bH5LORKSFMQ5es2A8hNrGWy1NVgkAouzGvXfwBPa.jpg','المركز الوطني للبحوث في علوم المواد',NULL,'المركز الوطني للبحوث في علوم المواد هو مؤسسة بحثية تونسية تُعنى بتطوير علوم المواد وهندستها لخدمة قطاعات الصناعة والطاقة والبيئة.\r\n يشكّل أحد المراكز الوطنية المتخصصة التابعة لوزارة التعليم العالي والبحث العلمي، ويُعدّ منصة أساسية للتعاون بين الجامعات والقطاع الصناعي في مجال تطوير المواد المتقدمة',NULL,'http://www.cnrsm.rnrt.tn/',5,4,1,'2026-06-04 13:47:01','2026-06-04 13:47:01'),(36,'Photos_ScientificResearchInnovationCenters/1w3gsy6I0pZdXhdtZMgd02V8JT8VzxPGyA1bOVzi.png','المركز الوطني الجامعي للتوثيق العلمي والتقني',NULL,'المركز الوطني الجامعي للتوثيق العلمي والتقني في تونس هو مؤسسة عمومية تابعة لوزارة التعليم العالي والبحث العلمي، تأسس سنة 1978، ويهتم بجمع وتنظيم وتوفير المعلومات والوثائق العلمية والتقنية لفائدة الباحثين والجامعات ومراكز البحث، كما يتيح قواعد بيانات ومصادر علمية ويساعد على نشر المعرفة وتسهيل الوصول إلى الأبحاث والدراسات لدعم البحث العلمي في البلاد.',NULL,'https://www.cnudst.rnrt.tn/',5,4,1,'2026-06-04 13:48:04','2026-06-04 13:48:04'),(37,'Photos_ScientificResearchInnovationCenters/4IpkVtU0JleHElLGDyl86i3o3XeY09s1sN4wSPXt.jpg','المجلس الوطني للبحث العلمي والتكنولوجيات',NULL,'يُعدّ المجلس الوطني للبحث العلمي والتكنولوجيات الهيئة الوطنية العليا المشرفة على منظومة البحث العلمي والتطوير التكنولوجي في الجزائر، وقد تأسس سنة 1998 بهدف وضع سياسات البحث العلمي، وتنسيق وتمويل المشاريع البحثية، ودعم الابتكار وربط البحث العلمي بالتنمية الصناعية والاقتصادية.',NULL,'https://www.cnrst.dz/',5,5,1,'2026-06-04 13:49:02','2026-06-04 13:49:02'),(38,'Photos_ScientificResearchInnovationCenters/Mnkuf0w4P0N0b6udvYzuFYIYPjz1lEYuxMkKYIHW.png','مركز تنمية التكنولوجيات المتطورة','cdta','يُعتبر مركز تنمية التكنولوجيات المتطورة مركزاً وطنياً للبحث والتطوير أُسس سنة 1988، ويختص في مجالات التكنولوجيات المتقدمة مثل الإلكترونيات الدقيقة، النانو تكنولوجيا، الأنظمة الذكية، والابتكار الصناعي، كما يساهم في تطوير حلول تكنولوجية تدعم الصناعة الجزائرية والتحول الرقمي',NULL,'https://www.cdta.dz/',5,5,1,'2026-06-04 13:49:59','2026-06-10 12:20:44'),(39,'Photos_ScientificResearchInnovationCenters/Qdg5W0g5LoljXInxiTSAiC5NYvOYkkSzAiRXbM2S.png','مركز البحث العلمي والتقني حول المناطق القاحلة',NULL,'يُعدّ مركز البحث العلمي والتقني حول المناطق القاحلة مؤسسة بحثية وطنية أُسست سنة 1992، وتهتم بالبحث العلمي في المناطق الصحراوية وشبه الجافة، من خلال تطوير الدراسات المتعلقة بالزراعة الصحراوية، وإدارة الموارد الطبيعية، ومكافحة التصحر، ودعم التنمية المستدامة في البيئات القاحلة.',NULL,'https://crstra.dz/ar',5,5,1,'2026-06-04 13:52:01','2026-06-04 13:52:01'),(40,'Photos_ScientificResearchInnovationCenters/0oIhQDsBWnTZerpcyC0qJU2HgndphqVbC3KcXeV3.png','مركز دعم التكنولوجيا والابتكار','Technology and Innovation Support Center','أنشأ مركز دعم التكنولوجيا و الإبتكار بجامعة عبد الحميد مهري قسنطينة 2 في إطار إتفاقية الشراكة و التعاون بين الجامعة و المعهد الوطني الجزائري للملكية الصناعية الموقعة يوم 17 جانفي 2021.\r\n\r\nوتحدد هذه الشراكة الشروط و الأحكام الخاصة بإنشاء المركز من أجل ضمان خدمات تتلاءم مع إحتياجات المستخدمين من أساتذة و  وباحثين و طلبة في مجال المعلومات التكنولوجية مع ضمان حماية ملكيتهم الصناعية.\r\n\r\nومن أهداف المركز:\r\n\r\nتفعيل دور الجامعة في تشجيع وتنمية القدرات الإبداعية والإبتكارية.\r\nالحث على تجسيد نتائج البحث العلمي والعمل الابداعي بالجامعة على أرض الواقع.\r\nتهيئة بيئة تدعم الابتكار والتطور التكنولوجي.',NULL,'https://www.univ-constantine2.dz/cati/?lang=ar',5,5,1,'2026-06-04 13:56:41','2026-06-10 12:06:03'),(41,'Photos_ScientificResearchInnovationCenters/kkDDgTSUy7CH3TGzhOtATsTLkSRRvt9YFxxAzHYN.png','المديرية العامة للبحث العلمي والتطوير التكنولوجي',NULL,'تُعتبر المديرية العامة للبحث العلمي والتطوير التكنولوجي الجهة الحكومية المشرفة على تنظيم وتطوير منظومة البحث العلمي في الجزائر، وقد أُنشئت سنة 2008 بهدف تنسيق برامج البحث، والإشراف على المراكز البحثية الوطنية، وتمويل المشاريع العلمية والتكنولوجية الكبرى.',NULL,'https://www.dgrsdt.dz/',5,5,1,'2026-06-04 13:58:22','2026-06-04 13:58:22'),(42,'Photos_ScientificResearchInnovationCenters/xbUiYMogDyoRlKJ0xwHiisdBqkBIfZzJbBkWxws4.jpg','مركز البحث في التكنولوجيات الصناعية',NULL,'يُعتبر مركزاً وطنياً متخصصاً في البحث والتطوير في مجال التكنولوجيات الصناعية، ويعمل على تطوير الحلول التقنية المرتبطة بالتصنيع، المواد، الروبوتات، الأنظمة الذكية، واللحام الصناعي. كما يساهم في نقل التكنولوجيا نحو المؤسسات الصناعية الجزائرية ودعم الابتكار الصناعي',NULL,'https://www.crti.dz/',5,5,1,'2026-06-04 14:01:38','2026-06-04 14:01:38'),(43,'Photos_ScientificResearchInnovationCenters/bk6ACyAgBPZcdDpBQAoex8gvQ4Lfh1aQRAj9iPYk.png','مركز البحث في تكنولوجيا نصف النواقل الطاقوية','crtse','يُعتبر مركز البحث في تكنولوجيا نصف النواقل الطاقوية مركزاً بحثياً وطنياً تأسس سنة 1992، ويعمل على تطوير تكنولوجيا أشباه الموصلات والخلايا الشمسية والمواد الإلكترونية لدعم الابتكار والصناعة الطاقوية في الجزائر.',NULL,'https://crtse.dz/',5,5,1,'2026-06-04 14:02:51','2026-06-10 12:16:13'),(44,'Photos_ScientificResearchInnovationCenters/BQnMg9N35pSaLmGCd6TJc2berqrvRQEYyyjZ1FBk.png','مركز الدراسات والبحوث العلمية',NULL,'يُعدّ مركز الدراسات والبحوث العلمية بجيبوتي المؤسسة الوطنية الرئيسية للبحث العلمي والتكنولوجي في جمهورية جيبوتي، وقد تأسس سنة 1979 بهدف تطوير البحث العلمي، وتعزيز الابتكار، ودعم الدراسات المرتبطة بالتنمية المستدامة والموارد الطبيعية والتكنولوجيا الحديثة.',NULL,'https://www.cerd.dj/',5,6,1,'2026-06-04 14:04:45','2026-06-04 14:04:45'),(46,'Photos_ScientificResearchInnovationCenters/wvQnL7AhGFzWfl5Ff8Ypu50K0UiBhiCcuwG1Z73X.png','مركز التكنولوجيا والابتكار من أجل التنمية',NULL,'يُعتبر مركز التكنولوجيا والابتكار من أجل التنمية أول حاضنة ومركز وطني للابتكار التكنولوجي في جيبوتي، وقد أُطلق سنة 2017 بهدف دعم ريادة الأعمال والابتكار في مجالات التكنولوجيا الرقمية، الطاقات المتجددة، والخدمات الذكية، مع تشجيع المشاريع ذات الأثر الاقتصادي والتنموي.',NULL,'https://ctid-djibouti.org/',5,6,1,'2026-06-04 14:09:28','2026-06-04 14:09:28'),(47,'Photos_ScientificResearchInnovationCenters/zHDnEUbGjnu4F4wXqiKxnWkQTrTzdisCMDgyeXVX.png','مرصد البحث والبيئة والمناخ',NULL,'يُعدّ مرصد البحث والبيئة والمناخ منصة علمية وبحثية متخصصة أُنشئت حديثاً لدعم البحث العلمي في مجالات البيئة والمناخ والصحة والموارد الطبيعية، كما يعمل على تطوير الدراسات العلمية المتعلقة بالتغيرات المناخية والتنمية المستدامة في جيبوتي والمنطقة.',NULL,'https://orrec.net/lorrec',5,6,1,'2026-06-04 14:10:44','2026-06-04 14:10:44'),(49,'Photos_ScientificResearchInnovationCenters/icPTuTTbuotQtZEfFeu01CDKKs4euACzokkJnnhO.jpg','مدينة الملك عبد العزيز للعلوم والتقنية','kacst','تُعدّ مدينة الملك عبد العزيز للعلوم والتقنية المؤسسة الوطنية الرئيسية للبحث العلمي والتطوير التكنولوجي في المملكة العربية السعودية، وقد تأسست سنة 1977 بهدف دعم الابتكار، وتطوير التكنولوجيا، وتمويل الأبحاث العلمية، ونقل المعرفة لدعم التنمية الصناعية والاقتصاد المعرفي.',NULL,'https://www.kacst.gov.sa/',5,7,1,'2026-06-04 14:13:02','2026-06-10 12:14:32'),(50,'Photos_ScientificResearchInnovationCenters/UhYAf5AstVW7S2ucBv809f224tpim5LW5TYFR0Z9.png','مدينة الملك عبدا لله للطاقة الذرية والمتجددة',NULL,'تعتبر مدينة الملك عبد الله للطاقة الذرية والمتجددة مركزاً وطنياً أُسس سنة 2010، ويهتم بتطوير أبحاث الطاقة المتجددة والطاقة النووية، ودعم الابتكار في مجال الطاقة المستدامة والتقنيات الحديثة.',NULL,'https://www.energy.gov.sa/',5,7,1,'2026-06-04 14:14:45','2026-06-04 14:14:45'),(51,'Photos_ScientificResearchInnovationCenters/TaXsCfhuB1t7tTWrBbMZtlAWbUkd1REfF0wpzxXq.jpg','مركز الثورة الصناعية الرابعة',NULL,'يُعدّ مركز الثورة الصناعية الرابعة السعودية مركزاً وطنياً أُطلق سنة 2021 بالتعاون مع المنتدى الاقتصادي العالمي، ويعمل على تطوير تقنيات الذكاء الاصطناعي، وإنترنت الأشياء، والتحول الرقمي، ودعم الصناعة 4.0 في المملكة.',NULL,'https://c4irsaudiarabia.org/',5,7,1,'2026-06-04 14:16:09','2026-06-04 14:16:09'),(52,'Photos_ScientificResearchInnovationCenters/cFla2HQTCIhQTCOFKgL1KmJnR29VtwfTRlmrjCBh.png','معهد الابتكار التقني',NULL,'يُعتبر معهد الابتكار التقني مركزاً بحثياً متقدماً في مجالات الذكاء الاصطناعي والروبوتات والتقنيات المستقبلية، وقد أُسس سنة 2020 بهدف دعم الابتكار الصناعي والتكنولوجي في إطار رؤية السعودية 2030.',NULL,'https://tii.sa/',5,7,1,'2026-06-04 14:18:33','2026-06-04 14:18:33'),(53,'Photos_ScientificResearchInnovationCenters/591KmNndylomeJAYmE7KvNjWiiXhLT6gZRsi2BPg.png','معهد بحوث البترول والطاقة',NULL,'يعدّ معهد بحوث البترول والطاقة مركزاً بحثياً متخصصاً في أبحاث النفط والطاقة والبتروكيماويات، ويعمل على تطوير تقنيات صناعية متقدمة لدعم قطاع الطاقة في المملكة، وقد تأسس سنة 1975.',NULL,'https://www.kfupm.edu.sa/',5,7,1,'2026-06-04 14:20:08','2026-06-04 14:20:08'),(54,'Photos_ScientificResearchInnovationCenters/CoaBsjMYAS8UdeQX48kEwNcmEf6wlTTuNKPyb0FS.png','المركز القومي للبحوث','National Centre for Research Sudan','يُعد من أهم المؤسسات البحثية الحكومية في السودان، ويعمل تحت إشراف وزارة التعليم العالي والبحث العلمي. يهتم بإجراء البحوث في مجالات العلوم الأساسية، البيئة، الصحة، والتكنولوجيا، إضافة إلى دعم الابتكار العلمي وخدمة التنمية الوطنية.',NULL,'https://ncr.gov.sd/',5,8,1,'2026-06-04 14:21:26','2026-06-04 14:21:26'),(55,'Photos_ScientificResearchInnovationCenters/ecReCy3sbCzPJ4KO3GkT47jGEn8jxQeBBjqLofuU.jpg','الهيئة السودانية للطاقة الذرية','Sudanese Atomic Energy Commission','مؤسسة وطنية متخصصة في البحث والتطوير في مجال الطاقة النووية وتطبيقاتها السلمية، خاصة في الطب النووي، الزراعة، والصناعة، إضافة إلى الأبحاث المتعلقة بالإشعاع والسلامة النووية.',NULL,'http://www.saec.gov.sd/',5,8,1,'2026-06-04 14:22:39','2026-06-19 13:57:31'),(56,'Photos_ScientificResearchInnovationCenters/W5gDijjD9bciurPIuuE7b7PbyUOpcZ39ZK6hZjUm.jpg','هيئة البحوث الزراعية','Agricultural Research Corporation Sudan','تُعتبر أكبر مؤسسة بحثية زراعية في السودان، وتعمل على تطوير المحاصيل الزراعية، تحسين الإنتاج، مقاومة الجفاف، ودعم الأمن الغذائي من خلال الابتكار في المجال الزراعي.',NULL,'https://arc.gov.sd/',5,8,1,'2026-06-04 14:24:25','2026-06-04 14:24:25'),(57,'Photos_ScientificResearchInnovationCenters/14dYs78oRUclYXkGqWNoOICYiJVJ7dRn7MRR60fA.png','مراكز البحوث والاستشارات الصناعية','Industrial Research and Consultancy Centre Sudan','أنشئ مركز البحوث والاستشارات الصناعية في فبراير من العام 1965م بدعم ومساعدة من منظمة الأمم المتحدة للتنمية الصناعية  (يونيدو) كمؤسسة قُطريّة بنيت على أسس غير تجارية، ليقدم خدماته الاستشاريــــة والبحثية والتطبيقية في استغلال المواد والموارد للقطاع الصناعي والقطاع الخدمي، بشقيه العام والخاص، تحت مسمى هيئة البحوث الصناعية، ثم معهد البحوث والاستشارات الصناعية.',NULL,'https://ircc.gov.sd/',5,8,1,'2026-06-04 14:28:50','2026-06-04 14:28:50'),(58,'Photos_ScientificResearchInnovationCenters/aJLp7HPbSkVVcbsjc1FvNFC5Ql5pbjd2Nr6flMWW.png','الهيئة العامة للطاقة الذرية السورية','Atomic Energy Commission of Syria','أحدثت هيئة الطاقة الذرية في الجمهورية العربية السورية في عام 1976 وبدأت ممارسة نشاطها المؤسساتي منذ عام 1979 وهي جهة حكومية مسؤولة عن شؤون الطاقة الذرية وتطبيقاتها في المجالات السلمية. \r\nوتعمل على وضع الأسس والقواعد الناظمة لشؤون هذه الاستخدامات في الأراضي السورية، وتعد هيئة الطاقة الذرية السورية السلطة الرقابية المتخصصة التي أنيطت بها مهام الإحاطة بالأنشطة الإشعاعية وتتولى مسؤولية مراقبة كافة الممارسات الإشعاعية في القطر ومراقبة واردات وصادرات القطر في المنافذ الحدودية للتأكد من خلوها من الإشعاع.',NULL,'http://www.aec.org.sy/',5,9,1,'2026-06-04 14:31:48','2026-06-04 14:31:48'),(59,'Photos_ScientificResearchInnovationCenters/RaInXAGz5kXOOJnCHPGQNJcvZzmGlWS7HAFoAxxG.jpg','الهيئة العامة للبحوث العلمية الزراعية','General Commission for Scientific Agricultural Research Syria','أُحدثت الهيئة عام 2000 كهيئة عامة ذات طابع علمي، وتتبع لوزارة الزراعة والإصلاح الزراعي، ومقرها الرئيسي في دمشق. وفي عام 2012 أعيد تنظيمها وإحداثها بموجب المرسوم التشريعي رقم 24 لعام 2012.\r\nوتُعد الهيئة الجهة الوطنية الرئيسية المسؤولة عن البحث العلمي الزراعي في سوريا، وتهدف إلى تطوير القطاع الزراعي من خلال إجراء البحوث والدراسات العلمية في مجالات الإنتاج النباتي والحيواني، والموارد الطبيعية، والتقانات الحيوية، وتحسين الأصناف الزراعية، ومكافحة الآفات والأمراض الزراعية. كما تعمل على نقل نتائج البحوث إلى المزارعين والجهات المعنية للمساهمة في تحقيق التنمية الزراعية المستدامة وتعزيز الأمن الغذائي',NULL,'https://gcsar.gov.sy/',5,9,1,'2026-06-04 14:36:34','2026-06-04 14:36:34'),(61,'Photos_ScientificResearchInnovationCenters/HMiuAogdjVJer6ZH8k7ifCuWiODrgrnKVzLJTZnn.png','المركز الوطني الصومالي للذكاء الاصطناعي',NULL,'تُعدّ المركز الوطني الصومالي للذكاء الاصطناعي مؤسسة حكومية حديثة \r\n التأسيس أُنشئت في أكتوبر 2024، وتهدف إلى تطوير وتعزيز البحث العلمي والابتكار في مجال الذكاء الاصطناعي داخل الصومال. ويسعى المركز إلى ترسيخ مكانة الصومال كمركز إقليمي رائد في مجال الذكاء الاصطناعي المسؤول والأخلاقي، من خلال دعم التعليم والبحث العلمي والتطبيقات الصناعية المرتبطة بالتقنيات الذكية.\r\nويعمل المركز على تشجيع تطوير حلول مبتكرة تعتمد على الذكاء الاصطناعي للمساهمة في مواجهة التحديات الوطنية وتحقيق التنمية الاجتماعية والاقتصادية، إضافة إلى دعم بناء القدرات الوطنية في المجالات الرقمية والتكنولوجية الحديثة، وتعزيز التعاون بين المؤسسات الحكومية والجامعات والقطاع الخاص في مجالات التحول الرقمي والابتكار التقني.',NULL,'https://snaic.gov.so/',5,10,1,'2026-06-04 14:43:14','2026-06-04 14:43:14'),(62,'Photos_ScientificResearchInnovationCenters/qzwVZjquCcQwzskr4NL2Id5VJM8hNMVjZyf8izzb.jpg','مركز البحوث والتنمية الصومالي',NULL,'يُعد مركز البحوث والتنمية الصومالي من المؤسسات العلمية التي تهدف إلى دعم الدراسات والبحوث المتعلقة بالتنمية والابتكار وبناء القدرات العلمية في الصومال، مع التركيز على قضايا التعليم والتنمية المستدامة والتكنولوجيا.',NULL,'https://www.srdi.so/',5,10,1,'2026-06-04 14:44:24','2026-06-04 14:44:24'),(63,'Photos_ScientificResearchInnovationCenters/Ri241y5zpwh6SwkAHg7Q9gcmbkR2Ry4ltFPSIOE6.png','مركز حديد للابتكار',NULL,'يُعدّ مركز حديد للابتكارمبادرة حديثة أُطلقت في الصومال خلال يناير 2024 بهدف تمكين الشباب الصومالي من خلال الابتكار والتكنولوجيا وريادة الأعمال. وقد أسسه مجموعة من رواد الأعمال الصوماليين سعياً إلى تعزيز المهارات التقنية والإبداعية وربط الشباب بمتطلبات الاقتصاد الرقمي العالمي.\r\nويركز المركز على توفير برامج التدريب والبحث والتوعية في مجالات التكنولوجيا والابتكار الاجتماعي وريادة الأعمال، مع العمل على تطوير بيئة تعليمية حديثة مجهزة بالبنية التحتية والتقنيات المتقدمة.\r\n كما يسعى المركز إلى إعداد كفاءات تقنية قادرة على الاندماج في سوق العمل العالمي والمساهمة في التنمية الاقتصادية والاجتماعية داخل الصومال، إضافة إلى دعم الحلول المبتكرة لمعالجة التحديات المجتمعية والتنموية.',NULL,'https://hadiid.so/hadiid-innovation-center/',5,10,1,'2026-06-04 14:46:01','2026-06-04 14:46:01'),(64,'Photos_ScientificResearchInnovationCenters/pfkkjSG2V6QHaXvL9dm7OFgtLSMPh1yWrZ07OKr3.png','مركز تكنولوجيا الطاقة والطاقات المتجددة',NULL,'يعتبر مركز تكنولوجيا الطاقة والطاقات المتجددة أحد الصروح العلمية في الجامعة التكنولوجية، وهو يهدف إلى المساهمة في دعم النهضة العلمية والتنموية في البلد وذلك من خلال إقامة وانجاز البحوث والمشاريع الريادية في مجال الطاقة المتجددة التي تصب في مصلحة الاقتصاد الوطني وبما يحقق أهداف خطط التنمية، كما يهدف المركز إلى المساهمة في نشر ثقافة استخدام الطاقة المتجددة للحصول على طاقة نظيفة وصديقة للبيئة من خلال التوعية بمدى فائدة منظومات الطاقة الشمسية ومنظومات طاقة الرياح في الحفاظ على البيئة من التلوث.',NULL,'https://www.uotechnology.edu.iq/eretc/',5,11,1,'2026-06-05 10:04:53','2026-06-05 10:04:53'),(65,'Photos_ScientificResearchInnovationCenters/fbswWpTCdhI4nP7U13psUBeqzyK890T07aEnBzPB.png','مركز بحوث الطاقة المتجددة',NULL,'تأسس مركز بحوث الطاقة المتجددة سنة 2012، بموجب موافقة وزارة التعليم العالي والبحث العلمي (العدد ب ت 3/6396 في 19/6/2012) والأمر الجامعي المرقم (7647 في 8/7/2012) والصادر عن جامعة الانبار. ويتكون المركز من ثلاثة أقسام هندسية رئيسية وهي: قسم تكنولوجيا الطاقة المتجددة، قسم أنظمة السيطرة والاتصالات، وقسم أنظمة القدرة الكهربائية. ومنذ إنشائه حددت للمركز مجموعة من الأهداف والتي تمثل الرؤية الأساسية والهدف من وجوده وهي على النحو التالي:\r\n* رفد مشاريع توليد الطاقة بالبحوث والدراسات التطبيقية وبناء النماذج العملية في مجال الطاقة التقليدية والمتجددة بمختلف انواعها.\r\n* الاشتراك الفعلي والإشراف الفني والاستشاري في تنفيذ المشاريع العملية الخاصة بتوليد الطاقة.\r\n* التواصل العلمي مع المراكز البحثية المحلية والدولية خدمة للعمل البحثي بمجال تخصصات المركز.',NULL,'https://rercenter.uoanbar.edu.iq/',5,11,1,'2026-06-05 10:05:50','2026-06-05 10:05:50'),(66,'Photos_ScientificResearchInnovationCenters/Phupqcb3MUVViYYfWUK1UGF9wETDe6TPxQLrxXMU.png','مركز ابحاث البيئة والطاقة المتجددة',NULL,'تأسس مركز كربلاء للدراسات والبحوث في العام 2013م، وهو من المؤسسات العلمية الرائدة في العتبة الحسينية المقدسة.\r\n    وجاءت فكرة تأسيسه من قبل الأمانة العامة للعتبة الحسينية ولفيف من السادة الأكاديميين في مدينة كربلاء المقدسة.',NULL,'https://www.c-karbala.com/',5,11,1,'2026-06-05 10:06:36','2026-06-05 10:06:36'),(67,'Photos_ScientificResearchInnovationCenters/QY2bSrfToU6G6TEDXjfl90JreuASzaceardZ2yMv.png','مركز بحوث النهرين للطاقة المتجددة',NULL,'ُسس مركز الطاقة المتجددة في جامعة النهرين ليكون مؤسسة أكاديمية وبحثية متخصصة في مجال الطاقات البديلة، ويُعد مرجعًا علميًا في تطوير وتطبيق تقنيات الطاقة النظيفة والمستدامة ويتضمن المركز ثلاث اقسام رئيسية هي:\r\nقسم طاقة الكتلة الحيوية  \r\n قسم طاقة البحوث الشمسية\r\nقسم طاقة الرياح',NULL,'https://ner.c.nahrainuniv.edu.iq/',5,11,1,'2026-06-05 10:07:29','2026-06-05 10:07:29'),(68,'Photos_ScientificResearchInnovationCenters/9tcABWyZsRjJiGODFhuPqQ2STLdqAVj3JAugHyFO.png','مركز البحث والتاهيل المعلوماتي',NULL,'تعد تقنيات المعلومات عاملا رئيسا في تشكيل مستقبل دول العالم المعاصر واحد اهم ركائز التطور والتقدم العلمي ونقل المجتمعات النامية الى مجتمعات متقدمة.\r\nمن هذا المنطلق فان جامعة الكوفة تولي مجال تقنيات المعلومات اهتماما ودعما كبيرا. تأسس مركز الحاسبة الالكترونية في عام 1989م واستمر في عطائه ورفده للجامعة بكافة الخدمات الالكترونية لمدة اكثر من عقدين من الزمان لتتوج جهود الجامعة بتأسيس مركز البحث والتأهيل المعلوماتي في عام 2010م الذي ضم خدمات مركز الحاسبة الالكترونية ضمن عمله واضاف البعد الاكاديمي اليه، ليساهم في دعم مسار الجامعة المتصاعد في خدمة الطالب والمجتمع.\r\nتاريخ التأسيس:\r\nاستحصلت موافقة وزارة التعليم العالي والبحث العلمي بتأسيس مركز البحث والتأهيل المعلوماتي وفقا لكتاب دائرة البحث والتطوير في الوزارة ذي العدد ب ت /580 والمؤرخ في 24 كانون الثاني 2010.',NULL,'https://itrdc.uokufa.edu.iq/',5,11,1,'2026-06-05 10:08:27','2026-06-05 10:08:27'),(69,'Photos_ScientificResearchInnovationCenters/C8i6HNPvhlxlRg67tv9Ez0Quqd8kPIaZTarudboQ.png','مركز ابحاث النانو تكنولوجي والمواد المتقدمة',NULL,'يُعد مركز أبحاث النانو تكنولوجي والمواد المتقدمة أحد المراكز البحثية المتخصصة داخل الجامعة التكنولوجية في بغداد، ويهتم بإجراء البحوث التطبيقية في مجالات تقنية النانو، وعلوم المواد المتقدمة، والليزر، والتطبيقات الهندسية الحديثة.\r\nتم تأسيس المركز بشكل رسمي عام2009 ضمن هيكل الجامعة التكنولوجية.',NULL,'https://uotechnology.edu.iq/NTRC/',5,11,1,'2026-06-05 10:10:31','2026-06-05 10:10:31'),(70,'Photos_ScientificResearchInnovationCenters/zZrXUjYv0rlYmi1gOL7XAN0gBHuhzgK2KJh8TZFW.png','مركز أبحاث الطاقة المستدامة','Sustainable Energy Research Center','تأسس مركز أبحاث الطاقة المستدامة في أغسطس 2017، ويُعنى بإجراء البحوث والدراسات في المجالات المرتبطة بالطاقة المستدامة، بما في ذلك إنتاج الطاقة، ومصادر الطاقة المتجددة، وسياسات الطاقة، وكفاءة الطاقة وإدارتها، وتحويل الطاقة. كما يعمل المركز كحلقة وصل بين الباحثين في مختلف التخصصات المتعلقة بالطاقة المستدامة والقطاع الصناعي، بما يسهم في تعزيز التعاون بين البحث العلمي والتطبيقات العملية.',NULL,'https://www.squ.edu.om/',5,12,1,'2026-06-05 10:16:32','2026-06-05 10:16:32'),(71,'Photos_ScientificResearchInnovationCenters/AtrjS6EmrBrbbvwKqk17TyXHCN1K5zCyLTsVIl1v.jpg','مركز الابتكار ونقل التكنولوجيا والاستشارات','Center for Innovation, Technology Transfer and Consulting','يهدف مركز الابتكار ونقل التكنولوجيا والاستشارات إلى تعزيز مكانة الجامعة العربية المفتوحة كجامعة رائدة في مجالات الابتكار ​والاستدامة البيئية وريادة الأعمال من خلال نقل التكنولوجيا وتطوير الأبحاث إلى حلول قابلة للتطبيق. يعتمد المركز على تعزيز القدرات الابتكارية وتنمية المهارات العملية للطلبة وأعضاء هيئة التدريس والباحثين والمجتمع، بالإضافة إلى دعم ريادة الأعمال وتحويل الابتكارات إلى مشاريع ذات جدوى اقتصادية تخدم السوق المحلي والإقليمي. وتوفير منصة لنقل الخبرات الاكاديمية لقطاع الاعمال والمجتمع من خلال تقديم الاستشارات.',NULL,'https://www.aou.edu.om/',5,12,1,'2026-06-05 10:17:22','2026-06-09 11:33:06'),(72,'Photos_ScientificResearchInnovationCenters/LhRi0rA10081C2AjroQJwt4uzeYVHEMFxE8n0XvT.png','أكاديمية الابتكار الصناعي','Industrial Innovation Academy','تعمل أكاديمية الابتكار الصناعي على تطوير وتنفيذ برامج مبتكرة تسهم في تعزيز نسبة المحتوى المحلي والابتكار الصناعي وبناء القدرات الوطنية. تعمل هذه البرامج من خلال تقديم خدمات استشارية وإعداد الدراسات والبحوث والخطط لعددٍ من القطاعات الاقتصادية بما يُسهم في تطويرها، وتحليل سلاسل القيمة لهذه القطاعات وإيجاد الفرص الاستثمارية المرتبطة بها، والعمل على تطويرها لتصبح ذات قيمة مضافة، إضافة إلى تدريب وتأهيل القدرات الوطنية، وتبني تقنيات الأتمتة والثورة الصناعية الرابعة ضمن سلاسل القيمة المرتبطة بها.',NULL,'https://iia.om/',5,12,1,'2026-06-05 10:18:24','2026-06-10 11:47:51'),(73,'Photos_ScientificResearchInnovationCenters/1buy9hck6Q6VTtx8tHObNsTjnj8ztRLPX9ITJgTo.png','مركز البحوث في علوم البيئة والتكنولوجيا','Environmental Science  & Technology Center','يُعتبرّ مركز البحوث في علوم البيئة والتكنولوجيا، بكلية الهندسة بالجامعة الوطنية للعلوم والتكنولوجيا في سلطنة عُمان، مركزًا رياديًا في مجال البحث العلمي والاستشارات المتقدمة، مع تركيز خاص على دراسات النفايات وتطبيقات تقنية النانو ضمن الأنظمة البيئية.\r\nسنة التأسيس: 2018',NULL,'https://nu.edu.om/research/environmental-science-technology-center/',5,12,1,'2026-06-05 10:26:51','2026-06-05 10:26:51'),(74,'Photos_ScientificResearchInnovationCenters/ucjjksQGoFdKE2adDCm0Puyyfwg4b8ASxTz7UNRD.png','مركز أبحاث تحلية المياه للشرق الأوسط',NULL,'مركز أبحاث تحلية المياه للشرق الأوسط مركز هو إقليمي متخصص في أبحاث تحلية المياه والتقنيات البيئية وإدارة الموارد المائية المستدامة.\r\nأنشئ المركز عام 1996 ضمن مبادرة السلام في الشرق الأوسط كمنصة علمية لتعزيز التعاون الإقليمي في قضايا المياه. تم دعمه من قبل دول عدة، منها عُمان، الولايات المتحدة، اليابان، والاتحاد الأوروبي. هدفه الأساسي كان بناء الثقة بين بلدان المنطقة من خلال مشاريع علمية مشتركة ذات منفعة إنسانية.',NULL,'https://www.medrc.org/',5,12,1,'2026-06-05 10:27:51','2026-06-05 10:27:51'),(75,'Photos_ScientificResearchInnovationCenters/UjBdy5aAfYqIO9FodPfhSSBtVziDPawXHL829Le4.jpg','أكاديمية فلسطين للعلوم والتكنولوجيا','Palestine Academy for Science and Technology','أنشئت المؤسسة بقرار رئاسي وفق القرار رقم 114 في عام 1997 والقرار رقم 13 في عام 2004، لتكون مؤسسة وطنية مستقلة ذاتية الإدارة، وتُعنى أكاديمية فلسطين للعلوم والتكنولوجيا بتحفيز سير العلوم والتقدم التكنولوجي والابتكار والإبداع في فلسطين، كما وتُعنى بحسن توظيف هذه المجالات نحو التنمية الاقتصادية والاجتماعية والإنسانية في المجتمع الفلسطيني.',NULL,'https://www.palast.ps/ar',5,13,1,'2026-06-05 10:28:58','2026-06-05 10:32:22'),(76,'Photos_ScientificResearchInnovationCenters/anrCX4JurOVD1BomnJDIToP4pVCBD93auwoFJ9Dv.png','المركز الفلسطيني الكوري للتكنولوجيا الحيوية',NULL,'مركز التكنولوجيا الحيوية للأبحاث هو أحد المراكز البحثية التابعة لعمادة الدراسات العليا والبحث العلمي في جامعة بوليتكنك فلسطين، ولقد بدأ المركز كوحدة بحثية وتدريبية أنشأت عبر صندوق تطوير الجودة / وزارة التربية والتعليم والممول من الاتحاد الأوروبي والبنك الدولي، وتم الافتتاح الرسمي للمركز عام 2009 بعد اكتمال البنية التحتية للمختبرات وذلك تزامناً مع اطلاق برنامج ماجستير التكنولوجيا الحيوية المشترك مع جامعة بيت لحم.',NULL,'https://biotech.ppu.edu/ar',5,13,1,'2026-06-05 10:30:59','2026-06-05 10:30:59'),(77,'Photos_ScientificResearchInnovationCenters/ozqGmoWLkDVNCliBxdEzKDzGs66ndUprdAbX9cKE.png','مركز الابتكار والشراكات الصناعية',NULL,'تم إنشاء \"مركز الابتكار والشراكات الصناعية\" في جامعة بوليتكنك فلسطين كجزء من رؤية الجامعة الاستراتيجية لتعزيز ارتباطها بالمجتمع الصناعي الوطني وخدمته بشكل فعال. يأتي هذا المركز كمحور أساسي للتعاون بين الجامعة والقطاع الصناعي، بهدف تعزيز الابتكار ونقل التكنولوجيا، وتقديم الدعم الفني والاستشاري، وتطوير الأعمال الرقمية والاقتصاد الأخضر.',NULL,'https://ppu.edu/p/ar/administrative-departments/ciip',5,13,1,'2026-06-05 10:33:29','2026-06-05 10:33:29'),(79,'Photos_ScientificResearchInnovationCenters/clBh3M0u8VRM49jcrBT9ie5mCQOmMx04XZJYanl3.png','معهد قطر لبحوث البيئة والطاقة',NULL,'يُعنى معهد قطر لبحوث البيئة والطاقة، التابع لجامعة حمد بن خليفة، بمواجهة التحديات المعقّدة المتعلّقة بالطاقة والمياه والبيئة، مع التركيز بشكل خاص على حالة دولة قطر والمناطق الجافة.\r\nفيعتمد على نهجٍ متعدد التخصصات في تطوير حلول مبتكرة، تعزّز الاستدامة والتكيّف، سعيًا لتحقيق التقدّم في هذه القطاعات عبر تطبيق أحدث الأبحاث وتشجيع التعاون، وضمان مستقبل مستدام وقابل على التكيّف للمنطقة والعالم أجمع.',NULL,'https://www.hbku.edu.qa/en/qeeri',5,14,1,'2026-06-05 10:36:05','2026-06-05 10:36:05'),(80,'Photos_ScientificResearchInnovationCenters/2ZJF8hZHhsppjfIDu2o4OYPTvnspz3iAKGBrkCSH.png','معهد قطر لبحوث الحوسبة',NULL,'يعد معهد قطر لبحوث الحوسبة معهًدا قوميًا للبحوث.\r\n تأسس المعهد عام 2010 بصفته أحد الكيانات التابعة لمؤسسة قطر للتربية والعلوم وتنمية المجتمع، وهي مؤسسة مستقلة غير ربحية تدعم تحول قطر من اقتصاد الكربون إلى الاقتصاد المعرفي.\r\n ويعمل معهد قطر لبحوث الحوسبة تحت مظلة جامعة حمد بن خليفة.',NULL,'https://www.hbku.edu.qa/ar/qcri',5,14,1,'2026-06-05 10:36:52','2026-06-05 10:36:52'),(81,'Photos_ScientificResearchInnovationCenters/dFMgVGvbIzrAwQrRlOEQ2qC0Z637ca0UFhIGTIld.png','واحة قطر للعلوم والتكنولوجيا',NULL,'واحة قطر للعلوم والتكنولوجيا هي مجمع بحثي وابتكاري تابع لـمؤسسة قطر، تأسست سنة 2009 وتقع في المدينة التعليمية بالدوحة. \r\nوتُعد مركزًا وطنيًا للبحث والتطوير يهدف إلى دعم الابتكار وريادة الأعمال التكنولوجية وتعزيز التحول نحو اقتصاد قائم على المعرفة في قطر. توفر الواحة بنية تحتية متقدمة ومختبرات متخصصة، وتستقطب شركات عالمية مثل مايكروسوفت وشل وجنرال إلكتريك، مع التركيز على تطوير حلول في مجالات الطاقة والبيئة والصحة وتكنولوجيا المعلومات.',NULL,'https://qstp.qa/joinus/',5,14,1,'2026-06-05 10:37:55','2026-06-05 10:37:55'),(82,'Photos_ScientificResearchInnovationCenters/XseJEKYrKw9McXZgfNEFm38jHhPowQy7IeHEJLvJ.png','مركز قطر للابتكار  وريادة الأعمال',NULL,'يُعد مركز قطر للابتكار وريادة الأعمال مؤسسة قطرية تهدف إلى دعم بيئة الابتكار، وتمكين رواد الأعمال، وتعزيز اقتصاد المعرفة في الدولة. يعمل المركز على تطوير منظومة متكاملة لاحتضان المشاريع الناشئة وتسهيل نقل المعرفة والتقنيات الحديثة إلى السوق المحلي.',NULL,'https://www.qdb.qa/',5,14,1,'2026-06-05 10:38:38','2026-06-05 10:38:38'),(83,'Photos_ScientificResearchInnovationCenters/T6YJeYoMu9Y1BGCMLyhYAjUX1sOVkNa2v9Tsghyp.png','مركز حاضنة الأعمال',NULL,'يركز مركز حاضنة الأعمال في واحة قطر للعلوم والتكنولوجيا على تسريع إنشاء ونمو الشركات الناشئة الواعدة في مجال التكنولوجيا من خلال التأسيس السريع لهذه الشركات في المنطقة الحرة بواحة قطر للعلوم والتكنولوجيا، وتوفير مساحة العمل المشترك التعاوني، وتسهيل الأعمال وخدمات الدعم التي تشمل الوصول إلى شبكة من المرشدين، وبرامج التمويل، ومرافق التدريب والنمذجة الأولية.',NULL,'https://qstp.qa/ar/incubation-center',5,14,1,'2026-06-05 10:39:27','2026-06-05 10:39:27'),(84,'Photos_ScientificResearchInnovationCenters/pOF9RKw2lbZO9rzgInxGF2aSHttbuX5WcMfaThiV.png','مركز قطر للابتكارات في التنقل',NULL,'هو مركز وطني للبحث والتطوير والابتكار، تأسس سنة 2009 بهدف تطوير حلول التنقل الذكي والمدن الذكية والأنظمة الرقمية المتقدمة في دولة قطر. \r\nمن أبرز مجالات عمله:\r\nأنظمة النقل الذكي \r\nالمدن الذكية \r\nالذكاء الاصطناعي وإنترنت الأشياء \r\nإدارة المواقف الذكية \r\nتحليل البيانات الجغرافية \r\nحلول السلامة والتنقل الحضري \r\nومن أشهر مشاريعه:\r\nتطبيق «وين» للمواصلات والمواقف \r\nأنظمة إدارة مواقف السيارات الذكية \r\nحلول مراقبة الحركة المرورية والتنقل الذكي في الفعاليات الكبرى مثل كأس العالم 2022 وكأس العرب.',NULL,'https://qmic.com/',5,14,1,'2026-06-05 10:40:42','2026-06-05 10:40:42'),(85,'Photos_ScientificResearchInnovationCenters/diCcWSaVG3RiZ3v95gwFgL0tYuqj9yhpbMfxioja.jpg','مركز المواد المتقدمة',NULL,'هو مركز بحثي تابع لـ جامعة قطر، تأسس سنة 2002 بهدف تطوير الأبحاث التطبيقية في علوم وهندسة المواد المتقدمة.\r\nيعمل المركز تحت إشراف مكتب نائب رئيس الجامعة للبحث والدراسات العليا، ويُعتبر من أهم مراكز البحث العلمي في قطر في مجالات المواد الحديثة والتقنيات الصناعية. \r\nمجالات البحث الرئيسية\r\nتقنية النانو \r\nالمواد المستدامة \r\nالتآكل وحماية المعادن \r\nمواد البوليمر \r\nمواد البناء المتقدمة \r\nالطاقة المتجددة \r\nالاختبارات غير الائتلافية \r\nمعالجة وتحلية المياه',NULL,'https://www.qu.edu.qa/ar/research/cam/',5,14,1,'2026-06-05 10:41:59','2026-06-05 10:41:59'),(86,'Photos_ScientificResearchInnovationCenters/xY9mUWlGkuQLTtIomcgeMSeJNTVHgBkPkmW54pVZ.png','المركز  العلمي','TSCK','تأسس المركز العلمي في أبريل 2000 كمبادرة من سمو الأمير الراحل الشيخ جابر الأحمد الجابر الصباح (رحمه الله)، الذي آمن بأهمية نشر العلوم وتحفيز الأجيال على الابتكار. وقد أوكلت مؤسسة الكويت للتقدم العلمي مهمة إنشاء مركز علمي تفاعلي يجمع بين التعليم والترفيه، ويقدم العلوم للجمهور بطريقة ممتعة وهادفة.\r\nمنذ افتتاحه، استقبل المركز أكثر من 11 مليون زائر من داخل الكويت وخارجها. من خلال المعارض التفاعلية، والبرامج التعليمية، والتجارب الغامرة، يواصل المركز العلمي إشعال شرارة الفضول ونشر الثقافة العلمية وتعزيز فهمنا للعالم من حولنا.',NULL,'https://tsck.org.kw/',5,15,1,'2026-06-05 10:42:56','2026-07-01 07:48:48'),(87,'Photos_ScientificResearchInnovationCenters/ii6t4o6Dq7rGHa1d6LYmzcKWZWnOzNvrUmnYYUHw.jpg','مركز صباح الأحمد للموهبة والإبداع','sacgc','مركز صباح الأحمد للموهبة والإبداع هو مؤسسة كويتية تعنى باكتشاف ودعم الموهوبين والمبدعين في مجالات العلوم والتكنولوجيا والفنون. يُعد أحد مبادرات مؤسسة الكويت للتقدم العلمي، ويهدف إلى تنمية رأس المال البشري الوطني عبر برامج تأهيلية ومشاريع ابتكارية.\r\nوتأسس سنة 2010.',NULL,'https://sacgc.org/ar/',5,15,1,'2026-06-05 10:44:17','2026-06-23 09:52:25'),(90,'Photos_ScientificResearchInnovationCenters/wVTznibGZzOYRQxLJVlZdWGhgb1nKg5PWRjPXLkJ.png','بيريتك',NULL,'بيريتك\r\nهي منظمة لبنانية رائدة في دعم ريادة الأعمال والابتكار، تتخذ من بيروت مقرًا لها.\r\n تأسست لتشجيع تطوير المشاريع الناشئة في مجالات التكنولوجيا والاقتصاد الرقمي، وتعدّ حاضنة ومسرّعة أعمال مركزية في النظام البيئي اللبناني للابتكار.\r\nسنة التأسيس: 2002',NULL,'https://berytech.org/',5,16,1,'2026-06-05 10:49:17','2026-06-05 10:49:17'),(91,'Photos_ScientificResearchInnovationCenters/oWhbmAEBAyE9f1F00JMtkk8iQ7kyOlVh4VdNR4tK.png','المجلس الوطني للبحوث العلمية','CNRS-L','المجلس الوطني للبحوث العلمية هو هيئة حكومية لبنانية تُعنى بتخطيط وتمويل وتنسيق البحث العلمي في لبنان. يُعدّ المرجع الوطني الأساسي في وضع السياسات البحثية وتطوير القدرات العلمية، ويعمل على تعزيز الابتكار وربط البحث بالقطاعات الاقتصادية والاجتماعية.\r\nتاريخ التأسيس: 1962',NULL,'https://cnrs.edu.lb/',5,16,1,'2026-06-05 10:50:36','2026-06-05 10:50:36'),(92,'Photos_ScientificResearchInnovationCenters/TMRAWbZyJj5ZIuHvFtcnxBfY2BVJbLnNuEdL1usB.png','اللجنة اللبنانية للطاقة الذرية   المركز الوطني للبحوث العلمية',NULL,'اللجنة اللبنانية للطاقة الذرية تأسست سنة 1996 تحت إشراف المجلس الوطني للبحوث العلمية وبدعم من الوكالة الدولية للطاقة الذرية، وتُعد الهيئة الوطنية المختصة بالاستخدام السلمي للطاقة والتكنولوجيا النووية في لبنان، حيث تعمل على تطوير السلامة الإشعاعية والحماية النووية ودعم التطبيقات العلمية والتكنولوجية للطاقة الذرية في مجالات الصحة، والبيئة، والزراعة، والصناعة.',NULL,'https://cnrs.edu.lb/lebanese-atomic-energy-commission/',5,16,1,'2026-06-05 10:52:18','2026-06-05 10:52:18'),(93,'Photos_ScientificResearchInnovationCenters/SZmHmxJyqNUrO6TrRvkLLpTFQrA9TRGQxCFoSXWI.jpg','المركز الوطني للاستشعار عن بعد',NULL,'المركز الوطني للاستشعار عن بعد تأسس سنة 1995، وهو الهيئة الوطنية اللبنانية المتخصصة في بيانات الأقمار الصناعية والتقنيات الجغرافية المكانية، ويعمل تحت إشراف المجلس الوطني للبحوث العلمية. يختص المركز بتطوير وتحليل بيانات رصد الأرض ونظم المعلومات الجغرافية لدعم إدارة الموارد الطبيعية والتخطيط العمراني والزراعة والبيئة والتنمية المستدامة، كما يُعد مركزًا وطنيًا وإقليميًا للبحث والابتكار في مجالات الاستشعار عن بعد والتكنولوجيا الجغرافية.',NULL,'https://cnrs.edu.lb/national-center-for-remote-sensing/',5,16,1,'2026-06-05 11:09:05','2026-06-05 11:09:05'),(94,'Photos_ScientificResearchInnovationCenters/r6GysfxburpjWwJt1uIaqjdjwOPNsWG2dGgmLlU8.png','المركز الليبي للمنظومات الإلكترونية والبرمجيات وبحوث الطيران',NULL,'تم تأسيس المركز الليبي للمنظومات الإلكترونية والبرمجيات وبحوث الطيران بموجب قرار رئاسة الوزراء رقم (234) لسنة 2012م ومقره مدينة طرابلس، وذلك بضم أربع مراكز بحثية كما جاء فى القرار وهي مركز المحاكة والواقع الافتراضي ومركز بحوث الضوئيات وتطبيقات الليزر ومركز بحوث البرمجيات ومركز بحوث الطيران. ويهــدف هذا المركز إلى تحقيق نهضة تقنية وعلمية متميزة وتطوير البحث العلمي في مجـال علوم الحاسب الآلي والمنظومات الإلكترونية وتطبيقاتها والحصول على درجة عالية من الجودة حسب المعايير الدولية، كما يساهم في التنمية البشرية للأكاديميين ورواد البحث العلمي من خلال العمل على بناء شراكات محلية ودولية وتبادل الخبرات ونقل المعرفة والذي سينعكس بدوره على الإيفاء باحتياجات التنمية الاقتصادية المستدامة للدولة الليبية.',NULL,'https://epc.ly/',5,17,1,'2026-06-05 11:42:09','2026-06-05 11:42:09'),(95,'Photos_ScientificResearchInnovationCenters/oVYDLJdjZim2S5P0zTNbtaP4xuicDJwxmmdZYALg.png','مركز بحوث الطاقة الشمسية','csers','تأسس مركز دراسات الطاقة الشمسية بموجب القرار الصادر عن اللجنة الشعبية العامة في منتصف عام 1978.\r\n ولقد حدد ذلك القرار أهداف المركز في نقاط ثلاث، هي:\r\n- القيام بالأبحاث والدراسات العلمية في مجال الطاقة الشمسية.\r\n- وضع واقتراح الخطط الكفيلة بتحقيق الاستغلال الموسع للطاقة الشمسية.\r\n- نشر الوعي العلمي في مجال الطاقة الشمسية.',NULL,'https://csers.ly/ar/about-us',5,17,1,'2026-06-05 11:43:52','2026-06-23 10:54:03'),(96,'Photos_ScientificResearchInnovationCenters/wLAXm9nc8arCqfZi6COYZelCuF3gAG4nloD9y27F.jpg','مركز البحوث النووية','aee','بداء مشروع انشاء المركز سنة 1976 وتم افتتاحه رسميا سنة 1982 ويعتبر مركز البحوث النووية بتاجوراء مركز متقدم للعلوم والتكنولوجيا ومتعدد التخصصات ومن أقدم وأكبر المراكز البحثية في ليبيا، يشمل عشرات من المباني والمنشآت ويشغل مساحة تناهز 300 هكتار.',NULL,'https://aee.gov.ly/tnrc/',5,17,1,'2026-06-05 11:45:00','2026-06-19 14:06:10'),(97,'Photos_ScientificResearchInnovationCenters/4JTFOnV9p9MFfUcLUgxAdEWlg0WLgiyTZbVX1W0B.png','الهيئة الليبية للبحث العلمي','aonsrt','أسست الهيئة سنة 1978م لغرض تنفيذ مخططات الدولة الاستراتيجية من خلال اتّباع منهجية البحث العلمي، وتعبئة جهود العلماء والباحثين والخبراء والمخترعين في مختلف المجالات.\r\nوتقوم الهيئة بمتابعة واجباتها المتمثلة في إدارة ومتابعة البحوث والدراسات في المراكز البحثية التابعة لها ذات الاختصاصات في شتى مجالات البحث العلمي، وذلك من خلال اعتماد الخطط والبرامج البحثية، وتقديم الدعم المادي، وإعداد وتوثيق التقارير العلمية، والمتابعة الدورية للأبحاث والدراسات والتطوير العلمي.',NULL,'https://www.aonsrt.ly/',5,17,1,'2026-06-05 11:46:52','2026-06-19 13:38:09'),(98,'Photos_ScientificResearchInnovationCenters/zpIufSPt7nCwGbkSwMsPciZpwFi7UumJGD8xvdp5.png','مركز البحوث الصناعية',NULL,'يُعد مركز البحوث الصناعية إحدى الجهات التابعة لوزارة الصناعة والمعادن، ويعمل كركيزة أساسية لدعم التطور الصناعي في ليبيا. يركز المركز على تطوير الأبحاث التطبيقية والعملية التي تهدف إلى تحقيق أقصى استفادة من الموارد الطبيعية والخامات المحلية، بما يساهم في تعزيز الإنتاجية وتحقيق التنمية المستدامة.\r\nيقوم المركز بدور محوري في تعزيز القدرات البحثية والتقنية، حيث يقدم مجموعة من الخدمات تشمل إعداد الدراسات الفنية والاقتصادية، وتنفيذ مشاريع بحثية تدعم احتياجات الصناعة، وتقديم الاستشارات الفنية للمؤسسات العامة والخاصة. كما يسهم المركز في تحسين طرق الإنتاج، وتطوير المنتجات الصناعية باستخدام التقنيات الحديثة، فضلاً عن تحسين كفاءة العمليات وتقليل التكاليف.',NULL,'https://irc.ly/',5,17,1,'2026-06-05 11:51:08','2026-06-05 11:51:08'),(99,'Photos_ScientificResearchInnovationCenters/HMlTnoYmPUNlkXnOWr4oy6SMata3VGgtx817ldrI.png','مركز الطاقات المتجددة',NULL,'مركز الطاقات المتجددة هو أحد الجهات التابعة لوزارة الصناعة والمعادن في ليبيا، ويُعد مؤسسة بحثية استشارية وتدريبية رائدة في مجال الطاقات المتجددة وكفاءة الطاقة. يركز المركز على البحث والتطوير في مجالات الطاقات المتجددة، ويعمل على تطبيق تقنيات الطاقة المستدامة بما يتناسب مع البيئة المحلية. يُعتبر المركز منصة هامة للابتكار والبحث العلمي، حيث يسهم في توطين تقنيات الطاقات المتجددة وتطويرها لتلبية احتياجات السوق الليبي والمجتمع، وتحقيق أهداف التنمية المستدامة.',NULL,'http://rec.misuratau.edu.ly/',5,17,1,'2026-06-05 11:52:08','2026-06-05 11:52:08'),(100,'Photos_ScientificResearchInnovationCenters/3bhrA9Qf1F9PeneySP7LOhP2hbzDx58hjifFoZVj.png','أكاديمية البحث العلمي والتكنولوجيا',NULL,'أكاديمية البحث العلمي والتكنولوجيا هي الأكاديمية الوطنية لمصر في مجال العلوم والتكنولوجيا والابتكار وبيت الخبرة ووعاء الفكر الوطني المعني بالتخطيط الاستراتيجي وإعداد خرائط الطريق التكنولوجية والدراسات المستقبلية وتقديم الاستشارات العلمية المجردة للحكومة ولصناع القرار بشأن القضايا المتعلقة بالعلوم والتكنولوجيا في مصر والعالم. وهي الداعم الحكومي للابتكار وريادة الأعمال والحاضنات التكنولوجية والتسويق التكنولوجي وحماية الملكية الفكرية.',NULL,'http://www.asrt.sci.eg/',5,18,1,'2026-06-05 11:53:46','2026-06-05 11:53:46'),(101,'Photos_ScientificResearchInnovationCenters/kceE7YNcI7HjQypuRRcGmNDl6m3JIkxJOL2aButn.jpg','مدينة الأبحاث العلمية والتطبيقات التكنولوجية','SRTA-City','تُعد مدينة الأبحاث العلمية والتطبيقات التكنولوجية واحدة من أبرز المؤسسات البحثية في مصر والمنطقة العربية. تأسست لتكون مركزاً للتميز والإبداع، حيث تعمل كحلقة وصل حيوية بين البحث الأكاديمي والاحتياجات الصناعية. تضم المدينة مجموعة من المعاهد البحثية المتخصصة والمراكز التكنولوجية المجهزة بأحدث التقنيات، مما يجعلها بيئة خصبة لإنتاج المعرفة وتحويلها إلى حلول تطبيقية تخدم الاقتصاد الوطني.',NULL,'https://srtacity.sci.eg/ar',5,18,1,'2026-06-05 11:54:35','2026-06-05 11:54:35'),(102,'Photos_ScientificResearchInnovationCenters/E1jfMg0EmNUp766q83LbzRD9cHpHFLYsAkmddwfa.jpg','المركز القومي للبحوث','nrc.','تأسس المركز القومي للبحوث كمنظمة عامة مستقلة في عام 1956 ، بهدف \"تعزيز البحث العلمي الأساسي والتطبيقي، لا سيما في الصناعة والزراعة والصحة العامة وقطاعات الاقتصاد الوطني الأخرى\". وهي أكبر المؤسسات التابعة لوزارة البحث العلمي وتوظف حوالي 60٪ من مجموع العلماء العاملين في هذه المؤسسات.',NULL,'https://www.nrc.sci.eg/',5,18,1,'2026-06-05 11:55:28','2026-06-19 14:03:39'),(103,'Photos_ScientificResearchInnovationCenters/mSMw4HjBTOsbmWlGfwy9cXu3gK3y19L5g97VMPUv.png','مركز بحوث الإلكترونيات',NULL,'تأسس بالقرار الجمهوري رقم 38 لسنة 1989 وهو احدى المعاهد المتخصصة التابعة لوزارة البحث العلمي. تشمل أنشطة الابحاث النظرية والتطبيقية في مجالات الاليكترونيات، والاتصالات، وأجهزة الحاسوب، والمعلوماتية. وتقديم خدمات الاستشارات العلمية للقطاع الصناعي من أجل الانتاج والخدمات. ويتكون حاليا من سبعة أقسام تضم أكثر من مائتي عضو باحث ليكون واحد من أكبر كيانات البحث العلمي في مصر.',NULL,'https://eri.sci.eg/ar/about-us',5,18,1,'2026-06-05 11:57:20','2026-06-05 11:57:20'),(104,'Photos_ScientificResearchInnovationCenters/chjfg7o1VkU57wzuLkrjvthdTwVumfZzyiZ6fVJs.png','مركز تحديث الصناعة','INDUSTRIAL MODERNISATION CENTER','مركز تحديث الصناعة هو كيان تم تأسيسه في ديسمبر 2000 بقرار جمهوري، بدعم من الاتحاد الأوروبي والحكومة المصرية، بهدف تعزيز الصناعة المصرية وتحقيق نمو اقتصادي مستدام. يعمل المركز على تقديم الدعم لمختلف المنشآت الصناعية في11 قطاعًا متخصصًا، حيث يقوم بدراسة احتياجاتها ووضع استراتيجيات لتحسين الإنتاجية وزيادة التنافسية.',NULL,'https://www.imc-egypt.org/ar',5,18,1,'2026-06-05 11:59:08','2026-06-19 14:00:54'),(105,'Photos_ScientificResearchInnovationCenters/8vdtOT2iMAL0nCsIXzwp0r4fiUuDsOK8Q97XFIJL.png','هيئة الطاقة الذرية','eaea','تأسست سنة 1955، وهي المؤسسة الوطنية المختصة بالأبحاث النووية والتكنولوجيا الذرية السلمية، وتعمل في مجالات الطاقة النووية، التطبيقات الصناعية والطبية، والفيزياء الإشعاعية.',NULL,'http://www.eaea.org.eg/',5,18,1,'2026-06-05 11:59:57','2026-06-19 13:36:10'),(107,'Photos_ScientificResearchInnovationCenters/g754pQFAyMDAePTr02oaAdcGxXxWOPqJuuWBKqeP.jpg','مركز الطاقة المتجددة والتصميم الالكتروني','center-of-renewable-energy-and-electronic-projects','مركز الطاقة المتجددة والتصميم الالكتروني التابع لجامعة العلوم والتكنولوجيا كيان علمي بحثي تطبيقي تأسس في عام 1996 كأول مركز للطاقة الشمسية في الجمهورية اليمنية على يد نخبة من المتخصصين المتميزين في هذا المجال ومن ثم أسس مركز التدريب والتصميم الالكتروني ليعمل على تدريب الكوادر الهندسية في مجال التصاميم الالكترونية والمجالات الفنية الهندسية المختلفة. في عام 2012 تم دمج المركزين كمركز واحد باسم مركز الطاقة المتجددة والتصميم الالكتروني لتحقيق التكامل بين المركزين.',NULL,'https://ust.edu/center-of-renewable-energy-and-electronic-projects/',5,21,1,'2026-06-05 12:03:48','2026-06-19 14:17:10'),(109,'Photos_ScientificResearchInnovationCenters/0aOY5Dh7PhTGW3byT2pMS978NrAGWeT5oJcWe7hX.jpg','مركز العلوم والتكنولوجيا','Science and Technology Center','تعتبر مراكز العلوم والتكنولوجيا من أهم المراكز العلمية التي تحتويها جامعات العالم المتقدمة. مركز العلوم والتكنولوجيا (جامعة عدن) يشكل حلقة وصل علمية تكنولوجية  فعالة بين الجامعة والمجتمع . فهو المنسق الوحيد - فيما يخص مجالات فرقه البحثية-  بين جامعة عدن والجامعات والمراكز والمؤسسات العلمية المناظرة المحلية والعربية والأجنبية وكذا المنظمات الداعمة. مركز العلوم والتكنولوجيا يعمل من جهة على تعريف المجتمع بالقدرات البحثية والخبرات العلمية لدى أعضاء هيئة التدريس بالجامعة خاصة منهم أعضاء الفرق البحثية بالمركز لكي يستطيع المجتمع بمؤسساته الإنتاجية والخدمية الاستفادة من تلك الكفاءات والخبرات. ومن جهة أخرى  يقوم المركز بالنزول الميداني للمؤسسات الإنتاجية والخدمية والتعرف عن قرب على التكنولوجيات المتبعة فيها ومواطن النقص ومواطن الحاجة للبحث العلمي لدى تلك المؤسسات، وذلك لغرض توجيه الدراسات والبحوث العلمية بما يخدم حاجة المجتمع حتى يكون لتلك الدراسات والبحوث التطبيق العملي والمردود السريع والملموس وبما يلبي حاجة المجتمع . فدور المركز دور تنويري تنسيقي بحثي خدماتي.',NULL,'http://www.stcau-ti.net/',5,21,1,'2026-06-05 12:07:02','2026-06-19 14:23:35'),(111,'Photos_ScientificResearchInnovationCenters/F9cfsjjHXmM8bYZGtTpXwEkb6RDLh00STHOhtDDM.jpg','الوكالة الوطنية للبحث العلمي والابتكار','anrsi','تأسست سنة 2021، وهي الهيئة الوطنية المكلفة بتطوير البحث العلمي والابتكار في موريتانيا، وتعمل على دعم المشاريع البحثية والتكنولوجية وربط البحث العلمي بالتنمية الاقتصادية والصناعية.',NULL,'https://anrsi.mr/expert-anrsi',5,20,1,'2026-06-05 12:10:15','2026-06-19 14:09:38'),(114,'Photos_ScientificResearchInnovationCenters/0JcxFAFfG0rQxskNdMFusPxi6ZvGANH0UIjxywk3.jpg','مركز كوزموس للابتكار و ريادة الأعمال','Kosmos Innovation Center','مركز وطني لدعم الابتكار وريادة الأعمال، أُطلق في موريتانيا سنة 2018 بهدف تمكين الشباب ورواد الأعمال من تطوير مشاريع مبتكرة وقابلة للنمو.\r\n يوفر المركز برامج للتدريب والاحتضان والإرشاد والتمويل الأولي، ويساهم في تعزيز منظومة الشركات الناشئة ودعم التنمية الاقتصادية المستدامة  وفي تمويل أفكار المشاريع الصغيرة في أفريقيا، وخاصةً لرواد الأعمال الشباب في غانا والسنغال وموريتانيا. نحن الآن منظمة رائدة تُحقق تغييرًا إيجابيًا من خلال التمكين والابتكار في موريتانيا.',NULL,'https://kosmosinnovationcenter.com/',5,20,1,'2026-06-05 14:18:58','2026-06-05 14:22:57'),(115,'Photos_ScientificResearchInnovationCenters/f2UEIXtz1kca99rWAEANEN0vlmQ9WF9ljI0WZdc8.png','المعهد الموريتاني للبحث العلمي','imrspc','أنشئ المعهد الموريتاني للبحث العلمي بموجب المرسوم رقم: 74/243 الصادر بتاريخ 31/12/1974 الذي ألغاه وحل محله المرسوم رقم: 088/2004 الصادر بتاريخ 14/10/2004 الذي بموجبه أصبح اسمه المعهد الموريتاني للبحث والتكوين في مجال التراث. وهي مؤسسة عمومية ذات طابع إداري علمي ، ثقافي وتقني ومستقلة ماليا وإداريا، خاضعة لوصاية الوزير المكلف بالثقافة. وقد نيطت بالمعهد مهمة النهوض بالبحث العلمي في مختلف ميادين العلوم الإنسانية من مخطوطات وآثار وتراث مروي والقيام بالدراسات والتحقيقات المؤدية إلى معرفة أفضل للتراث الثقافي والعلمي والطبيعي وإثرائه وحمايته وتثمينه ونشره وتشجيع تكوين وتدريب الباحثين الوطنيين والأجانب في مجال العلوم الإنسانية',NULL,'https://www.imrspc.mr/',5,20,1,'2026-06-05 14:31:40','2026-06-09 10:55:34'),(116,'Photos_MinistriesHigherEducationScientificResearch/DSE9VTMq3pKjkk060264JymZ12WinYMszmFiBrek.png','وزارة التعليم العالي والبحث العلمي والابتكار','enssup','وزارة التعليم العالي والبحث العلمي والابتكار هي الجهة الحكومية المكلفة بتطوير التعليم العالي والبحث العلمي والابتكار بالمغرب، وتعمل على تعزيز جودة التكوين الجامعي، ودعم البحث العلمي ونقل التكنولوجيا، وتشجيع التعاون بين الجامعات والقطاع الصناعي لتحقيق التنمية المستدامة والاقتصاد القائم على المعرفة.',NULL,'https://www.enssup.gov.ma/ar',5,19,3,'2026-06-08 08:34:58','2026-06-23 08:44:05'),(117,'Photos_MinistriesHigherEducationScientificResearch/vccB7KS67Ey8G1BGdPb5DpUHa2gh47zBy6ug5ZUC.png','وزارة الصناعة والتجارة','mcinet','وزارة الصناعة والتجارة بالمملكة المغربية هي مؤسسة حكومية أُنشئت سنة 1955، وتتولى إعداد وتنفيذ السياسات العمومية في مجالات الصناعة والتجارة، بما يسهم في تعزيز التنمية الاقتصادية ورفع تنافسية الاقتصاد الوطني. وتضطلع الوزارة بدور محوري في تطوير النسيج الصناعي، ودعم المقاولات، وتشجيع الاستثمار المنتج، وتنمية المبادلات التجارية على المستويين الوطني والدولي. كما تعمل على مواكبة التحول الصناعي والابتكار، وتحسين مناخ الأعمال، وتعزيز اندماج الاقتصاد المغربي في سلاسل القيمة العالمية. ويقع مقرها بمدينة الرباط.',NULL,'https://www.mcinet.gov.ma/',5,19,3,'2026-06-08 08:37:26','2026-06-22 14:45:55'),(118,'Photos_MinistriesHigherEducationScientificResearch/4h3kiS9x68YtTurj2fWdUBJumU7vMYecZwvPAOey.png','وزارة الانتقال الرقمي وإصلاح الإدارة','mmsp','وزارة الانتقال الرقمي وإصلاح الإدارة هي مؤسسة حكومية مغربية تُعنى بقيادة التحول الرقمي للإدارة العمومية وتطوير الخدمات الرقمية الموجهة للمواطنين والمقاولات، إلى جانب تحديث الإدارة العمومية وتحسين جودة الخدمات العمومية. كما تعمل على إعداد وتنفيذ الاستراتيجيات الوطنية في مجال الرقمنة، وتعزيز الحكومة الإلكترونية، وتبسيط المساطر الإدارية، وتطوير الكفاءات الرقمية، بما يساهم في رفع كفاءة الإدارة وتعزيز الشفافية وتحسين مناخ الأعمال.\r\nسنة التأسيس: أُحدثت الوزارة بصيغتها الحالية تحت اسم \"وزارة الانتقال الرقمي وإصلاح الإدارة\" سنة 2021 ضمن الهيكلة الحكومية الجديدة، مع تعزيز اختصاصاتها التنظيمية بموجب المراسيم الصادرة سنة 2023.',NULL,'https://www.mmsp.gov.ma/ar',5,19,3,'2026-06-08 08:42:42','2026-06-22 14:47:47'),(119,'Photos_MinistriesHigherEducationScientificResearch/p59l4wK2Z9sTwM0o0fVbEknJk3b5u3JKWj5Ju0oM.png','وزارة الإدماج الاقتصادي والمقاولة الصغرى والتشغيل والكفاءات','miepeec','وزارة الإدماج الاقتصادي والمقاولة الصغرى والتشغيل والكفاءاتهي مؤسسة حكومية مغربية أُنشئت بصيغتها الحالية سنة 2021، وتُعد من الفاعلين الرئيسيين في دعم سوق الشغل والتنمية الاقتصادية. تضطلع الوزارة بوضع وتنفيذ السياسات المتعلقة بالتشغيل وتنمية الكفاءات والتكوين المهني، مع التركيز على تأهيل الموارد البشرية بما يستجيب لاحتياجات القطاع الصناعي. كما تعمل على إدماج الشباب في سوق العمل، ودعم المقاولات الصغرى والمتوسطة، وتعزيز قابلية التشغيل والابتكار وريادة الأعمال، بما يساهم في رفع تنافسية الاقتصاد الوطني ودعم التنمية الصناعية المستدامة.',NULL,'https://miepeec.gov.ma/',5,19,3,'2026-06-08 08:44:57','2026-06-08 08:50:44'),(120,'Photos_MinistriesHigherEducationScientificResearch/9Wdzfp03gCGQ5AfCWhkX2CcZTVSK2sZ1nNNT6POv.jpg','وزارة الانتقال الطاقي والتنمية المستدامة','mtedd','وزارة الانتقال الطاقي والتنمية المستدامة هي مؤسسة حكومية مغربية أُنشئت بصيغتها الحالية سنة 2021، وتُعد من الفاعلين الرئيسيين في تحقيق التنمية المستدامة وتعزيز الأمن الطاقي بالمملكة. تتولى الوزارة إعداد وتنفيذ السياسات الوطنية في مجالات الطاقة والمعادن والبيئة والتنمية المستدامة، مع التركيز على تطوير الطاقات المتجددة، وتحسين النجاعة الطاقية، وتقليص الاعتماد على الوقود الأحفوري. كما تعمل على حماية البيئة والحد من التلوث، وتشجيع الاستثمار في مشاريع الطاقة النظيفة، ودعم البحث والابتكار في المجال الطاقي، بما يساهم في تحقيق التوازن بين النمو الاقتصادي والمحافظة على الموارد الطبيعية للأجيال القادمة.',NULL,'https://www.mtedd.gov.ma/',5,19,3,'2026-06-08 08:47:14','2026-06-08 08:50:28'),(123,'Photos_MinistriesHigherEducationScientificResearch/KdMNlF5YkW6jOGceBoMa4ruZ34YiR56Z9RiZpkzX.png','وزارة الصناعة والتجارة والتموين','mit','وزارة الصناعة والتجارة والتموين هي الجهة المسؤولة عن تعزيز موقع المنتج الأردني في الأسواق العالمية ودخول الصناعة الأردنية لأسواق جديدة، وتعزيز تنافسية الصناعات الأردنية والقطاعات الخدمية وتحسين انتاجها وتنظيم التجارة الداخلية والخارجية ومراقبتها، بالإضافة في تنظيم قطاع التأمين ، ومن مهامها أيضاً تشجيع القطاعات الصناعية على الأبداع والابتكار، وتوفير التشريعات الجاذبة لبيئة الأعمال، كذلك تتولى الوزارة إدارة المؤسسات الاستهلاكية المدنية في الأردن.',NULL,'http://www.mit.gov.jo/',5,1,3,'2026-06-08 09:34:07','2026-06-08 09:35:48'),(124,'Photos_MinistriesHigherEducationScientificResearch/wGxVVwgdWVM9GwvTa8MCl3DKJiu9DV4fOqJ0uN0p.jpg','وزارة الاقتصاد الرقمي والريادة','modee','تُعدّ وزارة الاقتصاد الرقمي والريادة (سابقًا: وزارة الاتصالات وتكنولوجيا المعلومات) الجهة الحكومية المسؤولة عن وضع السياسات والتشريعات المنظمة لقطاعات تكنولوجيا المعلومات والاتصالات والبريد في الأردن، كما تتولى الإشراف على استكمال وتطوير وإدامة شبكة الحكومة الإلكترونية، ودعم المبادرات الوطنية في مجالات التحول الرقمي والابتكار وريادة الأعمال.\r\nوفي مايو 2019، تم تغيير اسم الوزارة رسميًا إلى «وزارة الاقتصاد الرقمي والريادة»، وذلك بهدف دعم التحول الرقمي في المملكة، وتعزيز تبني مفاهيم الاقتصاد الرقمي، إلى جانب تطوير منظومة ريادة الأعمال والابتكار في الأردن.',NULL,'https://www.modee.gov.jo/',5,1,3,'2026-06-08 09:35:10','2026-06-08 09:35:10'),(125,'Photos_MinistriesHigherEducationScientificResearch/erBDnyPCpeV7bqMcPztGJ4h838xgaP3TpwH408dk.png','وزارة التعليم العالي والبحث العلمي','mohesr','منذ تشييد لبنات اتحاد دولة الإمارات العربية المتحدة في العام 1971 ، حظي التعليم باهتمام القائد المؤسس الشيخ زايد بن سلطان آل نهيان طيب الله ثراه وإخوانه المؤسسين الأوائل، إيماناً ​منهم بأنه الركيزة الأساسية لبناء مجتمع متمكن قادر على مسايرة ركب التقدم، وعلى مدار العقود المنصرمة تمحور اهتمام القيادة الرشيدة للدولة في بناء نظام تعليمي يضاهي مثيلاته في الدول المتقدمة، مسخرة كافة الإمكانات، لتحقيق أجندة الدولة والرؤية الوطنية. وتحقيقاً للرؤى المستقبلية وتطلعات القيادة الحكيمة، بُذلت جهود حثيثة لتطوير التعليم، واعتماد أفضل النظم لتحقيق مخرجات تعليمية عالية الجودة.​\r\n\r\n\r\nولأن الاستثمار في رأس المال البشري هو الهدف الأساس، حرصت دولة الإمارات منذ تأسيس وزارة التربية والتعليم على تهيئة الظروف المواتية لبناء مدرسة إماراتية رائدة في المعايير والشكل والمضمون، تتميز ببيئة تعليمية فائقة الجودة، ومزودة بأعلى أدوات التقنية الحديثة؛ لتخريج أجيال قادرة على استكمال مسيرة تعليمها الجامعي بخطىً واثقة، في مؤسسات التعليم العالي لتواكب متطلبات سوق العمل. وقد عملت الوزارة على توفير منظومة تعلم ذكية ومنصات رقمية، عالية الجودة، بجانب التطوير المستمر في المناهج الدراسية بمعايير تعلم وطنية، وسياسة تقييمية قائمة على القياس من أجل التعلم، وأعلى درجات الجودة لتحاكي أفضل الممارسات العالمية، فضلاً عن توفير مسارات تعليمية متنوعة تدعم قدرات ومهارات الطلبة، وتسهم في تحقيق استراتيجية الدولة لتشجيع ثقافة الإبداع والابتكار من خلال إكساب الطلبة مهارات القرن الحادي والعشرين، وحفزهم على التحلي بالأفكار الجديدة التي تتصل بالواقع، وتستشرف المستقبل للمساهمة في إيجاد الحلول الجذرية المستدامة للقضايا الحيوية، وتحسين القدرة على التنافسية، ودعم الحكومة الذكية؛ سعيًا لمواكبة التطورات العالمية، والنهوض بالتعليم والدفع به إلى آفاق واسعة من التميز والريادة والتنافسية.',NULL,'https://www.mohesr.gov.ae/ar',5,2,3,'2026-06-08 09:36:56','2026-06-29 11:39:41'),(126,'Photos_MinistriesHigherEducationScientificResearch/Hq5x7sIB0qzQINKitwascnKFPJT5Hyj7VDaUR2oP.jpg','وزارة الصناعة والتكنولوجيا المتقدمة','moiat','تُعدّ وزارة الصناعة والتكنولوجيا المتقدمة إحدى الجهات الحكومية الاستراتيجية في الإمارات العربية المتحدة، وقد أُنشئت سنة 2020 بهدف تطوير القطاع الصناعي الوطني وتعزيز مكانة الدولة كمركز عالمي للصناعة المتقدمة والتكنولوجيا والابتكار.\r\nتتولى الوزارة وضع السياسات والاستراتيجيات الخاصة بالصناعة والتكنولوجيا المتقدمة، كما تعمل على دعم التحول الصناعي الرقمي، وتبني تقنيات الثورة الصناعية الرابعة، ورفع تنافسية المنتجات الوطنية، إضافة إلى تعزيز البحث والتطوير والابتكار الصناعي.',NULL,'https://moiat.gov.ae/',5,2,3,'2026-06-08 09:38:06','2026-06-22 14:41:03'),(127,'Photos_MinistriesHigherEducationScientificResearch/VphDZ6cW8x3Vo8C6tJXU2NkQYj4V1qznf5fl1yYW.jpg','وزارة الصناعة   والتجارة','moic','وزارة الصناعة والتجارة هي الجهة الحكومية المسؤولة عن تنظيم وتطوير القطاعين الصناعي والتجاري في مملكة البحرين. أُنشئت بصيغتها الحالية سنة 2022 ضمن إعادة هيكلة الجهاز الحكومي، وتعمل على إعداد وتنفيذ السياسات والاستراتيجيات الرامية إلى تعزيز النمو الاقتصادي المستدام، وتنمية الصناعات الوطنية، ورفع تنافسية القطاع الخاص. كما تضطلع الوزارة بدعم بيئة الأعمال والاستثمار، وتطوير الأنشطة التجارية والصناعية، وتشجيع الابتكار وريادة الأعمال، بما ينسجم مع رؤية البحرين الاقتصادية 2030 ويسهم في تحقيق التنمية الاقتصادية الشاملة.',NULL,'https://www.moic.gov.bh/',5,3,3,'2026-06-08 09:43:49','2026-06-22 14:36:59'),(131,'Photos_MinistriesHigherEducationScientificResearch/C7R35DE8clDx93XS2d1khzOEPJJaQxrBpYYLhTT1.png','وزارة التعليم العالي والبحث العلمي','mes','وزارة التعليم العالي والبحث العلمي في تونس هي مؤسسة حكومية مسؤولة عن تنظيم وتطوير التعليم العالي والبحث العلمي في البلاد، وتشرف على الجامعات ومراكز البحث وتضع السياسات الوطنية للبحث العلمي وتشجع الابتكار وربط الجامعة بالتنمية.\r\n تم إحداثها سنة1987    \r\n بعد إعادة تنظيم قطاع التعليم العالي والبحث العلمي في تونس.',NULL,'http://www.mes.tn/',5,4,3,'2026-06-08 10:29:16','2026-06-08 10:29:16'),(132,'Photos_MinistriesHigherEducationScientificResearch/WMn5D2XktMN3Z1ul7trwAH5qwGQhx6dQFoolEZql.jpg','وزارة الصناعة والمناجم والطاقة','energiemines','وزارة الصناعة والمناجم والطاقة  هي وزارة حكومية في الجمهورية التونسية تُعنى بوضع وتنفيذ السياسات العمومية المتعلقة بقطاعات الصناعة والمناجم والطاقة. وتضطلع بدور محوري في تطوير القطاع الصناعي، وتنظيم واستغلال الموارد المنجمية، وتنمية مصادر الطاقة التقليدية والمتجددة، بما يساهم في دعم النمو الاقتصادي وتعزيز التنافسية الوطنية.\r\nكما تعمل الوزارة على تشجيع الاستثمار الصناعي، ودعم الابتكار والتجديد التكنولوجي في المجالات الإنتاجية، وتعزيز الأمن الطاقي للبلاد، إلى جانب دعم الانتقال نحو الطاقات النظيفة والحد من الاعتماد على المصادر الأحفورية، بما ينسجم مع أهداف التنمية المستدامة.\r\nوتعود جذور هذه الوزارة إلى تطور تدريجي في الهيكلة الحكومية التونسية المرتبطة بقطاعات الصناعة والطاقة والمناجم، حيث تم توحيدها بصيغتها الحالية عبر مراحل تنظيمية مختلفة لمواكبة التحولات الاقتصادية والطاقية في البلاد.',NULL,'https://www.energiemines.gov.tn/',5,4,3,'2026-06-08 10:35:09','2026-06-29 11:46:42'),(133,'Photos_MinistriesHigherEducationScientificResearch/w9sV6ySHyG9Ey5UHiOxouF0jHEbeABbRUhRybKNC.png','وزارة تكنولوجيات الاتصال','mtc','وزارة تكنولوجيات الاتصال هي وزارة حكومية تتولى اقتراح السياسة العامة في مجال تكنولوجيا المعلومات والاتصال والإشراف على تنفيذها، بهدف تعزيز دور هذا القطاع في دعم التنمية الاقتصادية والاجتماعية.\r\nوتعمل الوزارة على وضع الاستراتيجية الوطنية لقطاع تكنولوجيات الاتصال ومتابعة تنفيذها، إلى جانب إعداد البرامج والإجراءات الرامية إلى تطوير هذا القطاع ودعمه. كما تسعى إلى تعزيز البنية التحتية الرقمية، وتحفيز الاستثمار في مجالات التكنولوجيا والابتكار، ودعم التحول الرقمي بما يساهم في رفع تنافسية الاقتصاد الوطني وتحسين جودة الخدمات الرقمية.',NULL,'https://www.mtc.gov.tn/',5,4,3,'2026-06-08 10:37:23','2026-06-29 11:43:40'),(134,'Photos_MinistriesHigherEducationScientificResearch/WsSR1zArhZURvnvzcnA3w60VPH6RWC1VCxHFFxrl.png','وزارة التعليم العالي والبحث العلمي','mesrs','وزارة التعليم العالي والبحث العلمي الجزائرية هي أحد وزارات الحكومة الجزائرية تشرف هذه الوزارة على قطاع التعليم العالي والجامعات والبحث العلمي في الجزائر. استحدثت هذه الوزارة لأول مرة سنة 1970، في بعض الأوقات، كانت مقسمة إلى قطاعين أو تحت وصاية وزير منتدب.',NULL,'https://www.mesrs.dz/ar',5,5,3,'2026-06-08 10:42:47','2026-06-08 10:43:01'),(135,'Photos_MinistriesHigherEducationScientificResearch/H56BbMwxRRoRjlJZMUJq10Fwia7rWMjJmQldplil.jpg','وزارة الصناعة',NULL,'وزارة الصناعة هي الجهة الحكومية المسؤولة عن تطوير القطاع الصناعي في الجزائر، حيث تشرف على إعداد وتنفيذ السياسات الصناعية الوطنية، ودعم الإنتاج المحلي، وتشجيع الاستثمار الصناعي، إلى جانب تطوير المؤسسات الصغيرة والمتوسطة.\r\n\r\nكما تعمل الوزارة على تنويع الاقتصاد الوطني وتقليل الاعتماد على قطاع المحروقات، من خلال تعزيز التصنيع، وتحسين القدرة التنافسية للمؤسسات، ودعم الابتكار والتحديث التكنولوجي داخل القطاع الصناعي.',NULL,'https://www.industrie.gov.dz/',5,5,3,'2026-06-08 11:18:48','2026-06-08 11:18:48'),(136,'Photos_MinistriesHigherEducationScientificResearch/AvNp1plQbb59GFtJnZL6IGQgkpMv0vC3hkqdv2dT.png','وزارة الطاقة والمناجم',NULL,'وزارة الطاقة والمناجم هي وزارة حكومية في الجزائر تُعنى بوضع وتنفيذ السياسات الوطنية في مجالي الطاقة والمناجم. وتشرف على استغلال وتطوير الموارد الطاقية والمعدنية، بما في ذلك المحروقات والكهرباء والغاز والموارد المنجمية، مع العمل على ضمان الأمن الطاقي وتثمين الثروات الطبيعية.\r\nكما تعمل الوزارة على تطوير قطاع الطاقة، ودعم الاستثمارات في مجالات البحث والاستكشاف والإنتاج، وتحسين كفاءة استغلال الموارد المنجمية، إضافة إلى مواكبة التحولات العالمية نحو الطاقات النظيفة وتعزيز الاستدامة الطاقية، بما يخدم التنمية الاقتصادية الوطنية.',NULL,'https://www.energy.gov.dz',5,5,3,'2026-06-08 11:26:57','2026-06-08 11:26:57'),(137,'Photos_MinistriesHigherEducationScientificResearch/TCPkbT4mcYroEWBrMll2uoryYVn0PHpk7Sra8yh1.jpg','وزارة البريد والمواصلات السلكية واللاسلكية',NULL,'وزارة البريد والمواصلات السلكية واللاسلكية هي هيئة وزارية تابعة لحكومة الجزائر تُعنى بتطوير وتنظيم قطاعات البريد والاتصالات السلكية واللاسلكية، والرقمنة. \r\nتمثل المحرك المركزي لسياسات التحول الرقمي الوطني والبنية التحتية للاتصال في البلاد.',NULL,'https://www.mpt.gov.dz/',5,5,3,'2026-06-08 11:27:58','2026-06-08 11:27:58'),(138,'Photos_MinistriesHigherEducationScientificResearch/1ttl1IKJfN2rw6iBIT6KIsgzNKqoJsYECR55wWGI.jpg','وزارة التربية الوطنية والتكوين المهني',NULL,'وزارة التربية الوطنية والتكوين المهني \r\nهي وزارة حكومية في جمهورية جيبوتي تتولى الإشراف على قطاع التربية الوطنية والتكوين المهني، وتُعد الجهة المسؤولة عن وضع وتنفيذ السياسات التعليمية في البلاد.\r\nتعمل الوزارة على تطوير منظومة التعليم الأساسي والثانوي، وتحسين جودة التعليم، وتوسيع فرص الولوج إلى التعليم لجميع الفئات، إضافة إلى الإشراف على برامج التكوين المهني بهدف إعداد وتأهيل الشباب لسوق العمل. كما تسعى إلى مواءمة مخرجات التعليم مع حاجيات التنمية الاقتصادية والاجتماعية، وتعزيز الكفاءات والمهارات المهنية بما يدعم الإدماج المهني والتشغيل.\r\nسنة التأسيس:\r\nأُنشئت الوزارة بصيغتها الحديثة بعد استقلال جيبوتي، حيث تعود بداياتها إلى سنة 1977 مع تأسيس الدولة، مع تطور مستمر في بنيتها واختصاصاتها لاحقاً.',NULL,'http://www.education.gov.dj/',5,6,3,'2026-06-08 12:52:06','2026-06-08 12:52:06'),(139,'Photos_MinistriesHigherEducationScientificResearch/IMNiJRKHXHLlW1fQo3mJA6TtaCTI3tV6S3OMrsb9.jpg','وزارة التعليم العالي والبحث العلمي','.','وزارة التعليم العالي والبحث العلمي هي وزارة حكومية في جمهورية جيبوتي تتولى الإشراف على قطاع التعليم العالي والبحث العلمي، وتعمل على وضع السياسات الوطنية الخاصة بتطوير الجامعات ومؤسسات التعليم العالي، وتحسين جودة التكوين الجامعي، وتعزيز البحث العلمي والابتكار.\r\nكما تسعى الوزارة إلى ربط التعليم العالي بحاجيات التنمية الاقتصادية والاجتماعية، ودعم الكفاءات الوطنية، وتطوير الشراكات الأكاديمية مع المؤسسات الدولية، بما يساهم في رفع مستوى التعليم العالي في البلاد وتعزيز القدرات البحثية.',NULL,'http://www.enseignementsup.gouv.dj/',5,6,3,'2026-06-08 12:52:56','2026-06-23 08:43:50'),(140,'Photos_MinistriesHigherEducationScientificResearch/7GA97jBKrn19e8BLzEqFDrAFU18AMYepMZM5N7NG.jpg','وزارة الاقتصاد والمالية المكلفة بالصناعة والتخطيط','null','تُعد وزارة الاقتصاد والمالية المكلفة بالصناعة والتخطيط إحدى الوزارات السيادية في جمهورية جيبوتي، وتتولى إعداد وتنفيذ السياسات الاقتصادية والمالية والصناعية للدولة، إلى جانب الإشراف على التخطيط التنموي وإدارة الموارد المالية العامة. كما تضطلع الوزارة بوضع الاستراتيجيات الاقتصادية متوسطة وطويلة المدى، وإدارة الاستثمارات العامة، وتعزيز التنمية الصناعية، وتنسيق التعاون مع الشركاء الدوليين والمؤسسات المالية، بما يسهم في تحقيق أهداف رؤية جيبوتي 2035 وتعزيز النمو الاقتصادي المستدام. وتشرف الوزارة كذلك على تعبئة الموارد الداخلية والخارجية، وإدارة الدين العام، ومتابعة المشروعات التنموية، وتحسين مناخ الاستثمار، ودعم القطاعين الصناعي والخاص بما يعزز التنمية الاقتصادية والاجتماعية في البلاد.',NULL,'http://www.mefip.gouv.dj/',5,6,3,'2026-06-08 12:53:58','2026-06-29 11:55:57'),(141,'Photos_MinistriesHigherEducationScientificResearch/TM35K5znUGVx8e2aBzFAbxK3fvhnydKaqlzmD8jF.jpg','وزارة البيئة والتنمية المستدامة','.','هي وزارة حكومية مسؤولة عن حماية البيئة والحفاظ على الموارد الطبيعية في جمهورية جيبوتي، إضافة إلى وضع وتنفيذ السياسات المتعلقة بالتنمية المستدامة. تعمل الوزارة على مكافحة التصحر، وحماية التنوع البيولوجي، وإدارة التحديات البيئية مثل التغير المناخي ونقص المياه. كما تسعى إلى تحقيق توازن بين التنمية الاقتصادية والحفاظ على البيئة لضمان مستقبل مستدام للأجيال القادمة.',NULL,'https://www.environnement.gouv.dj/',5,6,3,'2026-06-08 12:54:48','2026-06-22 13:58:07'),(142,'Photos_MinistriesHigherEducationScientificResearch/XU34T2PrWzb9G96MhVwfQt7D4lyfPjBGG1pymOEz.png','وزارة الاقتصاد والمالية والصناعة','.','تعمل وزارة الاقتصاد والمالية والصناعة في جمهورية جيبوتي على تنفيذ وتنسيق السياسات الاقتصادية والمالية للدولة، من خلال إدارة الموارد والأصول العامة، وضمان الاستخدام الأمثل للميزانية بما يخدم التنمية الوطنية. كما تشرف على توجيه السياسات الاقتصادية والاستراتيجيات الوطنية المتعلقة بالنمو والتنافسية والتكامل الإقليمي، إضافة إلى دعم القطاع الصناعي وتحسين مناخ الاستثمار',NULL,'https://www.ministere-finances.dj/',5,6,3,'2026-06-08 12:55:55','2026-06-19 14:28:41'),(143,'Photos_MinistriesHigherEducationScientificResearch/Yu6o7BXmVYC2q5KWc5A26eW8bDoAlUWyEe9mDoGT.jpg','وزارة التعليم العالي والبحث العلمي',NULL,'أُنشئت وزارة التعليم العالي بالمرسوم الملكي رقم 236/1 بتاريخ 8/5/1395هـ (1975م) لتتولى تنفيذ سياسة المملكة في مجال التعليم العالي، وبموجب هذا القرار أصبح وزير التعليم العالي مسؤولًا عن تنفيذ سياسة الدولة في التعليم الجامعي.\r\nوقد حظي التعليم الجامعي في المملكة بدعم كبير تمثل في إنشاء جامعات جديدة وكليات تطبيقية، إلى جانب تخصيص اعتمادات مالية كبيرة في الميزانيات، مما أسهم في توسع منظومة التعليم العالي. وقد بلغ عدد الجامعات الحكومية نحو 27 جامعة حكومية، إضافة إلى 36 جامعة وكلية أهلية، ونحو 25 معهداً موزعة على مختلف مناطق المملكة، وتضم تخصصات علمية وتطبيقية متعددة.\r\nكما تبنّت وزارة التعليم العالي توجهات حديثة في مجالات البحث العلمي والتخطيط الاستراتيجي المستقبلي، بما يواكب متطلبات التنمية الوطنية وسوق العمل.',NULL,'https://www.moe.gov.sa/',5,7,3,'2026-06-08 13:02:36','2026-06-08 13:02:36'),(144,'Photos_MinistriesHigherEducationScientificResearch/l2BxpvHXeEE6P8xO2Apv7y2lgimFWjSPDUNw45bZ.jpg','وزارة الصناعة والثروة المعدنية',NULL,'وزارة الصناعة والثروة المعدنية هي وزارة سعودية أُنشئت بأمر ملكي في 30 أغسطس 2019م، بعد أن كانت ضمن هيكلة وزارة الطاقة والصناعة والثروة المعدنية، ويشغل منصب وزيرها بندر بن إبراهيم الخريف.\r\nوتهدف الوزارة إلى تطوير قطاعي الصناعة والتعدين في المملكة، وتعزيز تنافسيتهما محليًا وعالميًا، والمساهمة في تنويع الاقتصاد الوطني ورفع مساهمتهما في الناتج المحلي الإجمالي، تماشيًا مع رؤية السعودية 2030، من خلال تنفيذ برامج ومبادرات برنامج تطوير الصناعة الوطنية والخدمات اللوجستية، إضافة إلى تنظيم وترخيص الأنشطة الصناعية والتعدينية.',NULL,'https://www.mim.gov.sa/',5,7,3,'2026-06-08 13:28:12','2026-06-08 13:28:12'),(145,'Photos_MinistriesHigherEducationScientificResearch/nr6nYCeBCpJO0pFVWQb3BN0T9jnxAu8Oq3wXE1DU.jpg','وزارة الطاقة',NULL,'وزارة الطاقة هي وزارة سعودية مسؤولة عن إدارة وتنظيم قطاع الطاقة في المملكة، وقد أعيد تنظيمها بصيغتها الحالية عام 2019م ضمن إطار إعادة هيكلة قطاع الطاقة، ويشرف عليها وزير الطاقة الأمير عبد العزيز بن سلمان بنعبد العزيز آل سعود.\r\nوتهدف الوزارة إلى تأمين واستدامة إمدادات الطاقة في المملكة، وتعزيز كفاءة إنتاج واستهلاك مصادر الطاقة المختلفة بما فيها النفط والغاز والطاقة المتجددة، كما تعمل على تنويع مزيج الطاقة ودعم التحول نحو مصادر أكثر استدامة، بما يتوافق مع مستهدفات رؤية السعودية 2030.',NULL,'https://www.moenergy.gov.sa/',5,7,3,'2026-06-08 13:29:02','2026-06-08 13:29:02'),(146,'Photos_MinistriesHigherEducationScientificResearch/IyHDzsGGlLUIZVibRZi9h8CUULUGbTNgUFTWucL0.jpg','وزارة الاقتصاد والتخطيط',NULL,'وزارة الاقتصاد والتخطيط هي وزارة سعودية أُنشئت في ستينيات القرن العشرين، وتُعد الجهة المسؤولة عن وضع السياسات الاقتصادية العامة والتخطيط التنموي الشامل في المملكة، ويشرف عليها وزير الاقتصاد والتخطيط فيصل بن فاضل الإبراهيم.\r\nوتهدف الوزارة إلى رفع كفاءة الاقتصاد الوطني وتنويعه وتقليل الاعتماد على النفط، من خلال وضع الخطط الاستراتيجية ومتابعة الأداء الاقتصادي والتنموي، ودعم تحقيق أهداف رؤية السعودية 2030، إضافة إلى تحسين مؤشرات النمو والاستدامة الاقتصادية على المدى الطويل.',NULL,'https://www.mep.gov.sa/',5,7,3,'2026-06-08 13:30:02','2026-06-08 13:30:02'),(147,'Photos_MinistriesHigherEducationScientificResearch/4MtFhZFWBKfr4qQDTrTshCUDCC6wgKtiEE32VZjh.jpg','وزارة الاتصالات وتقنية المعلومات','mcit','تهدف وزارة الاتصالات وتقنية المعلومات  إلى بناء مجتمع رقمي مزدهر من خلال عملها على تطوير المهارات وتمكين الطاقات الوطنية الرقمية لتكون قادرة على تسريع عملية التحول الرقمي والإسهام في تحقيق توجهاتنا الاستراتيجية المستمدة من رؤية المملكة 2030، أطلقنا العديد من المبادرات إليكم أبرزها',NULL,'https://mcit.gov.sa/',5,7,3,'2026-06-08 13:40:30','2026-06-24 12:38:56'),(148,'Photos_MinistriesHigherEducationScientificResearch/hmmcXeuvlSfbfA9sqd4a2hoFylQWJfKawOZ8MeRN.jpg','وزارة التعليم العالي والبحث العلمي',NULL,'وزارة التعليم العالي والبحث العلمي هي وزارة سودانية أُنشئت سنة 1992، وهي الجهة الحكومية المسؤولة عن الإشراف على قطاع التعليم العالي والبحث العلمي في السودان، بما في ذلك تنظيم الجامعات والكليات ومراكز البحث العلمي، ووضع السياسات العامة للتعليم الجامعي والدراسات العليا.\r\nوتهدف الوزارة إلى تطوير جودة التعليم العالي والارتقاء بمنظومة البحث العلمي داخل البلاد، ودعم الابتكار والإنتاج العلمي بما يخدم التنمية الاقتصادية والاجتماعية، إضافة إلى تعزيز التعاون العلمي مع المؤسسات الإقليمية والدولية، وتشجيع البحث التطبيقي وربطه باحتياجات سوق العمل في مجالات مثل الزراعة، والصناعة، والصحة، والتكنولوجيا.',NULL,'http://www.mohe.gov.sd/',5,8,3,'2026-06-08 13:46:58','2026-06-08 13:46:58'),(149,'Photos_MinistriesHigherEducationScientificResearch/Kh2i7y6ZK4ld6Rfa7LRF2mh7vUmrNCKqkBPpgXyN.jpg','وزارة الصناعة والتجارة',NULL,'وزارة الصناعة والتجارة هي وزارة سودانية مسؤولة عن تنظيم وتطوير القطاعين الصناعي والتجاري في البلاد، حيث تعمل على وضع السياسات والخطط الهادفة إلى تنمية الصناعات الوطنية وتعزيز حركة التجارة الداخلية والخارجية.\r\nوتهدف الوزارة إلى دعم الإنتاج الصناعي ورفع تنافسية المنتجات السودانية، وتشجيع الاستثمار في القطاع الصناعي، إضافة إلى تنظيم الأسواق وحماية المستهلك وتطوير الصادرات الوطنية، بما يساهم في تحقيق التنمية الاقتصادية وتنويع مصادر الدخل في السودان.',NULL,'http://www.mtic.gov.sd/',5,8,3,'2026-06-08 13:48:40','2026-06-08 13:48:40'),(150,'Photos_MinistriesHigherEducationScientificResearch/ZhTHhzk61mOOSEvz50i58He8nb2Vc6ClqIrpboaG.jpg','وزارة الطاقة والنفط',NULL,'وزارة الطاقة والنفط هي وزارة سودانية مسؤولة عن إدارة وتنظيم قطاعي الطاقة والنفط في البلاد، وتشرف على استكشاف وإنتاج وتطوير الموارد النفطية، إضافة إلى وضع السياسات المتعلقة بالطاقة والكهرباء والوقود.\r\nوتهدف الوزارة إلى تعزيز أمن الطاقة وتحقيق الاستغلال الأمثل للموارد الطبيعية، ودعم التنمية الاقتصادية من خلال تطوير الصناعات النفطية والطاقة الكهربائية والطاقة المتجددة، إلى جانب جذب الاستثمارات المحلية والأجنبية في قطاع الطاقة، وتحسين البنية التحتية المرتبطة بالإنتاج والتوزيع.',NULL,'https://www.mop.gov.sd/',5,8,3,'2026-06-08 13:50:18','2026-06-08 13:50:18'),(151,'Photos_MinistriesHigherEducationScientificResearch/o5EVVN03dNOLLNsW9l46yItkar6jNmvPGCH9K3TA.jpg','وزارة الاتصالات والتحول الرقمي','mtdt','تعمل الوزارة على تحقيق التحول الرقمي بمفهومه الشامل لضمان الاستثمار الأمثل لكل من قطاعي الاتصالات والبريد؛ وإنفاذ برامج ومشاريع الحكومة الالكترونية عبر ممعاملات آمنة وبحجية قانونية معتمدة.',NULL,'https://mtdt.gov.sd/ar',5,8,3,'2026-06-08 13:51:05','2026-06-22 09:52:10'),(152,'Photos_MinistriesHigherEducationScientificResearch/ueEJKVJ2q3QTgncJzLYy0UysfZbckndSwxES74MT.jpg','وزارة التعليم العالي والبحث العلمي','mohe','تُعد وزارة التعليم العالي والبحث العلمي السورية الجهة الحكومية المسؤولة عن تنظيم وتطوير التعليم الجامعي والبحث العلمي في الجمهورية العربية السورية، وقد أُنشئت عام 1966 بهدف الإشراف على الجامعات والمعاهد العليا والمشافي التعليمية ومراكز البحث العلمي. تعمل الوزارة على وضع السياسات التعليمية وتطوير البرامج الأكاديمية ودعم الابتكار والبحث العلمي، إضافة إلى تعزيز التعاون العلمي مع المؤسسات التعليمية العربية والدولية بما يسهم في إعداد الكفاءات الوطنية وخدمة التنمية في البلاد.',NULL,'http://www.mohe.gov.sy/',5,9,3,'2026-06-08 13:52:02','2026-06-19 14:28:06'),(153,'Photos_MinistriesHigherEducationScientificResearch/UBS2Tq8F6MFY9ynBo5bWKkOhHdR7hP1Yc5LN7SMh.png','وزارة الاقتصاد والصناعة','mitcp','تُعد وزارة الاقتصاد والصناعة من الوزارات الاقتصادية الرئيسية في سوريا، وهي وزارة حديثة التشكيل أُنشئت عام 2025 نتيجة دمج وزارات الاقتصاد والتجارة الخارجية والصناعة والتجارة الداخلية وحماية المستهلك. تهدف الوزارة إلى إدارة السياسات الاقتصادية والصناعية والتجارية، ودعم الاستثمار والإنتاج الوطني، وتعزيز التنمية الصناعية والتحول الرقمي وتحسين بيئة الأعمال، بما يسهم في تنشيط الاقتصاد السوري ورفع القدرة التنافسية للقطاع الصناعي والتجاري.',NULL,'https://mitcp.gov.sy/',5,9,3,'2026-06-08 13:54:27','2026-06-22 10:07:13'),(154,'Photos_MinistriesHigherEducationScientificResearch/j4SRlXt5CjuQniG6vHNRwcAMBvc4oATLruITXq84.png','وزارة الكهرباء السورية الجهة الحكومية',NULL,'تُعد وزارة الكهرباء السورية الجهة الحكومية المسؤولة عن إدارة وتطوير قطاع الكهرباء في الجمهورية العربية السورية، حيث تتولى الإشراف على إنتاج ونقل وتوزيع الطاقة الكهربائية في مختلف المحافظات. تعمل الوزارة على تنفيذ مشاريع البنية التحتية الكهربائية، وصيانة الشبكات ومحطات التوليد، إضافة إلى دعم خطط التوسع في الطاقة وتحسين كفاءة الخدمات الكهربائية لتلبية احتياجات التنمية الاقتصادية والخدمية في البلاد. كما تسعى إلى تعزيز استخدام مصادر الطاقة المتجددة وتطوير التعاون الفني والاستثماري في قطاع الطاقة الكهربائية.',NULL,'https://moe.gov.sy/',5,9,3,'2026-06-08 13:55:24','2026-06-08 13:55:24'),(155,'Photos_MinistriesHigherEducationScientificResearch/7RKw5PqHc0B0iKD8WtDLzn6rqrm7Dj7FqcNuCd2h.jpg','وزارة التربية والثقافة والتعليم العالي',NULL,'وزارة التربية والثقافة والتعليم العالي في جمهورية الصومال هي وزارة حكومية تتولى الإشراف على قطاع التعليم بمختلف مستوياته، من التعليم الأساسي إلى التعليم العالي، إضافة إلى دعم الشأن الثقافي وحماية التراث الوطني. تعمل الوزارة على وضع السياسات التعليمية وتطوير المناهج وتحسين جودة التعليم في المدارس والمعاهد والجامعات، كما تسعى إلى تأهيل الكفاءات البشرية ورفع مستوى التعليم بما يخدم احتياجات سوق العمل. وتضطلع أيضاً بدور في تعزيز الهوية الثقافية ونشر المعرفة ودعم البحث العلمي.',NULL,'https://moe.gov.so/en/',5,10,3,'2026-06-08 13:56:30','2026-06-08 13:56:30'),(156,'Photos_MinistriesHigherEducationScientificResearch/kAhFTtCdQneYOTrS2iW418OyAPUkhr6QKtobYCso.png','وزارة الاتصالات والتكنولوجيا','Ministry of Communications and Technologie','وزارة الاتصالات وتكنولوجيا المعلومات في جمهورية أرض الصومال هي جهة حكومية مسؤولة عن وضع السياسات وتنظيم وتطوير قطاع الاتصالات والتقنيات الحديثة في البلاد، بهدف تعزيز البنية التحتية الرقمية وتحسين خدمات الهاتف والإنترنت ودعم التحول الرقمي. تأسست الوزارة سنة 1993 تحت اسم وزارة البريد والاتصالات، ثم تم تغيير تسميتها لاحقاً لتشمل مجالات التكنولوجيا الحديثة. وتعمل الوزارة على مواكبة التطور التقني وتشجيع الاستثمار في قطاع الاتصالات بما يساهم في تنمية الاقتصاد الوطني وتسهيل الخدمات الرقمية للمواطنين.',NULL,'https://moct.gov.so/',5,10,3,'2026-06-08 13:57:27','2026-06-08 13:59:55'),(157,'Photos_MinistriesHigherEducationScientificResearch/96vnX80sTfGFHcUkhqhxCAmFRjw3iVgCnk5A1LQ9.png','وزارة التجارة والصناعة','null','وزارة التجارة والصناعة في جمهورية الصومال هي جهة حكومية مسؤولة عن تنظيم الأنشطة التجارية والصناعية داخل البلاد، ووضع السياسات والتشريعات التي تنظم الأسواق وتعزز بيئة الأعمال. تعمل الوزارة على دعم القطاع الخاص وتشجيع الاستثمارات المحلية والأجنبية، وتطوير الصناعة الوطنية لزيادة الإنتاج وتحسين الجودة. كما تسهر على مراقبة حركة الاستيراد والتصدير وحماية المستهلك من الممارسات غير القانونية. وتهدف بشكل عام إلى تنشيط الاقتصاد الوطني وتحقيق التنمية المستدامة من خلال تقوية القطاعين التجاري والصناعي.',NULL,'https://moci.gov.so/',5,10,3,'2026-06-08 13:59:07','2026-06-23 11:48:04'),(158,'Photos_MinistriesHigherEducationScientificResearch/8cuTqitJe146Jk47MLOLeOXjzimLFrx5CW8AWxqc.png','وزارة التعليم العالي والبحث العلمي','mohesr','إن وزارة التعليم العالي والبحث العلمي تهدف إلى إجراء تغييرات كمية ونوعية في الحركة العلمية والتقنية والثقافية في العراق، وتقوم بتوجيه المؤسسات العلمية والبحثية لتتولى عملية خلق جيل جديد مزود بالعلم والمعرفة، لتكون هذه المؤسسات قوة فاعلة ومؤثرة في المجتمع العراقي.\r\n كما تهدف الوزارة إلى تطوير العلاقات العلمية والثقافية وتوسيع العلاقات الودية في هذه المجالات مع الدول الأخرى والمنظمات العلمية والأكاديمية المختلفة في جميع أنحاء العالم من. أجل تحقيق الانسجام والتكامل في مجالات العلم والمعرفة.',NULL,'https://mohesr.gov.iq/ar/',5,11,3,'2026-06-08 14:01:01','2026-06-08 14:01:01'),(159,'Photos_MinistriesHigherEducationScientificResearch/yjA4cSL3bUYScpNbJQNxhDfA43pcu18cHihXYy5L.png','وزارة الصناعة والمعادن','.','وزارة الصناعة والمعادن العراقية هي وزارة حكومية في جمهورية العراق مسؤولة عن تنظيم وتطوير القطاع الصناعي والاستخراجية غير النفطي، بما يشمل إدارة الشركات العامة الصناعية، ودعم الإنتاج المحلي، وتشجيع الاستثمار الصناعي، وتطوير البنية التحتية للصناعة الوطنية.\r\nتعمل الوزارة على تعزيز التنمية الصناعية وتنويع الاقتصاد من خلال دعم الصناعات الكيمياوية والهندسية والغذائية والدوائية والإنشائية وغيرها، إضافة إلى الإشراف على الهيئات والمراكز البحثية التابعة لها، مثل هيئة البحث والتطوير الصناعي.',NULL,'https://www.industry.gov.iq/',5,11,3,'2026-06-08 14:02:06','2026-06-22 09:41:07'),(161,'Photos_MinistriesHigherEducationScientificResearch/pthVtegSqgT3YDrcR3xn5Sxm4BBLiDbZPzG2Q6Sf.png','وزارة التعليم العالي والبحث العلمي والابتكار','moheri','هي الجهة الحكومية المسؤولة عن تنظيم وتطوير منظومة التعليم العالي والبحث العلمي والابتكار في سلطنة عُمان. تعمل الوزارة على وضع السياسات والخطط التي تهدف إلى تعزيز جودة التعليم الجامعي، ودعم الأبحاث العلمية، وتشجيع الابتكار وريادة الأعمال، بما يساهم في بناء اقتصاد قائم على المعرفة.\r\nكما تسعى إلى ربط البحث العلمي باحتياجات المجتمع وسوق العمل، وتطوير الكفاءات الوطنية، وتعزيز التعاون بين الجامعات والمؤسسات البحثية والقطاعين العام والخاص، بما ينسجم مع رؤية عُمان 2040 في بناء مجتمع معرفي مبتكر ومستدام.',NULL,'https://www.moheri.gov.om/',5,12,3,'2026-06-08 14:04:29','2026-06-22 09:37:18'),(162,'Photos_MinistriesHigherEducationScientificResearch/PnfQ72qEbpTltFoyKwdqyoG4Bz1DFK1epWcffGQt.png','وزارة النقل والاتصالات وتقنية المعلومات','mtcit','هي وزارة حكومية تأسست عام 2019، وتعد الجهة المسؤولة عن النقل، والاتصالات، وتقنية المعلومات، والتحول الرقمي في سلطنة عُمان. تعمل على تطوير البنية الأساسية الرقمية واللوجستية في الدولة، بما يشمل الطرق والموانئ والاتصالات، إضافة إلى قيادة برامج الحكومة الرقمية.\r\nكما تتولى الوزارة تنفيذ برنامج التحول الرقمي الحكومي، الذي يهدف إلى تحويل الخدمات الحكومية إلى خدمات إلكترونية ذكية، وتحسين كفاءة الأداء الحكومي، وتعزيز الابتكار في استخدام التقنيات الحديثة مثل الذكاء الاصطناعي والخدمات الرقمية، بما يساهم في بناء اقتصاد رقمي متطور يتماشى مع رؤية عُمان 2040.',NULL,'https://www.mtcit.gov.om/',5,12,3,'2026-06-08 14:13:50','2026-06-22 09:28:11'),(163,'Photos_MinistriesHigherEducationScientificResearch/dksqshDhob0qc2s5dUUOXQZ6Kgu2p3q6VLzY50mD.jpg','وزارة التجارة والصناعة وترويج الاستثمار','mociip','هي وزارة مسؤولة عن تنظيم التجارة والصناعة وجذب الاستثمارات في سلطنة عُمان، وتهدف إلى تطوير بيئة الأعمال، وتسهيل إجراءات تأسيس الشركات، ودعم القطاع الخاص، وترويج الاستثمار المحلي والأجنبي، إضافة إلى تعزيز التنافسية وتنويع الاقتصاد',NULL,'https://www.mociip.gov.om/',5,12,3,'2026-06-08 14:15:01','2026-06-22 09:26:40'),(164,'Photos_MinistriesHigherEducationScientificResearch/dB8qaeA5vAhm9b0d9SgtiT4HeS6sUooWmAM28jBg.jpg','وزارة الطاقة والمعادن','mem','تعمل الوزارة على تنظيم وتطوير قطاع الطاقة والمعادن في سلطنة عُمان، بهدف تحقيق الاستغلال الأمثل للموارد الطبيعية ضمن إطار يراعي الصحة والسلامة المهنية وحماية البيئة. كما تسعى إلى تطوير مصادر الطاقة المختلفة مثل النفط والغاز والطاقة المتجددة، إضافة إلى قطاع المعادن، بكفاءة عالية وابتكار، بما يدعم الاقتصاد الوطني ويعزز استدامته.\r\nوترتكز رؤية الوزارة على تطوير واستغلال مصادر الطاقة والمعادن بطرق حديثة وفعالة تسهم في دعم النمو الاقتصادي. أما رسالتها فتركز على تنظيم وتنمية هذا القطاع الحيوي بما يضمن الاستخدام الأمثل للثروات الوطنية.',NULL,'https://www.mem.gov.om/',5,12,3,'2026-06-08 14:15:56','2026-06-22 09:22:57'),(165,'Photos_MinistriesHigherEducationScientificResearch/2B2lP5wohXH5YNgiA9nHgqMV4Sz8ePOQDAoU8iZ3.jpg','وزارة التربية والتعليم العالي','moe','نشأت وزارة التربية والتعليم العالي بعد تسلم السلطة الوطنية الفلسطينية، مهام التعليم في فلسطين عام 1994.\r\n وفي عام 1996 أنيطت صلاحيات التعليم العالي بوزارة جديدة حملت اسم وزارة التعليم العالي والبحث العلمي، فيما ظلت الوزارة الأم تحمل اسم وزارة التربية والتعليم. وفي تعديل وزاري على الحكومة الفلسطينية عام 2002 تم إعادة دمج الوزارتين في وزارة واحدة حملت اسم وزارة التربية والتعليم العالي.',NULL,'https://www.moe.edu.ps/',5,13,3,'2026-06-08 14:17:36','2026-06-08 14:17:52'),(167,'Photos_MinistriesHigherEducationScientificResearch/JIIXfW8RmyjwwW7ez89oCjd2m9ozt7NVEcu8K8HT.png','وزارة الصناعة','palgov','تُعد وزارة الصناعة الجهة الحكومية المسؤولة عن تطوير وتنظيم القطاع الصناعي في دولة فلسطين، حيث تعمل على تعزيز القدرة التنافسية للصناعات الوطنية، ودعم الاستثمار الصناعي، وتحسين جودة المنتجات الفلسطينية بما يتوافق مع المعايير الدولية. كما تسعى الوزارة إلى تشجيع الابتكار والتكنولوجيا الصناعية، وتوفير بيئة أعمال ملائمة لنمو المنشآت الصناعية، بما يساهم في تحقيق التنمية الاقتصادية المستدامة وخلق فرص العمل.',NULL,'https://www.mind.gov.ps/',5,13,3,'2026-06-08 14:20:06','2026-06-19 14:29:16'),(168,'Photos_MinistriesHigherEducationScientificResearch/TKD7qJjFTrNoowF0IlrtiYAdzyg6WtiuTfr2PORX.jpg','وزارة التربية والتعليم والتعليم العالي','.','تُشرف الوزارة على تطوير منظومة التعليم والتعليم العالي في دولة قطر، وتعمل على رفع جودة التعليم والبحث العلمي، وتعزيز الابتكار وتنمية الكفاءات الوطنية. كما تسعى إلى بناء نظام تعليمي متطور يدعم الاقتصاد القائم على المعرفة ويواكب متطلبات التنمية المستدامة ورؤية قطر الوطنية 2030.',NULL,'https://www.edu.gov.qa/ar/',5,14,3,'2026-06-08 14:23:57','2026-06-22 09:10:53'),(169,'Photos_MinistriesHigherEducationScientificResearch/VD5n0vp3vNOA6bCM5bnjvigXZieIoNOdcJqLc2de.webp','وزارة التجارة والصناعة','moci','تُعد وزارة التجارة والصناعة الجهة الحكومية المسؤولة عن تنظيم وتطوير الأنشطة التجارية والصناعية في دولة قطر، وتهدف إلى تعزيز بيئة الأعمال وجذب الاستثمارات المحلية والأجنبية بما يدعم النمو الاقتصادي المستدام. تعمل الوزارة على وضع وتنفيذ السياسات والتشريعات المتعلقة بالتجارة والصناعة، وتطوير القطاع الخاص، وحماية المستهلك، وتعزيز التنافسية والابتكار في مختلف القطاعات الاقتصادية. كما تسهم في دعم التنويع الاقتصادي وتشجيع الصناعات الوطنية وريادة الأعمال، بما ينسجم مع أهداف رؤية قطر الوطنية 2030 الرامية إلى بناء اقتصاد متنوع قائم على المعرفة والاستدامة.',NULL,'https://www.moci.gov.qa/',5,14,3,'2026-06-08 14:25:11','2026-06-22 09:08:22'),(170,'Photos_MinistriesHigherEducationScientificResearch/99OFsOOo83rU6yklhzemBAZdT36Mq1Umq1dQYQT8.webp','وزارة الاتصالات وتكنولوجيا المعلومات','mcit','تُعد الوزارة الجهة المسؤولة عن قيادة التحول الرقمي في دولة قطر، وتطوير البنية التحتية الرقمية، وتعزيز الأمن السيبراني، وتمكين الاقتصاد الرقمي. كما تعمل على تسريع تبني التقنيات الحديثة والذكاء الاصطناعي، وتطوير الخدمات الحكومية الرقمية، ودعم الابتكار التكنولوجي بما يعزز مكانة قطر كمركز رقمي متقدم في المنطقة.',NULL,'https://www.mcit.gov.qa/',5,14,3,'2026-06-08 14:26:02','2026-06-22 09:05:30'),(172,'Photos_MinistriesHigherEducationScientificResearch/HW4LCkDcYckEYcObUoMWdz7QJpIqfITpHveVho4a.png','وزارة التعليم العالي',NULL,'وزارة التعليم العالي – دولة الكويت هي الجهة الحكومية المسؤولة عن الإشراف على التعليم العالي والابتعاث وتنمية الكفاءات الوطنية، وقد تأسست عام 1988.\r\nوتعمل الوزارة على توفير فرص التعليم والتخصص في مختلف المجالات العلمية والإنسانية، ودعم البحث العلمي وإعداد الموارد البشرية المؤهلة بما يخدم التنمية الوطنية.',NULL,'https://www.mohe.edu.kw/',5,15,3,'2026-06-08 14:28:05','2026-06-08 14:28:05'),(173,'Photos_MinistriesHigherEducationScientificResearch/gO0Z3jE5SaLiT5zuuxNhYybzVLcGx1Qfw5HBBd7p.jpg','وزارة التجارة والصناعة','moci','وزارة التجارة والصناعة  هي الجهة الحكومية المسؤولة عن تنظيم ودعم الأنشطة التجارية والصناعية والاقتصادية في الدولة. \r\nتعود نشأتها الى عام 1963\r\nتحت اسم وزارة التجارة، ثم أصبحت وزارة التجارة والصناعة عام1965.\r\n تعمل الوزارة على تطوير\r\n بيئة الأعمال، وتشجيع الاستثمار، وتوفير السلع والخدمات، وتعزيز النمو الاقتصادي والتنافسية بما يدعم التنمية المستدامة في دولة الكويت.',NULL,'https://www.moci.gov.kw/',5,15,3,'2026-06-08 14:29:00','2026-06-23 11:35:51'),(177,'Photos_MinistriesHigherEducationScientificResearch/ULv57I51k8lIE5ZarjRJK2nNc7u2kKsTJHyT6lCp.jpg','وزارة الصــناعة','null','تأسست وزارة الصناعة عام 1993، وتُعنى بتطوير القطاع الصناعي اللبناني وتعزيز تنافسيته، ودعم الاستثمار والإنتاج الصناعي، وتشجيع الابتكار والتكنولوجيا الصناعية بما يساهم في النمو الاقتصادي وخلق فرص العمل.',NULL,'https://www.industry.gov.lb/',5,16,3,'2026-06-08 14:34:34','2026-06-23 11:31:31'),(179,'Photos_MinistriesHigherEducationScientificResearch/zGngbub8TWYA803k8gepwzRRwkdhOjy9tlMzFINv.jpg','وزارة التعليم العالي والبحث العلمي','mhesr','استُحدِثت وزارة التعليم العالي والبحث العلمي بقرار من مجلس وزراء حكومة الوحدة الوطنية رقم (39) لسنة 2021م بشأن اعتماد الهيكل التنظيمي وتحديد اختصاصات وزارة التعليم العالي والبحث العلمي، لتتولى تنفيذ سياسة الدولة في التعليم العالي. وبموجب القرار المذكور تمت تسمية السيد/ د. عمران محمد القيب كوزيرٍ للتعليم العالي والبحث العلمي.',NULL,'https://mhesr.gov.ly/',5,17,3,'2026-06-08 14:41:11','2026-06-23 11:34:12'),(180,'Photos_MinistriesHigherEducationScientificResearch/08XwEqPUwIs1yuunNynVVjBUC8Nbg1dN0IKgCrZE.png','وزارة الصناعة والمعادن','industry','وزارة الصناعة والمعادن إحدى الوزارات التابعة لحكومة الوحدة الوطنية، والمسؤولة عن تطوير وتنظيم القطاع الصناعي في ليبيا، حيث تقوم بتحديد السياسات والاستراتيجيات الصناعية، ووضع الأهداف وتطوير التشريعات اللازمة لرفع كفاءة القطاع وتحقيق التنمية المستدامة.\r\n تسعى الوزارة إلى تعزيز الاقتصاد الوطني من خلال دعم المشروعات الصناعية الصغرى والمتوسطة، وتوفير بيئة تشجع على الابتكار والإبداع، مما يساهم في خلق فرص العمل وزيادة الإنتاج المحلي.',NULL,'https://www.industry.gov.ly/',5,17,3,'2026-06-08 14:42:04','2026-06-22 08:59:43'),(182,'Photos_MinistriesHigherEducationScientificResearch/QpLpD0PpGr9HwDLlKgaXgeF04yRFHFUYcs9ZR01n.png','وزارة الاتصالات والمعلوماتية','cim','وزارة الاتصالات والمعلوماتية تعنى بشؤون الاتصالات وتقنية المعلومات وتمثل أعلى سلطة مسؤولة عن قطاع الاتصالات في ليبيا. نسعى إلى تحقيق التحول الرقمي في جميع قطاعات الدولة، وتطوير البنية التحتية الرقمية، وتعزيز الابتكار في مجال الاتصالات وتقنية المعلومات، وتوفير خدمات رقمية متقدمة للمواطنين والمقيمين.',NULL,'https://www.cim.gov.ly/',5,17,3,'2026-06-08 14:43:46','2026-06-24 12:42:10'),(183,'Photos_MinistriesHigherEducationScientificResearch/PatYN6LGesJq37W4zaZvMuHEok0W2UzvacxFBtOR.png','وزارة التعليم العالي والبحث العلمي','mohesr','وزارة التعليم العالي والبحث العلمي هي الجهة الحكومية المسؤولة عن تطوير منظومة التعليم العالي والبحث العلمي في مصر، وقد تأسست عام 1961.\r\n تعمل الوزارة على دعم الجامعات والمراكز البحثية، وتعزيز الابتكار والتطوير التكنولوجي، وإعداد الكوادر العلمية المؤهلة بما يواكب متطلبات التنمية الوطنية.',NULL,'https://mohesr.gov.eg/ar/',5,18,3,'2026-06-08 14:44:58','2026-06-08 14:44:58'),(184,'Photos_MinistriesHigherEducationScientificResearch/8YuQk9pkXkzjRNxPeujJSjRlt7OPUYLwQ871LNXl.png','وزارة الصناعة','mind','وزارة الصناعة هي الجهة الحكومية المسؤولة عن تنمية وتطوير القطاع الصناعي في جمهورية مصر العربية، من خلال إعداد وتنفيذ السياسات والاستراتيجيات الصناعية الهادفة إلى تعزيز الإنتاج والتصنيع المحلي ورفع القدرة التنافسية للصناعة المصرية.\r\nوتعمل الوزارة على تشجيع الاستثمار الصناعي، وتوطين التكنولوجيا الحديثة، وتطوير المناطق الصناعية، ودعم المشروعات الصغيرة والمتوسطة، بما يسهم في زيادة الصادرات الصناعية وتوفير فرص العمل وتحقيق التنمية الاقتصادية المستدامة. كما تضطلع بدور محوري في تعزيز الابتكار الصناعي وتحسين بيئة الأعمال، بما يدعم رؤية مصر للتنمية الاقتصادية الشاملة.\r\nسنة التأسيس: تعود جذور الوزارة إلى بدايات التنظيم الحكومي للقطاع الصناعي بعد ثورة 1952، بينما تشكلت الوزارة بمسمياتها واختصاصاتها الحالية عبر عدة عمليات إعادة هيكلة حكومية متعاقبة.',NULL,'https://mind.gov.eg/',5,18,3,'2026-06-08 14:47:20','2026-06-19 14:27:24'),(186,'Photos_MinistriesHigherEducationScientificResearch/X44K3sXcN1qwZfIcXW3FD05wmpUsG3Fa1h30Olzk.png','وزارة الاتصالات وتكنولوجيا المعلومات',NULL,'هيئة تنمية صناعة تكنولوجيا المعلومات (إيتيدا) هي هيئة حكومية تأسست عام 2004 وتتبع وزارة الاتصالات وتكنولوجيا المعلومات.\r\n تعمل على تنمية قطاع تكنولوجيا المعلومات والاتصالات، ودعم الابتكار وريادة الأعمال الرقمية، وتعزيز صادرات الخدمات التكنولوجية، وبناء القدرات الرقمية للشباب والشركات.',NULL,'https://mcit.gov.eg/',5,18,3,'2026-06-08 14:49:52','2026-06-08 14:49:52'),(187,'Photos_MinistriesHigherEducationScientificResearch/Po8Ncq2zA68aKJp1v8hWHhdGcNgqhVWipjmZPG1X.png','وزارة التعليم العالي والبحث العلمي','null','وزارة التعليم العالي والبحث العلمي هي الجهة الحكومية المسؤولة عن تطوير منظومة التعليم العالي والبحث العلمي في موريتانيا. وتعمل الوزارة على إعداد وتنفيذ السياسات الوطنية المتعلقة بالتعليم الجامعي والبحث العلمي، بما يسهم في الارتقاء بجودة التكوين الأكاديمي وتعزيز مساهمة الجامعات في التنمية الوطنية.\r\nكما تسعى الوزارة إلى دعم البحث العلمي والابتكار، وتطوير مؤسسات التعليم العالي، وتشجيع التعاون العلمي والأكاديمي، وإعداد الكفاءات الوطنية المؤهلة القادرة على الاستجابة لمتطلبات التنمية الاقتصادية والاجتماعية، وتعزيز اقتصاد المعرفة وبناء مجتمع قائم على العلم والتكنولوجيا.\r\nسنة التأسيس: تعود جذور الإشراف الحكومي على التعليم العالي في موريتانيا إلى سبعينيات القرن العشرين، بينما تشكلت الوزارة بمسمياتها واختصاصاتها الحالية عبر عدة عمليات إعادة هيكلة حكومية متعاقبة.',NULL,'https://www.mesrs.gov.mr/',5,20,3,'2026-06-08 14:53:29','2026-06-23 11:25:35'),(188,'Photos_MinistriesHigherEducationScientificResearch/dXfjVoRbMqwVO8N3uMfNzRKOCymNgrVmXi3i5k5O.jpg','وزارة التحول الرقمي وعصرنة الإدارة','mtnima','وزارة التحول الرقمي وعصرنة الإدارة هي الجهة الحكومية المسؤولة عن قيادة التحول الرقمي في موريتانيا، وقد أُنشئت عام 2022. تعمل الوزارة على تطوير البنية التحتية الرقمية، وتحديث الإدارة العمومية، وتعزيز الحكومة الإلكترونية، وتحسين جودة الخدمات الرقمية المقدمة للمواطنين والمؤسسات.',NULL,'https://mtnima.gov.mr/',5,20,3,'2026-06-08 14:54:36','2026-06-19 14:42:39'),(189,'Photos_MinistriesHigherEducationScientificResearch/Ih2rz2XPXWRTb9UwhmAyGwVqdZ9BTrNOuBeFgE51.jpg','وزارة المعادن والصناعة','mines','وزارة المعادن والصناعة هي وزارة حكومية موريتانية تعود جذورها إلى مرحلة ما بعد الاستقلال سنة 1960، وتتولى تطوير وتنظيم القطاعين الصناعي والتعديني. تعمل على تشجيع الاستثمار، وتعزيز القيمة المضافة للموارد الطبيعية، وتطوير الصناعات الوطنية، ودعم الاستغلال المستدام للثروات المعدنية بما يسهم في تحقيق النمو الاقتصادي والتنمية المستدامة.',NULL,'https://www.mines.gov.mr/',5,20,3,'2026-06-08 14:56:12','2026-06-23 11:29:39'),(191,'Photos_MinistriesHigherEducationScientificResearch/cIaiWemxqcbXpwCmVkCObag9Lre4SKhZeOIE1n9p.jpg','وزارة التعليم العالي والبحث العلمي','mohe','وزارة التعليم العالي والبحث العلمي  هي وزارة حكومية يمنية تعود جذورها إلى إنشاء وزارة التعليم العالي والبحث العلمي عام 1990م، بينما أُنشئت وزارة التعليم الفني والتدريب المهني عام 2001م، وتم جمع اختصاصاتهما ضمن الهيكلة الحكومية الحالية. وتتولى الوزارة الإشراف على مؤسسات التعليم العالي والبحث العلمي والتعليم الفني والتدريب المهني، وتعمل على تطوير جودة التعليم، ودعم البحث العلمي والابتكار، وتأهيل الكفاءات الوطنية، ومواءمة مخرجات التعليم مع احتياجات سوق العمل بما يسهم في تحقيق التنمية المستدامة.',NULL,'https://www.mohe-ye.org/',5,21,3,'2026-06-08 14:59:05','2026-06-22 13:50:26'),(194,'Photos_IndustrialPropertyPatentOffices/bs92g1BjHrgKaCRmo0yQ5aPg86iQ0HU7nXPLU8O7.jpg','وزارة الصناعة و التجارة /مديرية الملكية الفكرية','null','براءات الاختراع و العلامات التجارية و حق التصاميم الصناعية.\r\nالمقر :عمان',NULL,'https://www.mit.gov.jo',6,1,4,'2026-06-09 10:59:14','2026-06-09 11:18:34'),(196,'Photos_IndustrialPropertyPatentOffices/g0Q0LiL1ohl0DCUVavIGjHpSp0jVgoPBUWiUwzFh.png','وزارة الاقتصاد /ادارة تنمية الابتكار و الملكية الصناعية',NULL,'براءات الاختراع و النماذج الصناعية و العلامات التجارية.\r\nالمقر : ابو ظبي',NULL,'https://www.economy.gov.ae',6,2,4,'2026-06-09 11:42:04','2026-06-09 11:42:04'),(197,'Photos_IndustrialPropertyPatentOffices/9TElacZhzK78lyshHEDmTnKXZA1muq2uNpeehSVT.jpg','وزارة الصناعة والتجارة /وحدة الملكية الفكرية.',NULL,'وزارة الصناعة والتجارة /وحدة الملكية الفكرية.\r\nالمقر :المنامة.\r\nالاهداف :حماية حقوق الملكية الفكرية و براءات الاختراع و حق الملكية و العلامات التجارية و حق التصاميم',NULL,': https://www.moic.gov.bh',6,3,4,'2026-06-09 12:25:53','2026-06-09 12:25:53'),(198,'Photos_IndustrialPropertyPatentOffices/cYF5hOgP98g2yMoa2XKEw7qPVTIzYgYS1Jb4KI0j.jpg','المعهد الوطني للتقيس و الملكية الصناعية','null','الجهة المختصة :المعهد الوطني للتقيس و الملكية الصناعية وهو موسسة عمومية ذات طابع صناعي و تجاري.\r\nالمقر : تونس\r\nالخدمات: حماية براءات الاختراع والعلامات التجارية و التصاميم الصناعية و التقيس و الجودة.',NULL,': https://www.innorpi.tn',6,4,4,'2026-06-09 12:33:21','2026-06-09 12:38:06'),(199,'Photos_IndustrialPropertyPatentOffices/BE2zlJGQAEokpZlIJKc7MLF6lxr5nVNFaJ6tTKqY.png','المعهد الوطني الجزائري للملكية الصناعية','null','المعهد الوطني الجزائري للملكية الصناعية هو مؤسسة عمومية تحت وصاية وزارة الصناعة .\r\nالمقر : العاصمة الجزائر .\r\nالخدمات :حماية الملكية الصناعية و براءات الاختراع و النماذج الصناعية و العلامات التجارية',NULL,'https://www.inapi.org',6,5,4,'2026-06-09 12:44:35','2026-06-09 12:47:35'),(200,'Photos_IndustrialPropertyPatentOffices/73hAlIwVv0JhLmGZj8WZutxrys6b3g8yyNGpUPlF.png','وزارة التجارة والصناعة /المكتب الجيبوتي للملكية الصناعية والتجارية (ODPIC)','null','المكتب الجيبوتي للملكية الصناعية والتجارية (ODPIC)\r\nالمقر :جيبوتي .\r\nالخدمات : حماية براءات الاختراع و العلامات التجارية و الملكية .',NULL,'https://odpic.dj/',6,6,4,'2026-06-09 13:25:06','2026-06-09 13:25:15'),(201,'Photos_IndustrialPropertyPatentOffices/44GplGRB7UxrDK08xm6kTPJpqfTIluYK9kVhE7Di.jpg','الهيئة السعودية للملكية الفكرية','SAIP','الهيئة السعودية للملكية الفكرية (SAIP) مرتبطة  تنظيمياً بـ رئيس مجلس الوزراء. وهي تتمتع بالشخصية الاعتبارية العامة والاستقلال المالي والإداري.\r\nالمقر : الرياض- المملكة السعودية.\r\nالخدمات :تسجيل و متابعة وحماية العلامات التجارية و الملكية الفكرية و النمازج الصناعية.',NULL,'https://www.saip.gov.sa',6,7,4,'2026-06-09 13:36:59','2026-07-01 14:16:14'),(202,'Photos_IndustrialPropertyPatentOffices/CjlH5119DKVx5APMxMG3T5ZnubwMVwk8vWf0GCz1.png','المسجل العام لإدارة الملكية الصناعية',NULL,'المسجل العام لإدارة الملكية الفكرية تُدار الملكية الصناعية في السودان عبر المسجل العام لإدارة الملكية الفكرية التابع لـ وزارة العدل السودانية.\r\nالمقر :العاصمة السودانية الخرطوم.\r\nالخدمات :تسجيل و متابعة و حماية العلامات التجارية وبراءات الاختراع والنماذج الصناعية .',NULL,'https://www.moj.gov.sd/posts/post/224',6,8,4,'2026-06-09 13:52:54','2026-06-09 13:52:54'),(203,'Photos_IndustrialPropertyPatentOffices/yveT1JlQPl7DYaTSrdjzFN4X2QRQMVG9lAaTquoX.png','مكتب الملكية الصناعية','null','مديرية حماية الملكية التجارية والصناعية، والتي تتبع إدارياً لـ وزارة التجارة الداخلية وحماية المستهلك.\r\nالمقر :العاصمة دمشق، سوريا.\r\nالخدمات :تسجيل و متابعة و حماية براءات الاختراع والعلامات التجارية و النماذج الصناعية و النشر الرسمي في جريدة حماية الملكية الصناعية و التجارية .',NULL,'http://dcip.gov.sy/disarticle.php?id=96',6,9,4,'2026-06-09 14:06:28','2026-06-09 14:13:26'),(206,'Photos_ScientificResearchInnovationCenters/L5XmtnDJruXszNu9zhm0Jkfg54dGD50G0vi0fbZH.png','مؤسسة الكويت للتقدم العلمي','.','مؤسسة وطنية تدعم البحث العلمي والابتكار والتطوير التكنولوجي في دولة الكويت، من خلال تمويل المشاريع البحثية، وتشجيع الإبداع العلمي، وبناء القدرات الوطنية في مجالات العلوم والتكنولوجيا.\r\n كما تعمل على نشر الثقافة العلمية وتعزيز اقتصاد المعرفة والتنمية المستدامة.',NULL,'https://www.kfas.org/',5,15,1,'2026-06-09 14:12:01','2026-06-23 09:48:11'),(207,'Photos_ScientificResearchInnovationCenters/XFkOfNEqR3KQRYeVB6JXFnSRYD3Vy8JjSyLEVVRN.jpg','معهد الكويت للأبحاث العلمية','kisr','يُعد من أبرز المؤسسات البحثية في دولة الكويت، ويختص بإجراء الدراسات والأبحاث العلمية والتطبيقية في مجالات الطاقة والمياه والبيئة والتكنولوجيا. ويسهم المعهد في دعم الابتكار ونقل المعرفة العلمية وتطوير الحلول التقنية التي تخدم التنمية الاقتصادية والاجتماعية في الدولة.',NULL,'https://www.kisr.edu.kw/',5,15,1,'2026-06-09 14:13:15','2026-06-23 09:49:40'),(209,'Photos_ScientificResearchInnovationCenters/07DyJv7dBPH31oBTZEU37RxbwuXjqCjUDhuYNzJj.png','مجلس قطر للبحوث والتطوير والابتكار','qrdi','مجلس قطر للبحوث والتطوير والابتكار هو هيئة وطنية تأسست عام 2018 بهدف تعزيز منظومة البحث العلمي والتطوير والابتكار في دولة قطر. يعمل المجلس على وضع وتنفيذ الاستراتيجيات والسياسات التي تدعم الابتكار وتطوير المعرفة، وتسهم في تحقيق أهداف التنمية الاقتصادية والاجتماعية للدولة. كما أطلق استراتيجية قطر للبحوث والتطوير والابتكار 2030 بهدف بناء اقتصاد قائم على المعرفة وتعزيز التعاون بين الجهات الحكومية والمؤسسات الأكاديمية وقطاع الأعمال، بما يدعم التقدم العلمي والتكنولوجي ويواكب رؤية قطر الوطنية 2030.',NULL,'https://www.qrdi.org.qa/',5,14,1,'2026-06-09 14:16:29','2026-06-19 13:34:42'),(211,'Photos_ScientificResearchInnovationCenters/uHkdq2ClDbCFZv4gKJJo7PKTl0IH6sVClsfC3BGE.png','هيئة البحث والتطوير الصناعي','null','تأسست هيئة البحث والتطوير الصناعي في العراق عام 1994 ضمن وزارة الصناعة والمعادن، وهي جهة مختصة بدعم البحث العلمي والتطوير الصناعي في مختلف القطاعات مثل الصناعات الكيمياوية والهندسية، والغذائية، والدوائية، وغيرها.\r\n تهدف إلى تعزيز الابتكار وتطوير التكنولوجيا وبناء شراكات تدعم توطين الصناعة وتحقيق التنمية المستدامة، وقد حصلت على عدة شهادات جودة دولية مثل ISO 9001 وISO/IEC 17025 وGMP لمراكزها البحثية',NULL,'https://www.crid.industry.gov.iq/',5,11,1,'2026-06-09 14:19:55','2026-06-23 11:22:20'),(214,'Photos_ScientificResearchInnovationCenters/MMhJpcvsZRLZDrsNZGnPxeQ866RSXh4qFC2T7Zqt.png','الجمعية العلمية الملكية','Royal Scientific Society - RSS','الجمعية العلمية الملكية مؤسسة بحثية وطنية رائدة في المملكة الأردنية الهاشمية، تُعنى بتطوير العلوم والتكنولوجيا وتقديم الاستشارات والخدمات الفنية والصناعية للقطاعين العام والخاص. وقد تأسست سنة 1970 بمبادرة من المغفور له الملك الحسين بن طلال، وتُعتبر اليوم أكبر مركز للبحوث التطبيقية والدعم التقني في الأردن.',NULL,'https://www.rss.jo/Default/En',5,1,1,'2026-06-09 14:24:00','2026-06-09 14:24:00'),(215,'Photos_ScientificResearchInnovationCenters/Zu9x17yFSqbysTlTO8SNnXsEDl78xWJjDV0ywIHw.webp','المجلس الأعلى للعلوم والتكنولوجيا','hcst','أنشئ “المجلس الأعلى للعلوم والتكنولوجيا” في عام 1987 بموجب القانون رقم (30) كمؤسسة عامة مستقلة، تعمل كمظلة وطنية لجميع انشطة العلوم والتكنولوجيا في الأردن. \r\nتم إنشاء المجلس بهدف بناء قاعدة علمية وتكنولوجية وطنية تسهم في تحقيق الأهداف التنموية، وذلك من خلال زيادة الوعي بأهمية البحث العلمي والتطوير، وتقديم الدعم المالي المناسب له، وتوجيه النشاط العلمي والبحثي ضمن أولويات وطنية تنسجم مع التوجهات التنموية.',NULL,'https://www.hcst.gov.jo/?q=ar',5,1,1,'2026-06-09 14:25:08','2026-06-19 13:33:09'),(216,'Photos_IndustrialPropertyPatentOffices/VwNfCjQseT4MUbnDRvlu4PZYz7HkLdbuqBYyeiN1.png','مكتب الملكية الصناعية الصومال',NULL,'المكتب المسؤول عن الملكية الصناعية في الصومال هو قسم التطوير الصناعي (إدارة العلامات التجارية وبراءات الاختراع) التابع لـ وزارة التجارة والصناعة بجمهورية الصومال الفيدرالية.\r\nالمقر : مقديشو\r\nالخدمات:تسجيل و متابعة و حماية العلامات التجارية و الملكية الصناعية و الفكرية و فحص وتوثيق وحماية الشعارات والأسماء التجارية والرموز الخاصة بالشركات المحلية والأجنبيةنشر وتلقي الاعتراضات .',NULL,'https://moci.gov.so/',6,10,4,'2026-06-09 14:35:04','2026-06-09 14:35:04'),(217,'Photos_IndustrialPropertyPatentOffices/J1pyLCOMHd6TfMZq0aRDc1SUPBKLHj8UMGyIdarC.jpg','مديرية براءات الاختراع والنماذج الصناعية','null','مديرية براءات الاختراع والنماذج الصناعية : تقع ضمن الجهاز المركزي للتقييس والسيطرة النوعية (التابع لوزارة التخطيط)، وهي الجهة المسؤولة عن تسجيل الابتكارات، براءات الاختراع، والرسوم والنماذج الصناعية.\r\nالمقر:بغداد\r\nالخدمات :تسجيل و متابعة و حماية براءات الاختراع و حماية المستهلك و النماذج الصناعية حماية الشكل الخارجي أو الهيكل الجمالي والتصميمي للمنتجات و  تسجيل وحماية الابتكارات المصممة داخل العراق.',NULL,'https://www.cosqc.gov.iq/',6,11,4,'2026-06-10 07:57:20','2026-06-10 08:23:36'),(218,'Photos_IndustrialPropertyPatentOffices/u6qSQy6lb0o46w7lS4JXZNvABjJc29P4jQlxUFRJ.jpg','المكتب الوطني للملكية الفكرية',NULL,'تتم إدارة شؤون الملكية الصناعية في سلطنة عُمان من خلال المكتب الوطني للملكية الفكرية التابع لـ وزارة التجارة والصناعة وترويج الاستثمار. يتولى هذا المكتب تسجيل وحماية كافة حقوق الملكية الصناعية، والتي تشمل براءات الاختراع، العلامات التجارية، والرسوم والنماذج الصناعية.\r\nالمقر :مسقط، سلطنة عمان.\r\nالخدمات :يقوم المكتب بتقديم خدمات التسجيل والحماية القانونية لعدة مجالات رئيسية تشمل:لعلامات التجارية: تسجيل الشعارات، والأسماء التجارية، وعلامات الخدمة لتمييز المنتجات والمنشآت.براءات الاختراع: حماية الابتكارات التقنية والميكانيكية الجديدة ونماذج المنفعة.الرسوم والنماذج الصناعية: حماية المظهر الخارجي أو التصميم الجمالي للمنتجات الصناعية.المؤشرات الجغرافية: حماية وتوثيق المنتجات المرتبطة بمنشأ جغرافي عماني.',NULL,'https://www.tejarah.gov.om/ar',6,12,4,'2026-06-10 08:38:55','2026-06-10 08:38:55'),(219,'Photos_IndustrialPropertyPatentOffices/q7nxssaGdBDqe0heNHaR0F7KCMge8EUIjIgvuKl3.png','الإدارة العامة لحقوق الملكية الفكرية',NULL,'جهة الرسمية المسؤولة عن مكتب الملكية الصناعية في فلسطين هي الإدارة العامة لحقوق الملكية الفكرية التابعة لـ وزارة الاقتصاد الوطني الفلسطيني. يتولى هذا المكتب تنظيم وحماية عناصر الملكية الصناعية، والتي تشمل بشكل أساسي العلامات التجارية، وبراءات الاختراع، والرسوم والنماذج الصناعية.\r\nالمقر : رام الله، فلسطين.',NULL,'https://trademarks.mne.gov.ps/page.aspx?page_key=key_about_inner&lang=ar',6,13,4,'2026-06-10 08:47:20','2026-06-10 08:47:20'),(220,'Photos_IndustrialPropertyPatentOffices/NoIX4z46bBL1WviWUGI5xJ2AmdeeRqkPhPHJDkLj.jpg','إدارة حماية حقوق الملكية الفكرية',NULL,'تتولى إدارة حماية حقوق الملكية الفكرية التابعة لـ وزارة التجارة والصناعة القطرية مهام \"مكتب الملكية الصناعية\" في دولة قطر. وتقوم هذه الإدارة باستقبال وفحص طلبات براءات الاختراع، الرسوم والنماذج الصناعية، والعلامات التجارية.\r\nالمقر :مدينة لوسيل، قطر\r\nالخدمات :تسجيل براءات الاختراع: إيداع الطلبات وفحصها لحماية الابتكارات تقنياً.الرسوم والنماذج الصناعية: حماية المظهر الخارجي أو التصاميم الجمالية للمنتجات.تسجيل العلامات التجارية: قيد الأسماء، والشعارات، والبيانات التجارية الخاصة بالشركات.تجديد براءات الاختراع السنوي: دفع الرسوم السنوية للحفاظ على الحماية القانونية',NULL,'https://www.moci.gov.qa/',6,14,4,'2026-06-10 09:02:36','2026-06-10 09:02:36'),(221,'Photos_IndustrialPropertyPatentOffices/PczLs9YPWScDT8YBlJyrAkEqvvVQpeyB6DdjBLSX.jpg','إدارة براءات الاختراع والعلامات التجارية',NULL,'تتولى إدارة العلاقات التجارية وبراءة الاختراع (المعروفة بـ إدارة براءات الاختراع والعلامات التجارية) التابعة لـ وزارة التجارة والصناعة الكويتية، كامل المسؤولية عن تنظيم وحماية حقوق الملكية الصناعية في دولة الكويت.\r\nالاختصاصات:تشرف الادارة على العلامات التجارية: إصدار شهادات تسجيل العلامات، تجديدها، تعديلها، أو شطبها، بالإضافة إلى البت في طلبات المعارضة.براءات الاختراع: توثيق وإيداع براءات الاختراع، ونشرها في الجريدة الرسمية وفق القوانين المعمول بها.الرسوم والنماذج الصناعية: حماية وتوثيق النماذج والرسوم الصناعية والدوائر المتكاملة.التعاون الخليجي: التنسيق مع الأمانة العامة لمجلس التعاون لدول الخليج العربية لمتابعة تطبيق نظام براءات الاختراع الخليجي.',NULL,'https://www.moci.gov.kw/ar/',6,15,4,'2026-06-10 09:28:42','2026-06-10 09:28:42'),(222,'Photos_IndustrialPropertyPatentOffices/aWfItndGnnfqWOCPusAAtOf17d8WthWvyEuIWEoF.png','مصلحة حماية الملكية الفكرية',NULL,'تعرف الجهة الرسمية المسؤولة عن الملكية الصناعية والتجارية باسم مصلحة حماية الملكية الفكرية، وتتبع مباشرة لـ وزارة الاقتصاد والتجارة اللبنانية. يتولى هذا المكتب تسجيل براءات الاختراع، العلامات التجارية، والرسوم والنماذج الصناعية.\r\nالمقر : بيروت\r\nالخدمات :العلامات التجارية: حماية وتصديق الأسماء والشعارات التجارية لمنع التباسها مع علامات أخرى.براءات الاختراع: إيداع وفحص طلبات الاختراعات الجديدة وإصدار الشهادات الخاصة بها.الرسوم والنماذج الصناعية: تسجيل المظاهر الخارجية المبتكرة للمنتجات الصناعية.',NULL,'https://www.economy.gov.lb/ar/services/intellectual-property-right',6,16,4,'2026-06-10 09:36:34','2026-06-10 09:36:34'),(223,'Photos_IndustrialPropertyPatentOffices/eZ5Hpn5YEGML2CBVluTFSy6Rdd4vsjyBuTnrlJgV.jpg','مكتب الملكية الصناعية',NULL,'يتولى مكتب الملكية الصناعية في ليبيا تنظيم وحماية حقوق الملكية الفكرية والصناعية، وينقسم الاختصاص الإداري فيه إلى جهتين رئيسيتين بحسب نوع المعاملة:\r\nبراءات الاختراع والرسوم والنماذج الصناعية: تتبع إدارياً لـ مركز البحوث الصناعية التابع لوزارة التعليم العالي والبحث العلمي.العلامات التجارية والأسماء التجارية: تتبع لـ وزارة الاقتصاد والتجارة من خلال مصلحة السجل التجاري.\r\nالمقر :طرابلس، ليبيا.\r\nالخدمات:يقدم المكتب بـ مركز البحوث الصناعية الخدمات التالية:استقبال وفحص طلبات براءات الاختراع المحلية والدولية.تسجيل الرسوم والنماذج الصناعية وحمايتها.إصدار شهادات براءات الاختراع بعد استيفاء الشروط القانونية والفنية.',NULL,'https://irc.ly/',6,17,4,'2026-06-10 09:44:27','2026-06-10 09:44:27'),(224,'Photos_IndustrialPropertyPatentOffices/dQK6Wf2Cv0m14otC1YcnoAUwRoRmwG9tUeZXLozY.jpg','الجهاز المصري للملكية الفكرية.',NULL,'تم توحيد مكاتب وإدارات الملكية الصناعية والفكرية في مصر رسميًا تحت مظلة جهة موحدة تسمى الجهاز المصري للملكية الفكرية. حيث نُقلت إليه اختصاصات كل من مكتب براءات الاختراع المصري، وإدارة العلامات التجارية والنماذج الصناعية التابعة لـ جهاز تنمية التجارة الداخلية.\r\nالمقر : القاهرة\r\nالخدمات:',NULL,'https://www.itda.gov.eg/',6,18,4,'2026-06-10 09:55:48','2026-06-10 09:55:48'),(225,'Photos_IndustrialPropertyPatentOffices/oMr8BrV7fN58S61kLiG0pnBhrZElZTe9lEF8APK2.png','المكتب المغربي للملكية الصناعية والتجارية (OMPIC)',NULL,'المكتب المغربي للملكية الصناعية والتجارية (OMPIC)، وهو مؤسسة عمومية تخضع لوصاية وزارة الصناعة والتجارة المغربية. يتولى المكتب حماية حقوق الملكية الصناعية (كبراءات الاختراع والعلامات التجارية) وإدارة السجل التجاري المركزي.\r\nالمقر : الدار البيضاء.\r\nالخدمات :حماية الإبداعات الابتكارية: إصدار براءات الاختراع وحماية الرسوم والنماذج الصناعية.حماية الإشارات المميزة: تسجيل العلامات التجارية وعلامات الخدمة والأسماء التجارية.السجل التجاري المركزي: مسك السجل المركزي وتقديم الشهادات السلبية لتأسيس الشركات.',NULL,'http://www.ompic.ma/ar/content/dwr-lmktb-w-lmhm-lmnwt-bh',6,19,4,'2026-06-10 10:04:20','2026-06-10 10:04:20'),(226,'Photos_IndustrialPropertyPatentOffices/eIwRuOOrGQqPvAUdMfbQcBBy2QBYTuS1e6b62ONM.png','مديرية الملكية الصناعية',NULL,'تتولى مديرية الملكية الصناعية التابعة لـ وزارة المعادن والصناعة الموريتانية مسؤولية حماية حقوق الملكية الفكرية والصناعية داخل البلاد. ونظراً لأن موريتانيا عضو في المنظمة الأفريقية للملكية الفكرية (OAPI)، فإن تسجيل السندات يتبع نظاماً إقليمياً موحداً يمتد أثره القانوني تلقائياً إلى جميع الدول الأعضاء.\r\nالمقر: نواكشوط\r\nالخدمات: تسجيل السندات: تشمل براءات الاختراع والعلامات التجارية والأسماء التجارية، الرسوم والنماذج الصناعية، والمؤشرات الجغرافية.التوثيق: يدعم مركز توثيق الملكية الفكرية بنواكشوط الباحثين والمخترعين والمصنعين عبر توفير المراجع العلمية والقانونية.الربط الإقليمي: تعمل المديرية كـ هيئة وطنية للربط وتنسيق الطلبات مع المكاتب المركزية لـ منظمة OAPI .',NULL,'https://www.commerce.gov.mr/?q=node/1545',6,20,4,'2026-06-10 10:10:44','2026-06-10 10:10:44'),(227,'Photos_CentersExcellenceArtificialIntelligence/uDSOklpnu3gS1L115dhgaMWcdhDwbJv4DV1XyWEj.jpg','جامعة محمد بن زايد للذكاء الاصطناعي','MBZUAI','جامعة محمد بن زايد للذكاء الاصطناعي هي جامعة بحثية للدراسات العليا مكرسة لتعزيز الذكاء الاصطناعي وتسخيره لمصلحة الإنسانية.\r\nوهي تهدف إلى تعليم طلاب من أصحاب المواهب وتطوير قدراتهم، فضلاً عن تعزيز بيئة تشجع الابتكار، وتوفير مؤسسة بحثية استراتيجية داعمة للقطاعين الحكومي والخاص.\r\nوتؤدي الجامعة دوراً جوهرياً في تحقيق العديد من الأهداف الاستراتيجية لدولة الإمارات العربية المتحدة، لاسيما وأن الذكاء الاصطناعي يشكل عنصراً بالغ الأهمية لتحقيق النمو والازدهار مستقبلاً. وتسعى رؤية الجامعة ورسالتها الاستراتيجيتان في آنٍ لترسيخ مكانة أبوظبي كقطب من أقطاب مجتمع الذكاء الاصطناعي الدولي..',NULL,'https://mbzuai.ac.ae/',5,2,2,'2026-06-10 10:12:21','2026-06-10 10:12:21'),(228,'Photos_IndustrialPropertyPatentOffices/oDoEBQEuLM9glgQBIkmvjHOh46LxtyIUmJB5y6xD.jpg','الإدارة العامة لحماية الملكية الفكرية التجارية والصناعية وبراءات الاختراع',NULL,'الإدارة العامة لحماية الملكية الفكرية التجارية والصناعية وبراءات الاختراع تابع وزارة الصناعة والتجارة (المكتب المستقل) - عدن.\r\nالمقر : عدن .\r\nالخدمات :يمتلك مكتبًا مستقلًا لحماية الملكية الفكرية والعلامات التجارية يتطلب إجراءات وتوثيقات منفصلة لضمان حماية العلامات والنماذج في المناطق التابعة لسيطرته.',NULL,'https://moit-ye.com/?page_id=9573',6,21,4,'2026-06-10 10:29:18','2026-06-10 10:29:18'),(229,'Photos_CentersExcellenceArtificialIntelligence/bq8tb8Rh6bvAfpOzZcphCoqrkoL00RaDoPijDGC0.png','المركز المصري للذكاء الاصطناعي',NULL,'أصبح الذكاء الاصطناعي ركيزة أساسية في مسار التحول الرقمي في مصر. ومن هذا المنطلق، تقود وزارة الاتصالات وتكنولوجيا المعلومات الجهود الوطنية لوضع إطار وطني شامل يدمج بين الحوكمة والبنية التحتية وتنمية الكفاءات والبحث العلمي والابتكار في هذا المجال، بما يضمن تبنّي تقنيات الذكاء الاصطناعي على نحو مسؤول ومستدام.\r\n\r\nويرتكز هذا النهج على قناعة راسخة بأن استخدام الذكاء الاصطناعي ينبغي أن يهدف إلى خدمة المجتمع، والارتقاء بجودة الخدمات العامة، ورفع القدرة التنافسية، والمساهمة في تحقيق التنمية المستدامة. ولهذا تحرص مصر على وضع سياسات قائمة على هيكل واضح، والتنسيق بين مؤسسات الدولة، وتعزيز التعاون الدولي، للمساهمة في بناء منظومة داعمة للابتكار، مع ضمان الالتزام بالمعايير الأخلاقية، وترسيخ مبدأ الشفافية، والحفاظ على القيم التي تراعي مصلحة الإنسان.',NULL,'https://mcit.gov.eg/',5,18,2,'2026-06-10 10:29:48','2026-06-10 10:29:48'),(230,'Photos_CentersExcellenceArtificialIntelligence/YDmpJatrvlvHozHvKomyCQ52gZPIx2xGNC6qGvjT.png','مركز الرقمنة من أجل التنمية المستدامة','D4SD','مركز الرقمنة من أجل التنمية المستدامة (D4SD) في المغرب هو مبادرة وطنية وإقليمية أُطلقت سنة 2025 بالشراكة مع برنامج الأمم المتحدة الإنمائي، ويهدف إلى جعل الرقمنة والذكاء الاصطناعي رافعة للتنمية المستدامة، مع التركيز على الصحة، التعليم، المناخ، والحوكمة.',NULL,'https://www.undp.org/fr/morocco',5,19,2,'2026-06-10 11:10:11','2026-06-12 09:01:15'),(231,'Photos_CentersExcellenceArtificialIntelligence/l5Cu9eQvD8RliBSfzOmw1eCpvLLJDys904TifO6f.png','مركز قطر للذكاء الاصطناعي','Qatar Center for Artificial Intelligence (QCAI)','مركز قطر للذكاء الاصطناعي (QCAI)\r\n\r\nتعمل مجموعة مركز قطر للذكاء الاصطناعي (QCAI) التابعة لـ Qatar Computing Research Institute على تطوير الأبحاث في مختلف مجالات الذكاء الاصطناعي، بدءًا من فهم البيانات وتطوير النماذج، وصولًا إلى الاستدلال والتنبؤ واتخاذ القرار.\r\n\r\nيسهم المركز في تعزيز الأسس العلمية للذكاء الاصطناعي من خلال الابتكارات في الخوارزميات، والتعلم متعدد الوسائط، والأنظمة الذكية، كما يقود إنجازات رائدة في مجال الطب الدقيق ويعزز استخدام الذكاء الاصطناعي لخدمة المجتمع وتحقيق المنفعة العامة.\r\n\r\nينشر باحثو المركز أبحاثهم في أبرز المؤتمرات والمجلات العلمية الدولية، ويطوّرون نماذج وأنظمة أولية مبتكرة تسهم في دعم الاكتشاف العلمي، وتحسين الرعاية الصحية، وخدمة المجتمعات حول العالم.','QCRI’s Qatar Center for Artificial Intelligence (QCAI) group advances research across the full AI spectrum — from data understanding and model development to reasoning, prediction, and decision-making. The group strengthens the foundations of AI through innovations in algorithms, multimodal learning, and intelligent systems, while driving breakthroughs in precision medicine and promoting the use of AI for social good. QCAI’s researchers publish in leading international venues and develop prototype systems that empower discovery, improve healthcare, and support communities worldwide.','https://qcai.qcri.org/',5,14,2,'2026-06-10 11:15:43','2026-06-16 08:56:48'),(232,'Photos_CentersExcellenceArtificialIntelligence/iPw02hBy82CiHF4pI3tQLrq2XMEd7yyvGpbJ8Djn.png','الهيئة السعودية للبيانات والذكاء الاصطناعي','(SDAIA)','الهيئة السعودية للبيانات والذكاء الاصطناعي (SDAIA) هي الجهة الوطنية المسؤولة عن قيادة استراتيجية المملكة في مجال البيانات والذكاء الاصطناعي، تأسست سنة 2019 وتُعد من أبرز المؤسسات الإقليمية في هذا المجال، حيث تشرف على المركز الوطني للذكاء الاصطناعي، مكتب إدارة البيانات الوطنية، ومركز المعلومات الوطني.',NULL,'https://sdaia.gov.sa/',5,7,2,'2026-06-10 11:20:51','2026-06-10 11:20:51'),(233,'Photos_CentersExcellenceArtificialIntelligence/0EQAIukeiAiBFtt3lji8CBNIJaGiRZaQSxwAe0r3.png','مركز ذكاء العربية','Arabic AL Center','مركز ذكاء العربية هو أول مركز متخصص في توظيف تقنيات الذكاء الاصطناعي لخدمة اللغة العربية، أطلقه مجمع الملك سلمان العالمي للغة العربية في أبريل 2024 بالرياض، ويهدف إلى تطوير أدوات حاسوبية ومعايير لغوية تعزز حضور العربية في العالم الرقمي.\r\n\r\nويقدم مركز ذكاء العربية مجموعةً من الخدمات المتكاملة والمجانية؛ لتمكين الباحثين والمطورين من أنحاء العالم كله من توظيف تقنيات الذكاء الاصطناعي في المعالجة الآلية للغة العربية، وبناء التطبيقات، والأدوات، والبرامج التي تكفل المحافظة على اللغة العربية.',NULL,'https://arai.ksaa.gov.sa/',5,7,2,'2026-06-10 11:26:00','2026-06-10 11:26:00'),(235,'Photos_CentersExcellenceArtificialIntelligence/2D6UBV6Z6zXzuifUnWXIaDH7G0Gf0NRuLJowD7FF.webp','مدرسة الهندسة الرقمية والذكاء الاصطناعي',NULL,'مدرسة الهندسة الرقمية والذكاء الاصطناعي (EIDIA) هي مدرسة رائدة بجامعة اليوروميد بفاس، مُتخصصة في مجال التقنيات الرقمية وعلوم الذكاء الاصطناعي.\r\n\r\nتتبوأ المركز مكانةً رفيعة كمحور للتميز عند تقاطع هندسة الحاسوب والرياضيات التطبيقية وعلوم البيانات والذكاء الاصطناعي والأنظمة المدمجة الذكية والتقنيات التحويلية (سلسلة الكتل، إنترنت الأشياء، الواقع الممتد...).\r\n\r\nطموحه ثلاثي الأبعاد:\r\n\r\nغير محدد\r\n\r\nغير محدد\r\n\r\nغير محدد\r\n\r\nبفضل منهجية تعليمية قائمة على المشروع، والتطوير الرشيق، وأساليب التعلم عن طريق الممارسة، وارتباط قوي بالنظام البيئي التكنولوجي، فإن طلاب إيديا مُهيأون للعمل في أكثر البيئات ديناميكية وابتكاراً.',NULL,'https://ueuromed.org/ar/etablissements/ecole-d-ingenierie-digitale-et-d-intelligence-artificielle',5,19,2,'2026-06-10 14:36:21','2026-06-10 14:36:21'),(236,'Photos_CentersExcellenceArtificialIntelligence/0gFmLmPTXLMe8aW0e8H2m24T85NAruo8Q4zARCIG.png','AI Movement','null','يُعد المركز الدولي المغربي للذكاء الاصطناعي التابع لـ Mohammed VI Polytechnic University من أهم مراكز البحث في الذكاء الاصطناعي بالمغرب. يهدف إلى تطوير الخبرات المغربية والإفريقية في الذكاء الاصطناعي وعلوم البيانات، وإيجاد حلول للتحديات الاقتصادية والاجتماعية والبيئية مع التركيز على الجوانب الأخلاقية والتطبيقية للذكاء الاصطناعي.',NULL,'https://aim.um6p.ma/',5,19,2,'2026-06-10 14:44:58','2026-06-23 11:24:43'),(238,'Photos_CentersExcellenceArtificialIntelligence/5dsIhnzmstioAnNrMXutCGm10dIGfbdTiwodqGKI.jpg','مركز الاستشراف و الذكاء الاصطناعي التابع لمنظمة الايسيسكو','Center of Foresight and Artificial intelligence','يعتبر مركز الإيسيسكو للاستشراف الاستراتيجي مركز الأبحاث الأول من نوعه في إفريقيا والعالم الإسلامي الذي يتبنى نهجا استشرافيا واستباقيا يستهدف المستويات المحلية والإقليمية والدولية، مما يرسخ مكانته كمركز بارز للخبرة',NULL,'https://icesco.org/ar/areas_of_expertise/the-strategic-foresight-center/',5,19,2,'2026-06-12 09:24:01','2026-06-12 09:25:47'),(239,'Photos_CentersExcellenceArtificialIntelligence/XpMbIBbvK6OeN4AK2LiO4kkQcShG22riqNfGTCyI.png','مركز بحوث العلوم الرقمية والذكاء الاصطناعي','null','يقود مركز بحوث العلوم الرقمية والذكاء الاصطناعي جهود التحول الرقمي من خلال ترسيخ اعتماد الأنظمة والتطبيقات المستقلة والمترابطة، مع الحرص على أن تكون هذه التطبيقات والأنظمة آمنة ومستدامة وعلى قدر عال من الثقة. ويتعاون خبراؤنا اللامعين في مجالات الذكاء الاصطناعي والأمن السيبراني والاتصالات اللاسلكية عن كثب مع مجموعة من المنظمات الدولية، مثل الاتحاد الدولي للاتصالات ومنظمة 3GPP، لإيجاد الحلول العملية المناسبة للتحديات الرئيسية وترك الأثر الإيجابي العميق على المجتمع.',NULL,'https://www.tii.ae/ar/ai-and-digital-science',5,2,2,'2026-06-16 08:03:33','2026-06-23 11:24:35'),(240,'Photos_CentersExcellenceArtificialIntelligence/0hc2AfmRQLRbmR3FiGOymC5CbGuscANPIuUZVYsD.png','مركز التميّز للذكاء الاصطناعي','Hub71 AI Center of Excellence','مركز Hub71 AI Center of Excellence (مركز التميّز للذكاء الاصطناعي) هو كيان ابتكار وتطوير يركّز على الذكاء الاصطناعي وتحليلات الأعمال، مقره في أبوظبي، الإمارات العربية المتحدة. يعمل كنقطة وصل بين الشركات الكبرى، والشركات الناشئة، والقطاع الحكومي لتسريع تبنّي حلول الذكاء الاصطناعي على مستوى',NULL,'https://www.hub71.com',5,2,2,'2026-06-16 08:24:07','2026-06-16 08:24:07'),(241,'Photos_CentersExcellenceArtificialIntelligence/OqxHPdQxs1yLcCtF6iIBlY4BWyeK3aBM8TZvV7wN.jpg','المركز العربي للذكاء الاصطناعي','Arab Center for Artificial Intelligence','المركز العربي للذكاء الاصطناعي هو مؤسسة متخصصة تسعى إلى أن تكون قوة رائدة في تشكيل مستقبل الذكاء الاصطناعي في العالم العربي، من خلال تمكين الأفراد والمؤسسات من الاستفادة من إمكانات الذكاء الاصطناعي وتوظيفها لإحداث تغيير إيجابي ومستدام. ويعمل المركز على تعزيز المعرفة وبناء القدرات وتطوير الابتكار في مجال الذكاء الاصطناعي، بما يسهم في دعم التنمية الاقتصادية والاجتماعية والتكنولوجية في الدول العربية','Arab Center for Artificial Intelligence\r\nTo be a leading force in shaping the future of Artificial Intelligence in the Arab World by empowering individuals and organizations to leverage its potential for positive change.','https://acforai.com/',5,14,2,'2026-06-16 08:43:53','2026-06-26 08:35:21'),(242,'Photos_CentersExcellenceArtificialIntelligence/zWlpTAVJFeEbOn99mznofJyfMuOkVjY1nyuekmOm.png','المعهد العربي للذكاء الاصطناعي (ألفا إنتليجنس للذكاء الاصطناعي)','AI² Institute','المعهد العربي للذكاء الاصطناعي (AI² Institute) هو معهد متخصص في التعليم والتدريب وبناء القدرات في مجال الذكاء الاصطناعي. يهدف إلى تطوير المهارات والكفاءات الرقمية من خلال تقديم برامج تدريبية ودورات متخصصة في الذكاء الاصطناعي وتعلم الآلة وعلوم البيانات، بما يسهم في إعداد الكفاءات القادرة على مواكبة متطلبات التحول الرقمي والاقتصاد المعرفي.',NULL,'https://www.aisquared.ae/ar',5,2,2,'2026-06-16 08:50:59','2026-06-16 08:52:44'),(243,'Photos_CentersExcellenceArtificialIntelligence/W9xnd4o6VO486mmibZPbOjJs0ewmzCvZfhUm6RDr.png','معهد قطر لبحوث الحوسبة (QCRI)','QCRI','يعتزم معهد قطر لبحوث الحوسبة (QCRI)، التابع لجامعة حمد بن خليفة، إطلاق مركز قطر للذكاء الاصطناعي (Q-CAI)، وهي مبادرة تهدف إلى تسريع تطوير تقنيات الذكاء الاصطناعي لخدمة الاحتياجات الوطنية لدولة قطر وتعزيز مكانتها كإحدى الدول الرائدة عالمياً في هذا المجال.\r\nويُعد معهد قطر لبحوث الحوسبة (QCRI) معهداً وطنياً للبحث العلمي، يساهم في دعم دولة قطر في بناء قدراتها في مجالي الابتكار والتكنولوجيا من خلال معالجة التحديات الحاسوبية واسعة النطاق وتطوير حلول تقنية متقدمة ذات أثر إيجابي على حياة الأفراد والمجتمع. ويتميز المعهد بأبحاثه متعددة التخصصات في مجالات الحوسبة والذكاء الاصطناعي وعلوم البيانات والأمن السيبراني، بما يعزز مكانة قطر كمركز إقليمي للبحث والابتكار التكنولوجي.',NULL,'https://qcai.qcri.org/',5,14,2,'2026-06-16 09:51:26','2026-06-16 09:55:52'),(244,'Photos_CentersExcellenceArtificialIntelligence/a1NzfUV5BoJYiaaoXyap4uN9v3VXZkIPBEVBxjiz.png','المركز الوطني للتعليم الإلكتروني','National e-learning Center','تأسس المركز الوطني للتعليم الإلكتروني بموجب قرار من مجلس الوزراء الموقر رقم (35) عام 1439هـ، ليكون جهة مستقلة لضبط جودة التعليم الإلكتروني، حيث يسعى المركز إلى أن يكون مركزاً عالمياً للتميّز في التعليم الرقمي، عبر تسريع وتنسيق بناء منظومة تشاركية، مرنة وسريعة الاستجابة للاحتياجات المتغيرة، ويتمتع المركز بالشخصية الاعتبارية المستقلة مالياً وإدارياً.\r\n\r\nوقد ركّزت استراتيجية المركز على أهدافٍ محورية تهدف إلى ضبط جودة التعليم والتدريب الإلكتروني، تتلخصُ في رسالته: تسريع وتنسيق وتنظيم بناء منظومة تشاركية مرنة وسريعة الاستجابة للاحتياجات المتغيّرة، وتعكس كذلك التزامه بتحقيق رؤيتهِ في أن يكون مركزاً عالمياً للتميّز في التعليم الرقمي، بما يسهم في إحداث أثر مستدام في قطاع التعليم والتدريب الإلكتروني بالمملكة.',NULL,'https://nelc.gov.sa/about',5,7,2,'2026-06-18 08:42:24','2026-06-18 08:42:24'),(247,'Photos_SupportingBodiesScientificResearch/vEWWZXMji5w7yjAmD9vMTA5vxiheLnUkkaNdlF9T.png','المجلس الأعلى للعلوم والتكنولوجيا',NULL,'المجلس الأعلى للعلوم والتكنولوجيا (HCST) هو مؤسسة عامة مستقلة في الأردن تُعنى بتوجيه ودعم منظومة العلوم والتكنولوجيا والبحث العلمي على المستوى الوطني. أُنشئ عام 1987 بموجب القانون رقم 30 ليكون المظلة الوطنية لأنشطة العلوم والتكنولوجيا، ويؤدي دورًا محوريًا في رسم السياسات العلمية ودعم الابتكار وربط البحث العلمي بأهداف التنمية الوطنية.\r\nالمقر : عمان',NULL,'https://www.hcst.gov.jo',6,1,5,'2026-06-24 12:40:50','2026-06-24 12:40:50'),(248,'Photos_SupportingBodiesScientificResearch/DK75a9pI7UrAyUQ39c2zcfQruxeQElOBFUsJOQfk.jpg','الجمعية العلمية الملكية',NULL,'الجمعية العلمية الملكية (Royal Scientific Society – RSS) هي أكبر مؤسسة بحثية تطبيقية مستقلة وغير ربحية في الأردن، وتُعد من أبرز الجهات العلمية والتقنية في المملكة. أُسست عام 1970 بموجب إرادة ملكية بهدف دعم التنمية الوطنية من خلال البحث العلمي، والاستشارات الفنية، والخدمات التقنية المتخصصة.',NULL,'https://www.rss.jo/Default/En',6,1,5,'2026-06-24 12:46:39','2026-06-24 12:46:39'),(249,'Photos_SupportingBodiesScientificResearch/LG1kmzU6r1lERRcfpz1Iwk4p98PUMCDvdbPZkQWg.png','مركز الملكة رانيا للريادة',NULL,'مركز الملكة رانيا للريادة (QRCE) هو منظمة غير ربحية أردنية تُعنى بتطوير ريادة الأعمال والابتكار، خصوصًا في قطاع التكنولوجيا والشركات الناشئة. تأسس عام 2004 ويعمل كمركز وطني للتميز في مجال الريادة، مع ارتباط مؤسسي بـ Princess Sumaya University for Technology، ويُعد أحد أبرز الجهات الداعمة لمنظومة الشركات الناشئة في الأردن.',NULL,'https://qrce.org/en?utm',6,1,5,'2026-06-24 12:52:21','2026-06-24 12:52:21'),(250,'Photos_SupportingBodiesScientificResearch/rxHDr6Qc09O7YcPaRDm81xMONNnyTNm2BvFpWNZz.jpg','صندوق الملك عبد الله الثاني للتنمية',NULL,'صندوق الملك عبد الله الثاني للتنمية (KAFD) هو مؤسسة أردنية غير ربحية أُنشئت بمبادرة ملكية عام 2001 بهدف دعم التنمية المستدامة وتمكين المواطنين في مختلف محافظات الأردن. يركز الصندوق على الاستثمار في الشباب والابتكار وريادة الأعمال، ويعمل بالشراكة مع القطاعين العام والخاص لتنفيذ برامج ومشاريع تنموية ذات أثر اقتصادي واجتماعي.',NULL,'https://www.kafd.jo',6,1,5,'2026-06-24 12:56:07','2026-06-24 12:56:07'),(251,'Photos_SupportingBodiesScientificResearch/QHpQGj3abGBMUEiNA5U38rB69Ipabb1sPhbGvbTS.png','مجلس أبحاث التكنولوجيا المتطورة (ATRC)',NULL,'هو جهة حكومية استراتيجية مقرها أبوظبي تقود توجهات البحث والتطوير في التقنيات المتقدمة داخل الإمارة وتدعم تحول دولة الإمارات إلى اقتصاد قائم على المعرفة والابتكار. تأسس المجلس عام 2020 ويعمل على تحديد أولويات البحث العلمي، وتمويل المبادرات التقنية، وربط الأبحاث بالتطبيقات التجارية والصناعية.',NULL,'https://www.atrc.gov.ae/ar',6,2,5,'2026-06-24 13:01:16','2026-06-24 13:01:16'),(252,'Photos_SupportingBodiesScientificResearch/8oMGJq6grAny5vzXAqerY7sGLk4ZWI9zKAilhEdK.png','مؤسسة دبي للمستقبل',NULL,'مؤسسة دبي للمستقبل هي منظمة حكومية استراتيجية في دولة الإمارات العربية المتحدة أُسست عام 2016 بهدف ترسيخ استشراف المستقبل وتصميمه كجزء من عملية صنع القرار والتنمية في دبي. تعمل المؤسسة على تعزيز مكانة دبي كإحدى المدن الرائدة عالمياً في الابتكار والتقنيات الناشئة والسياسات المستقبلية، من خلال برامج ومبادرات تجمع الحكومات والشركات الناشئة والباحثين ورواد الأعمال ضمن منظومة متكاملة للابتكار.',NULL,'https://www.dubaifuture.ae',6,2,5,'2026-06-24 13:05:33','2026-06-24 13:05:33'),(253,'Photos_SupportingBodiesScientificResearch/BTwJJQNqvXgfnlOQ6JWL3Oh8Fh8vU5n9R6aushem.png','مؤسسة محمد بن راشد للابتكار',NULL,'مؤسسة محمد بن راشد للابتكار، المعروفة دوليًا باسم Mohammed Bin Rashid Innovation Fund (MBRIF)، هي مبادرة اتحادية إماراتية أطلقتها وزارة المالية لدعم المبتكرين والشركات الناشئة ذات الإمكانات العالية. تعمل المؤسسة على تعزيز منظومة الابتكار في دولة الإمارات من خلال التمويل، وبرامج التسريع، والإرشاد، وبناء الشراكات التي تساعد الشركات على النمو والتوسع ومن  خلال لجان وخبراء مستقلين يدرسون الفكرة، والمنتج، ونموذج الأعمال، وإمكانات النمو. كما تعمل بالتعاون مع جهات حكومية ومؤسسات مالية وشركاء من القطاع الخاص لتوفير بيئة داعمة للمبتكرين.\r\nااتاسيس :2015',NULL,'https://mbrif.ae',6,2,5,'2026-06-24 13:53:20','2026-06-24 13:53:20'),(254,'Photos_ScientificResearchInnovationCenters/2SAFm2gB76bsVcXhf3JaBVpt89wTKmUWzjGv7ul2.webp','مركز محمد بن راشد للابتكار الحكومي',NULL,'تأسس مركز محمد بن راشد للابتكار الحكومي لتحفيز وإثراء ثقافة الابتكار في القطاع الحكومي من خلال وضع منظومة متكاملة للابتكار بحيث يصبح ركيزة أساسية من ركائز حكومة دولة الإمارات تطبيقاً لرؤية صاحب السمو الشيخ محمد بن راشد آل مكتوم نائب رئيس الدولة رئيس مجلس الوزراء حاكم دبي الهادفة إلى تطوير العمل الحكومي، وتعزيز تنافسية دولة الإمارات بحيث تكون حكومة دولة الامارات في مصاف الحكومات الأكثر ابتكاراً على مستوى العالم.',NULL,'https://mbrcgi.gov.ae/ar/',5,3,1,'2026-06-24 14:01:46','2026-06-24 14:01:46'),(255,'Photos_SupportingBodiesScientificResearch/oUt2lTiz5LK8DVLJnvWY6e4y73TkE0bBO87MAa1C.jpg','مكتب البحث العلمي',NULL,'هو مكتب تابع  لجامعة الإمارات العربية المتحدة للأبحاث) هو وحدة إدارة ودعم الأبحاث داخل جامعة الإمارات العربية المتحدة . وتساعد في تنسيق تمويل الأبحاث، والمشاريع المدعومة، واستراتيجية البحث، والشراكات التي تدعم دور الجامعة كمؤسسة بحثية رائدة في دولة الإمارات العربية المتحدة، يقدم المكتب الدعم للباحثين طوال دورة البحث، بما في ذلك إعداد المنح، وإدارة البحوث الممولة، وإجراءات الامتثال، ودعم بيانات البحث، والتعاون مع منظمات التمويل الخارجية.\r\nتاسس: عام 1976',NULL,'https://www.uaeu.ac.ae',6,2,5,'2026-06-24 14:04:20','2026-06-24 14:04:20'),(256,'Photos_ScientificResearchInnovationCenters/r2HPyFapNizS9CJScCK3IlisoX5TL8Tu0J9v3wkL.png','مركز مقديشو للبحوث والدراسات',NULL,'مركز مقديشو للبحوث والدراسات هو مركز بحثي وفكري صومالي مستقل تأسس في العاصمة الصومالية مقديشو، ويُعنى بإجراء البحوث والدراسات الاستراتيجية والسياسية والاقتصادية والاجتماعية المتعلقة بالصومال ومنطقة القرن الإفريقي. ويهدف المركز إلى الإسهام في نشر المعرفة العلمية، ودعم صناعة القرار، وتعزيز الحوار الفكري والتنمية المستدامة من خلال الدراسات والتقارير المتخصصة',NULL,'https://mogadishucenter.com/',5,10,1,'2026-06-24 14:16:25','2026-06-24 14:16:25'),(257,'Photos_SupportingBodiesScientificResearch/MeTORoE1oSoZDxKco6fAfXVnYqoR6flCT6qw35J1.jpg','مؤسسة المبرة الخليفية',NULL,'مؤسسة المبرة الخليفية هي منظمة بحرينية غير ربحية تأسست عام 2011 بهدف دعم التعليم وتمكين الشباب البحريني أكاديميًا ومهنيًا. تُعد من أبرز المؤسسات الأهلية في هذا المجال داخل البحرين، حيث تقدم منحًا دراسية وبرامج تطوير مهارات ومبادرات مجتمعية تتماشى مع أهداف التنمية الوطنية ورؤية البحرين 2030، وتشمل أهدافها دعم التعليم، تزويد الشباب بالخبرات المطلوبة لسوق العمل، تعزيز روح الابتكار والإبداع، وتنمية المسؤولية المجتمعية والعمل التطوعي.',NULL,'https://mkfbh.org',6,3,5,'2026-06-24 14:20:51','2026-06-24 14:20:51'),(258,'Photos_SupportingBodiesScientificResearch/4sycfRtIpIBzSrjnla13wNFlrmcfblcHC3oDhvf5.jpg','تمكين',NULL,'(تمكين)، أو صندوق عمل البحرين رسمياً، هي مؤسسة عامة في البحرين تأسست عام 2006 لتعزيز القطاع الخاص وتحسين الفرص المتاحة للأفراد والشركات البحرينية. وهي جزء أساسي من استراتيجية التنمية الاقتصادية في البحرين، حيث توفر التمويل والتدريب ودعم الأجور وبرامج نمو الأعمال التي تهدف إلى زيادة الإنتاجية والمهارات والتوظيف في المملكة.',NULL,'https://www.tamkeen.bh',6,3,5,'2026-06-24 14:42:22','2026-06-24 14:42:22'),(259,'Photos_CentersExcellenceArtificialIntelligence/kNZmqKM9ydF6eLZ4edoPhAaoIslR0cSSOGNDc8LO.jpg','مركز الذكاء الاصطناعي للطاقة','Artificial Intelligence Center for Energy','مركز الذكاء الاصطناعي للطاقة هو مركز سعودي أطلقه وزير الطاقة الأمير عبد العزيز بن سلمان ورئيس الهيئة السعودية للبيانات والذكاء الاصطناعي (سدايا) عبد الله بن شرف الغامدي في 31 يناير 2021 بهدف تحقيق مستهدفات رؤية السعودية 2030 المشتركة بين وزارة الطاقة وسدايا.',NULL,'https://saudipedia.com/%D9%85%D8%B1%D9%83%D8%B2-%D8%A7%D9%84%D8%B0%D9%83%D8%A7%D8%A1-%D8%A7%D9%84%D8%A7%D8%B5%D8%B7%D9%86%D8%A7%D8%B9%D9%8A-%D9%84%D9%84%D8%B7%D8%A7%D9%82%D8%A9',5,7,2,'2026-06-25 08:28:03','2026-06-25 08:31:05'),(260,'Photos_CentersExcellenceArtificialIntelligence/3yw7UIvuduTmCnSrMp31nY50Ft6YMarx7THuqVjG.png','مركز الدراسات المتقدمة في الذكاء الاصطناعي','IA CENTER OF ADVANCED STUDIES','مركز الدراسات المتقدمة في الذكاء الاصطناعي (ذكاء) هو مركز بحثي متخصص في تطوير تقنيات الذكاء الاصطناعي وتطبيقاته، ويتبع وكالة الجامعة للدراسات العليا والبحث العلمي. يهدف المركز إلى دعم منظومة البحث والابتكار في مجال الذكاء الاصطناعي على مستوى الجامعة والقطاعات الوطنية من خلال تقديم خدمات بحثية واستشارية تعتمد على أفضل الممارسات وأحدث المعايير والتقنيات العالمية.',NULL,'https://thakaa.ksu.edu.sa/ar',5,7,2,'2026-06-25 08:42:28','2026-06-25 08:42:28'),(261,'Photos_CentersExcellenceArtificialIntelligence/9DldAuvbDWVBMOOhQSgUCYlYnWGIZVXVB88NMT5k.jpg','دار الذكاء الاصطناعي','Artificial Intelligence House - University of Oran2','دار الذكاء الاصطناعي بجامعة وهران 2 هي فضاء أكاديمي وتكنولوجي أُنشئ بهدف نشر ثقافة الذكاء الاصطناعي وتعزيز البحث العلمي والابتكار داخل الجامعة. تعمل الدار على تطوير مهارات الطلبة والباحثين في مجالات الذكاء الاصطناعي وعلوم البيانات والتعلم الآلي، من خلال تنظيم الدورات التكوينية وورش العمل والندوات العلمية، ودعم المشاريع الابتكارية والشركات الناشئة ذات الطابع التكنولوجي. كما تسعى إلى تعزيز التعاون بين الجامعة والمؤسسات الاقتصادية والصناعية للمساهمة في التحول الرقمي والتنمية المستدامة.',NULL,'https://www.univ-oran2.dz/',5,5,2,'2026-06-25 09:03:03','2026-06-25 09:03:03'),(262,'Photos_SupportingBodiesScientificResearch/sk07MNKvT57YPY1TywO22qXMsh94vLRiqfM35GCE.png','بنك البحرين للتنمية',NULL,'بدأ البنك عملياته عام 1992 بعد تأسيسه بموجب تشريع حكومي في عام 1991. وقد أُوكلت إليه مهمة دعم التنمية الاقتصادية من خلال توفير التمويل والخدمات الاستشارية للمشروعات الصغيرة والمتوسطة ورواد الأعمال، بما يتماشى مع توجهات التنمية الاقتصادية في البحرين.\r\nالمقر: Manama، البحرين\r\nالملكية: حكومية\r\nالاختصاص: تمويل التنمية ودعم الشركات الصغيرة والمتوسطة وريادة الأعمال.',NULL,'https://www.bdb-bh.com/ar/',6,3,5,'2026-06-25 09:05:32','2026-06-25 09:05:32'),(263,'Photos_SupportingBodiesScientificResearch/d9CilBCNHtHh3gUfJDowr8tY71YLQ1fcLwL5Oraj.jpg','مجلس التنمية الاقتصادية البحريني',NULL,'وكالة حكومية بحرينية أُنشئت لقيادة جهود جذب الاستثمار وتعزيز البيئة الاقتصادية في المملكة. يُعد أحد أبرز الجهات المسؤولة عن الترويج للبحرين كمركز إقليمي للأعمال والاستثمار، كما يلعب دورًا مهمًا في دعم التنويع الاقتصادي وتقليل الاعتماد على عائدات النفط.\r\nتاسس عام :2000\r\nلقطاعات الاقتصادية المستهدفةيركز المجلس بشكل أساسي على خمسة قطاعات استراتيجية تمثل ركائز التنويع الاقتصادي للمملكة:الخدمات المالية: الاستفادة من مكانة البحرين كمركز مالي عريق ورائد في المنطقة.الصناعة التحويلية: تعزيز الصادرات والابتكار في قطاعات التصنيع المختلفة.تكنولوجيا المعلومات والاتصالات: دعم التحول الرقمي، الابتكار، والشركات التكنولوجية الناشئة.الخدمات اللوجستية والنقل: استغلال الموقع الجغرافي المتميز للربط بين الأسواق الإقليمية والعالمية.السياحة والاستثمار العقاري: دعم المشاريع الترفيهية والفندقية التي تعزز الجذب السياحي للمملكة .',NULL,'https://www.bahrainedb.com/ar',6,3,5,'2026-06-25 09:14:58','2026-06-25 09:14:58'),(264,'Photos_SupportingBodiesScientificResearch/EBlEfAWIWKYmQn2qY8GXXhbzLlq7yaGoB69l9yem.png','الوكالة الوطنية للنهوض بالبحث العلمي',NULL,'الوكالة الوطنية للنهوض بالبحث العلمي (ANPR) هي مؤسسة عمومية تونسية تعمل تحت إشراف وزارة التعليم العالي والبحث العلمي، وتُعنى بدعم منظومة البحث العلمي والابتكار في تونس. تضطلع بدور الوسيط بين الباحثين والجامعات ومراكز البحث والجهات الممولة الوطنية والدولية، مع التركيز على تعزيز قيمة البحث العلمي وتحويل نتائجه إلى أثر اقتصادي ومجتمعي.',NULL,'https://www.anpr.tn/',6,4,5,'2026-06-25 09:25:56','2026-06-25 09:25:56'),(265,'Photos_SupportingBodiesScientificResearch/WbdlOdgSsQCuPJ89ksAkH3oG3Hhjmsd7eGDawsVZ.jpg','مركز الدراسات والبحوث الاقتصادية والاجتماعية (CERES)',NULL,'مركز الدراسات والبحوث الاقتصادية والاجتماعية (CERES) هو مؤسسة بحثية عمومية تونسية متخصصة في الدراسات الاقتصادية والاجتماعية. تأسس في تونس عام 1962، ويُعد من أقدم مراكز البحث في البلاد، حيث يساهم في إنتاج المعرفة العلمية ودعم البحث الأكاديمي وصياغة التحليلات المتعلقة بقضايا التنمية والمجتمع والاقتصاد في تونس.',NULL,'https://www.facebook.com/ceres.tunisia',6,4,5,'2026-06-25 09:52:28','2026-06-25 09:52:28'),(266,'Photos_SupportingBodiesScientificResearch/IVRvdmp4ThrMPpbiZZELgUmNHH42pIFPF0ZfeggD.jpg','صندوق التشجيع على اللامركزية الصناعية (FOPRODI)',NULL,'هو صندوق تمويل وتحفيز عام تونسي تأسس عام 1973 لدعم ريادة الأعمال والتنمية الصناعية والنمو الاقتصادي الإقليمي. وقد أُنشئ بموجب المادة 45 من قانون المالية التونسي لعام 1974، ولا يزال أحد الآليات الرئيسية في البلاد لتشجيع الاستثمار الصناعي وإنشاء المشاريع الصغيرة والمتوسطة.\r\nتم تصميم الصندوق حول ثلاثة أهداف رئيسية:\r\nخلق جيل جديد من رواد الأعمال ومروجي المشاريع.\r\nدعم إنشاء وتنمية الشركات الصغيرة والمتوسطة في الصناعة والخدمات ذات الصلة بالصناعة والحرف اليدوية.\r\nتشجيع التنمية الإقليمية من خلال تعزيز الاستثمار خارج المراكز الاقتصادية التقليدية.',NULL,'https://www.tunisieindustrie.nat.tn/ar/doc.asp?mcat=4&mrub=155',6,4,5,'2026-06-25 11:00:46','2026-06-25 11:00:46'),(267,'Photos_SupportingBodiesScientificResearch/1P8FXdzAEXezfi7pO26c0YteDWIYWFkBik78wErM.jpg','وكالة الصعود للصناعة والتجديد (APII)',NULL,'وكالة النهوض بالصناعة والتجديد (APII) هي مؤسسة عمومية تونسية تأسست عام 1972 وتعمل تحت إشراف وزارة الصناعة والمناجم والطاقة التونسية. تمثل الوكالة الهيكل الأساسي المعني بتنفيذ سياسة الدولة الخاصة بمساندة وتطوير القطاع الصناعي، دفع الابتكار، ودعم الباعثين والمستثمرين الشبان لتأسيس مشاريعهم.\r\nتشمل مهام الوكالة ما يلي:\r\nتشجيع الاستثمار الجديد.\r\nمساعدة رواد الأعمال على تأسيس الشركات والحرص على اتخاذ الإجراءات القانونية والإدارية.\r\nتوفير قواعد بيانات ومعلومات خاصة بالقطاع الصناعي التونسي.\r\nإعداد الدراسات والمونوغرافيات القطاعية.\r\nدعم المنظمات الصناعية في مجالات التطوير التكنولوجي والتحديث.\r\nإدارة بعض برامج الحوافز والمزايا الاستثمارية المخصصة للمشاريع الصناعية.',NULL,'https://www.tunisieindustrie.nat.tn/ar/doc.asp?mcat=25&mrub=189',6,4,5,'2026-06-25 11:17:02','2026-06-25 11:17:02'),(268,'Photos_SupportingBodiesScientificResearch/2r570MJB6pOfdiTzXBw0wGnaSvr6uti8mPCGBBKF.png','الإدارة العامة للبحث العلمي التكنولوجي (DGRSDT)',NULL,'هي هيئة حكومية جزائرية تابعة لوزارة التعليم العالي والبحث العلمي، تتولى تنسيق وتنفيذ ومتابعة السياسة الوطنية للبحث العلمي والتطوير التكنولوجي. وتُعد أحد الأعمدة الرئيسية لمنظومة البحث والابتكار في الجزائر، \r\nالمهام :تطوير الموارد البشرية العلمية والبحثية.\r\nدعم البحث الجامعي والبحث التطبيقي.\r\nتشجيع الابتكار ونقل التكنولوجيا وتثمين نتائج البحث.',NULL,'https://dgrsdt.dz/ar/about_dgrsdt?utm_source=chatgpt.com',6,5,5,'2026-06-25 11:31:02','2026-06-25 11:31:02'),(269,'Photos_SupportingBodiesScientificResearch/lj5V5R7JyVehWTIkoExG0KDSYA89AHNMncN3XsSx.jpg','التخصصية للبحث في العلوم والتكنولوجيا (ATRST)',NULL,'منظمة بحثية عامة جزائرية تدعم وتنسق البحث العلمي والتطوير التكنولوجي في مجالات العلوم والتكنولوجيا. وتعمل الوكالة تحت إشراف هيئات البحث العلمي الجزائرية، وتضطلع بدور محوري في تخطيط وتمويل وتقييم وتعزيز البرامج البحثية التي تتماشى مع الأولويات الوطنية.\r\nتأسست عام 1995.\r\nالوظائف الرئيسية:\r\nبرمجة البحوث: تحديد وتنسيق مواضيع البحوث ذات الأولوية.\r\nتمويل المشاريع: تخصيص الموارد لمشاريع البحث المعتمدة.',NULL,'https://atrst.dz/',6,5,5,'2026-06-25 11:40:22','2026-06-25 11:40:22'),(270,'Photos_SupportingBodiesScientificResearch/8GAItVXWQq3i8m5uO1yfiiIogJUBpjIL3jRsZ8HN.png','مركز تنمية التكنولوجيا المتطورة (CDTA)',NULL,'عمل المركز تحت إشراف وزارة التعليم العالي والبحث العلمي الجزائرية، ويُعد أحد المراكز الرئيسية للبحث والتطوير في مجال التقنيات المتقدمة في البلاد، حيث يدعم البحث العلمي والابتكار ونقل التكنولوجيا والتدريب المتخصص ،يعمل المركز بشكل وثيق مع الجامعات والهيئات الحكومية والشركاء الصناعيين لتحويل البحوث إلى تطبيقات عملية تساهم في التنمية الاقتصادية والتكنولوجية للجزائر.\r\nتأسس المركز عام 1988.',NULL,'https://www.cdta.dz/ar',6,5,5,'2026-06-25 11:52:11','2026-06-25 11:52:11'),(271,'Photos_SupportingBodiesScientificResearch/URrZUgX8rz3Rt99tXYONf8pP6XKU6YdjbwH62QtZ.png','الوكالة الوطنية لثمين الباحثة الكائنة (ANVREDET)',NULL,'هي منظمة عامة جزائرية تُعنى بتعزيز الاستخدام العملي للبحوث العلمية من خلال ربط الباحثين والجامعات والشركات الناشئة والقطاع الصناعي. وتضطلع الوكالة بدور محوري في منظومة الابتكار الجزائرية عبر دعم نقل التكنولوجيا والملكية الفكرية وريادة الأعمال، بهدف تحويل البحوث إلى قيمة اقتصادية واجتماعية.\r\nمن اهدافها:\r\nنقل التكنولوجيا من الجامعات ومراكز الأبحاث إلى الشركات.\r\nدعم الابتكار للباحثين ورواد الأعمال و تسويق نتائج البحوث.\r\nحماية الملكية الفكرية ، بما في ذلك براءات الاختراع وحقوق الابتكار الأخرى.\r\nاحتضان المشاريع وتوجيهها للمشاريع الابتكارية',NULL,'https://anvredet.org.dz/',6,5,5,'2026-06-25 12:03:18','2026-06-25 12:03:18'),(272,'Photos_SupportingBodiesScientificResearch/QAJb4uxSYkDiUReQKKR7wFDbMSL3gNw6lwUtmJwu.png','صندوق الإيداع (CDD)','CDD','صندوق الودائع والتنمية (CDD) هو مؤسسة مالية عامة موريتانية تدير الودائع وتدعم تمويل التنمية الوطنية طويلة الأجل. تأسس الصندوق عام 2011، ويعمل باستقلالية مالية تحت إشراف أعلى السلطات في البلاد، ويلعب دورًا هامًا في تمويل أولويات السياسة العامة والاستثمار الإنتاجي.\r\nتاسس عام : 2011\r\nتمول مشاريع تتماشى مع أولويات التنمية الحكومية.',NULL,'https://cdd.gov.mr/',6,20,5,'2026-06-25 12:14:08','2026-06-25 12:15:35'),(273,'Photos_SupportingBodiesScientificResearch/pa1Ua8HWca3WyZbvS0yjfMNCkL2QWBHVyZrdgxFI.png','الوكالة الوطنية للبحث العلمي',NULL,'الوطنية للبحث العلمي والابتكار (ANRSI) هي الوكالة الوطنية في موريتانيا المسؤولة عن تعزيز البحث العلمي والابتكار. وتضطلع بدور محوري في تمويل البحوث، وتعزيز التعاون بين الباحثين والمؤسسات، ودعم الابتكار بما يتماشى مع أولويات التنمية في البلاد.\r\n مهامها:دعم البحث العلمي من خلال برامج التمويل ودعوات تقديم المقترحات التنافسية.\r\nتشجيع الابتكار الذي يلبي الاحتياجات الاقتصادية والاجتماعية والثقافية للبلاد.\r\nمراقبة وتقييم المشاريع البحثية التي تمولها الوكالة.\r\nتعزيز نشر نتائج البحوث وتسويقها .\r\nتقييم أثر الاستثمار العام في البحث العلمي والابتكار.',NULL,'https://anrsi.mr/',6,20,5,'2026-06-25 12:38:24','2026-06-25 12:38:24'),(274,'Photos_SupportingBodiesScientificResearch/ehNNdcUNjRhAow0n7bsOCeY1BRLzV8UnHiICCAMX.jpg','صندوق الأمم المتحدة الإنمائي (UNDP) - موريتانيا',NULL,'يُعدّ برنامج الأمم المتحدة الإنمائي في موريتانيا المكتب القطري لوكالة الأمم المتحدة العالمية للتنمية. ويعمل البرنامج مع حكومة موريتانيا، ووكالات الأمم المتحدة، والمجتمع المدني، وشركاء التنمية، لتعزيز التنمية المستدامة، وتقوية المؤسسات، والحد من الفقر، وتحسين القدرة على الصمود. وينشط البرنامج في موريتانيا منذ ستينيات القرن الماضي، ويُواءم عمله مع أولويات التنمية الوطنية في البلاد وأهداف التنمية المستدامة .',NULL,'https://www.undp.org/ar/arab-states',6,20,5,'2026-06-25 12:49:12','2026-06-25 12:49:12'),(275,'Photos_SupportingBodiesScientificResearch/YyjIC76zQnfqbD92vXajvmDzil8UfaRHPmOWkcA0.png','المجلس الأعلى للبحث العلمي والابتكار',NULL,'المجلس الأعلى للبحث العلمي والابتكار هو هيئة وطنية رفيعة المستوى في موريتانيا تُعنى بتوجيه السياسات العامة للبحث العلمي والابتكار وتنسيق الأولويات الاستراتيجية في هذا المجال. ويؤدي المجلس دورًا محوريًا في تنفيذ الاستراتيجية الوطنية للبحث العلمي والابتكار، من خلال متابعة الإصلاحات وتقديم التوصيات المتعلقة بتمويل البحث، وبناء القدرات، وتعزيز الابتكار.\r\nالدور والمهام\r\nيعمل المجلس على وضع التوجهات الاستراتيجية للبحث العلمي والابتكار، ومتابعة تنفيذ السياسات الوطنية، وتعزيز التنسيق بين الجهات الحكومية والجامعات ومؤسسات البحث. كما يشرف على دراسة التوصيات المتعلقة بتطوير منظومة البحث العلمي، بما في ذلك الحوكمة، والتمويل، وآليات المتابعة والتقييم.\r\nملاحظة:مجلس الأعلى للبحث العلمي والابتكار في موريتانيا عبارة عن هيئة استشارية وتوجيهية عليا يرأسها الوزير الأول، وبالتالي لا يمتلك موقعاً إلكترونياً مستقلاً خاصاً به.',NULL,'https://prs-mesrs.gov.mr/ar/',6,20,5,'2026-06-25 13:01:34','2026-06-25 13:01:34'),(276,'Photos_SupportingBodiesScientificResearch/Sa2cPL3BlhWvfYvC8zimSyWmzY2PpjDqC9LElBTs.png','صندوق التنمية الاجتماعية الجيبوتي (ADDS)',NULL,'العربية باسم صندوق التنمية الاجتماعية الجيبوتي ، هي وكالة حكومية تابعة لحكومة جيبوتي، تُعنى بالحد من الفقر وتحسين التنمية الاجتماعية والاقتصادية. تأسست الوكالة عام 2007، وتُعدّ جهة تنفيذية رئيسية لبرامج التنمية الممولة وطنياً ودولياً، \r\nمهام الصندوق:دعم ADDS مجموعة واسعة من أنشطة التطوير، بما في ذلك:\r\nالبنية التحتية الأساسية ، مثل المدارس والمرافق الصحية وشبكات المياه والبنية التحتية المجتمعية.\r\nالتوظيف وسبل العيش ، بما في ذلك التدريب المهني، ودعم ريادة الأعمال، والأنشطة المدرة للدخل',NULL,'https://www.adds.dj/agence/mot-du-directeur-general/',6,6,5,'2026-06-25 13:40:33','2026-06-25 13:40:33'),(277,'Photos_SupportingBodiesScientificResearch/D1LYNbALD9R7oqUv0W5YQ4ePEKdHCTQfc08yeL7K.png','مركز الدراسات والبحوث في جيبوتي (CERD)',NULL,'هي المؤسسة الوطنية العامة الرئيسية للبحث العلمي في جمهورية جيبوتي. يتبع وزارة التعليم العالي والبحث، ويتمتع بالشخصية الاعتبارية والاستقلال المالي والإداري، ويقود برامج بحثية تخدم أولويات التنمية الوطنية في مجالات العلوم الطبيعية والإنسانية والتكنولوجي .\r\nتاسس عام :1979\r\nالمهام الرئيسية:\r\nإجراء البحوث العلمية والتطوير التكنولوجي بما يتوافق مع أولويات الحكومة.\r\nنشر المعرفة العلمية وإصدار الأبحاث وتوفير المعلومات العلمية والتقنية.\r\nدعم الباحثين والمؤسسات الوطنية وتعزيز التدريب والتعاون العلمي.\r\nإقامة شراكات مع الجامعات ومراكز البحث داخل جيبوتي وخارجها.',NULL,'https://www.cerd.dj/cerd.html',6,6,5,'2026-06-25 13:56:12','2026-06-25 13:56:12'),(278,'Photos_CentersExcellenceArtificialIntelligence/49GMeYn2bJeigXGe82Ifdd8UDMqrrkw1lcowZ5rN.jpg','مركز حوسبة للذكاء الاصطناعي','null','مركز حوسبة للذكاء الاصطناعي هو  أول مركز حوسبة عالي الأداء للذكاء الاصطناعي في الجزائر, الذي أشرف عليه وزير البريد والمواصلات السلكية واللاسلكية بوهران, على وضع حجر أساسه, خطوة استراتيجية نحو السيادة الرقمية. \r\nويهدف إلى توفير قدرات حوسبة عالية للباحثين والشركات الناشئة والمؤسسات الوطنية لتطوير تطبيقات الذكاء الاصطناعي في الصحة والصناعة والأمن السيبراني والمدن الذكية.',NULL,'https://univ-oran1.dz/',5,5,2,'2026-06-25 14:23:08','2026-06-25 14:26:22'),(279,'Photos_CentersExcellenceArtificialIntelligence/fVZY3VOu73gWUTvCGqkV1VS8nZhkxjK03QDzi5Ef.jpg','المدرسة الوطنية العليا للذكاء الاصطناعي',NULL,'المدرسة الوطنية العليا للذكاء الاصطناعي (ENSIA) هي مؤسسة امتياز للتعليم العالي تتمثل مهمتها في تدريس المهندسين المتخصصين في نظرية الذكاء الاصطناعي وعلوم البيانات تهدف الى ان تكون لها القدرة على تطوير ونشر حلول عملية ومبتكرة لمشاكل القطاعات الاجتماعية والاقتصادية المختلفة (الصحة ، الطاقة ، الزراعة ، النقل ، إلخ) ، مما يساهم في التنمية العلمية والاقتصادية للجزائر.',NULL,'https://www.ensia.edu.dz/',5,5,2,'2026-06-25 14:29:48','2026-06-25 14:29:48'),(280,'Photos_SupportingBodiesScientificResearch/zPNV8VorMRWfpNMQ2OGYMlv2o6uwyFZllmCgOmds.jpg','هيئة تنمية البحث والتطوير والابتكار',NULL,'هيئة تنمية البحث والتطوير والابتكار هي جهة حكومية سعودية تقود تطوير منظومة البحث العلمي والتطوير والابتكار في المملكة. أُنشئت لدعم مستهدفات رؤية السعودية 2030 من خلال تنسيق السياسات، وتمويل المبادرات، وتعزيز التعاون بين الجامعات، ومراكز الأبحاث، والقطاع الخاص، والجهات الحكومية.\r\nالمهام :اقتراح التشريعات والتنظيمات التي تدعم نمو القطاع.\r\nتقديم برامج التمويل والمنح للباحثين والمشروعات الابتكارية.\r\nتعزيز الشراكات بين الأوساط الأكاديمية والصناعة لتسريع نقل المعرفة والتقنيات إلى تطبيقات عملية. \r\nتاسست عام :2021',NULL,'https://x.com/SaudiRDI',6,7,5,'2026-06-25 14:30:57','2026-06-25 14:30:57'),(281,'Photos_CentersExcellenceArtificialIntelligence/G05dCeFqxltuybpBUvLzBv2zEhI4EhugTciTBMck.png','كلية الذكاء الاصطناعي',NULL,'كلية الذكاء الاصطناعي – جامعة بغداد (العراق) هي كلية أكاديمية متخصصة أُنشئت لتأهيل الكفاءات في مجالات الذكاء الاصطناعي والبيانات الضخمة والتطبيقات الهندسية والطبية الحيوية، وتهدف الى دعم البحث العلمي والابتكار التقني بما يسهم في التحول الرقمي والتنمية المعرفية في العراق.',NULL,'https://coai.uobaghdad.edu.iq/',5,11,2,'2026-06-25 14:40:36','2026-06-25 14:40:36'),(282,'Photos_CentersExcellenceArtificialIntelligence/heZyyfq8xRt2mxiUoCRI5HdvRC5tBdJ6R1insCav.png','أكاديمية الذكاء الاصطناعي','AI Academy','أكاديمية الذكاء الاصطناعي هي شركة ناشئة رائدة ومكرسة لتعزيز المعرفة والابتكار في مجال الذكاء الاصطناعي وعلوم الحاسوب. نقدم تدريبًا وتعليمًا شاملًا في المجالات العلمية والمهنية لجماهير متنوعة تشمل الأطفال والشباب والمحترفين والخريجين الجدد والمؤسسات.\r\nتهدفالى  سد الفجوة بين المعرفة النظرية والتطبيقات العملية للذكاء الاصطناعي، وتمكين الطلاب من تسخير قوة الذكاء الاصطناعي لحل المشكلات العملية ودفع الابتكار في مختلف القطاعات والمراحل العمرية.',NULL,'https://www.aiaj.xyz/',5,13,2,'2026-06-25 14:47:05','2026-06-25 14:48:12'),(283,'Photos_SupportingBodiesScientificResearch/FgO39o5z08M29tBPuLWc7UF2imSk4zUYzVbEXins.jpg','مدينة الملك عبدالعزيز للعلوم والتقنية (KACST)',NULL,'مدينة الملك عبد العزيز للعلوم والتقنية (KACST) هي المنظمة الوطنية للعلوم والتقنية في المملكة العربية السعودية، ومقرها الرياض . تأسست عام 1977 وأعيد تسميتها إلى KACST عام 1985، وتُعد مركزًا رئيسيًا للبحث العلمي والابتكار وسياسة البحث الوطنية، وتلعب دورًا محوريًا في تطوير منظومة البحث والتطوير في المملكةو تدعم   البحوث العلمية والتطبيقية ، وتموّل المشاريع البحثية، وتطور المبادرات التكنولوجية الوطنية، وتقدم المشورة للحكومة السعودية بشأن سياسات العلوم والتكنولوجيا. كما تدير مختبرات وطنية، وتتعاون مع الجامعات والهيئات الحكومية والقطاع الخاص لتعزيز البحث والتطوير والابتكار في جميع أنحاء المملكة.',NULL,'https://www.kacst.gov.sa/',6,7,5,'2026-06-26 07:50:36','2026-06-26 07:50:36'),(284,'Photos_SupportingBodiesScientificResearch/feKIIHEoY3ofRkLeYGlCvbJ8WpcLsLaVZAnvSxOe.png','صندوق التعليم العالي الجامعي للبحث والابتكار',NULL,'هو منظمة حكومية سعودية مستقلة إداريًا وماليًا تُعنى بدعم وتطوير التعليم الجامعي من خلال تنمية الموارد المالية والاستثمار وتمويل المبادرات ذات الأولوية. ويؤدي الصندوق دورًا مهمًا في تعزيز الاستدامة المالية للجامعات الحكومية بما يتماشى مع مستهدفات رؤية المملكة 2030، مع التركيز على رفع جودة التعليم والبحث والابتكار.\r\nاهداف الصندوق:يركز الصندوق على تنويع مصادر تمويل الجامعات وتقوية مواردها الذاتية، إلى جانب تمويل المشاريع التي لا يمكن تغطيتها من الميزانيات التشغيلية المعتادة. كما يعمل على استقطاب مساهمات القطاع الخاص لدعم البرامج الأكاديمية، والمراكز البحثية، والمنح الدراسية،',NULL,'https://hef.gov.sa/about/',6,7,5,'2026-06-26 08:01:30','2026-06-26 08:01:30'),(286,'Photos_SupportingBodiesScientificResearch/eHGj83ZATphoM9bcAk0kNBc26og1T7aS9EOz2bYU.jpg','مؤسسة موهبة',NULL,'هي مؤسسة سعودية وقفية غير إختيارية تُعنى باكتشاف ورعاية الموهوبين، مع تركيز خاص على المجالات العلمية والتقنية المتنوعة. ويعد من أبرز الممثلين في المملكة الذين يعملون على بناء المبدعين الشباب وتأهيلهم للمنافسة المحلية بشكل مباشر ،تأسست المؤسسة عام 1999 (1420هـ) بأمر ملكي، ثم توسع النطاق لاحقًا ليشمل دعم الموهبة بشكل أشمل، وليس فقط رعاية الطلاب الموهوبين. وهي إحدى منشآت اليوم التابعة لمؤسسة الملك عبدالله الإنسانية، وتسعى إلى إكس العقول الشابة المتميزة من خلال شراكات وبرامج متخصصة متخصصة مع مستهدفات رؤية السعودية 2030 .',NULL,'https://www.mawhiba.sa/',6,7,5,'2026-06-26 08:36:40','2026-06-26 08:36:40'),(287,'Photos_SupportingBodiesScientificResearch/0pIQgSP6kKWFQ8FFSU0JPyogUKGeLnE3lwWoj9h6.jpg','صندوق الاستثمارات العامة (PIF)',NULL,'صندوق الاستثمارات العامة (PIF) هو صندوق الثروة السيادية للمملكة العربية السعودية . وهو أحد أكبر صناديق الاستثمار المملوكة للدولة في العالم، ويلعب دورًا محوريًا في تمويل التنويع الاقتصادي، وتطوير الصناعات الاستراتيجية، والنهوض بأهداف التنمية طويلة الأجل للبلاد في إطار رؤية 2030 .\r\nتأسس: عام 1971م\r\nالاهداف: تحفيز النمو الاقتصادي، وخلق فرص العمل، وجذب الاستثمارات الخاصة، وتطوير قطاعات جديدة في المملكة العربية السعودية. وقد أصبح الصندوق أداة رئيسية للمشاريع التي تهدف إلى تقليل اعتماد المملكة على عائدات النفط.',NULL,'https://www.pif.gov.sa/ar/',6,7,5,'2026-06-26 08:42:54','2026-06-26 08:42:54'),(288,'Photos_SupportingBodiesScientificResearch/ssQ1gZhg6NRbN9ngRHyLHJMZhIAiGoPDCExc66fx.png','المركز القومي للبحوث',NULL,'معلومات أساسية\r\nالاسم العربي: المركز القومي للبحوث\r\nالاسم الإنجليزي: National Centre for Research (NCR)\r\nالمقر الرئيسي: الخرطوم، السودان.\r\nالتأسيس: 1991 (امتدادًا للمجلس القومي للبحوث الذي تأسس عام 1970).\r\nالجهة المشرفة: وزارة التعليم العالي والبحث العلمي السودانية.\r\nالمهمة الأساسية: إجراء البحوث العلمية والتطبيقية لخدمة التنمية في السودان و \r\nوتطوير التقنيات الملائمة للبيئة المحلية، ودعم الابتكار، وتدريب الباحثين. كما أنه عضو في عدد من الشبكات العلمية الدولية، ويعمل على تعزيز التعاون البحثي الإقليمي والدولي.',NULL,'https://ncr.gov.sd/',6,8,5,'2026-06-26 09:16:17','2026-06-26 09:16:17'),(290,'Photos_SupportingBodiesScientificResearch/DVBp0e7pZhr5pWA40ehFTNPcM6P35G1rmZson7ff.png','المركز الصناعي للبحوث والاستشارات (IRCC)',NULL,'هو مؤسسة سودانية وطنية للبحث والتطوير والاستشارات الصناعية. أُنشئ عام 1965 بدعم من منظمة الأمم المتحدة للتنمية الصناعية (UNIDO)، ويُعد الذراع الفني لوزارة الصناعة السودانية مع استقلال مالي وتنظيمي بموجب قانون عام 1981.\r\nيهدف المركز :إلى دعم التنمية الصناعية في السودان من خلال البحث العلمي التطبيقي، ونقل التكنولوجيا، وتقديم الاستشارات الفنية للقطاعين العام والخاص. ويركز على تحسين استغلال الموارد المحلية، وزيادة القيمة المضافة للصناعات الوطنية، وتعزيز القدرة التنافسية للمنتجات السودانية،',NULL,'https://ircc.gov.sd/about-us-ar',6,8,5,'2026-06-26 09:21:14','2026-06-26 09:21:14'),(291,'Photos_CentersExcellenceArtificialIntelligence/QZ3SOOQNvpyyKOIBDTnulpt0vfr0u9Vj1eUZSqcy.png','المركز الدولي لأبحاث وأخلاقيات الذكاء الاصطناعي','ICAIRE','المركز الدولي لأبحاث وأخلاقيات الذكاء الاصطناعي (ICAIRE) هو مركز دولي من الفئة الثانية تحت رعاية منظمة اليونسكو، يتخذ من الرياض مقراً له، ويهدف إلى تعزيز البحث العلمي في مجال الذكاء الاصطناعي، وترسيخ المبادئ الأخلاقية والمسؤولة لاستخدامه على المستوى العالمي. يعمل المركز على دعم التعاون الدولي، وبناء القدرات، وتطوير السياسات والمعايير الأخلاقية، وتشجيع الابتكار والبحث العلمي بما يسهم في تحقيق أهداف التنمية المستدامة، وبما يتوافق مع توصية اليونسكو بشأن أخلاقيات الذكاء الاصطناعي. كما يطلق مبادرات وبرامج دولية لنشر المعرفة، وتأهيل الكفاءات، وتعزيز الاستخدام الآمن والمسؤول لتقنيات الذكاء الاصطناعي لخدمة المجتمعات.',NULL,'https://icaire.org/ar/default.aspx',5,7,2,'2026-06-26 09:23:09','2026-06-26 09:23:09'),(292,'Photos_CentersExcellenceArtificialIntelligence/2Fu0890qcxAgtiZVVsAgdhyoKzPCrbYdJMZ6khRe.png','مركز دبي لاستخدامات الذكاء الاصطناعي','Dubai Centre for Artificial Intelligence','مركز دبي لاستخدامات الذكاء الاصطناعي هو مبادرة أطلقتها مؤسسة دبي للمستقبل بهدف تسريع تبني تطبيقات الذكاء الاصطناعي في القطاع الحكومي، وترسيخ مكانة دبي كإحدى المدن العالمية الرائدة في تطوير واستخدام تقنيات الذكاء الاصطناعي. يعمل المركز على تطوير السياسات والتشريعات الداعمة، وبناء القدرات الوطنية، وتعزيز الابتكار، وإطلاق المشاريع التجريبية، ودعم الشراكات مع الشركات الناشئة والمؤسسات التقنية، بما يسهم في تحسين الخدمات الحكومية ورفع كفاءة الأداء والإنتاجية، وتعزيز جاهزية دبي للتحولات المستقبلية في مختلف القطاعات.',NULL,'https://www.dubaifuture.ae/ar/dubai-centre-for-artificial-intelligence/',5,2,2,'2026-06-26 09:50:35','2026-06-26 09:50:35'),(293,'Photos_SupportingBodiesScientificResearch/jJrKx8ShwXP9A7PQg9y2GpX67Rp61OTxmFskge7g.jpg','صندوق دعم الطلاب',NULL,'هو مؤسسة حكومية سودانية تُعنى بتقديم خدمات الرعاية لطلاب مؤسسات التعليم العالي، مع تركيز خاص على السكن والدعم الاجتماعي والصحي والمالي. ويُعد من أبرز الجهات الحكومية التي تدير خدمات الرعاية الطلابية على مستوى البلاد.\r\nتاسس عام :1990\r\nالمهام:إدارة المجمعات السكنية الجامعية، وتقديم برامج الكفالة والتسليف للطلاب المستحقين وفق معايير محددة، إضافة إلى خدمات الإرشاد النفسي، والرعاية الصحية، ودعم الطلاب ذوي الإعاقة بالأجهزة والمساعدات المناسبة. ووفقًا للمعلومات المنشورة من الصندوق، فإنه يشرف على مئات الوحدات السكنية ويقدم خدماته لمئات الآلاف من المستفيدين عبر برامجه المختلفة.',NULL,'https://nswf-sd.org/author/ala/',6,8,5,'2026-06-26 09:59:41','2026-06-26 09:59:41'),(294,'Photos_CentersExcellenceArtificialIntelligence/YcSXPoCRwzOrvNFHsr14OF9rOeKbW3sYibJevU7w.jpg','المعهد العالي للرقمنة',NULL,'المعهد العالي للرقمنة (SupNum) هو مؤسسة تعليم عالٍ حكومية متخصصة في مجالات الرقمنة وتكنولوجيا المعلومات، وتتبع منظومة التعليم العالي في موريتانيا. \r\nأُنشئ المعهد بهدف إعداد كفاءات وطنية مؤهلة في تخصصات التحول الرقمي والذكاء الاصطناعي وعلوم البيانات والأمن السيبراني وهندسة البرمجيات، بما يواكب متطلبات الاقتصاد الرقمي وسوق العمل. كما يركز على دعم البحث العلمي والابتكار، وإقامة شراكات مع الجامعات والمؤسسات الدولية، وتنظيم برامج تدريبية ومشاريع تطبيقية لتعزيز المهارات الرقمية وريادة الأعمال، والمساهمة في تسريع التحول الرقمي في موريتانيا. ويقدم المعهد برامج أكاديمية ومهنية متخصصة، من بينها ماجستير في هندسة البيانات وتعلم الآلة، إضافة إلى مبادرات لتأهيل الشباب في المهن الرقمية بالتعاون مع منظمات دولية.',NULL,'https://supnum.mr/',5,20,2,'2026-06-26 10:11:16','2026-06-26 10:11:16'),(295,'Photos_CentersExcellenceArtificialIntelligence/asoT9WjTb7HNk2KqS0myvARjYdXWSc4SDgTmZ57K.jpg','المركز الوطني العراقي للذكاء الاصطناعي','National Center for Artificial Intelligence','المركز الوطني العراقي للذكاء الاصطناعي هو جهة حكومية تابعة لمكتب رئيس مجلس الوزراء في جمهورية العراق، تُعنى بقيادة جهود التحول الرقمي وتعزيز تبني تقنيات الذكاء الاصطناعي في مختلف القطاعات الحكومية والتنموية. يهدف المركز إلى إعداد وتنفيذ الاستراتيجية الوطنية للذكاء الاصطناعي، وبناء بيئة وطنية داعمة للابتكار والبحث العلمي، وتطوير الكفاءات البشرية، وتعزيز الشراكات مع الجامعات والمؤسسات البحثية والقطاع الخاص، إلى جانب دعم تطوير البنية التحتية الرقمية وتطبيقات الذكاء الاصطناعي في مجالات التعليم والصحة والزراعة والصناعة والخدمات الحكومية، بما يسهم في تحقيق التنمية المستدامة وبناء اقتصاد رقمي قائم على المعرفة.',NULL,'https://nc.ai.gov.iq/',5,11,2,'2026-06-26 10:17:29','2026-06-26 10:17:29'),(296,'Photos_CentersExcellenceArtificialIntelligence/19LOOVBhNgT3ElgVSb1fHzhq2GQ6fEmdMpNRPwjO.png','دار الذكاء الاصطناعي','AI House  University Center of Illizi','دار الذكاء الاصطناعي هي فضاء علمي وابتكاري تابع للمركز الجامعي بإليزي في الجزائر، أُنشئت بهدف نشر ثقافة الذكاء الاصطناعي وتعزيز البحث العلمي والابتكار في هذا المجال. تعمل الدار على توفير بيئة تعاونية للطلبة والباحثين والأساتذة لتطوير مشاريع وحلول قائمة على تقنيات الذكاء الاصطناعي، كما تنظم دورات تدريبية وورش عمل وندوات ومسابقات علمية تسهم في تنمية المهارات الرقمية وبناء القدرات. وتسعى إلى تشجيع ريادة الأعمال، وتعزيز التعاون مع الجامعات والمؤسسات الاقتصادية والبحثية، ودعم التحول الرقمي من خلال توظيف تطبيقات الذكاء الاصطناعي في مختلف المجالات التنموية، بما يخدم احتياجات المجتمع والاقتصاد الوطني.',NULL,'https://www.cuillizi.dz/ai_house/',5,5,2,'2026-06-26 10:26:19','2026-06-26 10:26:19'),(297,'Photos_SupportingBodiesScientificResearch/TuEZIZU4wRPxgy0AkjbQ3qF98MF0Ii8dA2U6btT4.jpg','مؤسسة الدراسات السودانية',NULL,'مؤسسة الباحثين السودانيين (SRF) هي منظمة علمية سودانية تطوعية غير حكومية وغير ربحية، تُعنى بتعزيز البحث العلمي والتعليم والتعاون بين الباحثين السودانيين.\r\nتاسس في عام :2009\r\nيهدف صندوق البحوث السوداني : إلى تعزيز بيئة البحث العلمي في السودان من خلال بناء مهارات الباحثين، وتشجيع التعاون العلمي، وإبراز الإنجازات البحثية السودانية.',NULL,'https://www.sudaneseresearchers.org/',6,8,5,'2026-06-26 10:33:02','2026-06-26 10:33:02'),(298,'Photos_CentersExcellenceArtificialIntelligence/jZ9fIZIPiINfvgTSwKkhngGVls3Er9mtxj1M4E7J.png','بوابة الذكاء الاصطناعي المصرية المنصة الرسمية للمجلس الوطني للذكاء الاصطناعي','null','تُعد بوابة الذكاء الاصطناعي المصرية المنصة الرسمية للمجلس الوطني للذكاء الاصطناعي في جمهورية مصر العربية، وقد أُطلقت لدعم تنفيذ الاستراتيجية الوطنية للذكاء الاصطناعي وتعزيز التحول الرقمي. توفر البوابة معلومات شاملة حول الاستراتيجية الوطنية، والمشروعات والمبادرات الحكومية، والفعاليات، والبرامج التدريبية، والموارد البحثية، إضافة إلى فرص الابتكار والاستثمار والشراكات في مجال الذكاء الاصطناعي. كما تهدف إلى تنسيق الجهود بين الجهات الحكومية والجامعات ومراكز البحوث والقطاع الخاص، بما يسهم في بناء منظومة وطنية متكاملة للذكاء الاصطناعي ودعم التنمية المستدامة.',NULL,'https://ai.gov.eg/',5,18,2,'2026-06-26 10:34:27','2026-06-29 10:24:41'),(299,'Photos_ScientificResearchInnovationCenters/9eJFIO7qUY4WRDRrkyGv9941NQ9GLhxDp1NOyHBh.png','المجلس الوطني للذكاء الاصطناعي والحوسبة الكمية والتكنولوجيات البازغة',NULL,'يُعد المجلس الوطني للذكاء الاصطناعي والحوسبة الكمية والتكنولوجيات البازغة الجهة الوطنية المسؤولة عن قيادة وتنسيق جهود تطوير الذكاء الاصطناعي في مصر، ويتبع مجلس الوزراء برئاسة وزير الاتصالات وتكنولوجيا المعلومات. يهدف المجلس إلى وضع وتنفيذ الاستراتيجية الوطنية للذكاء الاصطناعي، وتعزيز حوكمة واستخدام تقنيات الذكاء الاصطناعي بصورة آمنة ومسؤولة، ودعم البحث العلمي والابتكار، وبناء القدرات الوطنية، وتشجيع التعاون بين الجهات الحكومية والجامعات ومراكز البحث والقطاع الخاص والمنظمات الدولية. كما يعمل على توظيف الذكاء الاصطناعي في مختلف القطاعات التنموية، مثل التعليم، والصحة، والزراعة، والصناعة، والخدمات الحكومية، بما يسهم في تحقيق التنمية المستدامة وتعزيز الاقتصاد الرقمي في مصر.',NULL,'https://ai.gov.eg/',5,18,1,'2026-06-26 10:35:18','2026-06-26 10:35:18'),(300,'Photos_CentersExcellenceArtificialIntelligence/tFI5As5jOCdAeio1T64xaJJWLKTDAfgEOY54VTHn.png','مراكز إبداع مصر الرقمية',NULL,'مراكز إبداع مصر الرقمية (كريتيفا – CREATIVA) هي مبادرة وطنية أطلقتها وزارة الاتصالات وتكنولوجيا المعلومات المصرية بالتعاون مع وزارة التعليم العالي والبحث العلمي، بهدف بناء منظومة متكاملة لدعم الابتكار وريادة الأعمال والتحول الرقمي في مختلف محافظات مصر. توفر المراكز بيئة متطورة للتدريب التقني، وتنمية المهارات الرقمية، ودعم الشركات الناشئة، والبحث والابتكار، من خلال برامج متخصصة في مجالات الذكاء الاصطناعي، وعلوم البيانات، والأمن السيبراني، وتطوير البرمجيات، والعمل الحر، وريادة الأعمال. كما تسهم في ربط الشباب باحتياجات سوق العمل، وتعزيز الشراكات بين الجامعات والقطاع الصناعي والمؤسسات الحكومية، بما يدعم تنفيذ استراتيجية مصر الرقمية ويعزز الاقتصاد القائم على المعرفة.',NULL,'https://creativa.gov.eg/',5,18,2,'2026-06-26 10:40:14','2026-06-26 10:40:14'),(301,'Photos_CentersExcellenceArtificialIntelligence/3zPdGLH2fHBqxPjLiG4O1ReikHzLXQ75JVNyQZ4i.jpg','مركز NGN للتدريب','NGNTrainingCenter','مركز NGN للتدريب هو الذراع التدريبي لشركة NGN International في مملكة البحرين، ويُعد مركزًا متخصصًا في التدريب التقني والمهني يهدف إلى تمكين الأفراد والمؤسسات من اكتساب المهارات اللازمة لمواكبة التحول الرقمي. يقدم المركز برامج تدريبية وشهادات احترافية معتمدة في مجالات الذكاء الاصطناعي، والأمن السيبراني، والحوسبة السحابية، وتحليل البيانات، والشبكات، والتسويق الرقمي، وإدارة تقنية المعلومات، بالتعاون مع جهات اعتماد دولية. كما يركز على بناء القدرات الوطنية، وتقديم التدريب العملي، وتطوير الكفاءات المهنية، ودعم المؤسسات في رحلتها نحو الابتكار والتحول الرقمي من خلال برامج تدريبية عالية الجودة يقدمها خبراء معتمدون.',NULL,'https://training.ngnintl.com/',5,3,2,'2026-06-26 10:47:43','2026-06-26 10:47:43'),(302,'Photos_SupportingBodiesScientificResearch/bRHyKRMMe1NuPnombEsjj0W5EuzjSS2OCgTnHeub.png','الهيئة العليا للبحث العلمي','hcsr','العلمية (HCSR) هي منظمة حكومية سورية مسؤولة عن تنسيق وتعزيز البحث العلمي، ووضع السياسات الوطنية للعلوم والابتكار، ودعم الأنشطة البحثية في الجامعات والمؤسسات البحثية. تأسست الهيئة بموجب مرسوم تشريعي عام 2006، وتعمل حاليًا تحت مظلة وزارة التعليم العالي والبحث العلمي السورية.\r\nالمهام : تقديم الدعم المالي لمشاريع البحث المؤهلة.\r\nتعزيز أخلاقيات البحث والسلوك العلمي المسؤول.\r\nدعم نقل التكنولوجيا من خلال المكتب الوطني لنقل التكنولوجيا.\r\nنشر التقارير والمجلات العلمية وتنظيم المؤتمرات وورش العمل للباحثين.',NULL,'https://www.hcsr.gov.sy/',6,9,5,'2026-06-26 10:48:55','2026-06-26 11:33:58'),(303,'Photos_CentersExcellenceArtificialIntelligence/DIxESnqHj2Hy0Pg5QJQoNuvUUtQ4YvlerVRVsUAX.png','مركز الخوارزمي للذكاء الاصطناعي',NULL,'مركز الخوارزمي للذكاء الاصطناعي هو اوئل المراكز العراقية المتخصصة في مجال الذكاء الاصطناعي، مسجل رسميًا لدى دائرة المنظمات غير الحكومية التابعة للأمانة العامة لمجلس الوزراء تحت رقم التسجيل(1SM2410009)\r\n\r\nيسعى المركز إلى تقديم حلول متقدمة تعتمد على الذكاء الاصطناعي لدعم وتحسين مختلف القطاعات الحيوية في العراق ، ويعمل على استقطاب المتخصصين والخبراء لتعزيز مكانة الذكاء الاصطناعي في العراق. بهدف تحقيق نقلة نوعية في استخدامات الذكاء الاصطناعي داخل العراق في مجالات الصحة، التعليم، الزراعة، والقطاع الحكومي. , وبقية القطاعات المهمة .',NULL,'https://kcaiiq.org/',5,11,2,'2026-06-26 11:10:56','2026-06-26 11:10:56'),(304,'Photos_SupportingBodiesScientificResearch/0bfg19S2EmYyfBnCUIVszHmYkPkWuRR7669wJ98B.jpg','صندوق دعم البحث العلمي التقاني',NULL,'هو صندوق حكومي سوري أُنشئ لدعم وتمويل البحث العلمي والتطوير التقاني، ويعمل ضمن منظومة وزارة التعليم العالي والبحث العلمي. يهدف إلى تشجيع المشاريع البحثية ذات الأولوية الوطنية، وربط مخرجات البحث العلمي باحتياجات التنمية والاقتصاد، مع إطلاق دورات تمويل دورية للباحثين في الجامعات والمراكز البحثية.\r\nتاسس عام :2006\r\nالاهداف :يركز الصندوق على تمويل الأبحاث العلمية والتطويرية التي تخدم الأولويات الوطنية، وتشمل مهامه دعم المشاريع البحثية، والمساهمة في برامج التعاون العلمي مع جهات خارجية، وتشجيع الابتكار والتطوير التقاني.',NULL,'https://moed.gov.sy/site/web/',6,9,5,'2026-06-26 11:32:53','2026-06-26 11:32:53'),(305,'Photos_SupportingBodiesScientificResearch/V17IzEGaFNqOb4IwaHFcTo19uvY5rdSf2H69fV9Z.jpg','صندوق التنمية السوري',NULL,'هو مؤسسة اقتصادية وطنية سورية تأسست عام 2025 لدعم إعادة إعمار البلاد وتنميتها على المدى الطويل. ويعمل الصندوق باستقلالية مالية وإدارية، ويتولى مهمة حشد التمويل لمشاريع البنية التحتية والإنعاش الاقتصادي والتنمية في أعقاب سنوات الصراع.\r\nاهداف: يسعى الصندوق إلى تمويل مشاريع التنمية، وتعزيز خلق فرص العمل، وتحسين الظروف المعيشية من خلال آليات مثل قروض التنمية بدون فوائد وغيرها من أدوات التمويل.',NULL,'https://syrfund.gov.sy/',6,9,5,'2026-06-26 11:57:29','2026-06-26 11:57:29'),(306,'Photos_SupportingBodiesScientificResearch/SMcNUUnipEfQwniYnk5QyKNQLEJyyYF2m3obuRQm.png','مركز التميز البحثي',NULL,'مركز التميز البحثي ( CRE ) هو مركز بحثي تابع لجامعة مقديشو . ويعمل كمركز محوري للنهوض بالبحث العلمي، وتشجيع الابتكار، ودعم الحلول القائمة على الأدلة للتحديات الأكاديمية والمجتمعية في الصومال.\r\nمهمة المركز المعلنة : في تعزيز جودة البحث العلمي من خلال الابتكار ، وتطوير أعضاء هيئة التدريس ، وإنتاج بحوث مؤثرة. وتتمثل رؤيته طويلة الأمد في أن يصبح المركز البحثي الرائد في الصومال من خلال تشجيع إنتاج المعرفة والابتكار بما يسهم في التنمية المستدامة.',NULL,'https://cre.mu.edu.so/about/',6,10,5,'2026-06-26 12:12:30','2026-06-26 12:12:30'),(307,'Photos_CentersExcellenceArtificialIntelligence/BErPxnqBdPBZyrpRlEbk2ZS6EYYHkGbMD2qUBcuO.png','مركز المستقبل لتطبيقات الذكاء الاصطناعي',NULL,'مركز المستقبل لتطبيقات الذكاء الاصطناعي يعنى بفهم وتقديم حلول عملية في علم الحوسبة. يتمحور الذكاء الاصطناعي حول إنشاء أنظمة ذكية قادرة على أداء المهام بشكل ذاتي، دون الحاجة لتدخل بشري. يمتاز المركز بقدرته على دمج التطبيقات الذكية في مختلف المجالات مثل الرعاية الصحية، الصناعة، التعليم، البيئة، النقل، رعاية ذوي الاحتياجات الخاصة والمسنين.. الخ. يستند العمل في المركز إلى الخوارزميات والنماذج الإحصائية، التي تمكِّن الآلات من التعلم والتفكير واتخاذ قرارات بشكل مشابه للبشر. يُظهر الذكاء الاصطناعي قدرته على التعامل مع مجموعة واسعة من التحديات، من خلال التعرف على الأنماط والتنبؤات وحتى حل المشكلات المعقدة. يتابع مركزنا تطورات الذكاء الاصطناعي بسرعة، وذلك من خلال الابتكار في مجالات التعلم الآلي ومعالجة البيانات. يسعى المركز إلى تحقيق تأثير فعّال في مجتمعنا من خلال تطبيق تكنولوجيا الذكاء الاصطناعي في حلول عملية ومستدامة.',NULL,'https://wwww.uomus.edu.iq/Units/Default.aspx?UnitID=18',5,11,2,'2026-06-26 12:12:58','2026-06-26 12:12:58'),(308,'Photos_SupportingBodiesScientificResearch/Nbc01S5HgDYM1IGxycV7vRWkhAr1W4tlyDWDnLIL.jpg','منظمة المنح الدراسية الصومالية (SSO)',NULL,'هي منظمة تعليمية مقرها في Mogadishu تعمل على دعم الطلاب الصوماليين من خلال نشر فرص المنح الدراسية والإرشاد الأكاديمي. تهدف إلى تسهيل الوصول إلى التعليم العالي داخل الصومال وخارجه عبر توفير المعلومات والموارد المتعلقة بالمنح وفرص الدراسة.\r\nمجالات الدعم:\r\nتشمل الأنشطة التي تبرزها المنظمة:\r\nنشر فرص المنح الدراسية المحلية والدولية.\r\nتقديم معلومات وإرشادات حول إجراءات التقديم.\r\nمشاركة تحديثات تخص البرامج التعليمية والفرص الأكاديمية.\r\nتأسست منظمة المنح الدراسية الصومالية (SSO) في عام 2015.',NULL,'https://sso.org.so/about.html',6,10,5,'2026-06-26 13:22:19','2026-06-26 13:22:19'),(309,'Photos_SupportingBodiesScientificResearch/g7999rQKh9gbhon0ILym9BSC73BfgFh4jsi5GmJB.jpg','منظمة الباحثين الصوماليين (SRA)',NULL,'ومقرها في مقديشو. تركز على إنتاج البحوث الاجتماعية، والرصد والتقييم، وبناء القدرات البحثية لدعم السياسات والبرامج التنموية في مختلف أنحاء الصومال، مع الاعتماد على باحثين وخبراء محليين.\r\nجالات العمل\r\nتركز SRA على إجراء الأبحاث التطبيقية والدراسات الميدانية التي تخدم صناع القرار والمنظمات التنموية. وتشمل أنشطتها:\r\nالبحوث الاجتماعية على المستويات المحلية والإقليمية والوطنية.\r\nالرصد والتقييم (Monitoring & Evaluation) للمشروعات والبرامج.\r\nجمع البيانات والمسوح الميدانية.\r\nبناء القدرات والتدريب للباحثين والمؤسسات.\r\nدعم الدراسات المتعلقة بالتعليم، والصحة، والحوكمة،',NULL,'https://www.sra.so/about-us/',6,10,5,'2026-06-26 13:31:09','2026-06-26 13:31:09'),(310,'Photos_ScientificResearchInnovationCenters/QBqGR9E72bm1d52X6zeJcxJcGZpocUPZTmklnxc6.webp','مركز سیف بن هلال لدراسات وأبحاث علوم الطاقة','sbhcenter','مركز سيف بن هلال لدراسات وأبحاث علوم الطاقة هو مركز بحثي متخصص مقره جمهورية مصر العربية، ويُعد الذراع البحثي للوكالة الدولية لأمن الطاقة (IAFES). يهدف المركز إلى تعزيز البحث العلمي في مجالات الطاقة وأمن الطاقة، وإجراء الدراسات والتحليلات الاستراتيجية المتعلقة بالطاقة التقليدية والمتجددة، ورصد المخاطر والفرص في أسواق الطاقة العالمية، ودعم الابتكار والتخطيط الاستراتيجي. كما يعمل على تنظيم المؤتمرات والندوات وورش العمل، وتعزيز التعاون مع الحكومات والجامعات والمؤسسات البحثية والمنظمات الدولية، وإعداد الدراسات والإحصاءات التي تسهم في دعم أمن الطاقة وتحقيق التنمية المستدامة، مع التركيز على الحياد العلمي واستشراف مستقبل قطاع الطاقة.',NULL,'https://sbhcenter.com/',5,18,1,'2026-06-26 14:13:09','2026-06-26 14:13:09'),(311,'Photos_SupportingBodiesScientificResearch/KggsI8DE9riyvvIMsmfgHlNORDsbx4bce1zOaJnz.jpg','هيئة البحث العلمي',NULL,'هي مؤسسة حكومية عراقية تابعة لـوزارة التعليم العالي والبحث العلمي، تُعنى بتنسيق ودعم وتطوير منظومة البحث العلمي في العراق. تعمل الهيئة من خلال مراكز بحثية متخصصة وبرامج أكاديمية وبحثية تهدف إلى تعزيز الابتكار، دعم الباحثين، وربط البحث العلمي باحتياجات التنمية الوطنية.\r\n تأسست هيئة البحث العلمي بصيغتها الستراتيجية والقانونية المستقلة الحالية في أغسطس 2024.\r\nالمهام:  تمويل ودعم المشاريع العلمية، وتشجيع التعاون بين المؤسسات البحثية والجامعات العراقية والدولية، ورفع جودة المخرجات البحثية. كما تركز على تحويل المعرفة العلمية إلى حلول عملية تخدم المجتمع والاقتصاد العراقي.',NULL,'https://src.edu.iq/index.html',6,11,5,'2026-06-26 14:17:58','2026-06-26 14:17:58'),(312,'Photos_ScientificResearchInnovationCenters/A1V1honhjOOCU9gBXwwplBlbFAU27mMREQpsVRd0.png','مركز الصومال للدراسات','Somalia Studies Center','مركز الصومال للدراسات (Somalia Studies Center) هو مركز بحثي مستقل مقره مقديشو، جمهورية الصومال الفيدرالية، يُعنى بإجراء البحوث والدراسات العلمية في المجالات السياسية والاقتصادية والاجتماعية والثقافية والتنموية، مع تركيز خاص على قضايا الصومال ومنطقة القرن الإفريقي.\r\n ويهدف المركز إلى إنتاج المعرفة الرصينة، ودعم صناع القرار، وتعزيز الحوار الفكري، من خلال إعداد الدراسات والتقارير الاستراتيجية، وتنظيم المؤتمرات والندوات وورش العمل والبرامج التدريبية، إضافة إلى نشر المقالات والأبحاث العلمية، وبناء شراكات مع المؤسسات الأكاديمية ومراكز الفكر والبحث على المستويين الإقليمي والدولي، بما يسهم في دعم التنمية والاستقرار في الصومال والمنطقة.',NULL,'https://www.somaliastudies.com/',5,10,1,'2026-06-26 14:23:01','2026-06-26 14:23:35'),(313,'Photos_SupportingBodiesScientificResearch/ipoHHHTOXUpJ9taL0lRinQTFWAe2NpC6JjwDxVuo.jpg','مركز بحوث الطاقة والطاقات المتجددة',NULL,'مركز بحوث الطاقة والطاقات المتجددة هو منظمة بحثية عراقية تركز على الطاقة المتجددة، كفاءة الطاقة، والتقنيات الداعمة للتنمية المستدامة. يعمل ضمن منظومة مؤسسات التعليم العالي والبحث العلمي في العراق، ويسهم في إجراء البحوث التطبيقية، وتطوير الحلول التقنية،\r\nالمهام :يشارك في تصميم وتنفيذ مشاريع تجريبية، وتقديم الاستشارات الفنية، ودعم الدراسات المتعلقة باستخدام مصادر الطاقة المتجددة ورفع كفاءة استهلاك الطاقة.',NULL,'https://eretc.uotechnology.edu.iq/',6,11,5,'2026-06-26 14:41:19','2026-06-26 14:41:19'),(314,'Photos_ScientificResearchInnovationCenters/lK69ucsUGCh2tj6VC1BwsiSu8RdCakGtEPsjMgoC.jpg','الشبكة اليمنية للعلوم والبيئة',NULL,'الشبكة اليمنية للعلوم والبيئة  هي منصة علمية وإعلامية يمنية مستقلة متخصصة في نشر العلوم والمعرفة، أُطلقت بمبادرة من مجموعة من الصحفيين العلميين اليمنيين بهدف تبسيط العلوم وتعزيز الثقافة العلمية لدى المجتمع اليمني والعربي. تعمل الشبكة على إنتاج ونشر الأخبار والتقارير والمقالات العلمية، وترجمة ملخصات الأبحاث والدراسات العالمية إلى اللغة العربية، وتغطية موضوعات متنوعة تشمل التكنولوجيا، والذكاء الاصطناعي، والصحة، والبيئة، والطاقة، والتغير المناخي، والفضاء، والابتكار. كما تسعى إلى إثراء المحتوى العلمي العربي على الإنترنت، ونشر الوعي العلمي، وتشجيع التواصل بين الباحثين والإعلام العلمي، بما يسهم في دعم التنمية القائمة على المعرفة',NULL,'https://yemenscience.net/',5,21,1,'2026-06-26 14:42:21','2026-06-26 14:42:21'),(315,'Photos_SupportingBodiesScientificResearch/u4I09DACECart4zjmS3QZfSbx2d1TBdstbLvdKdL.jpg','مركز بحوث التطبيقات الصناعية وتكنولوجيا المواد',NULL,'هو مركز أبحاث عراقي متخصص يركز على التطبيقات الصناعية وعلوم المواد وتطوير التكنولوجيا. وهي تعمل تحت إشراف هيئة البحث العلمي ضمن وزارة التعليم العالي والبحث العلمي العراقية، وتساهم في البحوث التطبيقية، وخدمات المختبرات، والتعاون مع الجامعات والصناعة.\r\nالمهام:يركز عمل المركز على البحوث العلمية التطبيقية التي تدعم التنمية الصناعية، وتحسن المواد وتقنيات التصنيع، وتشجع الابتكار. وهو أحد مراكز البحوث المتخصصة العديدة التي تديرها لجنة البحث العلمي،\r\nالموقع الإلكتروني الرسمي لـ مركز بحوث التطبيقات الصناعية وتكنولوجيا المواد يقع ضمن البوابة الرسمية للمؤسسة الأم التي يتبع لها:',NULL,'https://src.edu.iq/',6,11,5,'2026-06-26 15:15:33','2026-06-26 15:15:33'),(316,'Photos_SupportingBodiesScientificResearch/1HbhsU6O01hKgyLjBYJ7GYcztg54TcdLTQikJlW1.jpg','مركز بحوث النهرين للطاقة المتجددة',NULL,'هو مركز أكاديمي وبحثي تابع لجامعة النهرين في العراق، يركز على تطوير المعرفة والتقنيات المرتبطة بالطاقة النظيفة والمستدامة. ويُعد من المراكز الجامعية المتخصصة التي تدعم البحث العلمي، والابتكار، والتعاون مع المؤسسات الأكاديمية والحكومية في مجالات الطاقة المتجددة.\r\nتاسس عام :2014\r\nالمهام: تنظيم الورش والدورات العلمية، ودعم مشاريع تهدف إلى تعزيز استخدام مصادر الطاقة النظيفة في العراق.',NULL,'https://ner.c.nahrainuniv.edu.iq/en/about/',6,11,5,'2026-06-29 08:00:10','2026-06-29 08:00:10'),(317,'Photos_SupportingBodiesScientificResearch/8OafK8p7n33WMrr9NLZqOCGfe7Mr0Wep36hrourR.jpg','مجلس البحث العلمي',NULL,'قد لعب المجلس دوراً محورياً في بناء منظومة البحث العلمي في البلاد قبل إعادة تنظيم مسؤولياته في مؤسسات حكومية جديدة كجزء من الإصلاحات الإدارية.تم تعديل المسمى الرسمي لمجلس البحث العلمي في سلطنة عُمان بموجب المرسوم السلطاني رقم 11/2026 ليصبح هيئة البحث العلمي والابتكار، وهي هيئة عامة تتمتع بالاستقلال المالي والإداري وتتبع مجلس الوزراء. وتُعنى الهيئة ببناء منظومة متكاملة تدعم الباحثين والمبتكرين وتحويل الأفكار الأكاديمية إلى مشاريع استثمارية تخدم التنمية المستدامة و من خلال منح بحثية تنافسية ، ودعم باحثي الدراسات العليا ، ووضع أولويات بحثية وطنية، وتشجيع التعاون بين الجامعات والهيئات الحكومية والقطاع الصناعي. كما شجع المجلس الابتكار، ونظم مسابقات علمية، ودعم البنية التحتية البحثية بهدف المساهمة في التنمية الاقتصادية والاجتماعية طويلة الأجل للبلاد.',NULL,'https://orp.moheri.gov.om/?lang=ar',6,12,5,'2026-06-29 08:17:32','2026-06-29 08:17:32'),(318,'Photos_SupportingBodiesScientificResearch/qoMJy1LrdM4F2CNuofsihDhvpRsG1SIoLZG4L93R.png','معهد تكامل التقنيات المتقدمة (إيجاد)',NULL,'EJAAD, هو مؤسسة عُمانية تُعنى بربط البحث العلمي باحتياجات الصناعة من خلال بناء شراكات بين الجهات الحكومية والجامعات والقطاع الخاص. ويُعد أحد أبرز الأذرع الوطنية الداعمة لمنظومة البحث والتطوير والابتكار في سلطنة عُمان، مع تركيز خاص على تحويل التحديات الصناعية إلى مشاريع بحثية قابلة للتطبيق.\r\nتاسس عام :2019\r\nالمهام: يركز إيجاد على تسهيل التعاون بين الباحثين والمؤسسات الصناعية، ويعمل كمنصة للتواصل وإدارة مشاريع البحث والتطوير.',NULL,'https://orp.moheri.gov.om/ejaad/',6,12,5,'2026-06-29 08:35:06','2026-06-29 08:35:06'),(319,'Photos_CentersExcellenceArtificialIntelligence/s6BBqHT0Vu5o6LpY2l4OXGUDC4F3O4blMw6866nf.jpg','مركز التميز للمشاريع الإبداعية','Center of Excellence for Innovative Projects','أنشىء مركز التميز للمشاريع الإبداعية التابع  لجامعة العلوم والتكنولوجيا الأردنية لتوفير البيئة التقنية المناسبة لدعم ورعاية المبدعين من الجامعة والمجتمع المحلي على حد سواء، حيث يشتمل المركز على مجموعة من المرافق والخدمات المتكاملة لدعم المبدعين والرياديين ورعايتهم وتنمية مهاراتهم وتطوير إبداعاتهم ابتداءً من الفكرة ومرورًا بالنموذج الأولي للمنتج أو الخدمة وانتهاءً بتأسيس الأعمال الصغيرة وإطلاقها تجاريًا. \r\n\r\nويهدف المركز إلى تحقيق التنمية المستدامة من خلال توفير البيئة التقنية المناسبة والداعمة للإبداع في مختلف المجالات الصناعية والخدماتية وتطوير نماذج أولية لمنتجات قابلة للتصنيع والتسويق تجارياً أو خدمات مبتكرة وذلك باحتضانها كشركات ناشئة تتحول فيما بعد إلى شركات صغيرة إنتاجية مستقلة تدعم الاقتصاد الوطني بالتحول إلى إقتصاد المعرفة في تخصصات إنتاجية متعددة.',NULL,'https://www.just.edu.jo/',5,1,2,'2026-06-29 08:55:34','2026-06-29 08:55:34'),(320,'Photos_CentersExcellenceArtificialIntelligence/QZmODTsSwUCnnO8cCXR8preBKykIKuz890AeUU6f.jpg','مركز التميز الدعوي',NULL,'مركز التميز الدعوي شركة غير ربحية تعمل على تطوير العمل الدعوي لمواكبة التحديات والفرص المعاصرة، بهدف تحقيق مستقبل مشرق للمنظمات الدعوية. تتمثل رؤية المركز في أن يكون المرجعية الرائدة في التطوير المؤسسي للعمل الدعوي، بالاعتماد على القيم الأساسية مثل الاستشراف، المؤسسية، الابتكار، البحث العلمي، والمعيارية. يسعى المركز من خلال رسالته إلى تقديم نموذج مؤسسي مبتكر يكون بيت خبرة يستشرف توجهات العمل الدعوي ويرتقي بكياناته وكوادره.\r\n\r\nكما يركز المركز على بناء بيت خبرة متكامل يرسم استراتيجيات العمل الخيري الدعوي ويحدد أولوياته، بهدف تحسين جودة المنتجات الدعوية وضمان توافقها مع أفضل المعايير العالمية. يعمل المركز على تأهيل الكوادر الدعوية من خلال التدريب المستمر وبرامج متخصصة، إضافة إلى تنظيم ملتقيات دورية لتوثيق الخبرات وتحقيق التكامل في القطاع الدعوي.',NULL,'https://coedawah.org/',5,7,2,'2026-06-29 09:03:09','2026-06-29 09:03:09'),(321,'Photos_SupportingBodiesScientificResearch/7V24INOnT9O6va78luCjv6kWt0rScWI8crC1yX1S.png','مجلس البحث العلمي الفلسطيني',NULL,'هو هيئة وطنية تأسست للمساعدة في توجيه وتعزيز البحث العلمي في فلسطين. ويعمل المجلس تحت إشراف وزارة التعليم العالي والبحث العلمي الفلسطينية، ويساهم في صياغة سياسات البحث، وتشجيع التعاون، ودعم منظومة البحث والابتكار في البلاد.\r\nتاسس عام :1998\r\nالمهام : دعم بناء القدرات للباحثين والمؤسسات البحثية.\r\nتشجيع التعاون بين الجامعات والصناعة والحكومة.\r\nدعم المجلات العلمية الفلسطينية المحكمة والمؤتمرات الأكاديمية.\r\nتنسيق التعاون العلمي الدولي وإشراك الباحثين الفلسطينيين في الشتات.',NULL,'https://www.mohe.pna.ps/Councils-and-Commissions/Scientific-Research-Council',6,13,5,'2026-06-29 09:05:01','2026-06-29 09:05:01'),(322,'Photos_ScientificResearchInnovationCenters/ZjbNNGt0K4xWyu4KXVKTvUIgzeKJJb60PHMMJhYI.png','مؤسسة البحث والتطوير والابتكار في العلوم والهندسة','FRDISI','مؤسسة البحث والتطوير والابتكار في العلوم والهندسة (FRDISI) هي مؤسسة مغربية ذات منفعة عامة أُنشئت سنة 2016 بهدف تعزيز البحث العلمي والابتكار والشراكة بين الجامعات والقطاعين العام والخاص. تعمل المؤسسة على تطوير منصات للبحث والتكوين والابتكار، ودعم نقل التكنولوجيا إلى القطاع الصناعي، واحتضان المشاريع المبتكرة والشركات الناشئة، بما يسهم في تعزيز التنمية الاقتصادية والتكنولوجية بالمملكة المغربية. كما تضم المؤسسة شبكة واسعة من الجامعات ومراكز البحث والمؤسسات الصناعية، وتسعى إلى تكوين الكفاءات، وتثمين نتائج البحث العلمي، وتشجيع ريادة الأعمال والابتكار في مجالات الهندسة والتكنولوجيا والذكاء الاصطناعي والطاقة والبيئة',NULL,'https://www.frdisi.ma/fr',5,19,1,'2026-06-29 09:12:43','2026-06-29 09:12:43'),(323,'Photos_SupportingBodiesScientificResearch/7pDReW8BAPGqL319gcPdko3BPhSDEdw0elHZam4A.jpg','المجلس الأعلى للإبداع والتميز',NULL,'هو منظمة وطنية فلسطينية تُعنى بدعم الإبداع والابتكار والتميز لدى الأفراد والمؤسسات، مع تركيز خاص على الشباب والباحثين ورواد الأعمال. أُنشئ ليكون جهة تنسيقية واستراتيجية تعمل على تعزيز منظومة الابتكار في فلسطين، وتشجيع تحويل الأفكار الإبداعية إلى مشاريع ومبادرات ذات أثر مجتمعي واقتصادي.\r\nتاسس عام:2012\r\nالمهام :دعم المبدعين، وتشجيع الابتكار، وتعزيز التعاون بين القطاع الحكومي والجامعات والقطاع الخاص والمؤسسات الأهلية. كما يعمل على تطوير السياسات والتشريعات الداعمة للابتكار، وبناء قواعد معرفية.',NULL,'https://hcie.ps/?lang=en',6,13,5,'2026-06-29 09:20:28','2026-06-29 09:20:28'),(324,'Photos_CentersExcellenceArtificialIntelligence/8hIfKl9pAziNasw63NhVLF0aYoZpd6A3hMPzBvK4.png','مركز التميز في الذكاء الاصطناعي','DXC.CDG AI Center of Excellence','مركز التميز في الذكاء الاصطناعي (AI Center of Excellence) هو مركز متخصص أطلقته شركة DXC.CDG في مدينة تكنوبوليس بسلا، المغرب.\r\n ويهدف الى تعزيز الابتكار وتسريع التحول الرقمي من خلال تطوير وتطبيق حلول الذكاء الاصطناعي المتقدمة. ويُعد المركز ثمرة شراكة بين DXC Technology وصندوق الإيداع والتدبير (CDG)، ويشكل منصة للبحث والتطوير والابتكار في مجالات الذكاء الاصطناعي، وتحليل البيانات، والحوسبة السحابية، والأمن السيبراني. كما يهدف إلى دعم المؤسسات العمومية والخاصة في تبني التقنيات الذكية، وتطوير الكفاءات الوطنية، وتعزيز التعاون بين الخبراء والباحثين والشركات، بما ينسجم مع رؤية المغرب لترسيخ مكانته كمركز إقليمي للابتكار والتكنولوجيا في إفريقيا.',NULL,'https://dxc.com/',5,19,2,'2026-06-29 09:31:19','2026-06-29 09:31:19'),(325,'Photos_SupportingBodiesScientificResearch/LVWQnzfPze7Lxw0RwFVB7Q2EjEoGVfISpEfzwGY7.jpg','مركز منيب رشيد للبحث العلمي المصري وجود التعليم',NULL,'م إنشاؤه لتعزيز البحث العلمي والابتكار وجودة التعليم العالي. تم إنشاؤه من خلال مبادرات تدعمها مؤسسة منيب رشيد المصري ويشكل جزءًا من جهد أوسع لتوسيع القدرات البحثية والتعاون بين الجامعات الفلسطينة.\r\nتاسس عام 2023\r\nالمهام :تحسين جودة التعليم العالي من خلال الممارسات القائمة على البحث.\r\nتشجيع الابتكار والإبداع بين طلاب الجامعة وأعضاء هيئة التدريس.\r\nدعم البحوث التطبيقية التي تتناول التحديات التي تواجه المجتمع الفلسطيني.',NULL,'https://masrifoundation.org/home-ar/',6,13,5,'2026-06-29 09:36:05','2026-06-29 09:36:05'),(326,'Photos_SupportingBodiesScientificResearch/g31v6BxRSsZY4yJrwzsz0vrPLtcSyMuKYx6za5Mc.webp','مركز المنح والمشاريع الدولية – جامعة النجاح الوطنية',NULL,'هو وحدة متخصصة ضمن جامعة النجاح الوطنية تُعنى بتطوير وإدارة المشاريع الممولة دوليًا وبناء الشراكات الأكاديمية والبحثية. ويؤدي المركز دورًا محوريًا في ربط الجامعة ببرامج التمويل الدولية، مع دعم إعداد المقترحات وإدارة المشاريع وتنفيذها بما يتوافق مع الأهداف الاستراتيجية للجامعة.\r\nتاسس عام 2010\r\nالمهام :ابتداءً من البحث عن فرص التمويل والمنح، مرورًا بإعداد المقترحات التنافسية، ثم إدارة المشاريع بعد الحصول على التمويل، ومتابعة التنفيذ والتقارير والالتزام بمتطلبات الجهات المانحة.',NULL,'https://www.najah.edu/ar/igpc/',6,13,5,'2026-06-29 09:52:42','2026-06-29 09:52:42'),(327,'Photos_SupportingBodiesScientificResearch/zJF1xQH1AwzHq9R0Jp2VW1Vl6JxCj9qNAtZG74Eq.jpg','مركز بيسان للبحوث والإنماء',NULL,'هو منظمة فلسطينية غير ربحية من منظمات المجتمع المدني، مقرها رام الله، وتركز على البحث والتنمية المجتمعية والسياسات العامة. تأسس المركز عام 1989، ويشتهر بدمج البحث مع برامج المناصرة والبرامج المجتمعية المتعلقة بالعدالة الاجتماعية والحقوق الاقتصادية والمساواة بين الجنسين والشباب والتنمية المستدامة.\r\nالمهام :\r\nالمساهمة في بناء مجتمع مدني ديمقراطي وفاعل. وتركز برامجها على الحقوق الاقتصادية والاجتماعية ، والصحة العامة ، والعدالة بين الجنسين ، ومشاركة الشباب ، والتنمية المجتمعية ، إلى جانب إنتاج البحوث وأوراق السياسات والمنشورات التعليمية التي تهدف إلى إثراء النقاش العام وصنع القرار.',NULL,'https://www.bisan.org/content/50',6,13,5,'2026-06-29 10:00:11','2026-06-29 10:00:11'),(328,'Photos_SupportingBodiesScientificResearch/etmkUxo9phlq9BNoz32PPHI12rHwwIuvqpd523ga.jpg','معهد الأبحاث التطبيقية – القدس (ARIJ)',NULL,'هي مؤسسة  غير حكومية تأسست عام 1990، ويقع مقرها الرئيسي في بيت لحم بالضفة الغربية. ويُعرف المعهد بأعماله البحثية والسياساتية في مجالات التنمية المستدامة، والموارد الطبيعية، والزراعة، والمياه، ونظم المعلومات الجغرافية (GIS)، كما يتعاون مع شركاء محليين ودوليين في مشاريع تنموية.\r\nالمهام : التنمية المستدامة ، وحماية البيئة ، وتعزيز المعرفة العلمية والتقنية المتعلقة بالموارد الطبيعية في فلسطين. ويشمل عمله مجالاتٍ مثل إدارة المياه ، والزراعة المستدامة ، وتخطيط استخدام الأراضي ، والطاقة المتجددة ، والتكيف مع تغير المناخ ، وحماية البيئة، والتنمية الاجتماعية والاقتصادية. كما يُجري المعهد أبحاثًا تهدف إلى دعم التخطيط والسياسات العامة.',NULL,'https://www.arij.org/ar/home_ar/',6,13,5,'2026-06-29 10:10:58','2026-06-29 10:10:58'),(329,'Photos_CentersExcellenceArtificialIntelligence/rZ2h2yQ2TU0mo3DqL6YFnKtzz5Mn1m3eaFf79DOJ.jpg','مركز الابتكار التطبيقي','AIC','مركز الابتكار التطبيقي (AIC) هو مركز وطني متخصص في تطوير الحلول التكنولوجية المبتكرة وتوظيف التقنيات الحديثة لخدمة القطاعات الحكومية والاقتصادية والمجتمعية في مصر. يعمل المركز على تصميم وتطوير تطبيقات الذكاء الاصطناعي، وإنترنت الأشياء، وتحليل البيانات الضخمة، ومعالجة اللغات الطبيعية، والرؤية الحاسوبية، والتقنيات الرقمية الناشئة، وذلك بالتعاون مع الجهات الحكومية والجامعات ومراكز البحث والشركات التكنولوجية. ويهدف المركز إلى تحويل مخرجات البحث العلمي إلى تطبيقات عملية تسهم في دعم التحول الرقمي وتعزيز الابتكار وبناء اقتصاد قائم على المعرفة.',NULL,'https://aic.gov.eg/',5,18,2,'2026-06-29 10:15:45','2026-06-29 10:15:45'),(330,'Photos_SupportingBodiesScientificResearch/HVt39Q5TJyue3EUJN1hlMQKRBS98Ggc9sSN6sYZV.jpg','مجلس قطر للبحوث والتطوير والابتكار',NULL,'هي منظمة وطنية تقود منظومة البحث والتطوير والابتكار في دولة قطر. أُسس عام 2018 للمساعدة في تنسيق الاستراتيجية الوطنية للبحث والابتكار، وتعزيز التعاون بين الحكومة والجامعات والقطاع الخاص، ودعم تحول قطر إلى اقتصاد قائم على المعرفة بما يتماشى مع رؤية قطر الوطنية 2030.\r\nالمهام :طوير الاستراتيجيات والسياسات، وإطلاق برامج التمويل والمنح، وبناء الشراكات المحلية والدولية. كما يعمل على جذب المواهب العالمية، وتحفيز نقل التكنولوجيا، ومساعدة الباحثين والشركات على تحويل الأفكار العلمية إلى حلول ومنتجات قابلة للتطبيق.',NULL,'https://qrdi.org.qa/en-US/About',6,14,5,'2026-06-29 10:18:58','2026-06-29 10:18:58'),(331,'Photos_ScientificResearchInnovationCenters/7AIf69MdFU0QZewCLsXE5YhQZt7VK3EAjaZQERjL.jpg','هيئة تنمية صناعة تكنولوجيا المعلومات (إيتيدا)',NULL,'تأسست هيئة تنمية صناعة تكنولوجيا المعلومات (إيتيدا) عام 2004 لتكون الذراع التنفيذية لوزارة الاتصالات وتكنولوجيا المعلومات في تنمية قطاع تكنولوجيا المعلومات والاتصالات في مصر. وتعمل الهيئة على جذب الاستثمارات، ودعم الشركات التكنولوجية، وتنمية الصادرات الرقمية، وبناء القدرات البشرية، وتشجيع الابتكار وريادة الأعمال، إضافة إلى تطوير منظومة الذكاء الاصطناعي والتحول الرقمي. كما تشرف على العديد من المبادرات والمراكز المتخصصة، مثل مركز الإبداع التكنولوجي وريادة الأعمال (TIEC)، ومركز تقييم واعتماد هندسة البرمجيات (SECC)، وبرامج دعم الشركات الناشئة والابتكار.',NULL,'https://www.itida.gov.eg/arabic',5,18,1,'2026-06-29 10:20:55','2026-06-29 10:20:55'),(332,'Photos_SupportingBodiesScientificResearch/oNvtC7uE6M0ssTIgjXL6GSUTKYnSrFm9x6QgFzo2.png','صندوق قطر الوطني للبحوث',NULL,'أنشأت مؤسسة قطر الصندوق القطري لرعاية البحث العلمي (QNRF) عام 2006 كجزء من التزامها المستمر بجعل قطر اقتصادًا قائمًا على المعرفة. ترى مؤسسة قطر أن البحث العلمي عنصر أساسي في النمو الوطني والإقليمي، ووسيلة لتنويع الاقتصاد الوطني، وتعزيز العروض التعليمية، وتطوير المجالات التي تؤثر على المجتمع مثل الصحة والبيئة.\r\nالمهام :تمويل البحوث الأصلية القائمة على الجدارة والمتوافقة مع الأولويات الوطنية لدولة قطر. وتركز برامجها على مجالات مثل الطاقة والبيئة ، وعلوم الحاسوب وتكنولوجيا المعلومات والاتصالات ، والصحة وعلوم الحياة ، والعلوم الاجتماعية والفنون والعلوم الإنسانية . ويمكن للباحثين من المؤسسات الأكاديمية والمنظمات الحكومية والقطاع الخاص.',NULL,'https://tdv.motc.gov.qa/ar/Research-and-Development/Qatar-National-Research-Fund',6,14,5,'2026-06-29 10:38:51','2026-06-29 10:38:51'),(333,'Photos_SupportingBodiesScientificResearch/34yMtcUCk5siPvkXrrLRx7TWGveBQMI7u5zgzA2O.jpg','واحة قطر للعلوم والتكنولوجيا',NULL,'واحة قطر للعلوم والتكنولوجيا ( QSTP ) هي منظمة للابتكار والبحث العلمي مقرها المدينة التعليمية في الدوحة، قطر. وبصفتها عضواً في منظومة مؤسسة قطر، فإنها تعمل كمركز لشركات التكنولوجيا والشركات الناشئة والباحثين ورواد الأعمال الذين يعملون على تطوير وتسويق التقنيات الجديدة.\r\nتاسست عام 2009\r\nالمهام :تأسست مبادرة قطر للعلوم والتكنولوجيا بهدف تنويع اقتصاد قطر من خلال دعم البحوث التطبيقية ، وتسويق التكنولوجيا ، وريادة الأعمال . وتوفر المبادرة البنية التحتية، ودعم الأعمال، وإمكانية الوصول إلى شبكات البحث التي تربط الجامعات بالقطاع الصناعي، مما يسهل تحويل الأفكار العلمية إلى منتجات وخدمات جاهزة للتسويق.',NULL,'https://qstp.qa/ar/who-we-are/',6,14,5,'2026-06-29 11:30:39','2026-06-29 11:30:39'),(334,'Photos_SupportingBodiesScientificResearch/43WLfSo6dEzixnaXaiqmlRVLzzXd7NSGr2jKO3Id.jpg','معهد قطر لبحوث الحوسبة',NULL,'علوم الحوسبة، يعمل ضمن Hamad Bin Khalifa University، ويُعد جزءًا من منظومة Qatar Foundation. يركز على إجراء أبحاث تطبيقية متقدمة لمعالجة تحديات الحوسبة التي تخدم أولويات التنمية في قطر والمنطقة، مع اهتمام خاص بالذكاء الاصطناعي، وتحليل البيانات، والأمن السيبراني، وتقنيات اللغة العربية. \r\nتاسس عام 2010\r\nالاهتمام:\r\nتحليل البيانات الضخمة واستخلاص المعرفة منها.\r\nالأمن السيبراني وحماية الأنظمة والبيانات.\r\nالحوسبة الموزعة والبنية التحتية للحوسبة عالية الأداء.\r\nتطبيقات الذكاء الاصطناعي في مجالات مثل الطب الدقيق والعمل الإنساني والاستدامة.',NULL,'https://www.qf.org.qa/ar/research',6,14,5,'2026-06-29 11:39:12','2026-06-29 11:39:12'),(335,'Photos_SupportingBodiesScientificResearch/21bbhkZIEweYqQMt2vQ0RBZ0YpC9Ez7xQTIFPzjb.jpg','مؤسسة الكويت للتقدم العلمي',NULL,'مؤسسة الكويت للتقدم العلمي (KFAS) هي منظمة خاصة غير ربحية تأسست في الكويت عام 1976 بموجب مرسوم أميري بهدف تعزيز العلوم والتكنولوجيا والابتكار والبحث العلمي. وقد أصبحت إحدى المؤسسات العلمية الرائدة في البلاد، حيث تدعم البحث العلمي والتعليم وريادة الأعمال والثقافة العلمية، وتتعاون مع شركاء محليين ودوليين.\r\nالمهام : تمويل البحوث، وتنمية المواهب، ودعم الابتكار، وتشجيع الحلول القائمة على الأدلة للتحديات الوطنية. وتشمل برامجها مجالات متنوعة كالصحة، والطاقة، والاستدامة البيئية، والتقنيات الرقمية، والتعليم، وريادة الأعمال، وتخدم الباحثين، والطلاب، والمعلمين، والشركات الناشئة، والمؤسسات العامة.',NULL,'https://www.kfas.org/ar/',6,15,5,'2026-06-29 11:50:27','2026-06-29 11:50:27'),(336,'Photos_SupportingBodiesScientificResearch/fU81ZcXgJcoH2mZHm8AnJZiiP2v2TQeYSju29LPB.png','معهد الكويت للأبحاث العلمية',NULL,'تأسس عام 1967، ويلعب دوراً محورياً في دعم الابتكار العلمي والتطوير التكنولوجي والحلول القائمة على الأدلة لمواجهة التحديات البيئية والطاقة والمياه والصناعية التي تواجه البلاد.\r\nالمهام : \r\nيُجري المعهد أبحاثًا علمية تطبيقية بدلًا من التركيز على التدريس الأكاديمي. ويشمل عمله مجالاتٍ عديدة، منها تقنيات البترول والطاقة، والموارد المائية، وحماية البيئة، وعلوم البحار، والزراعة الصحراوية، والأمن الغذائي، والبنية التحتية المستدامة، وإدارة الموارد الطبيعية.',NULL,'https://www.kisr.edu.kw/ar/discover-kisr/about-us/',6,15,5,'2026-06-29 12:00:12','2026-06-29 12:00:12'),(337,'Photos_CentersExcellenceArtificialIntelligence/IC3IND5vUSxHXQPlQEYfuBQo0FUomkTcDC65FPEj.jpg','مركز الذكاء الاصطناعي التابع لجامعة الملك خالد','Center for Artificial Intelligence (CAI)','يُعد مركز الذكاء الاصطناعي بجامعة الملك خالد مركزًا بحثيًا وأكاديميًا متخصصًا أُسس عام 2018، ويهدف إلى تعزيز البحث العلمي والابتكار في مجال الذكاء الاصطناعي وتطبيقاته. ويعمل المركز على تطوير حلول ذكية قائمة على تقنيات الذكاء الاصطناعي، وتعلم الآلة، وتحليل البيانات الضخمة، وإنترنت الأشياء، والروبوتات، والرؤية الحاسوبية، ومعالجة اللغات الطبيعية، بما يسهم في خدمة المجتمع ودعم التحول الرقمي وتحقيق مستهدفات رؤية المملكة العربية السعودية 2030. كما يركز المركز على تدريب وتأهيل الباحثين والطلاب، وتعزيز التعاون البحثي مع الجامعات والمؤسسات المحلية والدولية، وتنفيذ مشاريع تطبيقية في مختلف القطاعات.',NULL,'https://www.kku.edu.sa/ar',5,7,2,'2026-06-29 12:04:59','2026-06-29 12:04:59'),(338,'Photos_ScientificResearchInnovationCenters/D7YANLN9nxOLkgdkPdkzFUtszVMJVB61EVFa5dA8.jpg','مركز الذكاء الاصطناعي – جامعة الملك خالد','Center for Artificial Intelligence (CAI) – King Khalid University','يُعد مركز الذكاء الاصطناعي بجامعة الملك خالد مركزًا بحثيًا وأكاديميًا متخصصًا أُسس عام 2018، ويهدف إلى تعزيز البحث العلمي والابتكار في مجال الذكاء الاصطناعي وتطبيقاته. ويعمل المركز على تطوير حلول ذكية قائمة على تقنيات الذكاء الاصطناعي، وتعلم الآلة، وتحليل البيانات الضخمة، وإنترنت الأشياء، والروبوتات، والرؤية الحاسوبية، ومعالجة اللغات الطبيعية، بما يسهم في خدمة المجتمع ودعم التحول الرقمي وتحقيق مستهدفات رؤية المملكة العربية السعودية 2030. كما يركز المركز على تدريب وتأهيل الباحثين والطلاب، وتعزيز التعاون البحثي مع الجامعات والمؤسسات المحلية والدولية، وتنفيذ مشاريع تطبيقية في مختلف القطاعات.',NULL,'https://www.kku.edu.sa/ar',5,7,1,'2026-06-29 12:06:26','2026-06-29 12:06:26'),(339,'Photos_SupportingBodiesScientificResearch/0BqCceIHebsFNS2nX8ueJNUgHLPClQJwUO2qX6w1.jpg','الهيئة العامة للتطوير',NULL,'هي المسؤولة عن التعليم العالي التطبيقي والتدريب المهني. تأسست عام 1982 ، وتضطلع بدور محوري في إعداد خريجين تقنيين ومهنيين وذوي مهارات عالية لتلبية احتياجات سوق العمل في البلاد من خلال الكليات ومعاهد التدريب وبرامج التعليم المستمر.\r\nالمهام :أُنشئت الهيئة العامة للتعليم والتدريب التقني والمهني لتطوير القوى العاملة الوطنية في الكويت من خلال الجمع بين التعليم الأكاديمي التطبيقي والتدريب التقني والمهني . صُممت برامجها لمواءمة مهارات الخريجين مع متطلبات الجهات الحكومية، والرعاية الصحية، والصناعة، والأعمال، والتكنولوجيا، وغيرها من قطاعات الاقتصاد.',NULL,'https://www.paaet.edu.kw/',6,15,5,'2026-06-29 12:11:10','2026-06-29 12:11:10'),(340,'Photos_CentersExcellenceArtificialIntelligence/ZWN6Jx7Bzo81i4KqbknMShfWLcdxHHO7r1Ih5jk2.png','مركز الذكاء الاصطناعي','AI HUB Morocco','يُعد AI HUB Morocco أول منظومة متكاملة للابتكار والتميز في مجال الذكاء الاصطناعي بالمغرب، ويهدف إلى تسريع تبني تقنيات الذكاء الاصطناعي ودعم التحول الرقمي لدى المؤسسات والشركات. يوفر المركز خدمات تطوير الحلول الذكية، وهندسة الذكاء الاصطناعي، وأتمتة العمليات، وتكامل النماذج اللغوية الكبيرة (LLMs)، إضافة إلى برامج التدريب والماستر كلاس، وحاضنة للشركات الناشئة، ومساحات عمل مخصصة للمبتكرين ورواد الأعمال. كما يعمل على تعزيز منظومة الابتكار من خلال شبكة AI4Morocco التي تجمع الخبراء والباحثين والمؤسسات لدعم تطوير الذكاء الاصطناعي في المغرب وإفريقيا.',NULL,'https://www.aihub.ma/',5,19,2,'2026-06-29 12:21:47','2026-06-29 12:21:47'),(341,'Photos_CentersExcellenceArtificialIntelligence/LybK9VgYJaQvKrhHQZRY5ctYuAVgCwKasZVVuZDw.png','معهد الذكاء الاصطناعي','AI Institute by Holmarcom','يُعد AI Institute by Holmarcom مركزًا مغربيًا متخصصًا في التدريب والاستشارات في مجالات الذكاء الاصطناعي وعلوم البيانات والمهارات الرقمية. أُنشئ من قبل مجموعة هولماركوم (Holmarcom Group) بهدف إعداد الكفاءات الوطنية ومواكبة التحول الرقمي داخل المؤسسات. ويقدم المعهد برامج تدريبية وشهادات مهنية معتمدة، إضافة إلى خدمات الاستشارات، وتصميم حلول الذكاء الاصطناعي، ومرافقة المؤسسات في تبني تقنيات الذكاء الاصطناعي وتطوير حالات الاستخدام العملية. كما يعمل على تأهيل الأفراد والمؤسسات من خلال برامج مرنة تجمع بين التدريب، والاعتماد المهني، والاستشارات، بما يواكب أحدث التطورات العالمية في مجال الذكاء الاصطناعي.\r\n\r\nوفي إطار شراكة استراتيجية مع Microsoft، يسعى المعهد إلى تقديم برامج تدريبية متوافقة مع المعايير العالمية، وتعزيز الابتكار، ودعم التحول الرقمي للمؤسسات المغربية، مع التركيز على تطوير المهارات المطلوبة لسوق العمل.',NULL,'https://ai-institute.ma/',5,19,2,'2026-06-29 12:28:54','2026-06-29 12:28:54'),(342,'Photos_SupportingBodiesScientificResearch/EwfjqWd3vLD3XbpFANziVM85x71DjXVN7kTsEg3s.png','المجلس الوطني للبحوث العلمية',NULL,'هو المؤسسة العامة الوطنية الرئيسية المسؤولة عن دعم وتنسيق وتوجيه البحث العلمي في لبنان. أُسس عام 1962 ويتمتع باستقلال إداري ومالي، ويعمل تحت إشراف رئاسة مجلس الوزراء، مع دور محوري في صياغة السياسة العلمية الوطنية وتمويل الأبحاث وبناء القدرات البحثية. \r\nالمهام :دعم وتمويل المشاريع البحثية، وتشجيع التعاون العلمي، وإدارة برامج المنح الدراسية والبحثية، إضافة إلى تشغيل مراكز بحث وطنية متخصصة.',NULL,'https://cnrs.edu.lb/about-us/the-cnrs-overview/',6,16,5,'2026-06-29 12:32:24','2026-06-29 12:32:24'),(344,'Photos_SupportingBodiesScientificResearch/dyCBhqFmD9TutEFb9xR3CBZpd2mvuEsDGHpzdPaE.jpg','المركز الوطني للاستشعار عن بعد',NULL,'هو مركز بحثي وطني في لبنان متخصص في الاستشعار عن بعد، وبيانات الأقمار الصناعية، ونظم المعلومات الجغرافية (GIS). يعمل ضمن المجلس الوطني للبحوث العلمية، ويُعد الجهة الوطنية الرائدة في تطوير واستخدام بيانات رصد الأرض لدعم البحث العلمي وصنع القرار في مجالات البيئة والزراعة والموارد الطبيعية. \r\nتأسس المركز عام 1995\r\nالمهام :يخدم الجهات الحكومية والباحثين والمؤسسات التنموية. ويشمل دوره جمع بيانات رصد الأرض، ومعالجتها، وتحليلها، ونشرها، إضافة إلى تطوير أدوات مكانية تساعد في التخطيط والإدارة المستدامة للموار',NULL,'https://cnrs.edu.lb/national-center-for-geophysics/',6,16,5,'2026-06-29 12:55:29','2026-06-29 12:55:29'),(345,'Photos_CentersExcellenceArtificialIntelligence/nCAGQdQHLNGNnJTh3XT0Xa8sg8stmwEhbgptCXDC.png','مجتمع الذكاء الاصطناعي والبيانات الموريتاني','RIM-AI','يُعد RIM-AI أول مجتمع وطني متخصص في الذكاء الاصطناعي وعلوم البيانات في الجمهورية الإسلامية الموريتانية، ويهدف إلى بناء منظومة وطنية للابتكار من خلال تعزيز البحث العلمي، والتعليم، والتدريب، والتعاون بين الباحثين والمهندسين ورواد الأعمال. ويعمل المجتمع على تطوير مشاريع تطبيقية في الذكاء الاصطناعي، وتنظيم ورش العمل والندوات والبرامج التدريبية، ودعم المواهب الوطنية، ونشر المعرفة في مجالات تعلم الآلة، وعلوم البيانات، والذكاء الاصطناعي المسؤول. كما يسعى إلى توظيف الذكاء الاصطناعي لمعالجة التحديات الوطنية، من خلال مبادرات مثل تطوير حلول للغات واللهجات الموريتانية، ومنصات تعليمية لتنمية مهارات الذكاء الاصطناعي، وبناء شراكات مع المؤسسات الحكومية والأكاديمية والقطاع الخاص لدعم التحول الرقمي في موريتانيا.',NULL,'https://www.rim-ai.com/',5,20,2,'2026-06-29 12:58:06','2026-06-29 12:58:06'),(346,'Photos_CentersExcellenceArtificialIntelligence/Oeka3YqrMu6sYu4YPPnBZehI6q5qdkHnEygfELlp.webp','مختبر نواكشوط للابتكار','NIL','يُعد مختبر نواكشوط للابتكار (NIL) منصة موريتانية للابتكار وريادة الأعمال، تهدف إلى بناء منظومة وطنية مستدامة للابتكار من خلال دعم رواد الأعمال والمبتكرين وأصحاب المشاريع التقنية. يعمل المختبر على تحويل الأفكار الواعدة إلى حلول عملية ذات أثر اقتصادي واجتماعي، من خلال توفير الإرشاد الاستراتيجي، وتصميم المنتجات، والتحقق من جدوى الأفكار، وتطوير نماذج الأعمال، وبناء الهوية المؤسسية، والاستعداد لإطلاق المشاريع. كما يسعى إلى تعزيز ثقافة الابتكار والتعاون، وتمكين الشباب والمبدعين من تطوير حلول مبتكرة لمعالجة التحديات المحلية، والمساهمة في بناء اقتصاد معرفي قائم على التكنولوجيا والابتكار في موريتانيا.',NULL,'https://www.nouakchottinnovationlab.org/',5,20,2,'2026-06-29 13:00:38','2026-06-29 13:57:26'),(347,'Photos_SupportingBodiesScientificResearch/STa34cb1tkG9l4Oq9ys523C3ckrUjiECzvITUjtf.png','الجامعة اللبنانية',NULL,'الجامعة اللبنانية هي الجامعة الوطنية الحكومية في لبنان، والمؤسسة الحكومية الوحيدة في البلاد التي تمولها الدولة للتعليم العالي. تأسست عام 1951، ونمت لتصبح أكبر جامعة في لبنان، وتخدم الطلاب في جميع أنحاء البلاد من خلال شبكة من الفروع والجامعات.\r\nالمهام : إتاحة التعليم العالي من خلال رسوم دراسية منخفضة نسبياً. وهي تُعلّم طلاباً من خلفيات اجتماعية ودينية وإقليمية متنوعة، وتُعدّ مركزاً هاماً للبحث العلمي والتدريب المهني والخدمة العامة.',NULL,'https://ul.edu.lb/en/research',6,16,5,'2026-06-29 13:01:32','2026-06-29 13:01:32'),(348,'Photos_SupportingBodiesScientificResearch/p72i0myJpN0HRuOMbr7FnnZNFJVYNMH4yUEzHPBO.png','الهيئة الوطنية للبحث العلمي',NULL,'المعروفة رسميًا اليوم باسم الهيئة الليبية للبحث العلمي، هي مؤسسة حكومية ليبية تُعنى بتنسيق ودعم وإدارة منظومة البحث العلمي في البلاد. أُسست عام 1978، وتعمل على تطوير السياسات والبرامج البحثية، ودعم الباحثين والمراكز العلمية، وربط البحث العلمي بأولويات التنمية الوطنية.\r\nالمهام :تقديم الدعم للمشروعات العلمية، وتوثيق المخرجات البحثية ومتابعتها. كما تهدف إلى تعبئة جهود العلماء والباحثين والمخترعين لخدمة احتياجات الدولة في مختلف المجالات.',NULL,'https://www.aonsrt.ly/',6,17,5,'2026-06-29 13:33:28','2026-06-29 13:33:28'),(349,'Photos_SupportingBodiesScientificResearch/5RFqouzDCNcQV4I2XYKFXuLAWcoM4eyuHl4GK4N2.jpg','المركز القومي للبحوث والدراسات العلمية',NULL,'هو مؤسسة بحثية ليبية تُعنى بإعداد الدراسات والبحوث وتقديم الاستشارات العلمية في القضايا ذات الأهمية الوطنية. ويُعرف بدوره في دعم مؤسسات الدولة من خلال الأبحاث والتحليلات في المجالات السياسية والاقتصادية والاجتماعية والأمنية.\r\nتاسس عام :1985\r\nالمهام :  ربط البحث العلمي باحتياجات صنع القرار في ليبيا. ويجمع بين الإنتاج الأكاديمي والأنشطة التطبيقية، بما في ذلك إعداد الدراسات، وإقامة الفعاليات العلمية، ونشر الأبحاث، بهدف توفير معرفة يمكن أن تدعم التخطيط والسياسات العامة.',NULL,'https://ncrss.gov.ly/aboutus.html',6,17,5,'2026-06-29 13:40:32','2026-06-29 13:40:32'),(350,'Photos_CentersExcellenceArtificialIntelligence/gDmdgPd4jQxC5xHCfIDBx9jtrIqijOZtxwcrfHyi.png','مختبر الابتكار','Innovation Lab','يُعد مختبر الابتكار (Innovation Lab) مبادرة تقنية وتعليمية تهدف إلى تمكين الشباب من اكتساب مهارات الابتكار والتكنولوجيا وريادة الأعمال، من خلال برامج تدريبية عملية قائمة على التعلم بالمشاريع. يركز المختبر على مجالات التفكير التصميمي (Design Thinking)، وإنترنت الأشياء (IoT)، والحوسبة الفيزيائية، وتطوير تطبيقات الويب والهواتف الذكية، حيث يعمل المشاركون ضمن فرق متعددة التخصصات لتطوير حلول مبتكرة للتحديات الواقعية. كما يسهم المختبر في تعزيز ثقافة الابتكار والإبداع، وربط المعرفة الأكاديمية بالتطبيق العملي، ودعم إنشاء مشاريع تقنية ناشئة ذات أثر مجتمعي.',NULL,'https://lab.wikilogia.org/',5,9,2,'2026-06-29 14:02:29','2026-06-29 14:02:29'),(351,'Photos_CentersExcellenceArtificialIntelligence/JiTx49nGoEoQPOOqtcaRtZ7CWvt1GBHAGj8DI1EV.jpg','ابتكار (Ibtechar)',NULL,'ابتكار (Ibtechar) هي شركة قطرية رائدة في مجال تطوير وإدارة الابتكار، تأسست عام 2011 كأول شركة ناشئة احتضنها مركز قطر لحاضنات الأعمال. تعمل الشركة بالشراكة مع الجهات الحكومية والقطاع الخاص والمؤسسات غير الربحية لتطوير القدرات المؤسسية من خلال الاستشارات، والتدريب، وإدارة المشاريع، وتصميم وتنفيذ منظومات الابتكار. وتقدم خدماتها عبر ذراعين رئيسيين هما أكاديمية ابتكار (Ibtechar Academy) للتدريب وبناء القدرات، واستشارات ابتكار (Ibtechar Consultancy) لتطوير استراتيجيات الابتكار، وإنشاء مختبرات الابتكار، وتصميم البرامج والمبادرات الداعمة للتحول الرقمي. كما تدعم الشركة تبني التقنيات الناشئة، بما في ذلك الذكاء الاصطناعي، وتطوير المهارات الرقمية، بما يسهم في تحقيق أهداف التنمية الوطنية وتعزيز الابتكار في دولة قطر ودول الخليج.',NULL,'https://ibtechar.com/',5,14,2,'2026-06-29 14:14:21','2026-06-29 14:14:21'),(352,'Photos_SupportingBodiesScientificResearch/FkOyAHNnBFwPXPQC9vi0Jtrq9FvsEzjc6a3orAC0.png','مركز البحوث والاستشارات العلمية بجامعة سبها',NULL,'هو وحدة أكاديمية متخصصة تابعة لـ جامعة سبها تُعنى بدعم البحث العلمي وتقديم الاستشارات العلمية والتدريب. ويؤدي المركز دورًا محوريًا في تنسيق الأنشطة البحثية داخل الجامعة، وربط الخبرات الأكاديمية باحتياجات المجتمع والمؤسسات في ليبيا، بما يتماشى مع رسالة الجامعة في خدمة التنمية.\r\nتاسس عام 2006 \r\nالمهام : الإسهام في تطوير الخطط البحثية، والإشراف على تنفيذ استراتيجية الجامعة في مجال البحث العلمي، وتوجيه الدراسات نحو معالجة قضايا التنمية، وتقديم الاستشارات للمؤسسات الإنتاجية والخدمية، إلى جانب تنمية القدرات البحثية والتدريبية للكوادر الأكاديمية والباحثين.',NULL,'https://sebhau.edu.ly/scientific-research-consultation-center/',6,17,5,'2026-06-29 14:17:15','2026-06-29 14:17:15'),(353,'Photos_CentersExcellenceArtificialIntelligence/EleBk7DMfhNO4W2uxxBQUrjPpjWXB0PEXzzrTxk3.png','مركز ريادة الأعمال والابتكار',NULL,'يُعد مركز ريادة الأعمال والابتكار التابع لجامعة فاروس بالإسكندرية منصة جامعية متخصصة تهدف إلى نشر ثقافة الابتكار وريادة الأعمال، وتمكين الطلبة والخريجين ورواد الأعمال من تحويل أفكارهم الإبداعية إلى مشاريع ريادية مستدامة. ويعمل المركز على تنمية المهارات الريادية، وتعزيز الإبداع والابتكار، وتوفير بيئة داعمة لاحتضان المبادرات والمشروعات الناشئة، من خلال برامج التدريب، وورش العمل، والإرشاد والتوجيه، وبناء الشراكات مع مؤسسات التمويل وقطاع الأعمال. كما يسهم المركز في تعزيز التعاون بين الجامعة والمجتمع، ودعم التنمية الاقتصادية والاجتماعية والبيئية، وإعداد جيل من رواد الأعمال القادرين على قيادة المستقبل والمساهمة في تحقيق التنمية المستدامة.',NULL,'https://www.pua.edu.eg/entrepreneurship/',5,18,2,'2026-06-29 14:19:47','2026-06-29 14:19:47'),(354,'Photos_SupportingBodiesScientificResearch/JQ4IS319Fd2lYiROntekF76A0W3AaOpLs2LAbita.png','مركز البحوث والاستشارات العلمية بجامعة الزاوية',NULL,'هو الذراع البحثية والاستشارية التابعة لجامعة الزاوية في ليبيا، ويختص بدعم البحث العلمي، وتقديم الاستشارات، وتنظيم الأنشطة الأكاديمية، وتعزيز التعاون بين الجامعة والمجتمع.\r\nتاسس عام 1995\r\nالمهام : دعم البحث العلمي وتمويله وتوجيهه بما يخدم احتياجات المجتمع.\r\nتقديم الاستشارات والخبرات للقطاعين العام والخاص والأفراد من خلال خبرات أعضاء هيئة التدريس.',NULL,'https://rcc.zu.edu.ly/',6,17,5,'2026-06-29 14:21:36','2026-06-29 14:21:36'),(355,'Photos_CentersExcellenceArtificialIntelligence/Po0IBrWoCcIsRhTC7UtE3NAUz0rMesSuJZvWwYcp.jpg','معهد الابتكار العالمي – مركز الشرق الأوسط وشمال أفريقيا','Global Innovation Institute – Middle East & North Africa Center','يُعد معهد الابتكار العالمي – مركز الشرق الأوسط وشمال أفريقيا (GInI MENA) المركز الإقليمي لمعهد الابتكار العالمي (GInI)، ويهدف إلى نشر ثقافة الابتكار المؤسسي وتعزيز ممارسات إدارة الابتكار في منطقة الشرق الأوسط وشمال أفريقيا. ويوفر المركز برامج تدريبية احترافية، وشهادات مهنية معتمدة عالميًا، وخدمات استشارية واعتمادات للمؤسسات في مجالات الابتكار، والتفكير التصميمي، واستراتيجية الابتكار، وقيادة الابتكار، بما يسهم في تطوير الكفاءات البشرية وتعزيز القدرة التنافسية للمؤسسات. كما يعمل على نشر أفضل الممارسات العالمية في الابتكار من خلال تطوير المعايير والأدوات والبحوث التطبيقية، وبناء مجتمع مهني يدعم التحول نحو اقتصاد قائم على المعرفة والابتكار.',NULL,'https://ginimena.org/',5,2,2,'2026-06-29 14:24:32','2026-06-29 14:24:32'),(356,'Photos_ScientificResearchInnovationCenters/K9llgFoDEgmdqZACnMI2rSgMWycEDYX84uFs8d3G.jpg','معهد الابتكار العالمي – مركز الشرق الأوسط وشمال أفريقيا','Global Innovation Institute – Middle East & North Africa Center','يُعد معهد الابتكار العالمي – مركز الشرق الأوسط وشمال أفريقيا (GInI MENA) المركز الإقليمي لمعهد الابتكار العالمي (GInI)، ويهدف إلى نشر ثقافة الابتكار المؤسسي وتعزيز ممارسات إدارة الابتكار في منطقة الشرق الأوسط وشمال أفريقيا. ويوفر المركز برامج تدريبية احترافية، وشهادات مهنية معتمدة عالميًا، وخدمات استشارية واعتمادات للمؤسسات في مجالات الابتكار، والتفكير التصميمي، واستراتيجية الابتكار، وقيادة الابتكار، بما يسهم في تطوير الكفاءات البشرية وتعزيز القدرة التنافسية للمؤسسات. كما يعمل على نشر أفضل الممارسات العالمية في الابتكار من خلال تطوير المعايير والأدوات والبحوث التطبيقية، وبناء مجتمع مهني يدعم التحول نحو اقتصاد قائم على المعرفة والابتكار.',NULL,'https://ginimena.org/',5,2,1,'2026-06-29 14:25:28','2026-06-29 14:25:28'),(357,'Photos_CentersExcellenceArtificialIntelligence/YOLxBxmXSX1Ij4voUlFb2SRW3oNkOsevbQChVMux.webp','معهد متخصص في الذكاء الاصطناعي والتقنيات الرقمية','Tech Iftiin','يُعد معهد Tech Iftiin للذكاء الاصطناعي والتكنولوجيا أول معهد متخصص في جمهورية جيبوتي يُعنى بتأهيل الكفاءات في مجالات الذكاء الاصطناعي والتقنيات الرقمية. \r\nويهدف المعهد إلى إعداد جيل من المتخصصين القادرين على قيادة التحول الرقمي من خلال تقديم برامج تدريبية تطبيقية في الذكاء الاصطناعي، وتطوير البرمجيات، وعلوم البيانات، وهندسة الأوامر (Prompt Engineering)، والأمن السيبراني، وتطوير تطبيقات الويب والهواتف الذكية. كما يقدم المعهد خدمات استشارية وحلولًا تقنية للمؤسسات، ويسهم في دعم الابتكار وريادة الأعمال وبناء القدرات الرقمية، بما يعزز التنمية التكنولوجية في جيبوتي والمنطقة.',NULL,'https://techiftiin.com/',5,6,2,'2026-06-29 14:32:55','2026-06-29 14:32:55'),(358,'Photos_CentersExcellenceArtificialIntelligence/p32yP0qxImoxXN35yFugvN0ijlbgaH8bLKrPr2xk.jpg','مركز الذكاء الاصطناعي والتحول الرقمي','Artificial Intelligence and Digital Transformation Center - AIDTC','مركز الذكاء الاصطناعي والتحول الرقمي (AIDTC) هو مركز عربي متخصص في دعم البحث العلمي والابتكار والتدريب في مجالات الذكاء الاصطناعي والتحول الرقمي، ويهدف إلى تطوير الكفاءات وبناء شراكات علمية وتقنية بين الجامعات والمؤسسات العربية. يتخذ من جامعة عجلون الوطنية في الأردن مقراً له ويعمل تحت مظلة اتحاد الجامعات العربية.',NULL,'https://aidtc.org/c/',5,1,2,'2026-06-30 09:38:33','2026-06-30 09:41:49'),(359,'Photos_ScientificResearchInnovationCenters/4K1lkTAa6Q6pwaoVKCDRgKHqqdw0GRMYWE3goSg7.jpg','مركز الذكاء الاصطناعي والتحول الرقمي','Artificial Intelligence and Digital Transformation Center','مركز الذكاء الاصطناعي والتحول الرقمي (AIDTC) هو مركز عربي متخصص في دعم البحث العلمي والابتكار والتدريب في مجالات الذكاء الاصطناعي والتحول الرقمي، ويهدف إلى تطوير الكفاءات وبناء شراكات علمية وتقنية بين الجامعات والمؤسسات العربية. يتخذ من جامعة عجلون الوطنية في الأردن مقراً له ويعمل تحت مظلة اتحاد الجامعات العربية.',NULL,'https://aidtc.org/c/',5,1,1,'2026-06-30 09:41:02','2026-06-30 09:41:02'),(360,'Photos_SupportingBodiesScientificResearch/2y3VZYuwI5NM8vmZ6VEonhA71ZWm7GwrTVRpKU1d.png','صندوق رعاية المبتكرين والنوابغ',NULL,'هو مؤسسة حكومية مصرية تعمل تحت مظلة وزارة التعليم العالي والبحث العلمي لدعم الابتكار، ورعاية الموهوبين، وتحويل الأفكار البحثية والإبداعية إلى مشروعات ذات أثر اقتصادي ومجتمعي.\r\nتاسس عام:2019\r\nالمهام: تمويل المشروعات الابتكارية، وتقديم برامج للطلاب والباحثين ورواد الأعمال، إلى جانب بناء شراكات مع الجامعات والصناعة والمستثمرين. كما يدعم نقل التكنولوجيا، وتشجيع تأسيس الشركات الناشئة القائمة على المعرفة، بما يسهم في تحويل نتائج البحث العلمي إلى تطبيقات عملية.',NULL,'https://www.isf.gov.eg/',6,18,5,'2026-06-30 09:41:46','2026-06-30 09:41:46'),(361,'Photos_SupportingBodiesScientificResearch/TQYxJKAJSZ1xdbDTeoxkLEjhayVu3rRzFAToPubD.jpg','أكاديمية البحث العلمي والتكنولوجيا',NULL,'الجمعية المصرية للبحث العلمي والابتكار (ASRT) هي الهيئة الوطنية المصرية المسؤولة عن تخطيط وتنسيق ودعم البحث العلمي والتكنولوجيا والابتكار. تأسست عام 1971، وتعمل كهيئة استشارية وتمويلية مركزية تربط الجامعات ومعاهد البحوث والصناعة والحكومة لتعزيز بيئة البحث والابتكار في البلاد.\r\nالمهام :  تمويل المشاريع البحثية ، ودعم الابتكار وريادة الأعمال ، ووضع استراتيجيات وطنية للعلوم والتكنولوجيا ، وتعزيز التعاون بين المؤسسات الأكاديمية والقطاع الصناعي والشركاء الدوليين.',NULL,'https://ar.council.science/about-us/',6,18,5,'2026-06-30 10:02:25','2026-06-30 10:02:25'),(362,'Photos_CentersExcellenceArtificialIntelligence/HWaP3Yehyu3nS2uqGChpv2QFsioQq06tg8C2xFT1.jpg','مركز الذكاء الاصطناعي في مركز دبي للسلع المتعددة',NULL,'مركز الذكاء الاصطناعي في مركز دبي للسلع المتعددة  هو مركز رائد في المنطقة للابتكار العملي في مجال الذكاء الاصطناعي. \r\nويقود المركز مستقبلاً يُحفّز فيه الذكاء الاصطناعي تغييرات تحويلية في مختلف الصناعات، ويمكّن الشركات ويدفع النمو المستدام في التجارة العالمية.',NULL,'https://www.dubaichambers.com/',5,2,2,'2026-06-30 10:07:38','2026-06-30 10:07:38'),(363,'Photos_SupportingBodiesScientificResearch/HZiqVVDVAA73zkVvtwzUBfAaF4FLMu5H1pCu5wfs.png','هيئة تمويل العلوم الجديدة',NULL,'هيئة البحث العلمي هي المنظمة الوطنية المصرية لتمويل البحث العلمي وتطوير التكنولوجيا والابتكار. تعمل الهيئة في إطار نظام التعليم العالي والبحث العلمي في البلاد، وتدعم الباحثين والجامعات ومعاهد البحوث والشراكات الصناعية من خلال منح تنافسية تهدف إلى تعزيز القدرات البحثية في مصر وتشجيع الابتكار.\r\nتاسس عام 2019\r\nالمهام :دعم الباحثين الشباب، وتمويل مراكز التميز، وتشجيع التعاون العلمي الدولي، والمساعدة في تحويل نتائج البحوث إلى تطبيقات تجارية أو عملية. كما تشارك الهيئة في برامج تعزز ريادة الأعمال، وتطوير الملكية الفكرية، وبيئات الابتكار في جميع أنحاء مصر.',NULL,'https://stdf.eg/web/page/64152',6,18,5,'2026-06-30 10:17:28','2026-06-30 10:17:28'),(364,'Photos_SupportingBodiesScientificResearch/4fwFOqNKL3l83VVcBxNpZUd8DCqvmes3crz7MMgn.png','المركز القومي للبحوث',NULL,'يُعدّ المركز القومي للبحوث (NRC) أكبر مؤسسة بحثية علمية متعددة التخصصات في مصر، حيث يُجري بحوثًا أساسية وتطبيقية في طيف واسع من المجالات العلمية والتكنولوجية. تأسس المركز عام 1956 ، ويتبع لوزارة التعليم العالي والبحث العلمي المصرية، ويضطلع بدور محوري في دعم البحث والابتكار والتطوير التكنولوجي على المستوى الوطني.\r\nالمهام :يدير المركز بنية تحتية مختبرية واسعة النطاق، ومزارع بحثية، ومرافق متخصصة تدعم البحث العلمي، ونقل التكنولوجيا، وتطوير براءات الاختراع، والتعاون مع الجامعات والهيئات الحكومية والقطاع الصناعي.',NULL,'https://software.twasol-solutions.com/about-us',6,18,5,'2026-06-30 10:27:49','2026-06-30 10:27:49'),(365,'Photos_SupportingBodiesScientificResearch/B034k6zz5eKGMjaqO66ey3pMQFqohDW2kDy7hfIO.jpg','معهد بحوث الإلكترونيات',NULL,'هو و مؤسسة بحثية حكومية مصرية متخصصة في أبحاث الإلكترونيات والاتصالات وتكنولوجيا المعلومات. أُنشئ عام 1989 ويتبع وزارة البحث العلمي، ويُعد من أكبر المراكز البحثية المتخصصة في هذا المجال داخل مصر، مع تركيز على تحويل الأبحاث إلى تطبيقات صناعية وخدمات تقنية.\r\nالمهام : يشمل نشاط المعهد الأبحاث الأساسية والتطبيقية في مجالات مثل الإلكترونيات الدقيقة، وهندسة الموجات الدقيقة، والخلايا الكهروضوئية، وإلكترونيات القدرة، والحاسبات والنظم، والمعلوماتية. كما يقدم استشارات علمية وخدمات فنية للقطاعين الصناعي والخدمي، ويضم معامل مركزية متخصصة لدعم البحث والتطوير.',NULL,'https://eri.sci.eg/ar/about-us',6,18,5,'2026-06-30 10:44:59','2026-06-30 10:44:59'),(366,'Photos_ScientificResearchInnovationCenters/occGht0SnlLu3BV9WR1Av4ZGK6fhFQP6otVnvELV.png','مركز سمت للدراسات',NULL,'يُعد مركز سمت للدراسات مركزًا بحثيًا مستقلًا مقره الرياض، المملكة العربية السعودية، ويعنى برصد وتحليل المستجدات السياسية والاقتصادية والاستراتيجية والتقنية على المستويين الإقليمي والدولي. \r\nويهدف المركز إلى دعم صناعة القرار ونشر المعرفة من خلال إعداد الدراسات والتحليلات والتقارير المتخصصة، إضافة إلى ترجمة ونشر أبرز الأبحاث العالمية في مجالات الاقتصاد، والتحول الرقمي، والذكاء الاصطناعي، والطاقة، والأمن، والعلاقات الدولية. كما يوفر منصة معرفية للباحثين وصناع القرار والمهتمين بالشؤون الاستراتيجية والتنموية.',NULL,'https://smtcenter.net/archives/slider',5,7,1,'2026-06-30 10:45:41','2026-06-30 10:45:41'),(367,'Photos_SupportingBodiesScientificResearch/B1s31t9UBHpc8jyYL4tZ4W3CEWvsOgSxk77ugTK0.png','مؤسسة زويل للعلوم والتكنولوجيا والابتكار',NULL,'هي مؤسسة مصرية مستقلة غير هادفة للربح تجمع بين التعليم الجامعي والبحث العلمي والابتكار. تحمل اسم العالم الحائز على جائزة نوبل في الكيمياء أحمد زويل، وتهدف إلى دعم البحث العلمي المتقدم وإعداد كوادر قادرة على المساهمة في التنمية القائمة على المعرفة في مصر.\r\nتاسست عام :2011\r\nالمهام :تركز المؤسسة على التعليم القائم على الجدارة، والبحث العلمي عالي المستوى، وربط الجامعات بالصناعة والمجتمع. وتشارك فرقها البحثية في مشروعات وتعاونات علمية دولية،',NULL,'https://www.zewailcity.edu.eg/about/about-zewail-city',6,18,5,'2026-06-30 10:50:05','2026-06-30 10:50:05'),(368,'Photos_ScientificResearchInnovationCenters/o582rjttxvblzFqhdtzjOcua46zvPUvXS3hXamc2.png','المركز الوطني للذكاء الاصطناعي والتكنولوجيا','NCAI-YEMEN','المركز الوطني للذكاء الاصطناعي والتكنولوجيا (NCAI - YEMEN) هو مركز يمني أسسته الأكاديمية الوطنية اليمنية للعلماء الشباب (YEMSCI)، ويُعنى بتعزيز استخدام الذكاء الاصطناعي والتقنيات الناشئة لدعم التحول الرقمي وبناء القدرات الوطنية. يهدف المركز إلى إنشاء بنية معرفية متقدمة من خلال تقديم برامج التدريب الرقمي، ودعم البحث العلمي والابتكار، وتمكين الجامعات والمؤسسات من تبني تطبيقات الذكاء الاصطناعي في التعليم والخدمات والتنمية. كما يعمل وفق نموذج افتراضي متكامل يعتمد على منصات التعليم الإلكتروني والمختبرات الافتراضية وشبكة من الخبراء والمدربين من داخل اليمن وخارجه، بما يضمن إتاحة فرص التعلم والتأهيل للطلاب والباحثين في مختلف المحافظات، ويسهم في تحفيز البحث العلمي وتطوير حلول تقنية مبتكرة لخدمة التنمية وصنع القرار.',NULL,'https://ncai-ye.com/',5,21,1,'2026-06-30 11:04:33','2026-06-30 11:04:33'),(369,'Photos_CentersExcellenceArtificialIntelligence/e8jfdrBuBwhTEQUtAC8SfXmsvOfVzERiDGJqRkqu.png','المركز الوطني للذكاء الاصطناعي والتكنولوجيا','NCAI - YEMEN','المركز الوطني للذكاء الاصطناعي والتكنولوجيا  هو مركز متخصص في الذكاء الاصطناعي والتكنولوجيا، يهدف إلى نشر ثقافة الذكاء الاصطناعي وتطوير الكفاءات الوطنية في مجالات التقنيات الذكية، من خلال التدريب، ودعم البحث العلمي، والابتكار، وتمكين المؤسسات التعليمية والبحثية من تبني تطبيقات الذكاء الاصطناعي والتقنيات الناشئة. كما يسعى إلى بناء بيئة رقمية متقدمة تُسهم في إعداد كوادر مؤهلة، وتعزيز استخدام الذكاء الاصطناعي في مختلف القطاعات لدعم التنمية المستدامة وصنع القرار.',NULL,'https://ncai-ye.com',5,21,2,'2026-06-30 11:05:43','2026-06-30 11:17:29'),(370,'Photos_SupportingBodiesScientificResearch/otYdGev0hprb4x0qAkhwNXqOm6SN0dm12GGPVhsj.png','الوكالة الوطنية للنهوض بالمقاولة الصغرى والمتوسطة',NULL,'هي منظمة عامة مغربية تدعم التنمية والقدرة التنافسية للمؤسسات الصغيرة والمتوسطة (SMEs). وتلعب دورًا مركزيًا في تنفيذ البرامج الحكومية التي تساعد الشركات على التحديث وتحسين الإنتاجية وتبني التقنيات الرقمية وتعزيز قدرتها على المنافسة في الأسواق المحلية والدولية.',NULL,'https://marocpme.gov.ma/',6,19,5,'2026-06-30 11:25:54','2026-06-30 11:25:54'),(371,'Photos_CentersExcellenceArtificialIntelligence/UWIFrHfdRlCrw7PvPnekVOKYpH7ERyspxxPoahgt.jpg','المعهد العالي للذكاء الاصطناعي','Higher Institute of Artificial Intelligence - HIAI','المعهد العالي للذكاء الاصطناعي  هو مؤسسة تدريبية واستشارية متخصصة في الذكاء الاصطناعي، تتخذ من دبي، الإمارات العربية المتحدة مقرًا لها. يهدف المعهد إلى تمكين الأفراد والمؤسسات من اكتساب المعارف والمهارات اللازمة للاستفادة من تقنيات الذكاء الاصطناعي، من خلال تقديم برامج تدريبية متخصصة، واستشارات احترافية، ومؤتمرات وورش عمل، إلى جانب شهادات معتمدة دوليًا. ويسعى المعهد إلى دعم التحول الرقمي، وتعزيز الابتكار، ونشر ثقافة الذكاء الاصطناعي، وبناء كوادر مؤهلة قادرة على توظيف التقنيات الذكية في مختلف القطاعات، بما في ذلك التعليم والأعمال والخدمات.',NULL,'https://hiai.institute/',5,2,2,'2026-06-30 11:32:26','2026-06-30 11:32:26'),(372,'Photos_SupportingBodiesScientificResearch/LK1m7LoMHn2GZnIXyGpcDSEnwvE3l0nUiyggVA2B.png','وكالة التنمية الرقمية',NULL,'هي مؤسسة عامة مغربية مسؤولة عن تعزيز وتسريع التحول الرقمي في البلاد. وهي تدعم الابتكار الرقمي، ومبادرات الحكومة الإلكترونية، وريادة الأعمال، وتطوير النظام البيئي الرقمي الوطني، وذلك من خلال العمل مع المؤسسات العامة والشركات والأوساط الأكاديمية.\r\nتاسست عام 2017\r\nالمهام :تتمثل المهمة الرئيسية للوكالة في المساعدة على تنفيذ استراتيجية التنمية الرقمية في المغرب. ويشمل عملها دعم رقمنة الخدمات العامة، وتشجيع تبني التقنيات الرقمية في مختلف القطاعات، وتعزيز المهارات الرقمية، ودعم الابتكار، والمساعدة في تهيئة بيئة مواتية لنمو الشركات الناشئة وشركات التكنولوجيا. كما تنسق الوكالة مع الوزارات الحكومية والجهات المعنية الأخرى بشأن المبادرات الرقمية الوطنية.',NULL,'https://www.add.gov.ma/',6,19,5,'2026-06-30 11:39:24','2026-06-30 11:39:24'),(373,'Photos_SupportingBodiesScientificResearch/8EWmJpBF6QyHp0nqeYOszRStlcy55TwzDW1teBAa.jpg','المركز المغربي للابتكار وريادة الأعمال',NULL,'لمركز المغربي للابتكار وريادة الأعمال، المعروف دوليًا باسم MCISE (Moroccan Center for Innovation and Social Entrepreneurship)، هو منظمة مغربية غير ربحية تأسست عام 2012 لدعم الابتكار الاجتماعي وريادة الأعمال الاجتماعية في المغرب. ويعمل على تطوير حلول مبتكرة للتحديات الاجتماعية من خلال التدريب، والاحتضان، والإرشاد، وبناء الشراكات بين رواد الأعمال والقطاعين العام والخاص.\r\nيرتكز عمل المركز على ثلاثة محاور رئيسية:\r\nالإلهام (Inspire): نشر ثقافة الابتكار وريادة الأعمال الاجتماعية.\r\nالتعليم (Educate): تطوير محتوى وبرامج تدريبية للطلاب والباحثين ورواد الأعمال.\r\nالتطوير (Develop): تصميم وتنفيذ برامج احتضان وتسريع للمبادرات والمشاريع ذات الأثر الاجتماعي.',NULL,'https://mcise.org/who-we-are/',6,19,5,'2026-06-30 11:49:03','2026-06-30 11:49:03'),(374,'Photos_ScientificResearchInnovationCenters/g7kLgyNoZ2pnThlwFJiMK7MLRAuMtYqMjnnCVFvU.png','مركز إيلاف للدراسات',NULL,'مركز إيلاف للدراسات هو مؤسسة بحثية مستقلة مقرها عمّان، الأردن، تُعنى بإجراء الدراسات والبحوث الاستراتيجية والسياسية، وتحليل التحولات المحلية والإقليمية والدولية. \r\n\r\nويهدف المركز إلى ربط المعرفة الأكاديمية بصناعة القرار من خلال إنتاج أبحاث علمية رصينة، وتعزيز الحوار الفكري، وبناء القدرات، ودعم المشاركة المجتمعية. كما يعمل على تقديم رؤى وتحليلات موضوعية تسهم في فهم القضايا السياسية والاستراتيجية وصياغة السياسات العامة، بما يعزز الوعي والمعرفة على المستويين الأردني والعربي',NULL,'https://www.eilafcenter.org/',5,1,1,'2026-06-30 11:51:54','2026-06-30 11:51:54'),(375,'Photos_SupportingBodiesScientificResearch/NjOnWa2M6c9fR10521oPlyPEQRD7bRbSlSk2Y7TY.jpg','معهد البحث في الطاقة الشمسية والطاقات الجديدة',NULL,'هي منظمة بحثية مغربية غير ربحية تركز على الطاقة المتجددة وكفاءة الطاقة والابتكار التطبيقي . تأسست عام 2011 ومقرها في الرباط ، وتلعب دورًا رئيسيًا في دعم التحول في مجال الطاقة في المغرب من خلال ربط الجامعات والصناعة والشركات الناشئة والمؤسسات العامة من خلال البحث وتطوير التكنولوجيا.\r\nالمهام : مهمة المعهد في تسريع تطوير ونشر تقنيات الطاقة النظيفة في المغرب. و تمويل مشاريع الابتكار ، ودعم نقل التكنولوجيا، ومساعدة رواد الأعمال والباحثين على تحويل أفكارهم إلى منتجات تجارية، وتعزيز القدرات البحثية الوطنية. وتشمل المجالات الرئيسية الطاقة الشمسية، وطاقة الرياح، والهيدروجين الأخضر، والكتلة الحيوية، والشبكات الذكية، والمباني الموفرة للطاقة.',NULL,'https://iresen.org/accueil/',6,19,5,'2026-06-30 11:58:22','2026-06-30 11:58:22'),(376,'Photos_SupportingBodiesScientificResearch/ZUvEQKYQ0WX1gjV1YeJtCv9RyqCM0BLQ7fcMjC4e.jpg','المركز الوطني للكهرباء والعلوم والتقنيات الذكية',NULL,'هو المؤسسة الوطنية العمومية المغربية للعلوم والتكنولوجيا النووية وتطبيقاتها السلمية. وهو بمثابة المركز الرئيسي في البلاد للأبحاث النووية والخبرة الفنية والخدمات المتخصصة والتدريب المهني مع دعم السلطات الوطنية في المسائل النووية والإشعاعية.\r\nتأسس المركز الوطني لبحوث الطاقة المستدامة (CNESTEN) عام 1986 كمؤسسة عامة تحت إشراف وزارة التحول الطاقي المغربية. وتتألف مهمته من ثلاث وظائف رئيسية:\r\nالبحث والتدريب في العلوم والتكنولوجيا النووية.\r\nتقديم المشورة والدعم الفني للسلطات الحكومية بشأن السلامة والأمن النووي والإشعاعي والتأهب للطوارئ.\r\nخدمات علمية وتحليلية للمؤسسات العامة والصناعة والرعاية الصحية والزراعة والإدارة البيئية.',NULL,'https://www.cnesten.org.ma/',6,19,5,'2026-06-30 12:03:46','2026-06-30 12:03:46'),(377,'Photos_ScientificResearchInnovationCenters/DD3LPJVI67XspMFH3YTBQJIXJolhflvbReb6FSNZ.png','مركز LAB7 للابتكار وتطوير المنتجات','LAB7 – Innovation & Product Development Center','LAB7 هو مركز سعودي متخصص في دعم الابتكار وريادة الأعمال التقنية،\r\nو يهدف إلى تمكين الشركات الناشئة ورواد الأعمال من تطوير حلول ومنتجات تقنية مبتكرة وتحويلها إلى مشاريع مستدامة وقابلة للنمو. يوفر المركز بيئة متكاملة تشمل الإرشاد، وتطوير المنتجات، وبناء النماذج الأولية، والاستشارات، وربط المبتكرين بالمستثمرين والشركاء، بما يسهم في تعزيز منظومة الابتكار، وتسريع نقل التقنيات إلى السوق، ودعم التنمية الاقتصادية القائمة على المعرفة والابتكار',NULL,'https://lab7.com.sa/',5,7,1,'2026-06-30 12:06:12','2026-07-01 14:19:25'),(378,'Photos_SupportingBodiesScientificResearch/Ei8KleXkVcoKWTcIVoEoCH7lDfgiAYe0R3iklnOA.png','المركز الوطني للبحث العلمي والتقني',NULL,'المركز الوطني للبحث العلمي والتقني (CNRST) هو المؤسسة العمومية الوطنية في المغرب المكلفة بدعم وتطوير وتثمين البحث العلمي والتقني. ويُعد أحد أبرز الفاعلين في منظومة البحث والابتكار بالمملكة، إذ يدير برامج تمويل، وبنى تحتية بحثية، وشراكات علمية وطنية ودولية تحت إشراف وزارة التعليم العالي والبحث العلمي والابتكار.\r\nتاسس عام 2001\r\nالمهام :شمل مهام المركز تمويل مشاريع البحث، ودعم تكوين الباحثين وطلبة الدكتوراه، وتعزيز البنية التحتية العلمية، ونشر المعلومات العلمية والتقنية، إضافة إلى تشجيع نقل التكنولوجيا والتعاون بين الجامعات ومؤسسات البحث والقطاعين العام والخاص. كما ينظم بانتظام دعوات لتقديم المشاريع وبرامج للتعاون الدولي.',NULL,'https://www.cnrst.ma/ar/#',6,19,5,'2026-06-30 12:07:54','2026-06-30 12:07:54'),(379,'Photos_SupportingBodiesScientificResearch/xVI5lsme7cAx4NfEBVP3AhDumacAzvkd5IP3bASy.png','مؤسسة البحث والتعلم',NULL,'مؤسسة البحث والتنمية والابتكار في العلوم والهندسة (FRDISI) هي مؤسسة مغربية ذات منفعة عامة تعمل على دعم البحث العلمي، والابتكار، ونقل التكنولوجيا، وريادة الأعمال. وتجمع بين أنشطة البحث والتكوين واحتضان المشاريع بهدف تعزيز التعاون بين الجامعات والقطاع الصناعي والمساهمة في التنمية الاقتصادية والتكنولوجية في المغرب.\r\nتاسست عام  2013\r\nالمهام :البحث والتطوير في مجالات العلوم والهندسة.\r\nنقل التكنولوجيا وربط نتائج البحث العلمي باحتياجات الصناعة.\r\nاحتضان الشركات الناشئة ومواكبة رواد الأعمال.\r\nالتكوين والتدريب في مجالات الهندسة والتكنولوجيا.\r\nتنفيذ مشاريع تعاونية مع الجامعات والقطاعين العام والخاص .',NULL,'https://www.frdisi.ma/',6,19,5,'2026-06-30 12:14:57','2026-06-30 12:14:57'),(380,'Photos_SupportingBodiesScientificResearch/gZJwdvApHx7KiJN3uGYxbyA95drIZs21u0ut14Tk.png','مركز الدراسات والبحوث اليمنية',NULL,'يُعدّ المركز اليمني للدراسات والبحوث مؤسسة بحثية يمنية تُعنى بإنتاج ونشر الدراسات حول تاريخ البلاد ومجتمعها وثقافتها وسياستها وتنميتها. تأسس المركز عام ١٩٧٢ ، وهو من أقدم المراكز البحثية في اليمن، وقد اضطلع بدورٍ هام في توثيق التراث اليمني ودعم البحث الأكاديمي والدراسات العامة.\r\nالمهام : \r\nتتمثل المهمة الأساسية للمركز في تعزيز المعرفة حول اليمن من خلال البحث والتوثيق والنشر . ويشمل عمله طيفاً واسعاً من التخصصات، بما في ذلك التاريخ والأدب والاقتصاد والسياسة والعلوم الاجتماعية. ويُولي المركز اهتماماً بالغاً منذ زمن طويل بالحفاظ على التراث الفكري والثقافي الغني لليمن وتعزيزه من خلال نشر الدراسات الأكاديمية والمصادر التاريخية.',NULL,'https://www.alinaser.com/',6,21,5,'2026-06-30 12:33:57','2026-06-30 12:33:57'),(381,'Photos_CentersExcellenceArtificialIntelligence/br0IagjB4qqt7PWLYVgWe0a46jeYm0QZYsvci0mF.png','مركز المعرفة','KDA','مركز المعرفة (KDA) هو منصة تعليمية وتدريبية متخصصة في تنمية المهارات الرقمية والذكاء الاصطناعي، تهدف إلى تمكين الأفراد والمؤسسات من اكتساب المعارف والتطبيقات العملية لأحدث التقنيات. يقدم المركز برامج تدريبية متخصصة تغطي تطبيقات الذكاء الاصطناعي، وهندسة الأوامر، والأدوات الإنتاجية الذكية، والبرمجة، والتقنيات الرقمية، من خلال بيئة تعليمية تفاعلية تجمع بين الدورات الإلكترونية والحضورية، بما يسهم في إعداد كوادر قادرة على مواكبة التحول الرقمي وتعزيز الابتكار في مختلف القطاعات.',NULL,'https://thekda.ai',5,15,2,'2026-06-30 12:56:06','2026-06-30 12:57:24'),(382,'Photos_CentersExcellenceArtificialIntelligence/XwstDSWQJcAilQi6XRiyq6iR2X7X28PRRICns57I.png','المركز الوطني الصومالي للذكاء الاصطناعي','SNAIC','المركز الوطني الصومالي للذكاء الاصطناعي (SNAIC) هو مؤسسة حكومية أُسست في أكتوبر 2024، تُعنى بقيادة جهود تطوير الذكاء الاصطناعي في الصومال من خلال تعزيز البحث العلمي، والتعليم، والابتكار، وتبني التطبيقات الذكية في مختلف القطاعات. ويعمل المركز على بناء القدرات الوطنية، ودعم الأبحاث المتخصصة، وتمكين المؤسسات الحكومية والجامعات والقطاع الخاص من توظيف تقنيات الذكاء الاصطناعي لمعالجة التحديات التنموية، مع التركيز على الاستخدام المسؤول والأخلاقي للتقنيات الحديثة، وتعزيز الشراكات المحلية والدولية بما يسهم في دعم التنمية المستدامة والتحول الرقمي في الصومال.',NULL,'https://snaic.gov.so/',5,10,2,'2026-06-30 13:28:08','2026-06-30 13:28:08'),(383,'Photos_SupportingBodiesScientificResearch/Vpi390vdbkY1BgZSv5a3FaqRsPi7c4bYIEgQupDQ.png','مؤسسة العون للتنمية',NULL,'هي منظمة يمنية غير ربحية للتنمية، تأسست في مارس 2006، ومرخصة من قبل وزارة الشؤون الاجتماعية والعمل اليمنية. يقع مقرها في المكلا، حضرموت، وتركز على دعم التنمية طويلة الأجل من خلال التعليم والرعاية الصحية والمبادرات المجتمعية وبناء القدرات المؤسسية، ولها حضور قوي في شرق اليمن.\r\nالمهام : تعزيز التنمية المستدامة من خلال الاستثمار في الأفراد والمؤسسات بدلاً من تقديم الإغاثة قصيرة الأجل فقط. وتشمل برامجها قطاعات متعددة، منها التعليم والصحة والمياه والصرف الصحي والتمكين الاقتصادي والتنمية المجتمعية ، وغالباً ما تعمل بالشراكة مع الجامعات والهيئات الحكومية ومنظمات المجتمع المدني.',NULL,'https://alawn.org/',6,21,5,'2026-06-30 13:28:30','2026-06-30 13:28:30'),(384,'Photos_SupportingBodiesScientificResearch/W4ppyMHgnuGd17iEy9VT5TLrD6N3s83FEGgAioOC.png','المركز الوطني للذكاء الاصطناعي والتكنولوجيا',NULL,'هو مؤسسة يمنية تركز على تطوير الذكاء الاصطناعي والتقنيات الناشئة وبناء القدرات الرقمية . ويهدف إلى تعزيز الخبرات الوطنية من خلال توفير التدريب ودعم البحث والابتكار، وتعزيز التعاون بين الأوساط الأكاديمية والصناعية والحكومية لتشجيع تبني التكنولوجيا في اليمن.\r\nتاسس عام 2025\r\nالمهام : بناء قاعدة معرفية وطنية متقدمة في مجال الذكاء الاصطناعي والتقنيات الناشئة. وتركز أنشطتها على تطوير المهارات التقنية، وتعزيز الابتكار، وخلق بيئة داعمة للتحول الرقمي من خلال التعليم والتطوير المهني والشراكات.',NULL,'https://ncai-ye.com/',6,21,5,'2026-06-30 13:33:29','2026-06-30 13:33:29'),(385,'Photos_CentersExcellenceArtificialIntelligence/EOX8DZQ8XVhvQZMyxe3K5MtuuahQZUrBzS7Nrwtv.png','مركز المعرفة الرقمي','Digital Knowledge Hub - DKH','مركز المعرفة الرقمي (Digital Knowledge Hub - DKH) هو مركز متخصص في بناء القدرات الرقمية ونشر المعرفة التقنية، يهدف إلى تمكين الأفراد والمؤسسات من مواكبة التطورات التكنولوجية من خلال تقديم برامج تدريبية متخصصة، واستشارات، ومبادرات تعليمية تدعم الابتكار والتحول الرقمي. ويسعى المركز إلى إعداد كوادر مؤهلة، وتعزيز المهارات المستقبلية، وبناء شراكات مع المؤسسات الأكاديمية والقطاعين العام والخاص، بما يسهم في دعم الاقتصاد الرقمي وتطوير رأس المال البشري',NULL,'https://ddl.ae/',5,2,2,'2026-06-30 13:37:00','2026-06-30 13:37:00'),(386,'Photos_SupportingBodiesScientificResearch/tRwn1LxnzhdKaGooN9y6TjsI9UGUn9JXvXSnKFcH.png','الهيئة العامة للعلوم والبحوث العلمية المتنوعة',NULL,'هي هيئة حكومية مقرها صنعاء، اليمن، تُعنى بسياسات العلوم والبحوث وتطوير التكنولوجيا والابتكار. وتسعى الهيئة إلى تعزيز البيئة العلمية والتكنولوجية في اليمن من خلال دعم البحوث وتشجيع الابتكار وتعزيز نقل التكنولوجيا وتوطينها كجزء من أهداف التنمية الوطنية الأوسع.\r\nتاسست عام 2020\r\nالمهام : هي تهيئة بيئة وطنية داعمة للعلوم والتكنولوجيا والابتكار من خلال تطوير السياسات، ونقل التكنولوجيا، وتوطين المعرفة، ودعم المخترعين والمبتكرين. ووفقًا لهيكلها التنظيمي المنشور، يشمل عملها تنسيق البحوث، والتقنيات المتقدمة، ونقل التكنولوجيا، وتسجيل الابتكارات، والتخطيط، والاستثمار، وإنشاء مكتبة وطنية للعلوم والتكنولوجيا.',NULL,'https://hasti.gov.ye/',6,21,5,'2026-06-30 13:38:53','2026-06-30 13:38:53'),(387,'Photos_SupportingBodiesScientificResearch/UTKpJZu8tJVMjPXxV1SaX9pvgRDUbeqwW9pgAIu6.png','مؤسسة السعيد للعلوم الإنسانية',NULL,'هي مؤسسة يمنية غير ربحية ثقافية وعلمية تأسست عام 1996 لتعزيز البحث والتعليم والتنمية الثقافية. أسستها مجموعة هايل سعيد أنام تخليداً لذكرى الحاج هايل سعيد أنام ، وأصبحت من أبرز المؤسسات الثقافية الخاصة في اليمن بفضل مكتبتها ودعمها للبحوث وجوائزها وبرامجها العامة.\r\nالمهام :أُنشئت المؤسسة لتشجيع البحث العلمي والإبداع الثقافي ونشر المعرفة في اليمن. وتشمل أهدافها المعلنة دعم الباحثين، وتنظيم المؤتمرات والمحاضرات العلمية، وتعزيز الابتكار، والتعاون مع المؤسسات البحثية، والاعتراف بالإنجازات العلمية والثقافية المتميزة من خلال الجوائز والمبادرات الأخرى.',NULL,'https://www.hsagroup.com/hsa-ar/about-hsa/about-us.aspx',6,21,5,'2026-06-30 13:43:31','2026-06-30 13:43:31'),(388,'Photos_ScientificResearchInnovationCenters/nOd16pxV66qkjKXR6JeebDEOJS3huEd128wyYUtw.jpg','مركز الكويت للابتكار','Kuwait Innovation Center','مركز الكويت للابتكار (Kuwait Innovation Center - KIC) هو مركز وطني يُعنى بتعزيز الابتكار وتطوير الحلول التقنية، من خلال دعم البحث والتطوير، وتمكين المبتكرين ورواد الأعمال، وتحويل الأفكار إلى منتجات ومشروعات قابلة للتطبيق. ويوفر المركز بيئة متكاملة تشمل الاستشارات، وتطوير النماذج الأولية، ونقل التكنولوجيا، وبناء الشراكات مع المؤسسات الأكاديمية والقطاعين العام والخاص، بما يسهم في تعزيز منظومة الابتكار ودعم التنمية الاقتصادية القائمة على المعرفة.',NULL,'https://www.kinncenter.com/',5,15,1,'2026-06-30 14:05:22','2026-06-30 14:05:22'),(389,'Photos_ScientificResearchInnovationCenters/a1CCHaGndhMpUtcmKfuZhYsUsigY8CxL6ky3YGHl.png','مركز حمد عبدالعزيز الصقر للتقنية والابتكار',NULL,'مركز حمد عبدالعزيز الصقر للتقنية والابتكار هو مركز كويتي متخصص في دعم الابتكار والتطوير التقني، يهدف إلى تعزيز منظومة البحث والتطوير، وتمكين المبتكرين ورواد الأعمال، ودعم تطوير الحلول والتقنيات الحديثة التي تلبي احتياجات مختلف القطاعات. ويوفر المركز بيئة محفزة للابتكار من خلال البرامج التدريبية، والاستشارات، والشراكات مع المؤسسات الأكاديمية والبحثية والقطاع الخاص، بما يسهم في نقل المعرفة، وتنمية الكفاءات الوطنية، وتعزيز الاقتصاد القائم على الابتكار والتكنولوجيا.',NULL,'https://hamad.center/',5,15,1,'2026-06-30 14:13:24','2026-06-30 14:13:24'),(390,'Photos_CentersExcellenceArtificialIntelligence/SNAPgEpHwwUcQKy9SpLKxDNfJvLO48ZgBN7XiFft.webp','أكاديمية السودان للذكاء الاصطناعي',NULL,'أكاديمية السودان للذكاء الاصطناعي هي منصة تعليمية وتدريبية متخصصة في نشر المعرفة وتطوير المهارات في مجال الذكاء الاصطناعي، وتهدف إلى تمكين الأفراد من اكتساب المهارات العملية في استخدام تقنيات الذكاء الاصطناعي التوليدي وتطبيقاتها في مختلف المجالات. تقدم الأكاديمية برامج تدريبية ودورات إلكترونية وتفاعلية، تجمع بين الجوانب النظرية والتطبيقية، مع التركيز على بناء القدرات، وتعزيز الابتكار، وإعداد كوادر مؤهلة قادرة على توظيف أدوات الذكاء الاصطناعي في التعليم، وسوق العمل، وريادة الأعمال، بما يسهم في دعم التحول الرقمي ونشر الثقافة التقنية في السودان.',NULL,'https://sudanacademy.net/',5,8,2,'2026-06-30 14:16:12','2026-06-30 14:16:12'),(391,'Photos_CentersExcellenceArtificialIntelligence/9ovfYA6OHlMkCLLJehvT4K5PImnsfQLWlJr92ZJK.jpg','المركز السوداني لأمن المعلومات','Sudan CERT','المركز السوداني لأمن المعلومات هو المركز الوطني المختص بالأمن السيبراني والاستجابة لحوادث أمن المعلومات في السودان، أُنشئ عام 2010 بمبادرة من الهيئة القومية للاتصالات (التي أصبحت لاحقًا هيئة تنظيم الاتصالات والبريد). يهدف المركز إلى تعزيز أمن الفضاء السيبراني، وحماية البنية التحتية الرقمية، ورفع الوعي بأمن المعلومات، من خلال رصد وتحليل التهديدات السيبرانية، والاستجابة للحوادث الأمنية، وتقديم الاستشارات الفنية، ودعم التحقيقات والأدلة الجنائية الرقمية، إضافة إلى بناء القدرات الوطنية ونشر أفضل الممارسات في مجال الأمن السيبراني، بما يسهم في تعزيز أمن المؤسسات والمستخدمين في السودان',NULL,'https://www.cert.sd/',5,8,2,'2026-06-30 14:24:52','2026-06-30 14:24:52'),(392,'Photos_ScientificResearchInnovationCenters/Il8MkeibByakJPZhBV5Gybz5zS7iG7l5XSjYoWvr.jpg','مدينة العلوم',NULL,'مدينة العلوم بتونس هي مؤسسة علمية عمومية تونسية أُنشئت سنة 1992 بهدف نشر الثقافة العلمية والتكنولوجية وتعزيز الوعي بالعلوم لدى مختلف فئات المجتمع. \r\nوتعمل المؤسسة على تبسيط العلوم وتشجيع الابتكار من خلال تنظيم المعارض العلمية الدائمة والمؤقتة والمتنقلة، والأنشطة التعليمية والتوعوية، إضافة إلى توفير فضاءات للمعرفة ومكتبة علمية، بما يسهم في دعم التعليم ونشر الثقافة العلمية بين الأطفال والشباب والطلبة والباحثين والجمهور العام.',NULL,'http://www.cst.rnu.tn/',5,4,1,'2026-07-01 08:10:41','2026-07-01 08:10:41'),(393,'Photos_ScientificResearchInnovationCenters/glnLgA3mCYCFMW2CaZumjFEfIL0Cy3vJZHyKxqNU.png','تونس للأقطاب التكنولوجية الذكية','Smart Tunisian Technoparks - S2T','تونس للأقطاب التكنولوجية الذكية هي شركة عمومية تونسية تابعة لوزارة تكنولوجيات الاتصال، أُحدثت سنة 2019 لتتولى إحداث وإدارة وتشغيل الأقطاب التكنولوجية في تونس. تهدف المؤسسة إلى دعم منظومة الابتكار وريادة الأعمال الرقمية، وتعزيز التعاون بين البحث العلمي والتكوين والقطاع الصناعي، واحتضان الشركات الناشئة ورواد الأعمال، واستقطاب الاستثمارات في مجالات الاقتصاد الرقمي، إضافة إلى توفير بيئة تكنولوجية محفزة على الابتكار والإبداع، بما يسهم في دعم التحول الرقمي والتنمية الاقتصادية القائمة على المعرفة.',NULL,'https://www.s2t.tn/',5,4,1,'2026-07-01 08:58:12','2026-07-01 08:58:12'),(394,'Photos_CentersExcellenceArtificialIntelligence/kyV7EB6MtBCBYPuflvzMBfTyn0NeDrWDgK0sWp0Q.jpg','الجمعية التونسية للإعلام والذكاء الاصطناعي','ATMEDIA','الجمعية التونسية للإعلام والذكاء الاصطناعي (ATMEDIA) هي جمعية تونسية مستقلة وغير ربحية أُسست بهدف مواكبة التحولات الرقمية في قطاع الإعلام وتعزيز الاستخدام المسؤول لتقنيات الذكاء الاصطناعي في العمل الصحفي والإعلامي. تعمل الجمعية على تطوير قدرات الصحفيين والإعلاميين من خلال التكوين والتدريب وتنظيم الندوات والأنشطة العلمية، مع ترسيخ مبادئ أخلاقيات المهنة، وتعزيز الابتكار، ودعم إنتاج محتوى إعلامي موثوق يواكب التطورات التكنولوجية.',NULL,'https://www.facebook.com/atmedia.tunisia/',5,4,2,'2026-07-01 09:06:01','2026-07-01 09:06:01'),(395,'Photos_CentersExcellenceArtificialIntelligence/iV455ZDJ27CHXnybhA6yej0pDtfI2jNgE8DxsdO5.jpg','مركز أكيو لوجيك للذكاء الاصطناعي والتحول الرقمي','AQLLOGIC','AQLLOGIC هو مركز مغربي متخصص في الاستشارات والتدريب والتدقيق والمواكبة في مجال الذكاء الاصطناعي والتحول الرقمي، مقره مدينة الدار البيضاء. \r\nويهدف المركز إلى تمكين الأفراد والمؤسسات من تبني تقنيات الذكاء الاصطناعي من خلال تقديم برامج تدريبية متخصصة، واستشارات استراتيجية، وخدمات التدقيق وتقييم النضج الرقمي، إضافة إلى مرافقة المؤسسات في تصميم وتنفيذ حلول الذكاء الاصطناعي بما يعزز الابتكار ويرفع الكفاءة التشغيلية ويدعم التحول الرقمي المستدام.',NULL,'https://aqllogic.ai',5,19,2,'2026-07-01 09:53:22','2026-07-01 09:53:22'),(396,'Photos_CentersExcellenceArtificialIntelligence/gTlbDhT0SBX3Hn5q5k3vg3wtRMQ4HsVdzMqnAyhT.jpg','وكالة الذكاء الاصطناعي','IA Agency','وكالة الذكاء الاصطناعي هي وكالة رقمية مغربية متخصصة في تطوير حلول الذكاء الاصطناعي والتحول الرقمي للمؤسسات، لاسيما المقاولات الصغيرة والمتوسطة. تقدم خدمات تصميم وتطوير المواقع الإلكترونية، وأتمتة العمليات باستخدام تقنيات الذكاء الاصطناعي، والتسويق الرقمي، وتطوير البرمجيات، والصيانة التقنية، والأمن السيبراني، والحلول السحابية، بهدف تعزيز الكفاءة التشغيلية ودعم الابتكار والتحول الرقمي لدى عملائها.',NULL,'https://ai-agency.ma/',5,19,2,'2026-07-01 10:05:14','2026-07-01 10:05:14'),(397,'Photos_CentersExcellenceArtificialIntelligence/LZBpubg8vbBqi94k1XSxNCsQf77TypJ5TS0k72uV.png','Novation City',NULL,'يُعد\r\nNovation City\r\nأحد أبرز مراكز الابتكار والتكنولوجيا في تونس، ويحتضن مركز الابتكار في الذكاء الاصطناعي (AI Innovation Hub) الذي أُطلق بالشراكة مع شركة\r\nNVIDIA\r\n. يهدف المركز إلى دعم البحث العلمي والابتكار وريادة الأعمال في مجالات الذكاء الاصطناعي، والحوسبة عالية الأداء، وعلوم البيانات، والتقنيات الرقمية المتقدمة.\r\n\r\nكما يعمل على توفير بيئة متكاملة تجمع بين الجامعات والشركات الناشئة والمؤسسات الصناعية، من أجل تطوير حلول ذكية، ونقل التكنولوجيا، وتعزيز التحول الرقمي في تونس والمنطقة.',NULL,'https://novationcity.com/',5,4,2,'2026-07-01 13:09:37','2026-07-01 13:09:37'),(398,'Photos_ScientificResearchInnovationCenters/uzCz550PBQE8UboRCsoq3zoIUVB6Bj22a8P625PP.png','Novation City',NULL,'يُعد\r\nNovation City\r\nأحد أبرز مراكز الابتكار والتكنولوجيا في تونس، ويحتضن مركز الابتكار في الذكاء الاصطناعي (AI Innovation Hub) الذي أُطلق بالشراكة مع شركة\r\nNVIDIA\r\n. يهدف المركز إلى دعم البحث العلمي والابتكار وريادة الأعمال في مجالات الذكاء الاصطناعي، والحوسبة عالية الأداء، وعلوم البيانات، والتقنيات الرقمية المتقدمة.\r\n\r\nكما يعمل على توفير بيئة متكاملة تجمع بين الجامعات والشركات الناشئة والمؤسسات الصناعية، من أجل تطوير حلول ذكية، ونقل التكنولوجيا، وتعزيز التحول الرقمي في تونس والمنطقة.',NULL,'https://novationcity.com/',5,4,1,'2026-07-01 13:10:19','2026-07-01 13:10:19'),(399,'Photos_ScientificResearchInnovationCenters/LpNr32LLjsckVWGukfGQFCP7vZeycje1a3ZE6h2o.png','The Dot',NULL,'يُعد The Dot أول مركز وطني للابتكار الرقمي في تونس، أُطلق عام 2021 في إطار شراكة بين القطاعين العام والخاص وبدعم من الحكومة التونسية. يهدف المركز إلى دعم الشركات الناشئة ورواد الأعمال، وتعزيز منظومة الابتكار الرقمي، وتسريع التحول الرقمي من خلال برامج الاحتضان والتسريع، والتدريب، والإرشاد، وبناء الشراكات المحلية والدولية. كما يضم مبادرات متخصصة في مجالات الذكاء الاصطناعي، والصناعة 4.0، والابتكار الرقمي، بما يسهم في تطوير الحلول التكنولوجية وتعزيز الاقتصاد الرقمي في تونس',NULL,'https://thedot.tn/',5,4,1,'2026-07-01 13:13:10','2026-07-01 13:13:10'),(400,'Photos_CentersExcellenceArtificialIntelligence/6YsPS7Tid2E9Y0n6eXOyVDdYnUvBKYQLvUkhuVO2.png','مركز التحول بالذكاء الاصطناعي','Office of AI Transformation - OAIT','يُعد مركز التحول بالذكاء الاصطناعي التابع للجامعة العالمية في لبنان مركزًا متخصصًا في الذكاء الاصطناعي التطبيقي، يهدف إلى ربط البحث الأكاديمي بالتطبيقات العملية في مختلف القطاعات. ويقدم المكتب برامج تدريبية متخصصة، وورش عمل، ودبلومات في الذكاء الاصطناعي، إلى جانب تطوير البرمجيات الذكية، والاستشارات المؤسسية، وإنتاج المحتوى المدعوم بالذكاء الاصطناعي، ودعم البحث والتطوير. كما يسعى إلى تمكين المؤسسات والمهنيين والطلبة من تبني حلول الذكاء الاصطناعي وتعزيز التحول الرقمي على المستويين المحلي والإقليمي، مع التركيز على التطبيقات العملية والاستخدام المسؤول للتقنيات الحديثة.',NULL,'https://globaluni.ai/',5,16,2,'2026-07-01 13:18:26','2026-07-03 14:01:48'),(401,'Photos_CentersExcellenceArtificialIntelligence/odfdWuJg1Ai1HfwhHzJ6zRnm90ZqLHknK4zUzwe3.png','مركز أبحاث الذكاء الاصطناعي والميتافيرس','AI and Metaverse Research Center','يُعد مركز أبحاث الذكاء الاصطناعي والميتافيرس مركزًا بحثيًا متخصصًا تابعًا لكلية دراسات الحاسوب بجامعة التكنولوجيا البحرين، \r\nويهدف إلى تعزيز البحث العلمي والابتكار في مجالات الذكاء الاصطناعي، وتحليل البيانات، والتعلم الآلي، والميتافيرس، والتقنيات الرقمية الناشئة.\r\n ويعمل المركز على دعم المشاريع البحثية، وتنظيم المؤتمرات والندوات العلمية، وبناء شراكات مع المؤسسات الأكاديمية والقطاعات الحكومية والخاصة، بما يسهم في تطوير حلول مبتكرة تخدم مختلف القطاعات الاقتصادية والمجتمعية، إلى جانب تنمية مهارات الطلبة والباحثين في أحدث تطبيقات الذكاء الاصطناعي.',NULL,'https://www.utb.edu.bh/',5,3,2,'2026-07-01 13:45:24','2026-07-01 13:45:24'),(402,'Photos_CentersExcellenceArtificialIntelligence/HxSVT5ukNEYoBjZ0fPvyM6AXjt3MIP4RAz0vZjs3.png','هيئة المعلومات والحكومة الإلكترونية','Information & eGovernment Authority','هيئة المعلومات والحكومة الإلكترونية هي الجهة الحكومية المسؤولة عن قيادة التحول الرقمي في مملكة البحرين، وتطوير وتنفيذ استراتيجيات الحكومة الإلكترونية، ووضع السياسات والمعايير المنظمة لتقنية المعلومات والخدمات الرقمية. كما تشرف على تطوير البنية التحتية الرقمية، وتعزيز استخدام التقنيات الناشئة، بما في ذلك الذكاء الاصطناعي والحوسبة السحابية، وإدارة البيانات والإحصاءات الوطنية، بما يسهم في تحسين كفاءة الخدمات الحكومية ودعم التنمية الرقمية والابتكار في المملكة. وتنفذ الهيئة مبادرات وبرامج متخصصة لتنمية القدرات الوطنية في مجال الذكاء الاصطناعي، مثل برنامج AI Talent Program.',NULL,'https://www.iga.gov.bh/',5,3,2,'2026-07-01 13:47:03','2026-07-01 13:47:03'),(403,'Photos_ScientificResearchInnovationCenters/JNpVKvbsNHUvULiGupKqVuUwGwYdsY3z2sJMqMsz.png','هيئة المعلومات والحكومة الإلكترونية','Information & eGovernment Authority','هيئة المعلومات والحكومة الإلكترونية هي الجهة الحكومية المسؤولة عن قيادة التحول الرقمي في مملكة البحرين، وتطوير وتنفيذ استراتيجيات الحكومة الإلكترونية، ووضع السياسات والمعايير المنظمة لتقنية المعلومات والخدمات الرقمية. كما تشرف على تطوير البنية التحتية الرقمية، وتعزيز استخدام التقنيات الناشئة، بما في ذلك الذكاء الاصطناعي والحوسبة السحابية، وإدارة البيانات والإحصاءات الوطنية، بما يسهم في تحسين كفاءة الخدمات الحكومية ودعم التنمية الرقمية والابتكار في المملكة. وتنفذ الهيئة مبادرات وبرامج متخصصة لتنمية القدرات الوطنية في مجال الذكاء الاصطناعي، مثل برنامج AI Talent Program.',NULL,'https://www.iga.gov.bh/',5,3,1,'2026-07-01 13:48:12','2026-07-01 13:48:12'),(404,'Photos_CentersExcellenceArtificialIntelligence/WKW4DwwjRmnkSiRLKSa1m2LKLrFPLGFXicdQGVJx.png','المؤسسة السورية للذكاء الرقمي','SAIF','المؤسسة السورية للذكاء الرقمي (SAIF) هي مؤسسة غير ربحية مسجلة، تُعنى ببناء قدرات وطنية في مجال الذكاء الاصطناعي انطلاقًا من معارف سوريا وبلاد الشام ولغاتها وثقافاتها وبياناتها. تركز المؤسسة على البحث التطبيقي، وتطوير أنظمة الذكاء الاصطناعي العملية، وبناء الموارد المعرفية الموثوقة، وتنمية الكفاءات، ودعم تبني الذكاء الاصطناعي في المؤسسات الحكومية والأكاديمية والخاصة. كما تعمل على تطوير حلول قائمة على الذكاء الاصطناعي، وإعداد معايير ومنهجيات للتقييم، وبناء شراكات محلية ودولية تسهم في تعزيز الابتكار والتحول الرقمي وخدمة المجتمع.',NULL,'https://syriaaifoundation.org/',5,9,2,'2026-07-01 13:58:06','2026-07-01 13:58:06'),(405,'Photos_CentersExcellenceArtificialIntelligence/T1xTogjOJCOk8mtqPSiZveefWJgTgcbfXXrdtfAp.png','الجمعية السورية للذكاء الاصطناعي وريادة الأعمال','Syrian Association for AI & Entrepreneurship (SAAE)','الجمعية السورية للذكاء الاصطناعي وريادة الأعمال هي منظمة شبابية ومجتمعية تُعنى بنشر ثقافة الذكاء الاصطناعي وريادة الأعمال في المجتمع السوري، وتمكين الشباب والطلاب ورواد الأعمال من اكتساب المهارات التقنية والريادية. تعمل الجمعية على بناء بيئة معرفية تجمع بين التكنولوجيا الحديثة والابتكار من خلال تنظيم الدورات التدريبية، وورش العمل، والفعاليات العلمية، والمشاريع التطبيقية، إضافة إلى دعم البحث والتطوير، وتعزيز التحول الرقمي، وبناء مجتمعات متخصصة وشراكات تسهم في إعداد كوادر قادرة على توظيف تقنيات الذكاء الاصطناعي في مختلف المجالات. كما توفر منصة تعليمية متكاملة لتطوير المهارات التقنية والمهنية.',NULL,'https://aisyria.org/',5,9,2,'2026-07-01 14:00:53','2026-07-01 14:00:53'),(406,'Photos_CentersExcellenceArtificialIntelligence/Vv9lKfPdSzFulMXdIFoHyz5hRXQKEXHUkOu2G0Nf.png','مركز تحدي فلسطين لإنترنت الأشياء والذكاء الاصطناعي',NULL,'تحدي فلسطين لإنترنت الأشياء والذكاء الاصطناعي (Palestine IoT & AI Challenge) هو برنامج وطني لبناء القدرات والاحتضان الأولي، يهدف إلى تمكين طلبة الجامعات والمدارس الثانوية والشركات الناشئة من تطوير مشاريع وحلول مبتكرة في مجالات الذكاء الاصطناعي وإنترنت الأشياء والتقنيات المرتبطة بهما. يوفر البرنامج التدريب والإرشاد الفني وريادة الأعمال، ويساعد المشاركين على تطوير النماذج الأولية لمشاريعهم وربطها بمنظومة الابتكار، كما يؤهل الفائزين للمشاركة في نهائيات التحدي العربي للذكاء الاصطناعي وإنترنت الأشياء على المستوى الإقليمي.',NULL,'https://palestine.arabiotai.org/',5,13,2,'2026-07-02 09:21:18','2026-07-02 09:21:18'),(407,'Photos_CentersExcellenceArtificialIntelligence/c8PAA0QJSXHqRPDidNUInH1vYoWPnmTine5mxjfW.png','أكاديمية الخوارزمي للذكاء الاصطناعي',NULL,'أكاديمية الخوارزمي للذكاء الاصطناعي هي أول أكاديمية ليبية متخصصة في تعليم وتدريب الذكاء الاصطناعي، وتهدف إلى بناء القدرات الوطنية في مجالات الذكاء الاصطناعي والتقنيات الناشئة. تقدم الأكاديمية برامج تدريبية ودبلومات مهنية وورش عمل عملية تستهدف الأطفال والطلاب والمهنيين والقيادات التنفيذية، مع التركيز على اكتساب المهارات التطبيقية، وتنفيذ المشاريع الواقعية، ودعم الابتكار بما يسهم في إعداد كوادر قادرة على قيادة التحول الرقمي وتعزيز استخدام تقنيات الذكاء الاصطناعي في ليبيا.',NULL,'https://alkhawarizmi.ai/',5,17,2,'2026-07-02 10:09:15','2026-07-02 10:09:15'),(408,'Photos_CentersExcellenceArtificialIntelligence/20ZWOaAuMnnNlxgJ7ao9rOikZMOjRTpUCgvJHoaI.jpg','لبيب للذكاء الاصطناعي',NULL,'لبيب للذكاء الاصطناعي هي شركة ليبية ناشئة في مجال التكنولوجيا، متخصصة في الحلول الذكية المدعومة بالذكاء الاصطناعي. تهدف الشركة إلى تمكين المؤسسات من تحقيق تحول رقمي آمن وفعال، مع ضمان حماية خصوصية البيانات. كما تقدم لبيب للذكاء الاصطناعي برامج تدريبية متخصصة لمساعدة الشركات على استخدام الأدوات الذكية بفعالية، مما يعزز إنتاجيتها وابتكارها. تطمح الشركة إلى أن تكون شريكًا رائدًا للمؤسسات في ليبيا والمنطقة من خلال توفير حلول تقنية مبتكرة تدعم النمو المستدام وتطوير بيئة الأعمال المحلية.',NULL,'https://labebai.com/ar',5,17,2,'2026-07-02 10:11:21','2026-07-02 10:11:21'),(409,'Photos_CentersExcellenceArtificialIntelligence/kODAeeolwtrj26S7AMZ3wAVvukof9Teud0HYoUMj.png','أكاديمية رؤية للقيادة والتكنولوجيا',NULL,'أكاديمية رؤية للقيادة والتكنولوجيا هي أكاديمية ليبية متخصصة في إعداد القيادات الوطنية وتنمية المهارات الرقمية والتقنية، وتهدف إلى تأهيل الأفراد والمؤسسات لمواكبة التحول الرقمي من خلال برامج تدريبية متخصصة في القيادة الرقمية، والذكاء الاصطناعي، والأمن السيبراني، والحوكمة الرقمية، والتقنيات الناشئة. كما تعتمد الأكاديمية منهجًا يجمع بين التعليم النظري والتطبيق العملي، وتسعى إلى بناء شراكات مع القطاعين العام والخاص، مع رؤية مستقبلية لإنشاء مراكز تميز بحثية في مجالات الذكاء الاصطناعي والمدن الذكية والبنية التحتية الرقمية، وحاضنة ومسرعة للشركات التقنية الناشئة.',NULL,'https://royaacademy.ly/',5,17,2,'2026-07-02 10:16:57','2026-07-02 10:16:57'),(410,'Photos_CentersExcellenceArtificialIntelligence/3BnFYFRhdQuby6tILxiUbvXAaxJbMpurw2ckucDf.png','رواد الذكاء الاصطناعي','Roowaad AI','رواد (Ruwwad.ai) هي شركة متخصصة في تطوير وتطبيق حلول الذكاء الاصطناعي للمؤسسات، وتركز على تمكين الجهات الحكومية والخاصة من تبني تقنيات الذكاء الاصطناعي بطريقة عملية وسريعة تحقق أثراً ملموساً. تعتمد الشركة منهجية تبدأ بفهم التحديات وتحديد المشكلات بدقة، ثم تقييم الجدوى الاقتصادية، وتصميم حلول مرنة وسهلة التبني، بما يساعد المؤسسات على تحسين الكفاءة التشغيلية، وتعزيز الإنتاجية، وتحقيق عائد استثماري واضح من مشاريع الذكاء الاصطناعي.',NULL,'https://roowaad.ai/',5,15,2,'2026-07-02 10:33:22','2026-07-02 10:33:22'),(411,'Photos_CentersExcellenceArtificialIntelligence/rXNQ6pCKTv69LBet9AgZSJwIuGopLpBpmWV53FPm.png','رواد الذكاء الرقمي',NULL,'رواد الذكاء الرقمي هي شركة سعودية متخصصة في تطوير المنصات والأنظمة الرقمية الذكية، تأسست عام 2013 بهدف قيادة التحول الرقمي وتمكين المؤسسات من تحسين كفاءتها التشغيلية من خلال حلول تقنية مبتكرة. تقدم الشركة منصات وخدمات رقمية مخصصة لقطاعات متعددة، تشمل القطاع الحكومي، والقطاع الخاص، والقطاع غير الربحي، والضيافة، والخدمات الاجتماعية، مع التركيز على الأتمتة، وإدارة العمليات، ورفع جودة الخدمات، وتوفير حلول مرنة تلبي احتياجات مختلف الجهات.',NULL,'https://alrawad.sa/',5,7,2,'2026-07-02 10:35:56','2026-07-02 10:35:56'),(412,'Photos_CentersExcellenceArtificialIntelligence/OSGNbTSTzE04f8dPMTBKhJlqocORUUEjWSrN3Qv3.png','أكاديميا','Academea','أكاديميا (Academea) هي منصة تعليمية متخصصة في تعليم الذكاء الاصطناعي، أطلقتها شركة EKANI AI Consultancy في دولة الكويت بهدف إعداد الطلاب والمهنيين لمستقبل تقوده تقنيات الذكاء الاصطناعي. تقدم الأكاديمية برامج تدريبية عملية تغطي أساسيات الذكاء الاصطناعي، والذكاء الاصطناعي التوليدي، وهندسة الأوامر (Prompt Engineering)، والأتمتة، وتطوير التطبيقات بدون برمجة، مع التركيز على التعلم التطبيقي والمشروعات العملية وبناء المهارات الرقمية اللازمة لمواكبة متطلبات المستقبل',NULL,'https://www.academea.co/',5,15,2,'2026-07-02 10:43:16','2026-07-02 10:43:16'),(413,'Photos_ScientificResearchInnovationCenters/B2mK9g2NDEueJcBTQjAjrJTbKbMsVkAC9jregmWs.png','أركان للقيادة والابتكار','Arkaan Leadership & Innovation Hub','أركان للقيادة والابتكار (Arkaan Leadership & Innovation Hub) هي مؤسسة صومالية متخصصة في تنمية القدرات والابتكار والاستشارات المؤسسية، تعمل على تمكين الشباب والمؤسسات من خلال برامج التدريب المهني، وريادة الأعمال، والتطوير المؤسسي، والابتكار التقني. كما تقدم مبادرات في مجال الذكاء الاصطناعي والتحول الرقمي بهدف دعم الكفاءات المحلية وتعزيز استخدام التقنيات الحديثة في التعليم والأعمال والتنمية المجتمعية. يقع مقرها في\r\nمقديشو\r\nوتسعى إلى بناء منظومة داعمة للابتكار والتنمية المستدامة في الصومال والمنطقة.',NULL,'www.arkaan.so',5,10,1,'2026-07-02 10:48:14','2026-07-02 10:48:14'),(414,'Photos_CentersExcellenceArtificialIntelligence/7xGINYAXDmRFycRF2nlC8qGoEx2c4sOSrTx0U6TS.png','أركان للذكاء الاصطناعي','Arkaan AI','أركان للذكاء الاصطناعي (Arkaan AI) هي منصة ومركز متخصص في تقديم خدمات التدريب والاستشارات والحلول المعتمدة على تقنيات الذكاء الاصطناعي في الصومال، وتهدف إلى تمكين الأفراد والمؤسسات من الاستفادة من التقنيات الحديثة في تطوير الأعمال ورفع الكفاءة التشغيلية.\r\nتركز المنصة على بناء المهارات الرقمية, ونشر الوعي بتطبيقات الذكاء الاصطناعي، وتقديم برامج عملية تساعد على استخدام أدوات الذكاء الاصطناعي في مجالات متعددة مثل التعليم، والأعمال، والإنتاجية، والأتمتة، وتحليل البيانات.',NULL,'https://arkaan.so/ai',5,10,2,'2026-07-02 10:49:47','2026-07-02 10:49:47'),(415,'Photos_CentersExcellenceArtificialIntelligence/iapfeeTejqTKDlkaHa0G0Gvi4QIyEYqFNZcwMmz2.png','أكاديمية كولميس','Kulmis Academy','Kulmis Academy هي منصة تعليمية رقمية متخصصة في تعليم الذكاء الاصطناعي والبرمجة الحديثة، تهدف إلى تمكين المتعلمين من اكتساب مهارات عملية تؤهلهم لسوق العمل الرقمي. تقدم الأكاديمية مسارات تدريبية في الذكاء الاصطناعي، وأدوات الذكاء الاصطناعي، ووكلاء الذكاء الاصطناعي (AI Agents)، والبرمجة التقليدية، مع التركيز على التعلم التطبيقي من خلال بناء مشاريع حقيقية. كما توفر مساعدًا تعليمياً مدعوماً بالذكاء الاصطناعي، وتدعم التعلم باللغات الإنجليزية والصومالية والعربية، بما يسهم في توسيع فرص الوصول إلى التعليم التقني في الصومال والمنطقة.',NULL,'https://www.kulmisacademy.com/',5,10,2,'2026-07-02 11:03:49','2026-07-02 11:03:49'),(416,'Photos_ScientificResearchInnovationCenters/AFiyG1kbvGL2MwaUdY8qNDaAJFnuGDmcXB03d6D9.png','معهد كولان للتكنولوجيا والعلوم','Kulan Institute of Technology and Science','معهد كولان للتكنولوجيا والعلوم (KIST) هو مؤسسة تعليمية متخصصة في التكنولوجيا والعلوم، تابعة لمجموعة Kulan Group Ltd، وتهدف إلى توفير تعليم عالي الجودة في مجالات الذكاء الاصطناعي، والأمن السيبراني، والمهارات الرقمية للمجتمع الصومالي داخل البلاد وخارجها. يقدم المعهد برامجه باللغتين الإنجليزية والصومالية، مع التركيز على التعلم العملي، وإتاحة التعليم المجاني، وإعداد المتدربين لسوق العمل من خلال برامج مهنية وشهادات متخصصة، بما يسهم في تعزيز القدرات التقنية ودعم التحول الرقمي في المجتمع الصومالي',NULL,'https://kulaninstitute.org/',5,10,1,'2026-07-02 11:10:50','2026-07-02 11:10:50'),(417,'Photos_ScientificResearchInnovationCenters/JA0ytAyMF7rjQzhoujj4nOeAlZKX34RGZ5agu1Mh.jpg','المعهد الوطني للتكنولوجيا والعلوم بالكاف','Institut National des Technologies et des sciences du Kef','المعهد الوطني للتكنولوجيا والعلوم بالكاف (INTeK) هو مؤسسة عمومية للتعليم العالي والبحث العلمي في الجمهورية التونسية، أُحدثت سنة 2022 وتخضع لإشراف وزارة التعليم العالي والبحث العلمي، وتتبع جامعة جندوبة. يهدف المعهد إلى إعداد مهندسين وكفاءات متخصصة في مجالات التكنولوجيا والعلوم المتقدمة، من خلال برامج أكاديمية تجمع بين التكوين النظري والتطبيقي والبحث العلمي. كما يواكب التطورات الحديثة بإدراج تخصصات مرتبطة بالصناعة الذكية، والأنظمة المدمجة، وإنترنت الأشياء، والروبوتات، والذكاء الاصطناعي، بما يسهم في دعم الابتكار وتلبية احتياجات سوق العمل.',NULL,'https://intek.rnu.tn/fr',5,4,1,'2026-07-02 11:13:41','2026-07-02 11:13:41'),(418,'Photos_ScientificResearchInnovationCenters/UDFgquVSp8EbdTtr1rBAblmCVDmrj4rWXBgj7Nkv.jpg','الأكاديمية الوطنية اليمنية للعلماء الشباب','YEMSCI','الأكاديمية الوطنية اليمنية للعلماء الشباب (YEMSCI) هي مؤسسة علمية رائدة تهدف إلى دعم وتمكين الباحثين والعلماء الشباب في اليمن، وتعزيز البحث العلمي والابتكار والتعاون في مختلف التخصصات العلمية. تسعى الأكاديمية إلى الإسهام في تحقيق التنمية المستدامة ومواجهة التحديات الوطنية والعالمية من خلال تشجيع البحث متعدد التخصصات، وربط الباحثين اليمنيين بالشبكات العلمية الدولية، وتوفير فرص التدريب والإرشاد والتمويل لتطوير قدراتهم. كما تعمل على إعداد جيل جديد من العلماء القادرين على توظيف العلوم والتكنولوجيا لخدمة المجتمع ودفع مسيرة التنمية والابتكار في اليمن.',NULL,'https://www.yemsci.com/',5,21,1,'2026-07-02 11:29:04','2026-07-02 11:29:04'),(419,'Photos_CentersExcellenceArtificialIntelligence/SZ8ZGvYxeAemz8i5Cqz41KYOImhSkZaKCWUKxQjX.png','منصة اليمن الذكية','Yemen.ai','منصة اليمن الذكية (Yemen.ai) هي منصة يمنية رقمية متخصصة في توظيف تقنيات الذكاء الاصطناعي لتقديم خدمات تعليمية ومجتمعية مبتكرة. تهدف المنصة إلى تحسين جودة التعليم والخدمات الرقمية من خلال تطوير أدوات ذكية تدعم التعلم، وتوفر محتوى تفاعلياً للمناهج الدراسية، ومعلماً افتراضياً، وملخصات واختبارات إلكترونية، مع التوسع في تقديم حلول رقمية جديدة تسهم في خدمة المجتمع اليمني وتعزيز التحول الرقمي.',NULL,'https://yemen.ai/',5,21,2,'2026-07-02 11:58:22','2026-07-02 11:58:22'),(420,'Photos_CentersExcellenceArtificialIntelligence/aCS5tLImDixRyJg5psCxpEZIMi1U9gjlFubO1EI7.png','الذكاء الاصطناعي اليمن','AI Yemen','الذكاء الاصطناعي اليمن (AI Yemen) هي مبادرة غير ربحية تهدف إلى نشر وتعزيز تعليم وبحوث وتطبيقات الذكاء الاصطناعي في اليمن، وبناء مجتمع من الممارسين والباحثين والمهتمين بالتقنية لدعم الابتكار والتنمية. تعمل المبادرة على توفير برامج تدريبية وموارد تعليمية مجانية، وتنظيم ورش عمل وملتقيات، ودعم المشاريع والأبحاث التي توظف الذكاء الاصطناعي لمعالجة التحديات المحلية وخلق فرص للشباب اليمني. وتؤكد المبادرة على إتاحة تعليم الذكاء الاصطناعي لجميع اليمنيين وتعزيز الاستخدام الأخلاقي والمسؤول لهذه التقنيات لخدمة المجتمع.',NULL,'https://www.aiyemen.com/',5,21,2,'2026-07-02 11:59:54','2026-07-02 11:59:54'),(421,'Photos_CentersExcellenceArtificialIntelligence/pmkKP66eRSNiAP3E9HgreRI3hN7EOZdRZcjzMFfB.png','مركز تعلم الذكاء الاصطناعي','AI Learning Center - AILC','مركز تعلم الذكاء الاصطناعي هو مركز عُماني متخصص في تعليم وتطوير تطبيقات الذكاء الاصطناعي، يهدف إلى تمكين الأفراد والمؤسسات من خلال برامج تدريبية متقدمة، وورش عمل تفاعلية، ومشاريع بحثية وتطبيقية، إلى جانب بناء شراكات محلية ودولية في مجالات الذكاء الاصطناعي، وعلوم البيانات، والأمن السيبراني، والتقنيات الناشئة. ويسعى المركز إلى دعم الابتكار، وتأهيل الكفاءات الوطنية، والمساهمة في تحقيق مستهدفات رؤية عُمان 2040 عبر تطوير حلول تقنية ذات أثر عملي ومستدام.',NULL,'https://ailc-oman.com',5,12,2,'2026-07-02 12:21:09','2026-07-02 12:21:09'),(422,'Photos_CentersExcellenceArtificialIntelligence/LWXJa8e2WagMfKgTtY2gLl1vaMWfANQWeCcvFmHr.png','مركز التعلم السعودي بالذكاء الاصطناعي','Saudi Learn AI Hub','مركز التعلم السعودي بالذكاء الاصطناعي (Saudi Learn AI Hub) هو منصة تعليمية سعودية متخصصة في تنمية المهارات الرقمية والذكاء الاصطناعي، تقدم برامج ودورات تدريبية في مجالات الذكاء الاصطناعي، وعلوم البيانات، والأمن السيبراني، وتطوير البرمجيات، وإدارة الأعمال. تعتمد المنصة على تقنيات الذكاء الاصطناعي لتوفير تجربة تعلم مخصصة، وتشمل مساعدًا ذكيًا، ومسارات تعليمية تكيفية، وشهادات رقمية موثقة، بما يسهم في إعداد الكفاءات الوطنية ودعم مستهدفات رؤية المملكة 2030',NULL,'https://saudilearnaihub.com/',5,7,2,'2026-07-02 12:23:01','2026-07-02 12:23:01'),(423,'Photos_ScientificResearchInnovationCenters/lEvvhrHgqwKaOzZJ5LZJ96EnS6WHQYtmVFUFW9a0.png','أكاديمية تقنيات الذكاء الاصطناعي','AI Tech Academy','أكاديمية تقنيات الذكاء الاصطناعي (AI Tech Academy) هي أكاديمية عُمانية متخصصة في التدريب والتأهيل في مجالات الذكاء الاصطناعي والتقنيات الرقمية، تهدف إلى تمكين الأفراد والمؤسسات من اكتساب المهارات العملية اللازمة لمواكبة التحول الرقمي. تقدم الأكاديمية برامج تدريبية حضورية ومسجلة، وورش عمل احترافية، وحلولًا ذكية مخصصة للمؤسسات، مع التركيز على التطبيقات العملية للذكاء الاصطناعي، وهندسة الأوامر، والأتمتة، وتطوير المحتوى، والتحول المؤسسي، بما يسهم في إعداد كوادر قادرة على توظيف تقنيات الذكاء الاصطناعي في مختلف القطاعات.',NULL,'https://www.aitechacademy.om/',5,12,1,'2026-07-02 12:26:15','2026-07-02 12:26:15'),(424,'Photos_ScientificResearchInnovationCenters/forxRdcXQDUuPfB5SowQNgtFqfudb8M5FRVLJbCb.png','مركز أبحاث الذكاء الاصطناعي','AI Research Centre - AIRC','مركز أبحاث الذكاء الاصطناعي هو مركز بحثي تابع لكلية الهندسة في الجامعة الوطنية للعلوم والتكنولوجيا، ويُعد منصة وطنية للبحث والابتكار في مجال الذكاء الاصطناعي. يهدف المركز إلى تطوير حلول ذكية لمواجهة التحديات في قطاعات التعليم، والرعاية الصحية، والزراعة، والبيئة، والسياحة، والمجتمع، من خلال إجراء البحوث التطبيقية، وتعزيز التعاون مع المؤسسات المحلية والدولية، وبناء القدرات الوطنية في تقنيات الذكاء الاصطناعي والروبوتات والأنظمة الذكية، بما ينسجم مع مستهدفات رؤية عُمان 2040.',NULL,'https://nu.edu.om/',5,12,1,'2026-07-02 12:30:40','2026-07-02 12:30:40'),(425,'Photos_CentersExcellenceArtificialIntelligence/nU6wEo0l80hDcXg7RgYKIXUql23k6i04KSw9M9Wa.png','أكاديمية تقنيات الذكاء الاصطناعي','AI Tech Academy','أكاديمية تقنيات الذكاء الاصطناعي (AI Tech Academy) هي أكاديمية عُمانية متخصصة في التدريب والتأهيل في مجالات الذكاء الاصطناعي والتقنيات الرقمية، تهدف إلى تمكين الأفراد والمؤسسات من اكتساب المهارات العملية اللازمة لمواكبة التحول الرقمي. تقدم الأكاديمية برامج تدريبية حضورية ومسجلة، وورش عمل احترافية، وحلولًا ذكية مخصصة للمؤسسات، مع التركيز على التطبيقات العملية للذكاء الاصطناعي، وهندسة الأوامر، والأتمتة، وتطوير المحتوى، والتحول المؤسسي، بما يسهم في إعداد كوادر قادرة على توظيف تقنيات الذكاء الاصطناعي في مختلف القطاعات.',NULL,'https://www.aitechacademy.om/',5,12,2,'2026-07-02 12:37:34','2026-07-02 12:37:34'),(426,'Photos_CentersExcellenceArtificialIntelligence/5aDlxQENqBJewCOkBfsacaF3fjTtjBlPBn68eOiT.webp','مركز التميز للتطوير 4Future','4Future','مركز التميز للتطوير هو معهد تدريب عُماني تأسس عام 2022، ويهدف إلى إعداد الكفاءات المهنية وتمكين الأفراد والمؤسسات من خلال برامج تدريبية واستشارية متخصصة. \r\nيقدم المركز دورات في الذكاء الاصطناعي، والتحول الرقمي، والقيادة، والإدارة، وريادة الأعمال، والتطوير المؤسسي، بالتعاون مع شركاء واعتمادات دولية، كما يسعى إلى دعم الابتكار وبناء القدرات الوطنية بما يتماشى مع متطلبات سوق العمل ومستهدفات رؤية عُمان 2040.',NULL,'https://4future.om/',5,12,2,'2026-07-02 12:41:37','2026-07-02 12:41:37'),(427,'Photos_ScientificResearchInnovationCenters/dBHPPkmgOzSlGQD6KmeeZtvdZFzkGKcTQMM8iUDV.png','منصة إيجاد','(EJAAD)','إيجاد (EJAAD) هي منصة وطنية تعاونية تربط بين القطاع الصناعي والمؤسسات الأكاديمية والبحثية لتعزيز البحث العلمي التطبيقي، وتطوير التقنيات، ودعم الابتكار بما يسهم في بناء اقتصاد قائم على المعرفة في سلطنة عُمان. وتتوافق المنصة مع مستهدفات رؤية عُمان 2040، من خلال توظيف القدرات الوطنية والدولية في مجالات البحث والتطوير والابتكار، والاستفادة من التقنيات الناشئة لمعالجة التحديات الصناعية، وتبني أفضل الممارسات العالمية، وتعزيز تبادل المعرفة، بما يدعم تنافسية سلطنة عُمان ويرفع مكانتها في مؤشرات الابتكار العالمية، ويسهم في تحقيق أهداف التحول في قطاع الطاقة والوصول إلى الحياد الصفري للانبعاثات.',NULL,'https://orp.moheri.gov.om/ejaad',5,12,1,'2026-07-02 12:51:54','2026-07-02 12:51:54'),(428,'Photos_ScientificResearchInnovationCenters/HJaU72nPwIppPezMb5HmcG7xcXkxXmnWgSHH2pkY.jpg','مجمع الابتكار مسقط',NULL,'مجمع الابتكار مسقط هو مجمع وطني للبحث والابتكار وريادة الأعمال في سلطنة عُمان، يهدف إلى تحويل مخرجات البحث العلمي إلى منتجات وخدمات ذات قيمة اقتصادية، ودعم الشركات الناشئة القائمة على التكنولوجيا، وتعزيز التعاون بين الجامعات والمؤسسات البحثية والقطاعين الحكومي والخاص. ويوفر المجمع بنية تحتية متطورة تشمل المختبرات المتخصصة، وحاضنات ومسرعات الأعمال، ومساحات العمل، وخدمات نقل التكنولوجيا والاستثمار، مع التركيز على مجالات الذكاء الاصطناعي، والتقنيات الرقمية، والطاقة، والصحة، والبيئة، بما يسهم في تحقيق مستهدفات رؤية عُمان 2040.',NULL,'http://www.ipm.om',5,12,1,'2026-07-02 12:57:02','2026-07-02 12:57:02'),(429,'Photos_ScientificResearchInnovationCenters/pSoCZLsH7myvgK8yf6y6DL5VANLoFqXezid3hEVx.jpg','مركز الابتكار للخدمات الإلكترونية',NULL,'يُعد مركز الابتكار للخدمات الإلكترونية جهة رقمية متقدمة تختص بتقديم باقة متكاملة من الخدمات الإلكترونية الشرعية عن بُعد، واضعًا نصب عينيه توفير منصة موثوقة تُعنى بالجودة والكفاءة، وساعيًا إلى منح عملائه تجربة شراء إلكترونية متميزة، قائمة على الاحترافية والاعتماد الكامل عبر الإنترنت.',NULL,'https://al-epticar.com/',5,7,1,'2026-07-02 12:59:42','2026-07-02 12:59:42'),(430,'Photos_CentersExcellenceArtificialIntelligence/fFZUxWivoIvYoe0CvyIRqIKH73jmuHoqiu813W7S.png','Beirut AI',NULL,'تُعد Beirut AI منظمة لبنانية غير ربحية تأسست عام 2018، وتهدف إلى نشر المعرفة بالذكاء الاصطناعي وتمكين الأفراد من اكتساب المهارات اللازمة لتطبيق تقنياته في مختلف المجالات. وتُعرف بأنها أكبر مجتمع متخصص في الذكاء الاصطناعي التطبيقي في لبنان، حيث تنظم برامج تدريبية ومعسكرات تعليمية (Bootcamps)، وورش عمل، وهاكاثونات، وفعاليات للتواصل المهني، إضافة إلى التعاون مع الجامعات والمؤسسات لدعم الابتكار وإعداد الكفاءات لسوق العمل في مجال الذكاء الاصطناعي',NULL,'https://beirutai.org/',5,16,2,'2026-07-03 13:41:22','2026-07-03 13:41:22'),(431,'Photos_CentersExcellenceArtificialIntelligence/fFqdrfIZrgSvky0goZSxkOdiTMOUQpdxhLyIzOFW.png','مركز أنسنة الابتكار في الذكاء الاصطناعي','Humanity-AI Driven Center for Innovation','يُعد مركز أنسنة الابتكار في الذكاء الاصطناعي التابع للجامعة الإسلامية في لبنان مبادرة أكاديمية تهدف إلى دمج تقنيات الذكاء الاصطناعي مع القيم الإنسانية، من خلال تعزيز التعاون بين الباحثين والأكاديميين والمهندسين والمتخصصين من مختلف التخصصات. ويسعى المركز إلى ترسيخ مكانة الجامعة كمؤسسة رائدة في تطوير ذكاء اصطناعي أخلاقي وشامل، عبر دعم البحث العلمي، وإطلاق برامج تدريبية ومختبرات ابتكار، وتمكين الطلبة من تصميم حلول مبتكرة تلبي احتياجات المجتمع، مع التركيز على مبادئ الشفافية، والمسؤولية، والعدالة في استخدام تقنيات الذكاء الاصطناعي',NULL,'https://www.iul.edu.lb/',5,16,2,'2026-07-03 13:47:18','2026-07-03 13:47:18'),(432,'Photos_CentersExcellenceArtificialIntelligence/6q6ay1OAaEogrYrgV8kX0W6XVQwmZc5q1wQhYuxR.png','مركز AIFirst',NULL,'يُعد مركز AIFirst أول مركز تعليمي في لبنان مخصص بالكامل لدمج تقنيات الذكاء الاصطناعي في العملية التعليمية. \r\n\r\nويهدف إلى تطوير التعليم من خلال تمكين الطلبة والمعلمين والمهنيين من اكتساب المهارات والمعارف اللازمة للاستفادة من تطبيقات الذكاء الاصطناعي، عبر برامج تدريبية وورش عمل ومبادرات تعليمية مبتكرة. كما يسعى المركز إلى ترسيخ مكانة لبنان كمركز إقليمي في مجال التعليم المدعوم بالذكاء الاصطناعي، من خلال تعزيز ثقافة الابتكار، وتوسيع فرص الوصول إلى التعليم، وإعداد الكفاءات القادرة على مواكبة التحول الرقمي.',NULL,'https://www.aifirstcenter.com/',5,16,2,'2026-07-03 13:51:41','2026-07-03 13:51:41'),(433,'Photos_ScientificResearchInnovationCenters/kvyS3vD7XaZxh7rFCuaXCPDcuigomvASXxIvThEc.png','الأكاديمية العربية الدولية','International Academy','الأكاديمية العربية الدولية  هي مؤسسة تعليمية دولية خاصة تأسست في الدوحة،عام 2016، بهدف تقديم تعليم عالمي عالي الجودة يجمع بين التميز الأكاديمي وترسيخ الهوية العربية والقيم الثقافية. تعتمد الأكاديمية برامج البكالوريا الدولية (IB) في جميع مراحلها التعليمية، بما في ذلك برنامج السنوات الابتدائية (PYP)، وبرنامج السنوات المتوسطة (MYP)، وبرنامج الدبلوم (DP)، مع التركيز على تنمية التفكير النقدي، والإبداع، والبحث، والابتكار، وإعداد الطلبة ليكونوا مواطنين عالميين قادرين على مواجهة تحديات القرن الحادي والعشرين. كما توفر الأكاديمية بيئة تعليمية حديثة متعددة الثقافات، تضم طلبة ومعلمين من جنسيات مختلفة، وتدعم التعلم باللغتين العربية والإنجليزية مع الاهتمام بالأنشطة الثقافية والرياضية والتقنية التي تسهم في بناء شخصية الطالب بصورة متكاملة.',NULL,'https://doha.aia.qa/ar',5,14,1,'2026-07-06 09:01:57','2026-07-06 09:01:57'),(434,'Photos_CentersExcellenceArtificialIntelligence/VMZXItpmLayj7zdWlulDdB7OBnfeYNUU9qNCnqSw.jpg','كلية الذكاء الاصطناعي',NULL,'كلية الذكاء الاصطناعي – فرع العلمين هي إحدى كليات الأكاديمية العربية للعلوم والتكنولوجيا والنقل البحري، وتهدف إلى إعداد كوادر متخصصة قادرة على قيادة الابتكار في مجالات الذكاء الاصطناعي وعلوم البيانات والروبوتات والتقنيات الذكية. تعتمد الكلية منهجًا أكاديميًا يجمع بين الأسس النظرية والتطبيق العملي، من خلال مختبرات متطورة، ومشروعات بحثية، وبرامج تدريب ميداني، مع التركيز على معالجة التحديات الواقعية باستخدام تقنيات الذكاء الاصطناعي. كما توفر برامج أكاديمية في الأنظمة الذكية (Intelligent Systems) وعلوم البيانات (Data Science)، إلى جانب شراكات دولية تتيح للطلبة فرصًا للحصول على شهادات مشتركة، والمشاركة في مسابقات ومبادرات علمية، بما يعزز جاهزيتهم لسوق العمل محليًا ودوليًا. وتأتي الكلية ضمن حرم الأكاديمية بمدينة العلمين الجديدة، الذي يوفر بيئة تعليمية حديثة وخدمات أكاديمية متكاملة تدعم الابتكار والبحث العلمي.',NULL,'https://www.aast.edu/en/colleges/CAI/elalamein/',5,18,2,'2026-07-06 09:07:06','2026-07-06 09:07:06'),(435,'Photos_ScientificResearchInnovationCenters/rfhNFTVMsFgrcyLaQ8TB6xmmQqp2ZEfgZqN0kJEm.jpg','كلية الذكاء الاصطناعي',NULL,'كلية الذكاء الاصطناعي – فرع العلمين هي إحدى كليات الأكاديمية العربية للعلوم والتكنولوجيا والنقل البحري، وتهدف إلى إعداد كوادر متخصصة قادرة على قيادة الابتكار في مجالات الذكاء الاصطناعي وعلوم البيانات والروبوتات والتقنيات الذكية. تعتمد الكلية منهجًا أكاديميًا يجمع بين الأسس النظرية والتطبيق العملي، من خلال مختبرات متطورة، ومشروعات بحثية، وبرامج تدريب ميداني، مع التركيز على معالجة التحديات الواقعية باستخدام تقنيات الذكاء الاصطناعي. كما توفر برامج أكاديمية في الأنظمة الذكية (Intelligent Systems) وعلوم البيانات (Data Science)، إلى جانب شراكات دولية تتيح للطلبة فرصًا للحصول على شهادات مشتركة، والمشاركة في مسابقات ومبادرات علمية، بما يعزز جاهزيتهم لسوق العمل محليًا ودوليًا. وتأتي الكلية ضمن حرم الأكاديمية بمدينة العلمين الجديدة، الذي يوفر بيئة تعليمية حديثة وخدمات أكاديمية متكاملة تدعم الابتكار والبحث العلمي.',NULL,'https://www.aast.edu/en/colleges/CAI/elalamein/',5,18,1,'2026-07-06 09:07:50','2026-07-06 09:07:50'),(436,'Photos_CentersExcellenceArtificialIntelligence/yvgbExDUxPUXiUoZlEfD72RhZPfk2bAA3LPaK83h.jpg','المدرسة الوطنية للذكاء الاصطناعي والرقمنة',NULL,'تُعد المدرسة الوطنية للذكاء الاصطناعي والرقمنة ببركان (ENIAD) من بين أحدث المؤسسات الجامعية المتخصصة في تكوين أطر المستقبل في مجالات الذكاء الاصطناعي، التحول الرقمي، والتقنيات الناشئة. ويُشكل السلك التحضيري بهذه المدرسة مرحلة أولى أساسية نحو التكوين الهندسي العالي، ما يجعل الالتحاق به فرصة متميزة للتلاميذ المتفوقين في الشعب العلمية والتقنية.',NULL,'https://eniad.ump.ma/ar',5,19,2,'2026-07-06 09:54:34','2026-07-06 09:54:34'),(438,'Photos_CentersExcellenceArtificialIntelligence/D5JPjbVWW2mqIEVcdsIOaRBDgMBW1yHky9wv4yUH.png','أكاديمية العلوم والتكنولوجيا الصناعية','Academy of Science and Industrial Technology','أكاديمية العلوم والتكنولوجيا الصناعية هي مؤسسة تعليمية وتدريبية تقع في جمهورية جيبوتي، وتُعنى بإعداد وتأهيل الكوادر الوطنية في المجالات التقنية والهندسية والمهنية بما يتوافق مع احتياجات سوق العمل. تهدف الأكاديمية إلى تنمية مهارات الشباب من خلال برامج تعليمية وتدريبية تجمع بين الجانب الأكاديمي والتطبيق العملي، مع التركيز على التخصصات التقنية مثل الإلكترونيات الصناعية والتحكم، والقوى الكهربائية، والحاسوب وتقنية المعلومات، إضافة إلى التعليم الإلكتروني والتعلم عن بُعد. كما تحرص الأكاديمية على تعزيز الشراكات مع المؤسسات الحكومية والقطاع الخاص لتوفير التدريب الميداني، بما يسهم في إعداد خريجين يمتلكون الكفاءة الفنية والقدرة على مواكبة التطورات الصناعية والتكنولوجية.',NULL,'https://asti.dj/maintenance-2/',5,6,2,'2026-07-06 10:50:34','2026-07-06 10:50:34'),(439,'Photos_CentersExcellenceArtificialIntelligence/WQ11VDtEq2yuspWICSEtlrS7F2KJVH6QEeP82899.webp','معهد تيك افتين للذكاء الاصطناعي والتكنولوجيا','Tech Iftiin Institute of AI & Technology','معهد تيك افتين للذكاء الاصطناعي والتكنولوجيا هو مؤسسة تعليمية وتدريبية متخصصة مقرها مدينة جيبوتي، تُعنى بتأهيل الشباب والمهنيين في مجالات الذكاء الاصطناعي وتقنيات المعلومات والتحول الرقمي. يهدف المعهد إلى إعداد كوادر قادرة على مواكبة متطلبات الاقتصاد الرقمي من خلال برامج تدريبية عملية يقودها خبراء متخصصون، مع التركيز على التعلم التطبيقي وتنفيذ مشاريع واقعية. ويقدم المعهد دورات في الذكاء الاصطناعي، وهندسة الأوامر (Prompt Engineering)، وتطوير الويب الكامل (MERN Stack)، وتطوير تطبيقات الهاتف المحمول، والأمن السيبراني، ومعالجة اللغات الطبيعية، وبرمجة Python، إضافة إلى خدمات تطوير البرمجيات والاستشارات التقنية والتدريب المؤسسي، بما يسهم في دعم الابتكار والتحول الرقمي في جيبوتي والمنطقة.',NULL,'https://techiftiin.com/',5,6,2,'2026-07-06 12:09:15','2026-07-06 12:09:15'),(440,'Photos_ScientificResearchInnovationCenters/yWyb8OowOqAaRwA2NHsac52YM3E9nzFaFRIkeov4.png','الجمعية الجيبوتية للتعليم الرقمي والابتكار',NULL,'الجمعية الجيبوتية للتعليم الرقمي والابتكار (ADENI) هي منظمة غير ربحية مقرها جمهورية جيبوتي، تُعنى بتعزيز التعليم الرقمي، وتشجيع الابتكار، وتنمية المهارات التكنولوجية لدى مختلف فئات المجتمع. أُسست الجمعية استجابةً للتحديات التي تفرضها التحولات الرقمية المتسارعة، وحرصًا على إتاحة فرص عادلة لاكتساب مهارات القرن الحادي والعشرين. وتعمل ADENI على تمكين الشباب والطلاب وأفراد المجتمع من خلال تنفيذ برامج تدريبية، وورش عمل، ومبادرات توعوية، ومشاريع تعليمية في مجالات التكنولوجيا والابتكار، بما يسهم في بناء القدرات الرقمية، وتعزيز ثقافة الإبداع، ودعم التحول الرقمي والتنمية المستدامة في جيبوتي.',NULL,'https://adeni-dj.org/',5,6,1,'2026-07-06 12:12:30','2026-07-06 12:12:30'),(441,'Photos_CentersExcellenceArtificialIntelligence/M7pNkzG7dqGdmnU4qFNXSVmreIwUHeGMrJjKR2RD.webp','مدرسة بريستيني للذكاء الاصطناعي','Pristini School of AI','تُعد Pristini School of AI مؤسسة تونسية للتعليم العالي متخصصة في الذكاء الاصطناعي وعلوم البيانات، تأسست عام 2022 بمدينة سوسة داخل القطب التكنولوجي Novation City. وتُعرّف نفسها بأنها أول جامعة متخصصة في الذكاء الاصطناعي في تونس وإفريقيا، حيث تعتمد نموذجًا تعليميًا حديثًا يجمع بين التميز الأكاديمي والابتكار والتطبيق العملي، مع التركيز على إعداد كفاءات قادرة على مواكبة متطلبات الاقتصاد الرقمي وسوق العمل المستقبلي.\r\n\r\nوتقدم المؤسسة برامج البكالوريوس والماجستير والتكوين المستمر في مجالات الذكاء الاصطناعي، وعلوم البيانات، والذكاء الاصطناعي التطبيقي، وذكاء الأعمال، إلى جانب شهادات مهنية متخصصة. كما تعتمد على شراكات واسعة مع الشركات والمؤسسات الصناعية والجامعات الدولية، بهدف تعزيز البحث العلمي، وريادة الأعمال، والابتكار، ورفع قابلية توظيف خريجيها من خلال التدريب العملي والمشاريع التطبيقية.',NULL,'https://www.pristiniaiuniversity.tn/',5,4,2,'2026-07-06 12:17:57','2026-07-06 12:17:57'),(442,'Photos_CentersExcellenceArtificialIntelligence/xpPUahJgbQAzIBEaLLWWtACS6kpmurMYo3GGQRLB.png','DeepLearn Academy',NULL,'تُعد DeepLearn Academy من المؤسسات التونسية المتخصصة في تكوين الكفاءات في الذكاء الاصطناعي، وعلوم البيانات، وتعلم الآلة، حيث تقدم برامج تدريبية احترافية وشهادات معتمدة موجهة للطلبة والمهنيين والشركات. وتعتمد الأكاديمية على التدريب التطبيقي والمشاريع الواقعية، مع التركيز على إعداد متخصصين قادرين على تلبية احتياجات سوق العمل في مجالات الذكاء الاصطناعي والتقنيات الحديثة. كما تستند إلى خبرة شركة DeepAI التونسية في تطوير حلول الذكاء الاصطناعي والاستشارات التقنية.',NULL,'https://deeplearn.tn/',5,4,2,'2026-07-06 12:21:58','2026-07-06 12:21:58');
